export interface SimulationInputs {
  valorCompra: number;
  ipiFrete: number;
  mva: number;
  icmsInternoDestino: number;
  icmsInterestadual: number;
  pisCofinsRate: number;
  excluirIcmsPis: boolean;
  impostosVenda: number;
}

export interface SimulationResults {
  valorTotalNota: number;
  baseCalculoSt: number;
  icmsStBruto: number;
  creditoIcmsEntrada: number;
  stAPagar: number;
  basePisCofins: number;
  creditoPisCofinsValor: number;
  custoFinal: number;
}

export interface PriceRow {
  margem: number;
  prices: {
    comod: number;
    curvaA: number;
    curvaB: number;
    curvaC: number;
    prodTec: number;
  };
}

export interface GroundingSource {
  web?: {
    uri: string;
    title: string;
  };
}

export interface SearchResult {
  text: string;
  sources: GroundingSource[];
}

import { SimulationInputs, SimulationResults, PriceRow } from '../types';

export const calculateCosts = (inputs: SimulationInputs): SimulationResults => {
  const {
    valorCompra,
    ipiFrete,
    mva,
    icmsInternoDestino,
    icmsInterestadual,
    pisCofinsRate,
    excluirIcmsPis,
  } = inputs;

  // 1. Base Inicial
  const valorTotalNota = valorCompra + ipiFrete;

  // 2. Cálculos de ICMS ST
  const baseCalculoSt = valorTotalNota * (1 + mva / 100);
  const icmsStBruto = baseCalculoSt * (icmsInternoDestino / 100);
  const creditoIcmsEntrada = valorCompra * (icmsInterestadual / 100);

  // ST a Pagar (Débito - Crédito)
  const stAPagar = Math.max(0, icmsStBruto - creditoIcmsEntrada);

  // 3. Cálculo de Crédito PIS/COFINS
  let basePisCofins = valorCompra;
  if (excluirIcmsPis) {
    basePisCofins = valorCompra - creditoIcmsEntrada;
  }

  const creditoPisCofinsValor = basePisCofins * (pisCofinsRate / 100);

  // 4. Custo Final da Mercadoria
  const custoFinal = valorTotalNota + stAPagar - creditoPisCofinsValor;

  return {
    valorTotalNota,
    baseCalculoSt,
    icmsStBruto,
    creditoIcmsEntrada,
    stAPagar,
    basePisCofins,
    creditoPisCofinsValor,
    custoFinal,
  };
};

export const generatePriceMatrix = (
  custoFinal: number,
  impostosVenda: number
): PriceRow[] => {
  const margensAlvo = [10.0, 10.5, 11.0, 11.5, 12.0, 13.0, 14.0, 15.0];
  const fatoresAjuste = [0.0, 1.0, 2.0, 3.0, 5.0]; // Comod, A, B, C, Tec

  return margensAlvo.map((margem) => {
    const prices = fatoresAjuste.map((fator) => {
      const totalDeducoes = impostosVenda + margem + fator;
      if (totalDeducoes >= 100) return 0;

      const divisor = (100 - totalDeducoes) / 100;
      return custoFinal / divisor;
    });

    return {
      margem,
      prices: {
        comod: prices[0],
        curvaA: prices[1],
        curvaB: prices[2],
        curvaC: prices[3],
        prodTec: prices[4],
      },
    };
  });
};

export const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(val);
};

export const formatPercent = (val: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'percent',
    minimumFractionDigits: 2,
  }).format(val / 100);
};

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { SimulationInputs } from "../types";

// Helper to get AI instance with fresh key if needed
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- 1. Image Analysis (Receipt Extraction) ---
export const analyzeInvoiceImage = async (base64Image: string): Promise<Partial<SimulationInputs> | null> => {
  const ai = getAI();

  // Prompt optimized for the specific inputs we need
  const prompt = `
    Analyze this invoice/receipt image and extract the following values if visible. 
    Return a JSON object with these keys:
    - valorCompra (Total value of products)
    - ipiFrete (Total IPI + Freight if listed, otherwise 0)
    - icmsInterestadual (ICMS rate on the invoice, usually 4, 7, or 12)
    - mva (MVA adjusted or original if listed, otherwise null)

    If you cannot find a specific value, return null for that key. 
    Focus on numeric values.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            valorCompra: { type: Type.NUMBER, nullable: true },
            ipiFrete: { type: Type.NUMBER, nullable: true },
            icmsInterestadual: { type: Type.NUMBER, nullable: true },
            mva: { type: Type.NUMBER, nullable: true }
          }
        }
      }
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text) as Partial<SimulationInputs>;
  } catch (error) {
    console.error("Error analyzing image:", error);
    throw error;
  }
};

// --- 2. Google Search Grounding (Tax Consultant) ---
export const searchTaxInfo = async (query: string) => {
  const ai = getAI();

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: query,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text;
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    return { text, sources };
  } catch (error) {
    console.error("Error searching tax info:", error);
    throw error;
  }
};

// --- 3. Text-to-Speech (Audio Summary) ---
export const generateAudioSummary = async (text: string): Promise<AudioBuffer | null> => {
  const ai = getAI();

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Puck' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data returned");
    }

    // Decode Audio Logic
    const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

    // Convert base64 to binary
    const binaryString = atob(base64Audio);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    const audioBuffer = await decodeAudioData(bytes, outputAudioContext, 24000, 1);
    return audioBuffer;

  } catch (error) {
    console.error("Error generating speech:", error);
    throw error;
  }
};

// Helper for PCM decoding from Gemini Guide
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

