import React, { useState } from 'react';
import { SimulationInputs, SearchResult } from '../types';
import { analyzeInvoiceImage, searchTaxInfo, generateAudioSummary } from '../services/geminiService';
import { formatCurrency } from '../utils/calculations';

interface GeminiAssistantProps {
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
  currentResults: { custoFinal: number; stAPagar: number; valorTotalNota: number };
}

type Tab = 'scan' | 'consult' | 'audio';

const GeminiAssistant: React.FC<GeminiAssistantProps> = ({ setInputs, currentResults }) => {
  const [activeTab, setActiveTab] = useState<Tab>('scan');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // State for Search
  const [query, setQuery] = useState('');
  const [searchResult, setSearchResult] = useState<SearchResult | null>(null);

  // State for Audio
  const [isPlaying, setIsPlaying] = useState(false);

  // --- Handlers ---

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        try {
          const extractedData = await analyzeInvoiceImage(base64String);
          if (extractedData) {
            setInputs(prev => ({ ...prev, ...extractedData }));
            alert("Nota analisada! Campos atualizados com sucesso.");
          } else {
            setError("Não foi possível extrair dados desta imagem.");
          }
        } catch (err) {
          setError("Falha ao analisar a imagem. Tente novamente.");
        } finally {
          setLoading(false);
        }
      };
      reader.readAsDataURL(file);
    } catch (err) {
      setError("Erro ao ler o arquivo.");
      setLoading(false);
    }
  };

  const handleSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const result = await searchTaxInfo(query);
      setSearchResult(result);
    } catch (err) {
      setError("Falha ao buscar informações fiscais.");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateAudio = async () => {
    if (isPlaying) return;
    setLoading(true);
    setError(null);

    const summaryText = `
      Resumo de Precificação. 
      O valor base da nota é ${formatCurrency(currentResults.valorTotalNota)}.
      O ICMS-ST a pagar é ${formatCurrency(currentResults.stAPagar)}.
      O custo final calculado é ${formatCurrency(currentResults.custoFinal)}.
      Este custo final serve como base para sua matriz de preços.
    `;

    try {
      const audioBuffer = await generateAudioSummary(summaryText);
      if (audioBuffer) {
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsPlaying(false);
        source.start(0);
        setIsPlaying(true);
      }
    } catch (err) {
      setError("Falha ao gerar o resumo em áudio.");
    } finally {
      setLoading(false);
    }
  };

  // --- Render ---

  return (
    <div className="bg-gradient-to-br from-indigo-50 to-white border border-indigo-100 rounded-xl shadow-lg p-6">
      <div className="flex items-center gap-2 mb-4">
        <span className="bg-indigo-600 text-white p-1 rounded-md">
           <svg fill="none" height="20" width="20" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2"><path d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
        </span>
        <h2 className="text-xl font-bold text-indigo-900">Assistente Gemini</h2>
      </div>

      <div className="flex gap-2 mb-6 border-b border-indigo-200 pb-1">
        <button 
          onClick={() => setActiveTab('scan')} 
          className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'scan' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:text-indigo-600'}`}
        >
          Ler Nota
        </button>
        <button 
          onClick={() => setActiveTab('consult')} 
          className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'consult' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:text-indigo-600'}`}
        >
          Consultor
        </button>
        <button 
          onClick={() => setActiveTab('audio')} 
          className={`px-4 py-2 text-sm font-medium rounded-t-lg transition-colors ${activeTab === 'audio' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-500 hover:text-indigo-600'}`}
        >
          Áudio
        </button>
      </div>

      {error && (
        <div className="mb-4 p-3 bg-red-50 text-red-600 text-sm rounded-lg border border-red-100 flex items-center gap-2">
           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
           {error}
        </div>
      )}

      {loading && (
        <div className="flex justify-center my-8">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div>
        </div>
      )}

      {!loading && activeTab === 'scan' && (
        <div className="space-y-4">
          <p className="text-sm text-slate-600">Envie uma foto da sua nota fiscal para preencher automaticamente os valores de compra, MVA e alíquotas.</p>
          <div className="flex items-center justify-center w-full">
            <label className="flex flex-col items-center justify-center w-full h-32 border-2 border-indigo-300 border-dashed rounded-lg cursor-pointer bg-indigo-50 hover:bg-indigo-100 transition-colors">
              <div className="flex flex-col items-center justify-center pt-5 pb-6">
                <svg className="w-8 h-8 mb-4 text-indigo-500" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 20 16">
                  <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 13h3a3 3 0 0 0 0-6h-.025A5.56 5.56 0 0 0 16 6.5 5.5 5.5 0 0 0 5.207 5.021C5.137 5.017 5.071 5 5 5a4 4 0 0 0 0 8h2.167M10 15V6m0 0L8 8m2-2 2 2"/>
                </svg>
                <p className="text-sm text-indigo-600 font-semibold">Clique para enviar a nota</p>
                <p className="text-xs text-indigo-400">SVG, PNG, JPG (MAX. 800x400px)</p>
              </div>
              <input type="file" className="hidden" accept="image/*" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      )}

      {!loading && activeTab === 'consult' && (
        <div className="space-y-4">
          <p className="text-sm text-slate-600">Tire dúvidas sobre regulamento do ICMS-ST, taxas de MVA ou regras de substituição tributária.</p>
          <div className="flex gap-2">
            <input 
              type="text" 
              value={query} 
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Ex: Qual o MVA para autopeças em SP?"
              className="flex-1 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
            />
            <button 
              onClick={handleSearch}
              className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition-colors"
            >
              Perguntar
            </button>
          </div>

          {searchResult && (
            <div className="mt-4 p-4 bg-white rounded-lg border border-slate-200 text-sm">
              <div className="prose prose-sm text-slate-700 mb-3" dangerouslySetInnerHTML={{ __html: searchResult.text.replace(/\n/g, '<br />') }}></div>
              {searchResult.sources.length > 0 && (
                <div className="border-t border-slate-100 pt-2">
                  <p className="text-xs font-semibold text-slate-500 mb-1">Fontes:</p>
                  <ul className="list-disc pl-4 space-y-1">
                    {searchResult.sources.map((src, i) => (
                      <li key={i}>
                        <a href={src.web?.uri} target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:underline text-xs">
                          {src.web?.title || src.web?.uri}
                        </a>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {!loading && activeTab === 'audio' && (
        <div className="space-y-4 text-center">
          <div className="bg-indigo-900 rounded-lg p-6 text-white flex flex-col items-center">
             <div className="mb-4 bg-indigo-800 p-4 rounded-full">
                {isPlaying ? (
                   <div className="flex gap-1 h-6 items-end">
                      <div className="w-1 bg-white animate-[bounce_1s_infinite] h-3"></div>
                      <div className="w-1 bg-white animate-[bounce_1.2s_infinite] h-5"></div>
                      <div className="w-1 bg-white animate-[bounce_0.8s_infinite] h-4"></div>
                   </div>
                ) : (
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z"></path></svg>
                )}
             </div>
             <h3 className="text-lg font-semibold mb-2">Resumo em Áudio</h3>
             <p className="text-indigo-200 text-sm mb-6">Ouça um resumo do seu cálculo de custo atual e oportunidades de margem.</p>

             <button 
              onClick={handleGenerateAudio}
              disabled={isPlaying}
              className={`px-6 py-3 rounded-full font-bold shadow-lg transition-transform active:scale-95 ${isPlaying ? 'bg-slate-600 cursor-not-allowed opacity-50' : 'bg-white text-indigo-900 hover:bg-indigo-50'}`}
             >
               {isPlaying ? 'Tocando...' : 'Tocar Resumo'}
             </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default GeminiAssistant;

