export const calculateCosts = (inputs: SimulationInputs): SimulationResults => {
  const {
    valorCompra,
    ipiFrete,
    mva,
    icmsInternoDestino,
    icmsInterestadual,
    pisCofinsRate,
    excluirIcmsPis,
    impostosVenda,
  } = inputs;

  // 1. Base Inicial
  const valorTotalNota = valorCompra + ipiFrete;

  // 2. Cálculos de ICMS ST
  const baseCalculoSt = valorTotalNota * (1 + mva / 100);
  const icmsStBruto = baseCalculoSt * (icmsInternoDestino / 100);
  const creditoIcmsEntrada = valorCompra * (icmsInterestadual / 100);

  // ST a Pagar (Débito - Crédito)
  const stAPagar = Math.max(0, icmsStBruto - creditoIcmsEntrada);

  // 3. Cálculo de Crédito PIS/COFINS
  let basePisCofins = valorCompra;
  if (excluirIcmsPis) {
    basePisCofins = valorCompra - creditoIcmsEntrada;
  }

  const creditoPisCofinsValor = basePisCofins * (pisCofinsRate / 100);

  // 4. Custo Final da Mercadoria
  const custoFinal = valorTotalNota + stAPagar - creditoPisCofinsValor;

  // 5. Preço de Equilíbrio (Custo + Impostos de Venda, sem margem)
  // Fórmula: Preço = Custo / (1 - TaxaImpostos)
  const precoEquilibrio = impostosVenda < 100 ? custoFinal / ((100 - impostosVenda) / 100) : 0;

  return {
    valorTotalNota,
    baseCalculoSt,
    icmsStBruto,
    creditoIcmsEntrada,
    stAPagar,
    basePisCofins,
    creditoPisCofinsValor,
    custoFinal,
    precoEquilibrio,
  };
};

export const generatePriceMatrix = (
  custoFinal: number,
  impostosVenda: number
): PriceRow[] => {
  const margensAlvo = [-5.0, 0.0, 5.0, 10.0, 12.0, 15.0, 17.0, 20.0];
  const fatoresAjuste = [0.0, 1.0, 2.0, 3.0, 5.0]; // Comod, A, B, C, Tec

  return margensAlvo.map((margem) => {
    const prices = fatoresAjuste.map((fator) => {
      const totalDeducoes = impostosVenda + margem + fator;
      if (totalDeducoes >= 100) return 0;

      const divisor = (100 - totalDeducoes) / 100;
      return custoFinal / divisor;
    });

    return {
      margem,
      prices: {
        comod: prices[0],
        curvaA: prices[1],
        curvaB: prices[2],
        curvaC: prices[3],
        prodTec: prices[4],
      },
    };
  });
};

