export const generatePriceMatrix = (
  custoFinal: number,
  inputs: SimulationInputs
): PriceRow[] => {
  const baseDeducoes = inputs.pisCofinsVenda + inputs.comissaoVenda + inputs.icmsVenda + inputs.outrosCustosVariaveis + inputs.custosFixos;

  // Matriz de simulação genérica para comparação
  const margensSimulacao = [-5.0, 0.0, 5.0, 8.0, 10.0, 15.0, 20.0];
  const fatoresAjuste = [0.0, 1.0, 2.0, 3.0, 5.0]; // Offsets para Comod, A, B, C, Tec

  return margensSimulacao.map((margem) => {
    const prices = fatoresAjuste.map((fator) => {
      const totalDeducoes = baseDeducoes + margem + fator;
      if (totalDeducoes >= 100) return 0;

      const divisor = (100 - totalDeducoes) / 100;
      return custoFinal / divisor;
    });

    return {
      margem,
      prices: {
        comod: prices[0],
        curvaA: prices[1],
        curvaB: prices[2],
        curvaC: prices[3],
        prodTec: prices[4],
      },
    };
  });
};

export const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(val);
};

export const formatPercent = (val: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'percent',
    minimumFractionDigits: 3,
  }).format(val / 100);
};

