import { SimulationInputs, SimulationResults } from '../types';

export const getInterstateRate = (origem: string, destino: string): number => {
  if (origem === destino) return 0;

  const sulSudeste = ['SP', 'RJ', 'MG', 'ES', 'PR', 'SC', 'RS'];
  const norteNordesteCentroOeste = [
    'AC', 'AL', 'AM', 'AP', 'BA', 'CE', 'DF', 'GO', 'MA', 'MS', 'MT', 'PA', 'PB', 'PE', 'PI', 'RN', 'RO', 'RR', 'SE', 'TO'
  ];

  // Regra básica: 
  // Sul/Sudeste -> Norte/Nordeste/Centro-Oeste = 7%
  // Demais casos = 12%
  if (sulSudeste.includes(origem) && norteNordesteCentroOeste.includes(destino)) {
    return 7;
  }
  return 12;
};

export const calculateAdjustedMva = (mvaOriginal: number, alqInter: number, alqIntra: number): number => {
  if (alqInter === 0) return mvaOriginal;
  // Fórmula: [(1 + MVA-ST original) x (1 - ALQ inter) / (1 - ALQ intra)] - 1
  const mvaOriginalDecimal = mvaOriginal / 100;
  const alqInterDecimal = alqInter / 100;
  const alqIntraDecimal = alqIntra / 100;

  const adjusted = ((1 + mvaOriginalDecimal) * (1 - alqInterDecimal) / (1 - alqIntraDecimal)) - 1;
  return adjusted * 100;
};

export const calculateCosts = (inputs: SimulationInputs): SimulationResults => {
  const {
    valorCompra,
    ipiFrete,
    mva,
    icmsInternoDestino,
    icmsInterestadual,
    pisCofinsRate,
    excluirIcmsPis,
    pisCofinsVenda,
    comissaoVenda,
    icmsVenda,
    outrosCustosVariaveis,
    custosFixos,
    resultadoDesejado,
  } = inputs;

  const valorTotalNota = valorCompra + ipiFrete;
  const baseCalculoSt = valorTotalNota * (1 + mva / 100);
  const icmsStBruto = baseCalculoSt * (icmsInternoDestino / 100);
  const creditoIcmsEntrada = valorCompra * (icmsInterestadual / 100);
  const stAPagar = Math.max(0, icmsStBruto - creditoIcmsEntrada);

  let basePisCofins = valorCompra;
  if (excluirIcmsPis) {
    basePisCofins = valorCompra - creditoIcmsEntrada;
  }
  const creditoPisCofinsValor = basePisCofins * (pisCofinsRate / 100);

  const custoFinal = valorTotalNota + stAPagar - creditoPisCofinsValor;
  const deducoesSemMargem = pisCofinsVenda + comissaoVenda + icmsVenda + outrosCustosVariaveis + custosFixos;

  const precoEquilibrio = deducoesSemMargem < 100 ? custoFinal / ((100 - deducoesSemMargem) / 100) : 0;
  const totalDeducoesVendaPerc = deducoesSemMargem + resultadoDesejado;
  const precoVendaAlvo = totalDeducoesVendaPerc < 100 ? custoFinal / ((100 - totalDeducoesVendaPerc) / 100) : 0;

  return {
    valorTotalNota,
    baseCalculoSt,
    icmsStBruto,
    creditoIcmsEntrada,
    stAPagar,
    basePisCofins,
    creditoPisCofinsValor,
    custoFinal,
    precoEquilibrio,
    precoVendaAlvo,
    totalDeducoesVendaPerc
  };
};

const getPriceForMargin = (custoFinal: number, baseDeducoes: number, margin: number) => {
  const total = baseDeducoes + margin;
  return total < 100 ? custoFinal / ((100 - total) / 100) : 0;
};

export const generatePriceMatrix = (
  custoFinal: number,
  inputs: SimulationInputs
): any => {
  const baseDeducoes = inputs.pisCofinsVenda + inputs.comissaoVenda + inputs.icmsVenda + inputs.outrosCustosVariaveis + inputs.custosFixos;

  const categorias = [
    { label: 'Comod.', margin: 8 },
    { label: 'Curva A', margin: 10 },
    { label: 'Curva B', margin: 11 },
    { label: 'Curva C', margin: 12 },
    { label: 'Prod.Tec', margin: 15 }
  ];

  return categorias.map(cat => {
    const basePrice = getPriceForMargin(custoFinal, baseDeducoes, cat.margin);
    return {
      label: cat.label,
      margin: cat.margin,
      levels: {
        A: basePrice * 0.95,
        B: basePrice,
        C: basePrice * 1.111,
        D: basePrice * 1.1765
      }
    };
  });
};

export const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(val);
};

export const formatPercent = (val: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'percent',
    minimumFractionDigits: 2,
  }).format(val / 100);
};

import React from 'react';
