interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {

  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const updated = { ...inputs, [field]: val };

    // Atualiza alíquotas baseadas na UF
    const origUf = UF_LIST.find(u => u.sigla === (field === 'ufOrigem' ? val : inputs.ufOrigem));
    const destUf = UF_LIST.find(u => u.sigla === (field === 'ufDestino' ? val : inputs.ufDestino));

    if (origUf && destUf) {
      const interRate = getInterstateRate(origUf.sigla, destUf.sigla);
      const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf.icms);

      setInputs({
        ...updated,
        icmsInterestadual: interRate,
        icmsInternoDestino: destUf.icms,
        mva: adjMva
      });
    }
  };

  const handleNcmChange = (ncmCod: string) => {
    const ncm = NCM_DATABASE.find(n => n.codigo === ncmCod);
    if (!ncm) return;

    const interRate = inputs.icmsInterestadual;
    const adjMva = calculateAdjustedMva(ncm.mvaOriginal, interRate, inputs.icmsInternoDestino);

    setInputs(prev => ({
      ...prev,
      ncmCodigo: ncm.codigo,
      mvaOriginal: ncm.mvaOriginal,
      mva: adjMva
    }));
  };

  return (
    <div className="bg-[#1a2332] text-white p-6 rounded-2xl shadow-2xl mb-8 border border-slate-700">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
        <div>
          <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1.5 tracking-wider">UF de Origem</label>
          <select 
            value={inputs.ufOrigem}
            onChange={(e) => handleUfChange('ufOrigem', e.target.value)}
            className="w-full bg-[#0f172a] border border-slate-600 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-500 transition-colors"
          >
            {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.nome} ({uf.sigla})</option>)}
          </select>
        </div>
        <div>
          <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1.5 tracking-wider">UF de Destino</label>
          <select 
            value={inputs.ufDestino}
            onChange={(e) => handleUfChange('ufDestino', e.target.value)}
            className="w-full bg-[#0f172a] border border-slate-600 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-500 transition-colors"
          >
            {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.nome} ({uf.sigla})</option>)}
          </select>
        </div>
      </div>

      <div className="mb-6">
        <label className="block text-[10px] uppercase font-bold text-slate-400 mb-1.5 tracking-wider">Produto (NCM)</label>
        <select 
          value={inputs.ncmCodigo}
          onChange={(e) => handleNcmChange(e.target.value)}
          className="w-full bg-[#0f172a] border border-slate-600 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-500 transition-colors"
        >
          {NCM_DATABASE.map(ncm => (
            <option key={ncm.codigo} value={ncm.codigo}>{ncm.codigo} - {ncm.descricao}</option>
          ))}
        </select>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-4 border-t border-slate-700">
        <div>
          <h4 className="text-xs font-bold text-blue-400 mb-3 uppercase tracking-widest">Alíquotas de ICMS (%)</h4>
          <div className="space-y-1.5">
            <div className="flex justify-between text-[11px]">
              <span className="text-slate-400 italic">Interna ({inputs.ufOrigem}):</span>
              <span className="font-bold">{UF_LIST.find(u => u.sigla === inputs.ufOrigem)?.icms}%</span>
            </div>
            <div className="flex justify-between text-[11px]">
              <span className="text-slate-400 italic">Interna ({inputs.ufDestino}):</span>
              <span className="font-bold">{UF_LIST.find(u => u.sigla === inputs.ufDestino)?.icms}%</span>
            </div>
            <div className="flex justify-between text-[11px]">
              <span className="text-slate-400 italic">Interestadual ({inputs.ufOrigem} → {inputs.ufDestino}):</span>
              <span className="font-bold text-blue-300">{inputs.icmsInterestadual}%</span>
            </div>
          </div>
        </div>

        <div>
          <h4 className="text-xs font-bold text-orange-400 mb-3 uppercase tracking-widest">Margem de Valor Agregado (MVA %)</h4>
          <div className="space-y-1.5">
