import React, { useState, useRef, useEffect } from 'react';
import { SimulationInputs, NCMEntry } from '../types';
import { UF_LIST, NCM_DATABASE } from '../utils/ncmData';
import { getInterstateRate, calculateAdjustedMva } from '../utils/calculations';

interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const suggestionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const currentNcm = NCM_DATABASE.find(n => n.codigo === inputs.ncmCodigo);
    if (currentNcm) {
      setSearchTerm(`${currentNcm.codigo} - ${currentNcm.descricao}`);
    }
  }, []);

  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const newOrigem = field === 'ufOrigem' ? val : inputs.ufOrigem;
    const newDestino = field === 'ufDestino' ? val : inputs.ufDestino;

    const origUf = UF_LIST.find(u => u.sigla === newOrigem);
    const destUf = UF_LIST.find(u => u.sigla === newDestino);

    if (origUf && destUf) {
      const interRate = getInterstateRate(origUf.sigla, destUf.sigla);
      const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf.icms);

      setInputs(prev => ({
        ...prev,
        [field]: val,
        icmsInterestadual: interRate,
        icmsInternoDestino: destUf.icms,
        icmsVenda: prev.mode !== 'substituido' ? destUf.icms : prev.icmsVenda,
        mva: adjMva
      }));
    }
  };

  const selectNcm = (ncm: NCMEntry) => {
    const interRate = inputs.icmsInterestadual;
    const adjMva = calculateAdjustedMva(ncm.mvaOriginal, interRate, inputs.icmsInternoDestino);

    setInputs(prev => ({
      ...prev,
      ncmCodigo: ncm.codigo,
      mvaOriginal: ncm.mvaOriginal,
      mva: adjMva
    }));
    setSearchTerm(`${ncm.codigo} - ${ncm.descricao}`);
    setShowSuggestions(false);
  };

  const filteredNcms = NCM_DATABASE.filter(n => 
    n.codigo.toLowerCase().includes(searchTerm.toLowerCase()) || 
    n.descricao.toLowerCase().includes(searchTerm.toLowerCase())
  );

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const internalRateOrigem = UF_LIST.find(u => u.sigla === inputs.ufOrigem)?.icms || 0;
  const internalRateDestino = UF_LIST.find(u => u.sigla === inputs.ufDestino)?.icms || 0;

  return (
    <div className="bg-[#1a2332] text-white p-4 md:p-6 rounded-2xl shadow-xl border border-slate-700">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 mb-6">
        <div className="group">
          <label className="block text-[9px] md:text-[10px] uppercase font-black text-slate-400 mb-1.5 tracking-wider group-focus-within:text-blue-400 transition-colors">UF de Origem</label>
          <div className="relative">
            <select 
              value={inputs.ufOrigem}
              onChange={(e) => handleUfChange('ufOrigem', e.target.value)}
              className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-blue-500 transition-colors cursor-pointer appearance-none"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.nome} ({uf.sigla})</option>)}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
            </div>
          </div>
          <p className="mt-1 text-[8px] md:text-[9px] text-slate-500 font-bold uppercase tracking-tighter">Alíquota: {internalRateOrigem}%</p>
        </div>
        <div className="group">
          <label className="block text-[9px] md:text-[10px] uppercase font-black text-slate-400 mb-1.5 tracking-wider group-focus-within:text-blue-400 transition-colors">UF de Destino</label>
          <div className="relative">
            <select 
              value={inputs.ufDestino}
              onChange={(e) => handleUfChange('ufDestino', e.target.value)}
              className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-blue-500 transition-colors cursor-pointer appearance-none"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.nome} ({uf.sigla})</option>)}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
            </div>
          </div>
          <p className="mt-1 text-[8px] md:text-[9px] text-slate-500 font-bold uppercase tracking-tighter">Alíquota: {internalRateDestino}%</p>
        </div>
      </div>

      <div className="mb-6 relative" ref={suggestionRef}>
        <label className="block text-[9px] md:text-[10px] uppercase font-black text-slate-400 mb-1.5 tracking-wider">Produto ou NCM 2025</label>
        <div className="relative">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setShowSuggestions(true);
            }}
            onFocus={() => setShowSuggestions(true)}
            placeholder="Pesquisar produto..."
            className="w-full bg-[#0f172a] border border-slate-600 rounded-xl pl-10 pr-4 py-2.5 text-sm outline-none focus:border-blue-500 transition-colors placeholder:text-slate-600"
          />
          <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
          </div>
        </div>

        {showSuggestions && (
          <div className="absolute z-50 w-full mt-1 bg-[#1e293b] border border-slate-600 rounded-xl shadow-2xl max-h-60 overflow-y-auto custom-scrollbar">
            {filteredNcms.length > 0 ? (
              filteredNcms.map((ncm) => (
                <div 
                  key={ncm.codigo}
                  onClick={() => selectNcm(ncm)}
                  className="px-4 py-3 hover:bg-blue-600 cursor-pointer border-b border-slate-700/50 last:border-0 transition-colors group active:bg-blue-700"
                >
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-black text-blue-300 group-hover:text-white">{ncm.codigo}</span>
                    <span className="text-[9px] bg-slate-700 px-2 py-0.5 rounded font-black text-slate-300 group-hover:bg-blue-500">MVA: {ncm.mvaOriginal}%</span>
                  </div>
                  <div className="text-[11px] text-slate-400 group-hover:text-blue-100 mt-1 line-clamp-1">{ncm.descricao}</div>
                </div>
              ))
            ) : (
              <div className="px-4 py-8 text-center text-slate-500 text-[10px] font-bold uppercase tracking-widest italic">
                Nenhum resultado
              </div>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-slate-700/50">
        <div className="space-y-2">
          <h4 className="text-[9px] md:text-[10px] font-black text-blue-400 uppercase tracking-widest">ICMS Interestadual</h4>
          <div className="flex justify-between items-center bg-[#0f172a] p-2 rounded-lg border border-slate-700/50">
            <span className="text-[10px] text-slate-400 font-bold uppercase">{inputs.ufOrigem} → {inputs.ufDestino}</span>
            <span className="text-sm font-black text-blue-300">{inputs.icmsInterestadual}%</span>
          </div>
        </div>

        <div className="space-y-2">
          <h4 className="text-[9px] md:text-[10px] font-black text-orange-400 uppercase tracking-widest">MVA Ajustada (2025)</h4>
          <div className="flex justify-between items-center bg-[#0f172a] p-2 rounded-lg border border-slate-700/50">
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">Cálculo Dinâmico</span>
            <span className="text-sm font-black text-orange-500">{inputs.mva.toFixed(2).replace('.', ',')}%</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FiscalHeader;

import React from 'react';
import { SimulationResults, SimulationInputs } from '../types';
import { formatCurrency } from '../utils/calculations';

interface ResultsTableProps {
  results: SimulationResults;
  priceMatrix: any[];
  inputs: SimulationInputs;
}

const MetricCard: React.FC<{ label: string; value: string; subValue?: string; delta?: string; color?: string }> = ({ label, value, subValue, delta, color = "blue" }) => (
  <div className="bg-white p-4 md:p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-between transition-transform active:scale-[0.98]">
    <p className="text-[10px] md:text-sm text-slate-500 font-black uppercase tracking-widest mb-1">{label}</p>
    <div>
      <h3 className={`text-xl md:text-2xl font-black text-slate-800 tracking-tight`}>{value}</h3>
      {subValue && <p className="text-[9px] md:text-xs text-slate-400 font-bold uppercase mt-1 tracking-tighter">{subValue}</p>}
    </div>
    {delta && (
      <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-lg mt-3 w-fit tracking-widest ${
        color === 'red' ? 'bg-red-50 text-red-600' : 
        color === 'green' ? 'bg-green-50 text-green-600' : 
        'bg-blue-50 text-blue-600'
      }`}>
        {delta}
      </span>
    )}
  </div>
);

const ResultsTable: React.FC<ResultsTableProps> = ({ results, priceMatrix, inputs }) => {
  const pisCofinsValor = results.precoVendaAlvo * (inputs.pisCofinsVenda / 100);
  const comissaoValor = results.precoVendaAlvo * (inputs.comissaoVenda / 100);
  const icmsVendaValor = results.precoVendaAlvo * (results.icmsVendaEfetivo / 100);
  const outrosVariaveisValor = results.precoVendaAlvo * (inputs.outrosCustosVariaveis / 100);
  const custosFixosValor = results.precoVendaAlvo * (inputs.custosFixos / 100);
  const margemValor = results.precoVendaAlvo * (inputs.resultadoDesejado / 100);

  const totalCustoVenda = pisCofinsValor + comissaoValor + icmsVendaValor + outrosVariaveisValor + custosFixosValor + margemValor;

  return (
    <div className="space-y-6 md:space-y-8">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4">
        <MetricCard label="Total NF" value={formatCurrency(results.valorTotalNota)} subValue="Base NF-e" />
        {inputs.mode === 'substituido' ? (
          <MetricCard label="ICMS-ST" value={formatCurrency(results.stAPagar)} delta="Débito ST" color="red" />
        ) : (
          <MetricCard label="Crédito ICMS" value={formatCurrency(results.creditoIcmsEntrada)} delta="Ativo" color="green" />
        )}
        <MetricCard label="Créd. PIS/COF" value={formatCurrency(results.creditoPisCofinsValor)} delta="Ativo" color="green" />
        <MetricCard label="CUSTO LÍQ." value={formatCurrency(results.custoFinal)} delta="Base Venda" color="blue" />
      </div>

      <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
        <div className="bg-slate-300 p-2.5 text-center font-black text-slate-800 uppercase tracking-[0.2em] text-[10px]">
          Composição de Saída
        </div>
        <div className="p-4 md:p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 md:gap-x-10 mb-4">
            {[
              { label: 'PIS / COF (Saída)', val: pisCofinsValor, red: false },
              { label: `ICMS Venda ${inputs.mode === 'reduzido' ? '(Efetivo)' : ''}`, val: icmsVendaValor, red: inputs.mode === 'reduzido' },
              { label: 'Comissão de Venda', val: comissaoValor, red: false },
              { label: 'Custos Fixos Op.', val: custosFixosValor, red: false },
              { label: 'Resultado Líquido Alvo', val: margemValor, red: false, indigo: true },
              { label: 'Total Deduções', val: totalCustoVenda, red: true, bold: true },
            ].map((item, i) => (
              <div key={i} className="flex justify-between items-center border-b border-slate-100 py-2.5">
                <span className={`text-[10px] font-bold uppercase tracking-tight ${item.red && !item.indigo ? 'text-red-500' : item.indigo ? 'text-indigo-600' : 'text-slate-500'}`}>
                  {item.label}
                </span>
                <span className={`font-mono text-xs font-black ${item.red && !item.indigo ? 'text-red-600' : item.indigo ? 'text-indigo-700' : 'text-slate-900'}`}>
                  {formatCurrency(item.val)}
                </span>
              </div>
            ))}
          </div>

          <div className="bg-indigo-600 p-4 text-white flex flex-col sm:flex-row justify-between items-center rounded-2xl shadow-xl shadow-indigo-500/20 gap-2">
            <span className="font-black text-[10px] md:text-sm uppercase tracking-widest text-indigo-200">Preço de Venda Sugerido</span>
            <span className="text-2xl md:text-3xl font-black">{formatCurrency(results.precoVendaAlvo)}</span>
          </div>
        </div>
      </div>

      <div className="space-y-4">
        <div className="flex items-center gap-3">
          <h3 className="text-xs md:text-sm font-black text-slate-800 uppercase tracking-widest">Matriz de Condições 2025</h3>
          <div className="h-px flex-1 bg-slate-200"></div>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3 md:gap-4">
          {priceMatrix.map((cat, idx) => (
            <div key={idx} className="flex flex-col border border-slate-200 rounded-2xl overflow-hidden bg-white shadow-sm hover:shadow-md transition-shadow">
              <div className="bg-slate-100 text-slate-600 text-center py-2 font-black text-[9px] uppercase tracking-tighter border-b border-slate-200">
                {cat.label}
              </div>
              {[
                { l: 'A', bg: 'bg-[#C0504D]', cell: 'bg-[#F2DCDB]' },
                { l: 'B', bg: 'bg-[#EBC11F]', cell: 'bg-[#FFF9E5]' },
                { l: 'C', bg: 'bg-[#00B0F0]', cell: 'bg-[#EBF7FF]' },
                { l: 'D', bg: 'bg-[#92D050]', cell: 'bg-[#F4F9EB]' },
              ].map(row => (
                <div key={row.l} className="flex border-b border-slate-100 last:border-0 group">
                  <div className={`w-8 ${row.bg} flex items-center justify-center font-black text-white text-[10px] border-r border-slate-200/20`}>{row.l}</div>
                  <div className={`flex-1 ${row.cell} py-2.5 px-2 text-right font-black text-slate-800 text-[11px]`}>{formatCurrency(cat.levels[row.l]).replace('R$', '')}</div>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ResultsTable;

import React from 'react';
import { SimulationInputs } from '../types';

interface SidebarProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const Sidebar: React.FC<SidebarProps> = ({ inputs, setInputs }) => {

  const handleModeChange = (mode: SimulationInputs['mode']) => {
    setInputs(prev => ({ ...prev, mode }));
  };

  const handleChange = (field: keyof SimulationInputs, value: any) => {
    setInputs((prev) => ({
      ...prev,
      [field]: typeof value === 'string' ? parseFloat(value) || 0 : value,
    }));
  };

  const productCategories = [
    { label: 'Commodity', value: 8, key: 'comod' },
    { label: 'Curva A', value: 10, key: 'curvaA' },
    { label: 'Curva B', value: 11, key: 'curvaB' },
    { label: 'Curva C', value: 12, key: 'curvaC' },
    { label: 'Prod. Técnicos', value: 15, key: 'prodTec' },
  ];

  const handleCategorySelect = (type: typeof productCategories[0]) => {
    setInputs((prev) => ({
      ...prev,
      tipoProduto: type.key,
      resultadoDesejado: type.value,
    }));
  };

  return (
    <div className="space-y-6 md:space-y-8 pb-10 md:pb-0">
      {/* Seletor de Regime */}
      <div>
        <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
          <span className="h-px w-3 bg-slate-300"></span> 0. Regime Tributável
        </h2>
        <div className="grid grid-cols-1 gap-2">
          {[
            { id: 'substituido', label: 'Substituição Tributária (ST)' },
            { id: 'tributado', label: 'Tributável (Normal)' },
            { id: 'reduzido', label: 'Redução de Base' },
          ].map(item => (
            <button
              key={item.id}
              onClick={() => handleModeChange(item.id as any)}
              className={`px-4 py-3.5 rounded-xl border text-[11px] font-black transition-all text-left active:scale-[0.98] ${
                inputs.mode === item.id
                  ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-500/20'
                  : 'bg-white border-slate-200 text-slate-600 hover:border-blue-300'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      </div>

      <div>
