          <button 
            onClick={() => setMainTab('produtos')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'produtos' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Meus Produtos"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Meus Produtos</span>
            )}
            {mainTab === 'produtos' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>

          <button 
            onClick={() => setMainTab('configuracoes')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'configuracoes' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Catálogo NCM"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Catálogo NCM</span>
            )}
            {mainTab === 'configuracoes' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>
        </nav>

        <div className="p-4 border-t border-slate-800 overflow-hidden">
          <button 
            onClick={() => setIsAuthenticated(false)}
            className="w-full flex items-center gap-3 p-3 rounded-xl text-slate-500 hover:bg-red-500/10 hover:text-red-400 transition-all group"
            title="Sair"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Encerrar Sessão</span>
            )}
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        {renderContent()}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import Login from './components/Login';
import { SimulationInputs, SavedProduct } from './types';
import { calculateCosts, generatePriceMatrix, formatCurrency } from './utils/calculations';

const defaultInputs: SimulationInputs = {
  valorCompra: 100.00,
  ipiFrete: 0.00,
  mva: 32.00,
  mvaOriginal: 20.00,
  icmsInternoDestino: 20.00,
  icmsInterestadual: 12.00,
  ufOrigem: 'SP',
  ufDestino: 'RJ',
  ncmCodigo: '2523.29.10',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.250,
  comissaoVenda: 0.00,
  icmsVenda: 18.00,
  outrosCustosVariaveis: 0.00,
  custosFixos: 20.00,
  resultadoDesejado: 8.00,
  tipoProduto: 'comod',
  mode: 'substituido',
  percReducaoBase: 0
};

type MainTab = 'calculadora' | 'produtos' | 'configuracoes';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [mainTab, setMainTab] = useState<MainTab>('calculadora');
  const [activeCalcTab, setActiveCalcTab] = useState<'config' | 'results'>('config');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // Estado para produtos salvos
  const [savedProducts, setSavedProducts] = useState<SavedProduct[]>([]);
  const [isSavingModalOpen, setIsSavingModalOpen] = useState(false);
  const [newProductName, setNewProductName] = useState('');

  const PRODUCT_LIMIT = 100;

  // Carregar produtos do localStorage ao iniciar
  useEffect(() => {
    const saved = localStorage.getItem('tagway_saved_products');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          setSavedProducts(parsed);
        }
      } catch (e) {
        console.error("Erro ao carregar produtos salvos", e);
      }
    }
  }, []);

  // Salvar produtos no localStorage sempre que o estado mudar
  useEffect(() => {
    localStorage.setItem('tagway_saved_products', JSON.stringify(savedProducts));
  }, [savedProducts]);

  if (!isAuthenticated) {
    return <Login onLoginSuccess={() => setIsAuthenticated(true)} />;
  }

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  const handleSaveProduct = () => {
    if (!newProductName.trim()) return;

    if (savedProducts.length >= PRODUCT_LIMIT) {
      alert(`Limite de ${PRODUCT_LIMIT} produtos atingido! Remova algum item para salvar novos.`);
      return;
    }

    const product: SavedProduct = {
      id: crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(),
      nome: newProductName,
      data: new Date().toLocaleDateString('pt-BR'),
      inputs: { ...inputs },
      results: {
        custoFinal: results.custoFinal,
        precoVendaAlvo: results.precoVendaAlvo
      }
    };

    setSavedProducts(prev => [product, ...prev]);
    setNewProductName('');
    setIsSavingModalOpen(false);
  };

  const deleteSavedProduct = (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); // Evita carregar o produto ao clicar no botão de delete
    if (window.confirm('Deseja realmente excluir este produto permanentemente?')) {
      setSavedProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const loadSavedProduct = (product: SavedProduct) => {
    setInputs({ ...product.inputs });
    setMainTab('calculadora');
    setActiveCalcTab('results');
  };

  const renderContent = () => {
    switch (mainTab) {
      case 'calculadora':
        return (
          <div className="h-full flex flex-col md:flex-row relative">
            <aside className={`
              ${activeCalcTab === 'config' ? 'flex' : 'hidden md:flex'} 
              w-full md:w-80 lg:w-[450px] bg-white border-r border-slate-200 flex-shrink-0 flex-col h-full z-10 shadow-sm
            `}>
              <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-6 space-y-6">
                <div className="mb-4">
                  <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Configuração da Simulação</h2>
                  <FiscalHeader inputs={inputs} setInputs={setInputs} />
                </div>
                <div className="h-px bg-slate-100 w-full my-6"></div>
                <Sidebar inputs={inputs} setInputs={setInputs} />
              </div>
            </aside>

            <main className={`
              ${activeCalcTab === 'results' ? 'flex' : 'hidden md:flex'} 
              flex-1 flex-col overflow-y-auto custom-scrollbar bg-[#f8fafc]
            `}>
              <div className="max-w-6xl mx-auto w-full p-4 md:p-8">
                <div className="md:hidden mb-6 flex justify-between items-center px-2">
                   <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest italic">Resultados</h2>
                   <div className="bg-blue-50 text-blue-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border border-blue-100">
                     Simulação 2025
                   </div>
                </div>
                <ResultsTable 
                  results={results} 
                  priceMatrix={priceMatrix} 
                  inputs={inputs} 
                  onSave={() => setIsSavingModalOpen(true)}
                />
              </div>
            </main>

            {/* Modal de Salvamento */}
            {isSavingModalOpen && (
              <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-fadeIn">
                  <div className="p-6 border-b border-slate-100">
                    <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight italic">Salvar Simulação</h3>
                    <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Defina um nome para identificação</p>
                  </div>
                  <div className="p-6">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Nome do Produto/Serviço</label>
                    <input 
                      autoFocus
                      type="text"
                      value={newProductName}
                      onChange={(e) => setNewProductName(e.target.value)}
                      placeholder="Ex: Piso Porcelanato 60x60..."
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all"
                      onKeyDown={(e) => e.key === 'Enter' && handleSaveProduct()}
                    />
                  </div>
                  <div className="p-6 bg-slate-50 flex gap-3">
                    <button 
                      onClick={() => setIsSavingModalOpen(false)}
                      className="flex-1 px-4 py-3 rounded-xl border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-white transition-colors"
                    >
                      Cancelar
                    </button>
                    <button 
                      onClick={handleSaveProduct}
                      className="flex-1 px-4 py-3 rounded-xl bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-colors"
                    >
                      Confirmar
                    </button>
                  </div>
                </div>
              </div>
            )}

            <div className="md:hidden fixed bottom-0 left-16 right-0 bg-white border-t border-slate-200 flex items-center h-16 z-40 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
              <button 
                onClick={() => setActiveCalcTab('config')}
                className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'config' ? 'text-blue-600' : 'text-slate-400'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Ajustes</span>
              </button>
              <button 
                onClick={() => setActiveCalcTab('results')}
                className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'results' ? 'text-blue-600' : 'text-slate-400'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Resultados</span>
              </button>
            </div>
          </div>
        );
      case 'produtos':
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <div className="mb-10 flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight uppercase italic">Meus Produtos</h2>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Gerencie suas simulações guardadas</p>
                </div>
                <div className="flex flex-col items-end gap-1.5">
                   <div className="bg-white px-4 py-2 rounded-xl border border-slate-200 shadow-sm text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                     <span>Armazenamento:</span>
                     <span className={savedProducts.length >= PRODUCT_LIMIT ? 'text-red-600' : 'text-blue-600'}>
                       {savedProducts.length} / {PRODUCT_LIMIT}
                     </span>
                   </div>
                   <div className="w-32 h-1 bg-slate-200 rounded-full overflow-hidden">
                      <div 
                        className={`h-full transition-all duration-500 ${savedProducts.length >= PRODUCT_LIMIT ? 'bg-red-500' : 'bg-blue-500'}`}
                        style={{ width: `${(savedProducts.length / PRODUCT_LIMIT) * 100}%` }}
                      ></div>
                   </div>
                </div>
              </div>

              {savedProducts.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {savedProducts.map((p) => (
                    <div 
                      key={p.id}
                      onClick={() => loadSavedProduct(p)}
                      className="bg-white border border-slate-200 rounded-3xl p-6 hover:shadow-xl transition-all group flex flex-col h-full relative cursor-pointer active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-4">
                        <div className="bg-blue-50 text-blue-600 p-2 rounded-xl">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
                        </div>
                        <button 
                          onClick={(e) => deleteSavedProduct(p.id, e)}
                          className="text-slate-300 hover:text-red-500 transition-colors p-2 rounded-lg hover:bg-red-50 shadow-sm"
                          title="Excluir Produto"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                        </button>
                      </div>

                      <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight mb-1 line-clamp-1 group-hover:text-blue-600 transition-colors">{p.nome}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-4">Salvo em {p.data} • NCM {p.inputs.ncmCodigo}</p>

                      <div className="grid grid-cols-2 gap-3 mb-6 flex-1">
                        <div className="bg-slate-50 p-3 rounded-2xl">
                          <p className="text-[8px] text-slate-400 font-black uppercase tracking-tighter mb-1">Custo Líq.</p>
                          <p className="text-sm font-black text-slate-800 tracking-tight">{formatCurrency(p.results.custoFinal)}</p>
                        </div>
                        <div className="bg-blue-50 p-3 rounded-2xl">
                          <p className="text-[8px] text-blue-400 font-black uppercase tracking-tighter mb-1">Preço Sugerido</p>
                          <p className="text-sm font-black text-blue-600 tracking-tight">{formatCurrency(p.results.precoVendaAlvo)}</p>
                        </div>
                      </div>

                      <div className="w-full bg-slate-900 text-white text-[10px] font-black uppercase tracking-[0.2em] py-4 rounded-2xl group-hover:bg-blue-600 transition-all flex items-center justify-center gap-2">
                        Abrir Simulação
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="py-32 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100 flex flex-col items-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                    <span className="text-4xl grayscale opacity-30">📦</span>
                  </div>
                  <h2 className="text-xl font-black text-slate-300 uppercase tracking-[0.2em]">Nenhum produto salvo</h2>
                  <p className="text-slate-400 text-[10px] mt-2 uppercase font-bold tracking-widest">Simule um preço na calculadora e clique em "Salvar Produto".</p>
                </div>
              )}
            </div>
          </div>
        );
      case 'configuracoes':
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <ProductsView onSelectNcm={(ncm) => {
                 setInputs(prev => ({
                   ...prev,
                   ncmCodigo: ncm.codigo,
                   mvaOriginal: ncm.mvaOriginal
                 }));
                 setMainTab('calculadora');
                 setActiveCalcTab('config');
              }} />
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="h-screen w-full flex bg-[#f8fafc] overflow-hidden font-sans text-slate-900">
      <aside className={`bg-[#1a2332] flex flex-col border-r border-slate-800 z-50 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'w-16' : 'w-16 md:w-64'}`}>
        <div className="p-4 md:p-6 flex items-center border-b border-slate-800 overflow-hidden whitespace-nowrap relative">
          <div className="flex items-center gap-3 w-full">
            <div className="bg-blue-600 p-2 rounded-xl flex-shrink-0 shadow-lg shadow-blue-500/20">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
            </div>

            {!isSidebarCollapsed && (
              <div className="hidden md:flex items-center justify-between flex-1 animate-fadeIn">
                <h1 className="text-lg font-black text-white tracking-tighter italic uppercase">Tagway</h1>
                <button 
                  onClick={() => setIsSidebarCollapsed(true)}
                  className="ml-2 text-slate-500 hover:text-white transition-colors p-1"
                  title="Minimizar Menu"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 19l-7-7 7-7"></path>
                  </svg>
                </button>
              </div>
            )}

            {isSidebarCollapsed && (
              <button 
                onClick={() => setIsSidebarCollapsed(false)}
                className="hidden md:flex absolute left-[54px] bg-[#1a2332] border border-slate-700 p-1.5 rounded-full text-slate-400 hover:text-white hover:bg-slate-800 shadow-xl transition-all z-10"
                title="Expandir Menu"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 5l7 7-7 7"></path>
                </svg>
              </button>
            )}
          </div>
        </div>

        <nav className="flex-1 p-2 md:p-4 space-y-2 mt-4 overflow-x-hidden">
          <button 
            onClick={() => setMainTab('calculadora')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'calculadora' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Calculadora"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Calculadora</span>
            )}
            {mainTab === 'calculadora' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>

          <button 
            onClick={() => setMainTab('produtos')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'produtos' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Meus Produtos"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Meus Produtos</span>
            )}
            {mainTab === 'produtos' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>

          <button 
            onClick={() => setMainTab('configuracoes')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'configuracoes' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Catálogo NCM"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Catálogo NCM</span>
            )}
            {mainTab === 'configuracoes' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>
        </nav>

        <div className="p-4 border-t border-slate-800 overflow-hidden">
          <button 
            onClick={() => setIsAuthenticated(false)}
            className="w-full flex items-center gap-3 p-3 rounded-xl text-slate-500 hover:bg-red-500/10 hover:text-red-400 transition-all group"
            title="Sair"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Encerrar Sessão</span>
            )}
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        {renderContent()}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import Login from './components/Login';
import { SimulationInputs, SavedProduct } from './types';
import { calculateCosts, generatePriceMatrix, formatCurrency } from './utils/calculations';

const defaultInputs: SimulationInputs = {
  valorCompra: 100.00,
  ipiFrete: 0.00,
  mva: 32.00,
  mvaOriginal: 20.00,
  icmsInternoDestino: 20.00,
  icmsInterestadual: 12.00,
  ufOrigem: 'SP',
  ufDestino: 'RJ',
  ncmCodigo: '2523.29.10',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.250,
  comissaoVenda: 0.00,
  icmsVenda: 18.00,
  outrosCustosVariaveis: 0.00,
  custosFixos: 20.00,
  resultadoDesejado: 8.00,
  tipoProduto: 'comod',
  mode: 'substituido',
  percReducaoBase: 0
};

type MainTab = 'calculadora' | 'produtos' | 'configuracoes';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [mainTab, setMainTab] = useState<MainTab>('calculadora');
  const [activeCalcTab, setActiveCalcTab] = useState<'config' | 'results'>('config');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // Estado para produtos salvos
  const [savedProducts, setSavedProducts] = useState<SavedProduct[]>([]);
  const [isSavingModalOpen, setIsSavingModalOpen] = useState(false);
  const [newProductName, setNewProductName] = useState('');

  const PRODUCT_LIMIT = 100;

  // Carregar produtos do localStorage ao iniciar
  useEffect(() => {
    const saved = localStorage.getItem('tagway_saved_products');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          setSavedProducts(parsed);
        }
      } catch (e) {
        console.error("Erro ao carregar produtos salvos", e);
      }
    }
  }, []);

  // Salvar produtos no localStorage sempre que o estado mudar
  useEffect(() => {
    localStorage.setItem('tagway_saved_products', JSON.stringify(savedProducts));
  }, [savedProducts]);

  if (!isAuthenticated) {
    return <Login onLoginSuccess={() => setIsAuthenticated(true)} />;
  }

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  const handleSaveProduct = () => {
    if (!newProductName.trim()) return;

    if (savedProducts.length >= PRODUCT_LIMIT) {
      alert(`Limite de ${PRODUCT_LIMIT} produtos atingido! Remova algum item para salvar novos.`);
      return;
    }

    const product: SavedProduct = {
      id: Math.random().toString(36).substr(2, 9) + Date.now().toString(36),
      nome: newProductName,
      data: new Date().toLocaleDateString('pt-BR'),
      inputs: { ...inputs },
      results: {
        custoFinal: results.custoFinal,
        precoVendaAlvo: results.precoVendaAlvo
      }
    };

    setSavedProducts(prev => [product, ...prev]);
    setNewProductName('');
    setIsSavingModalOpen(false);
  };

  const deleteSavedProduct = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation(); 

    if (window.confirm('Deseja realmente excluir este produto permanentemente?')) {
      setSavedProducts(prev => {
        const filtered = prev.filter(p => p.id !== id);
        return filtered;
      });
    }
  };

  const loadSavedProduct = (product: SavedProduct) => {
    setInputs({ ...product.inputs });
    setMainTab('calculadora');
    setActiveCalcTab('results');
  };

  const renderContent = () => {
    switch (mainTab) {
      case 'calculadora':
        return (
          <div className="h-full flex flex-col md:flex-row relative">
            <aside className={`
              ${activeCalcTab === 'config' ? 'flex' : 'hidden md:flex'} 
              w-full md:w-80 lg:w-[450px] bg-white border-r border-slate-200 flex-shrink-0 flex-col h-full z-10 shadow-sm
            `}>
              <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-6 space-y-6">
                <div className="mb-4">
                  <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Configuração da Simulação</h2>
                  <FiscalHeader inputs={inputs} setInputs={setInputs} />
                </div>
                <div className="h-px bg-slate-100 w-full my-6"></div>
                <Sidebar inputs={inputs} setInputs={setInputs} />
              </div>
            </aside>

            <main className={`
              ${activeCalcTab === 'results' ? 'flex' : 'hidden md:flex'} 
              flex-1 flex-col overflow-y-auto custom-scrollbar bg-[#f8fafc]
            `}>
              <div className="max-w-6xl mx-auto w-full p-4 md:p-8">
                <div className="md:hidden mb-6 flex justify-between items-center px-2">
                   <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest italic">Resultados</h2>
                   <div className="bg-blue-50 text-blue-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border border-blue-100">
                     Simulação 2025
                   </div>
                </div>
                <ResultsTable 
                  results={results} 
                  priceMatrix={priceMatrix} 
                  inputs={inputs} 
                  onSave={() => setIsSavingModalOpen(true)}
                />
              </div>
            </main>

            {isSavingModalOpen && (
              <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-fadeIn">
                  <div className="p-6 border-b border-slate-100">
                    <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight italic">Salvar Simulação</h3>
                    <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Defina um nome para identificação</p>
                  </div>
                  <div className="p-6">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Nome do Produto/Serviço</label>
                    <input 
                      autoFocus
                      type="text"
                      value={newProductName}
                      onChange={(e) => setNewProductName(e.target.value)}
                      placeholder="Ex: Piso Porcelanato 60x60..."
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all"
                      onKeyDown={(e) => e.key === 'Enter' && handleSaveProduct()}
                    />
                  </div>
                  <div className="p-6 bg-slate-50 flex gap-3">
                    <button 
                      onClick={() => setIsSavingModalOpen(false)}
                      className="flex-1 px-4 py-3 rounded-xl border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-white transition-colors"
                    >
                      Cancelar
                    </button>
                    <button 
                      onClick={handleSaveProduct}
                      className="flex-1 px-4 py-3 rounded-xl bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-colors"
                    >
                      Confirmar
                    </button>
                  </div>
                </div>
              </div>
            )}

            <div className="md:hidden fixed bottom-0 left-16 right-0 bg-white border-t border-slate-200 flex items-center h-16 z-40 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
              <button 
                onClick={() => setActiveCalcTab('config')}
                className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'config' ? 'text-blue-600' : 'text-slate-400'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Ajustes</span>
              </button>
              <button 
                onClick={() => setActiveCalcTab('results')}
                className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'results' ? 'text-blue-600' : 'text-slate-400'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Resultados</span>
              </button>
            </div>
          </div>
        );
      case 'produtos':
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <div className="mb-10 flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight uppercase italic">Meus Produtos</h2>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Gerencie suas simulações guardadas</p>
                </div>
                <div className="flex flex-col items-end gap-1.5 min-w-[150px]">
                   <div className="bg-white px-4 py-2 rounded-xl border border-slate-200 shadow-sm text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                     <span className="text-slate-400">Total de Itens:</span>
                     <span className={savedProducts.length >= PRODUCT_LIMIT ? 'text-red-600' : 'text-blue-600'}>
                       {savedProducts.length} / {PRODUCT_LIMIT}
                     </span>
                   </div>
                   <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden">
                      <div 
                        className={`h-full transition-all duration-700 ${savedProducts.length >= (PRODUCT_LIMIT * 0.9) ? 'bg-red-500' : 'bg-blue-500'}`}
                        style={{ width: `${Math.min((savedProducts.length / PRODUCT_LIMIT) * 100, 100)}%` }}
                      ></div>
                   </div>
                </div>
              </div>

              {savedProducts.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {savedProducts.map((p) => (
                    <div 
                      key={p.id}
                      onClick={() => loadSavedProduct(p)}
                      className="bg-white border border-slate-200 rounded-3xl p-6 hover:shadow-xl hover:-translate-y-1 transition-all group flex flex-col h-full relative cursor-pointer active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-4">
                        <div className="bg-blue-50 text-blue-600 p-2.5 rounded-xl border border-blue-100 shadow-sm">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
                        </div>
                        <button 
                          onClick={(e) => deleteSavedProduct(p.id, e)}
                          className="bg-white text-slate-300 hover:text-red-500 hover:bg-red-50 p-2.5 rounded-xl border border-slate-100 shadow-sm transition-all"
                          title="Excluir"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                        </button>
                      </div>

                      <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight mb-1 line-clamp-1 group-hover:text-blue-600 transition-colors">{p.nome}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-4">Salvo em {p.data} • NCM {p.inputs.ncmCodigo}</p>

                      <div className="grid grid-cols-2 gap-3 mb-6 flex-1">
                        <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
                          <p className="text-[8px] text-slate-400 font-black uppercase tracking-tighter mb-1">Custo Líq.</p>
                          <p className="text-sm font-black text-slate-800 tracking-tight">{formatCurrency(p.results.custoFinal)}</p>
                        </div>
                        <div className="bg-blue-50 p-3 rounded-2xl border border-blue-100">
                          <p className="text-[8px] text-blue-400 font-black uppercase tracking-tighter mb-1">Preço Sugerido</p>
                          <p className="text-sm font-black text-blue-600 tracking-tight">{formatCurrency(p.results.precoVendaAlvo)}</p>
                        </div>
                      </div>

                      <div className="w-full bg-slate-900 text-white text-[10px] font-black uppercase tracking-[0.2em] py-4 rounded-2xl group-hover:bg-blue-600 transition-all shadow-lg flex items-center justify-center gap-2">
                        Ver Simulação Completa
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="py-32 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100 flex flex-col items-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                    <span className="text-4xl grayscale opacity-30">📦</span>
                  </div>
                  <h2 className="text-xl font-black text-slate-300 uppercase tracking-[0.2em]">Nenhum produto salvo</h2>
                  <p className="text-slate-400 text-[10px] mt-2 uppercase font-bold tracking-widest">Simule um preço na calculadora e clique em "Salvar Produto".</p>
                </div>
              )}
            </div>
          </div>
        );
      case 'configuracoes':
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <ProductsView onSelectNcm={(ncm) => {
                 setInputs(prev => ({
                   ...prev,
                   ncmCodigo: ncm.codigo,
                   mvaOriginal: ncm.mvaOriginal
                 }));
                 setMainTab('calculadora');
                 setActiveCalcTab('config');
              }} />
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="h-screen w-full flex bg-[#f8fafc] overflow-hidden font-sans text-slate-900">
      <aside className={`bg-[#1a2332] flex flex-col border-r border-slate-800 z-50 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'w-16' : 'w-16 md:w-64'}`}>
        <div className="p-4 md:p-6 flex items-center border-b border-slate-800 overflow-hidden whitespace-nowrap relative">
          <div className="flex items-center gap-3 w-full">
            <div className="bg-blue-600 p-2 rounded-xl flex-shrink-0 shadow-lg shadow-blue-500/20">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
            </div>

            {!isSidebarCollapsed && (
              <div className="hidden md:flex items-center justify-between flex-1 animate-fadeIn">
                <h1 className="text-lg font-black text-white tracking-tighter italic uppercase">Tagway</h1>
                <button 
                  onClick={() => setIsSidebarCollapsed(true)}
                  className="ml-2 text-slate-500 hover:text-white transition-colors p-1"
                  title="Minimizar Menu"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 19l-7-7 7-7"></path>
                  </svg>
                </button>
              </div>
            )}

            {isSidebarCollapsed && (
              <button 
                onClick={() => setIsSidebarCollapsed(false)}
                className="hidden md:flex absolute left-[54px] bg-[#1a2332] border border-slate-700 p-1.5 rounded-full text-slate-400 hover:text-white hover:bg-slate-800 shadow-xl transition-all z-10"
                title="Expandir Menu"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 5l7 7-7 7"></path>
                </svg>
              </button>
            )}
          </div>
        </div>

        <nav className="flex-1 p-2 md:p-4 space-y-2 mt-4 overflow-x-hidden">
          <button 
            onClick={() => setMainTab('calculadora')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'calculadora' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Calculadora"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Calculadora</span>
            )}
            {mainTab === 'calculadora' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>

          <button 
            onClick={() => setMainTab('produtos')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'produtos' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Meus Produtos"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Meus Produtos</span>
            )}
            {mainTab === 'produtos' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>

          <button 
            onClick={() => setMainTab('configuracoes')}
            className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${
              mainTab === 'configuracoes' 
                ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' 
                : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
            }`}
            title="Catálogo NCM"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Catálogo NCM</span>
            )}
            {mainTab === 'configuracoes' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>
        </nav>

        <div className="p-4 border-t border-slate-800 overflow-hidden">
          <button 
            onClick={() => setIsAuthenticated(false)}
            className="w-full flex items-center gap-3 p-3 rounded-xl text-slate-500 hover:bg-red-500/10 hover:text-red-400 transition-all group"
            title="Sair"
          >
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
            {!isSidebarCollapsed && (
              <span className="hidden md:block text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Encerrar Sessão</span>
            )}
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        {renderContent()}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import Login from './components/Login';
import { SimulationInputs, SavedProduct } from './types';
import { calculateCosts, generatePriceMatrix, formatCurrency } from './utils/calculations';

const defaultInputs: SimulationInputs = {
  valorCompra: 100.00,
  ipiFrete: 0.00,
  mva: 32.00,
  mvaOriginal: 20.00,
  icmsInternoDestino: 20.00,
  icmsInterestadual: 12.00,
  ufOrigem: 'SP',
  ufDestino: 'RJ',
  ncmCodigo: '2523.29.10',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.250,
  comissaoVenda: 0.00,
  icmsVenda: 18.00,
  outrosCustosVariaveis: 0.00,
  custosFixos: 20.00,
  resultadoDesejado: 8.00,
  tipoProduto: 'comod',
  mode: 'substituido',
  percReducaoBase: 0
};

type MainTab = 'calculadora' | 'produtos' | 'configuracoes';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [mainTab, setMainTab] = useState<MainTab>('calculadora');
  const [activeCalcTab, setActiveCalcTab] = useState<'config' | 'results'>('config');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  const [savedProducts, setSavedProducts] = useState<SavedProduct[]>([]);
  const [isSavingModalOpen, setIsSavingModalOpen] = useState(false);
  const [newProductName, setNewProductName] = useState('');

  const PRODUCT_LIMIT = 100;

  // Carregamento inicial do Storage
  useEffect(() => {
    const saved = localStorage.getItem('tagway_saved_products');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) setSavedProducts(parsed);
      } catch (e) {
        console.error("Erro ao carregar dados", e);
      }
    }
  }, []);

  // Persistência automática no Storage
  useEffect(() => {
    localStorage.setItem('tagway_saved_products', JSON.stringify(savedProducts));
  }, [savedProducts]);

  if (!isAuthenticated) {
    return <Login onLoginSuccess={() => setIsAuthenticated(true)} />;
  }

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  const handleSaveProduct = () => {
    if (!newProductName.trim()) return;

    if (savedProducts.length >= PRODUCT_LIMIT) {
      alert(`Ops! Você atingiu o limite de ${PRODUCT_LIMIT} itens. Remova algum produto para liberar espaço.`);
      return;
    }

    const product: SavedProduct = {
      id: Math.random().toString(36).substring(2, 11) + Date.now().toString(36),
      nome: newProductName.trim(),
      data: new Date().toLocaleDateString('pt-BR'),
      inputs: { ...inputs },
      results: {
        custoFinal: results.custoFinal,
        precoVendaAlvo: results.precoVendaAlvo
      }
    };

    setSavedProducts(prev => [product, ...prev]);
    setNewProductName('');
    setIsSavingModalOpen(false);
  };

  const deleteSavedProduct = (id: string, e: React.MouseEvent) => {
    // ESSENCIAL: Interromper propagação para não disparar o onClick do card
    e.stopPropagation();
    e.preventDefault();

    if (window.confirm('Excluir este produto permanentemente?')) {
      setSavedProducts(prev => {
        const newState = prev.filter(p => p.id !== id);
        return [...newState]; // Garantir nova referência de array
      });
    }
  };

  const loadSavedProduct = (product: SavedProduct) => {
    setInputs({ ...product.inputs });
    setMainTab('calculadora');
    setActiveCalcTab('results');
  };

  const renderContent = () => {
    switch (mainTab) {
      case 'calculadora':
        return (
          <div className="h-full flex flex-col md:flex-row relative">
            <aside className={`${activeCalcTab === 'config' ? 'flex' : 'hidden md:flex'} w-full md:w-80 lg:w-[450px] bg-white border-r border-slate-200 flex-shrink-0 flex-col h-full z-10 shadow-sm`}>
              <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-6 space-y-6">
                <div className="mb-4">
                  <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Configuração da Simulação</h2>
                  <FiscalHeader inputs={inputs} setInputs={setInputs} />
                </div>
                <div className="h-px bg-slate-100 w-full my-6"></div>
                <Sidebar inputs={inputs} setInputs={setInputs} />
              </div>
            </aside>

            <main className={`${activeCalcTab === 'results' ? 'flex' : 'hidden md:flex'} flex-1 flex-col overflow-y-auto custom-scrollbar bg-[#f8fafc]`}>
              <div className="max-w-6xl mx-auto w-full p-4 md:p-8">
                <div className="md:hidden mb-6 flex justify-between items-center px-2">
                   <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest italic">Resultados</h2>
                   <div className="bg-blue-50 text-blue-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border border-blue-100">Simulação 2025</div>
                </div>
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} onSave={() => setIsSavingModalOpen(true)} />
              </div>
            </main>

            {isSavingModalOpen && (
              <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-fadeIn">
                  <div className="p-6 border-b border-slate-100">
                    <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight italic">Salvar Simulação</h3>
                    <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Identifique este cálculo no seu painel</p>
                  </div>
                  <div className="p-6">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Nome do Produto</label>
                    <input autoFocus type="text" value={newProductName} onChange={(e) => setNewProductName(e.target.value)} placeholder="Ex: Porcelanato Eliane 60x60..." className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all" onKeyDown={(e) => e.key === 'Enter' && handleSaveProduct()} />
                  </div>
                  <div className="p-6 bg-slate-50 flex gap-3">
                    <button onClick={() => setIsSavingModalOpen(false)} className="flex-1 px-4 py-3 rounded-xl border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-white transition-colors">Cancelar</button>
                    <button onClick={handleSaveProduct} className="flex-1 px-4 py-3 rounded-xl bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-colors">Confirmar</button>
                  </div>
                </div>
              </div>
            )}

            <div className="md:hidden fixed bottom-0 left-16 right-0 bg-white border-t border-slate-200 flex items-center h-16 z-40 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
              <button onClick={() => setActiveCalcTab('config')} className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'config' ? 'text-blue-600' : 'text-slate-400'}`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Ajustes</span>
              </button>
              <button onClick={() => setActiveCalcTab('results')} className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'results' ? 'text-blue-600' : 'text-slate-400'}`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Resultados</span>
              </button>
            </div>
          </div>
        );
      case 'produtos':
        const storageUsagePerc = Math.min((savedProducts.length / PRODUCT_LIMIT) * 100, 100);
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <div className="mb-10 flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight uppercase italic">Meus Produtos</h2>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Gerencie suas simulações guardadas</p>
                </div>

                {/* Contador de Armazenamento */}
                <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm min-w-[200px]">
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Armazenamento</span>
                    <span className={`text-[11px] font-black ${savedProducts.length >= PRODUCT_LIMIT ? 'text-red-500' : 'text-blue-600'}`}>
                      {savedProducts.length} / {PRODUCT_LIMIT}
                    </span>
                  </div>
                  <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                    <div 
                      className={`h-full transition-all duration-1000 ${savedProducts.length >= (PRODUCT_LIMIT * 0.9) ? 'bg-red-500' : 'bg-blue-500'}`}
                      style={{ width: `${storageUsagePerc}%` }}
                    />
                  </div>
                </div>
              </div>

              {savedProducts.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 pb-20">
                  {savedProducts.map((p) => (
                    <div 
                      key={p.id}
                      onClick={() => loadSavedProduct(p)}
                      className="bg-white border border-slate-200 rounded-3xl p-6 hover:shadow-xl hover:-translate-y-1 transition-all group flex flex-col h-full relative cursor-pointer active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-4">
                        <div className="bg-blue-50 text-blue-600 p-2.5 rounded-xl border border-blue-100">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
                        </div>
                        <button 
                          onClick={(e) => deleteSavedProduct(p.id, e)}
                          className="text-slate-300 hover:text-red-500 hover:bg-red-50 p-2.5 rounded-xl border border-slate-100 transition-all z-20"
                          title="Remover permanentemente"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                        </button>
                      </div>

                      <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight mb-1 line-clamp-1 group-hover:text-blue-600 transition-colors">{p.nome}</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-4">Criado em {p.data} • NCM {p.inputs.ncmCodigo}</p>

                      <div className="grid grid-cols-2 gap-3 mb-6 flex-1">
                        <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
                          <p className="text-[8px] text-slate-400 font-black uppercase tracking-tighter mb-1">Custo Líq.</p>
                          <p className="text-sm font-black text-slate-800 tracking-tight">{formatCurrency(p.results.custoFinal)}</p>
                        </div>
                        <div className="bg-blue-50 p-3 rounded-2xl border border-blue-100">
                          <p className="text-[8px] text-blue-400 font-black uppercase tracking-tighter mb-1">Sugestão</p>
                          <p className="text-sm font-black text-blue-600 tracking-tight">{formatCurrency(p.results.precoVendaAlvo)}</p>
                        </div>
                      </div>

                      <div className="w-full bg-slate-900 text-white text-[10px] font-black uppercase tracking-[0.2em] py-4 rounded-2xl group-hover:bg-blue-600 transition-all flex items-center justify-center gap-2">
                        Abrir Simulação
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="py-32 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100 flex flex-col items-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                    <span className="text-4xl grayscale opacity-30">📦</span>
                  </div>
                  <h2 className="text-xl font-black text-slate-300 uppercase tracking-[0.2em]">Cofre Vazio</h2>
                  <p className="text-slate-400 text-[10px] mt-2 uppercase font-bold tracking-widest">Suas simulações salvas aparecerão aqui.</p>
                </div>
              )}
            </div>
          </div>
        );
      case 'configuracoes':
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <ProductsView onSelectNcm={(ncm) => {
                 setInputs(prev => ({
                   ...prev,
                   ncmCodigo: ncm.codigo,
                   mvaOriginal: ncm.mvaOriginal
                 }));
                 setMainTab('calculadora');
                 setActiveCalcTab('config');
              }} />
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="h-screen w-full flex bg-[#f8fafc] overflow-hidden font-sans text-slate-900">
      <aside className={`bg-[#1a2332] flex flex-col border-r border-slate-800 z-50 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'w-16' : 'w-16 md:w-64'}`}>
        <div className="p-4 md:p-6 flex items-center border-b border-slate-800 overflow-hidden whitespace-nowrap relative">
          <div className="flex items-center gap-3 w-full">
            <div className="bg-blue-600 p-2 rounded-xl flex-shrink-0 shadow-lg shadow-blue-500/20">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
            </div>
            {!isSidebarCollapsed && (
              <div className="hidden md:flex items-center justify-between flex-1 animate-fadeIn">
                <h1 className="text-lg font-black text-white tracking-tighter italic uppercase">Tagway</h1>
                <button onClick={() => setIsSidebarCollapsed(true)} className="ml-2 text-slate-500 hover:text-white transition-colors p-1" title="Minimizar Menu">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 19l-7-7 7-7"></path></svg>
                </button>
              </div>
            )}
            {isSidebarCollapsed && (
              <button onClick={() => setIsSidebarCollapsed(false)} className="hidden md:flex absolute left-[54px] bg-[#1a2332] border border-slate-700 p-1.5 rounded-full text-slate-400 hover:text-white hover:bg-slate-800 shadow-xl transition-all z-10" title="Expandir Menu">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 5l7 7-7 7"></path></svg>
              </button>
