            {!isSidebarCollapsed && <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Calculadora</span>}
            {mainTab === 'calculadora' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>

          <button onClick={() => setMainTab('produtos')} className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${mainTab === 'produtos' ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`} title="Meus Produtos">
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
            {!isSidebarCollapsed && <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Meus Produtos</span>}
            {mainTab === 'produtos' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>

          <button onClick={() => setMainTab('configuracoes')} className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all group relative ${mainTab === 'configuracoes' ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/10' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`} title="Catálogo NCM">
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
            {!isSidebarCollapsed && <span className="hidden md:block text-xs font-black uppercase tracking-widest whitespace-nowrap opacity-100">Catálogo NCM</span>}
            {mainTab === 'configuracoes' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-6 bg-white rounded-l-full"></div>}
          </button>
        </nav>

        <div className="p-4 border-t border-slate-800 overflow-hidden">
          <button onClick={() => setIsAuthenticated(false)} className="w-full flex items-center gap-3 p-3 rounded-xl text-slate-500 hover:bg-red-500/10 hover:text-red-400 transition-all group" title="Sair">
            <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg>
            {!isSidebarCollapsed && <span className="hidden md:block text-[10px] font-black uppercase tracking-widest whitespace-nowrap">Sair do Sistema</span>}
          </button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col overflow-hidden relative">
        {renderContent()}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import Login from './components/Login';
import { SimulationInputs, SavedProduct } from './types';
import { calculateCosts, generatePriceMatrix, formatCurrency } from './utils/calculations';

const defaultInputs: SimulationInputs = {
  valorCompra: 100.00,
  ipiFrete: 0.00,
  mva: 32.00,
  mvaOriginal: 20.00,
  icmsInternoDestino: 20.00,
  icmsInterestadual: 12.00,
  ufOrigem: 'SP',
  ufDestino: 'RJ',
  ncmCodigo: '2523.29.10',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.250,
  comissaoVenda: 0.00,
  icmsVenda: 18.00,
  outrosCustosVariaveis: 0.00,
  custosFixos: 20.00,
  resultadoDesejado: 8.00,
  tipoProduto: 'comod',
  mode: 'substituido',
  percReducaoBase: 0
};

type MainTab = 'calculadora' | 'produtos' | 'configuracoes';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [mainTab, setMainTab] = useState<MainTab>('calculadora');
  const [activeCalcTab, setActiveCalcTab] = useState<'config' | 'results'>('config');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  const [savedProducts, setSavedProducts] = useState<SavedProduct[]>([]);
  const [isSavingModalOpen, setIsSavingModalOpen] = useState(false);
  const [newProductName, setNewProductName] = useState('');
  const [productSearchTerm, setProductSearchTerm] = useState('');

  const PRODUCT_LIMIT = 100;

  // Carregamento inicial do Storage
  useEffect(() => {
    const saved = localStorage.getItem('tagway_saved_products');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) setSavedProducts(parsed);
      } catch (e) {
        console.error("Erro ao carregar dados", e);
      }
    }
  }, []);

  // Persistência automática no Storage
  useEffect(() => {
    localStorage.setItem('tagway_saved_products', JSON.stringify(savedProducts));
  }, [savedProducts]);

  // Filtragem para melhor gerenciamento
  const filteredSavedProducts = useMemo(() => {
    if (!productSearchTerm.trim()) return savedProducts;
    return savedProducts.filter(p => 
      p.nome.toLowerCase().includes(productSearchTerm.toLowerCase()) ||
      p.inputs.ncmCodigo.includes(productSearchTerm)
    );
  }, [savedProducts, productSearchTerm]);

  if (!isAuthenticated) {
    return <Login onLoginSuccess={() => setIsAuthenticated(true)} />;
  }

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  const handleSaveProduct = () => {
    if (!newProductName.trim()) return;

    if (savedProducts.length >= PRODUCT_LIMIT) {
      alert(`Limite de ${PRODUCT_LIMIT} simulações atingido. Exclua itens antigos para liberar espaço no cofre.`);
      return;
    }

    const product: SavedProduct = {
      id: 'prod_' + Math.random().toString(36).substring(2, 11) + '_' + Date.now(),
      nome: newProductName.trim(),
      data: new Date().toLocaleDateString('pt-BR'),
      inputs: { ...inputs },
      results: {
        custoFinal: results.custoFinal,
        precoVendaAlvo: results.precoVendaAlvo
      }
    };

    setSavedProducts(prev => [product, ...prev]);
    setNewProductName('');
    setIsSavingModalOpen(false);
  };

  const deleteSavedProduct = (id: string, e: React.MouseEvent) => {
    // REFORÇO ABSOLUTO: Impedir que o clique se propague para o card pai
    e.stopPropagation();
    if (e.nativeEvent.stopImmediatePropagation) {
      e.nativeEvent.stopImmediatePropagation();
    }
    e.preventDefault();

    if (window.confirm('Deseja remover este produto permanentemente? Esta ação liberará espaço no seu limite de 100 itens.')) {
      setSavedProducts(prev => {
        const newList = prev.filter(p => p.id !== id);
        // Sincronização manual imediata para garantir persistência
        localStorage.setItem('tagway_saved_products', JSON.stringify(newList));
        return [...newList];
      });
    }
  };

  const loadSavedProduct = (product: SavedProduct) => {
    setInputs({ ...product.inputs });
    setMainTab('calculadora');
    setActiveCalcTab('results');
  };

  const renderContent = () => {
    switch (mainTab) {
      case 'calculadora':
        return (
          <div className="h-full flex flex-col md:flex-row relative">
            <aside className={`${activeCalcTab === 'config' ? 'flex' : 'hidden md:flex'} w-full md:w-80 lg:w-[450px] bg-white border-r border-slate-200 flex-shrink-0 flex-col h-full z-10 shadow-sm`}>
              <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-6 space-y-6">
                <div className="mb-4">
                  <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Configuração da Simulação</h2>
                  <FiscalHeader inputs={inputs} setInputs={setInputs} />
                </div>
                <div className="h-px bg-slate-100 w-full my-6"></div>
                <Sidebar inputs={inputs} setInputs={setInputs} />
              </div>
            </aside>

            <main className={`${activeCalcTab === 'results' ? 'flex' : 'hidden md:flex'} flex-1 flex-col overflow-y-auto custom-scrollbar bg-[#f8fafc]`}>
              <div className="max-w-6xl mx-auto w-full p-4 md:p-8">
                <div className="md:hidden mb-6 flex justify-between items-center px-2">
                   <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest italic">Resultados</h2>
                   <div className="bg-blue-50 text-blue-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter border border-blue-100">Simulação 2025</div>
                </div>
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} onSave={() => setIsSavingModalOpen(true)} />
              </div>
            </main>

            {isSavingModalOpen && (
              <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-fadeIn">
                  <div className="p-6 border-b border-slate-100">
                    <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight italic">Salvar Simulação</h3>
                    <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Identifique este cálculo no seu painel</p>
                  </div>
                  <div className="p-6">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Nome do Produto</label>
                    <input autoFocus type="text" value={newProductName} onChange={(e) => setNewProductName(e.target.value)} placeholder="Ex: Porcelanato Eliane 60x60..." className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all" onKeyDown={(e) => e.key === 'Enter' && handleSaveProduct()} />
                  </div>
                  <div className="p-6 bg-slate-50 flex gap-3">
                    <button onClick={() => setIsSavingModalOpen(false)} className="flex-1 px-4 py-3 rounded-xl border border-slate-200 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:bg-white transition-colors">Cancelar</button>
                    <button onClick={handleSaveProduct} className="flex-1 px-4 py-3 rounded-xl bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-colors">Confirmar</button>
                  </div>
                </div>
              </div>
            )}

            <div className="md:hidden fixed bottom-0 left-16 right-0 bg-white border-t border-slate-200 flex items-center h-16 z-40 shadow-[0_-4px_10px_rgba(0,0,0,0.05)]">
              <button onClick={() => setActiveCalcTab('config')} className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'config' ? 'text-blue-600' : 'text-slate-400'}`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Ajustes</span>
              </button>
              <button onClick={() => setActiveCalcTab('results')} className={`flex-1 flex flex-col items-center justify-center gap-1 h-full transition-colors ${activeCalcTab === 'results' ? 'text-blue-600' : 'text-slate-400'}`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path></svg>
                <span className="text-[10px] font-bold uppercase tracking-tighter">Resultados</span>
              </button>
            </div>
          </div>
        );
      case 'produtos':
        const storageUsagePerc = (savedProducts.length / PRODUCT_LIMIT) * 100;
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <div className="mb-10 flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight uppercase italic">Meu Cofre de Produtos</h2>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Gerencie suas simulações salvas (Máximo 100)</p>
                </div>

                <div className="flex flex-col sm:flex-row items-center gap-4 w-full lg:w-auto">
                  {/* Contador de Armazenamento Dinâmico */}
                  <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex-1 min-w-[220px] w-full lg:w-64">
                    <div className="flex justify-between items-center mb-2">
