                    />
                    <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                  </div>
                </div>
              </div>

              {filteredSavedProducts.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 pb-20">
                  {filteredSavedProducts.map((p) => (
                    <div 
                      key={p.id}
                      onClick={() => loadSavedProduct(p)}
                      className="bg-white border border-slate-200 rounded-[32px] p-6 hover:shadow-xl hover:-translate-y-1 transition-all group flex flex-col h-full relative cursor-pointer active:scale-[0.98] overflow-hidden"
                    >
                      <div className="flex justify-between items-start mb-4 relative z-10">
                        <div className="bg-blue-50 text-blue-600 p-2.5 rounded-xl border border-blue-100">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path></svg>
                        </div>

                        {/* Botão de Excluir - REFORÇADO PARA FUNCIONAR AUTOMATICAMENTE */}
                        <button 
                          type="button"
                          onClick={(e) => deleteSavedProduct(p.id, e)}
                          className="bg-white text-slate-300 hover:text-red-500 hover:bg-red-50 p-2.5 rounded-xl border border-slate-100 transition-all relative z-[100] shadow-sm active:scale-90"
                          title="Apagar permanentemente"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
                        </button>
                      </div>

                      <div className="relative z-10">
                        <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight mb-1 line-clamp-1 group-hover:text-blue-600 transition-colors">{p.nome}</h3>
                        <div className="flex items-center gap-2 mb-4">
