                          <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
                          <span className="text-[10px] text-blue-500 font-black uppercase tracking-widest">NCM {p.inputs.ncmCodigo}</span>
                        </div>

                        <div className="grid grid-cols-2 gap-3 mb-6">
                          <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
                            <p className="text-[8px] text-slate-400 font-black uppercase tracking-tighter mb-1">Custo Líq.</p>
                            <p className="text-sm font-black text-slate-800 tracking-tight">{formatCurrency(p.results.custoFinal)}</p>
                          </div>
                          <div className="bg-blue-50 p-3 rounded-2xl border border-blue-100">
                            <p className="text-[8px] text-blue-400 font-black uppercase tracking-tighter mb-1">Sugestão</p>
                            <p className="text-sm font-black text-blue-600 tracking-tight">{formatCurrency(p.results.precoVendaAlvo)}</p>
                          </div>
                        </div>

                        <div className="w-full bg-slate-900 text-white text-[10px] font-black uppercase tracking-[0.2em] py-4 rounded-2xl group-hover:bg-blue-600 transition-all flex items-center justify-center gap-2 shadow-lg">
                          Ver Simulação
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8l4 4m0 0l-4 4m4-4H3"></path></svg>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="py-32 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100 flex flex-col items-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                    <span className="text-4xl grayscale opacity-30">📦</span>
                  </div>
                  <h2 className="text-xl font-black text-slate-300 uppercase tracking-[0.2em]">Cofre Vazio</h2>
                  <p className="text-slate-400 text-[10px] mt-2 uppercase font-bold tracking-widest">
                    {productSearchTerm ? 'Nada encontrado para sua busca.' : 'Suas simulações salvas aparecerão aqui.'}
                  </p>
                </div>
              )}
            </div>
          </div>
        );
      case 'configuracoes':
        return (
          <div className="h-full overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-10">
            <div className="max-w-7xl mx-auto">
              <ProductsView onSelectNcm={(ncm) => {
                 setInputs(prev => ({
                   ...prev,
                   ncmCodigo: ncm.codigo,
                   mvaOriginal: ncm.mvaOriginal
                 }));
                 setMainTab('calculadora');
                 setActiveCalcTab('config');
              }} />
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="h-screen w-full flex bg-[#f8fafc] overflow-hidden font-sans text-slate-900">
      <aside className={`bg-[#1a2332] flex flex-col border-r border-slate-800 z-50 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'w-16' : 'w-16 md:w-64'}`}>
