            {!isSidebarCollapsed && (
              <div className="hidden md:flex items-center justify-between flex-1 animate-fadeIn">
                <h1 className="text-lg font-black text-white tracking-tighter italic uppercase">Tagway</h1>
                <button onClick={() => setIsSidebarCollapsed(true)} className="ml-2 text-slate-500 hover:text-white transition-colors p-1" title="Minimizar Menu">
