import React, { useState, useRef, useEffect } from 'react';
import { SimulationInputs, NCMEntry } from '../types.ts';
import { UF_LIST, NCM_DATABASE } from '../utils/ncmData.ts';
import { getInterstateRate, calculateAdjustedMva } from '../utils/calculations.ts';

interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const suggestionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const currentNcm = NCM_DATABASE.find(n => n.codigo === inputs.ncmCodigo);
    if (currentNcm) {
      setSearchTerm(`${currentNcm.codigo} - ${currentNcm.descricao}`);
    }
  }, []);

  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const newOrigem = field === 'ufOrigem' ? val : inputs.ufOrigem;
    const newDestino = field === 'ufDestino' ? val : inputs.ufDestino;
    const destUf = UF_LIST.find(u => u.sigla === newDestino);

    if (destUf) {
      const interRate = getInterstateRate(newOrigem, newDestino);
      const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf.icms);

      setInputs(prev => ({
        ...prev,
        [field]: val,
        icmsInterestadual: interRate,
        icmsInternoDestino: destUf.icms,
        mva: adjMva
      }));
    }
  };

  const selectNcm = (ncm: NCMEntry) => {
    const adjMva = calculateAdjustedMva(ncm.mvaOriginal, inputs.icmsInterestadual, inputs.icmsInternoDestino);
    setInputs(prev => ({
      ...prev,
      ncmCodigo: ncm.codigo,
      mvaOriginal: ncm.mvaOriginal,
      mva: adjMva
    }));
    setSearchTerm(`${ncm.codigo} - ${ncm.descricao}`);
    setShowSuggestions(false);
  };

  return (
    <div className="bg-[#1a2332] text-white p-6 rounded-2xl shadow-xl border border-slate-700">
      <div className="grid grid-cols-2 gap-4 mb-6">
        <div>
          <label className="block text-[9px] uppercase font-black text-slate-400 mb-1">Origem</label>
          <select value={inputs.ufOrigem} onChange={(e) => handleUfChange('ufOrigem', e.target.value)} className="w-full bg-[#0f172a] border border-slate-600 rounded-xl p-2.5 text-sm outline-none">
            {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-[9px] uppercase font-black text-slate-400 mb-1">Destino</label>
          <select value={inputs.ufDestino} onChange={(e) => handleUfChange('ufDestino', e.target.value)} className="w-full bg-[#0f172a] border border-slate-600 rounded-xl p-2.5 text-sm outline-none">
            {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla}</option>)}
          </select>
        </div>
      </div>

      <div className="relative" ref={suggestionRef}>
        <label className="block text-[9px] uppercase font-black text-slate-400 mb-1">Produto / NCM 2025</label>
        <input 
          type="text" 
          value={searchTerm} 
          onFocus={() => setShowSuggestions(true)}
          onChange={(e) => { setSearchTerm(e.target.value); setShowSuggestions(true); }}
          className="w-full bg-[#0f172a] border border-slate-600 rounded-xl p-2.5 text-sm outline-none focus:border-blue-500"
        />
        {showSuggestions && (
          <div className="absolute z-50 w-full mt-1 bg-[#1e293b] border border-slate-600 rounded-xl shadow-2xl max-h-40 overflow-y-auto">
            {NCM_DATABASE.filter(n => n.codigo.includes(searchTerm) || n.descricao.toLowerCase().includes(searchTerm.toLowerCase())).map(n => (
              <div key={n.codigo} onClick={() => selectNcm(n)} className="p-3 hover:bg-blue-600 cursor-pointer text-xs border-b border-slate-700 last:border-0">
                <span className="font-black text-blue-300">{n.codigo}</span> - {n.descricao}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default FiscalHeader;

