    <div className="space-y-6 md:space-y-8 pb-20">
      <div className="hidden md:grid grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard label="Total NF" value={formatCurrency(results.valorTotalNota)} subValue="Base NF-e" />
