import React, { useState, useRef, useEffect } from 'react';
import { SimulationInputs, NCMEntry } from '../types.ts';
import { UF_LIST, NCM_DATABASE } from '../utils/ncmData.ts';
import { getInterstateRate, calculateAdjustedMva } from '../utils/calculations.ts';

interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const suggestionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const currentNcm = NCM_DATABASE.find(n => n.codigo === inputs.ncmCodigo);
    if (currentNcm) {
      setSearchTerm(`${currentNcm.codigo} - ${currentNcm.descricao}`);
    }
  }, []);

  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const newOrigem = field === 'ufOrigem' ? val : inputs.ufOrigem;
    const newDestino = field === 'ufDestino' ? val : inputs.ufDestino;

    const origUf = UF_LIST.find(u => u.sigla === newOrigem);
    const destUf = UF_LIST.find(u => u.sigla === newDestino);

    if (origUf && destUf) {
      const interRate = getInterstateRate(origUf.sigla, destUf.sigla);
      const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf.icms);

      setInputs(prev => ({
        ...prev,
        [field]: val,
        icmsInterestadual: interRate,
        icmsInternoDestino: destUf.icms,
        icmsVenda: prev.mode !== 'substituido' ? destUf.icms : prev.icmsVenda,
        mva: adjMva
      }));
    }
  };

  const selectNcm = (ncm: NCMEntry) => {
    const interRate = inputs.icmsInterestadual;
    const adjMva = calculateAdjustedMva(ncm.mvaOriginal, interRate, inputs.icmsInternoDestino);

    setInputs(prev => ({
      ...prev,
      ncmCodigo: ncm.codigo,
      mvaOriginal: ncm.mvaOriginal,
      mva: adjMva,
      nomeProduto: ncm.descricao
    }));
    setSearchTerm(`${ncm.codigo} - ${ncm.descricao}`);
    setShowSuggestions(false);
  };

  const filteredNcms = NCM_DATABASE.filter(n => 
    n.codigo.toLowerCase().includes(searchTerm.toLowerCase()) || 
    n.descricao.toLowerCase().includes(searchTerm.toLowerCase())
  );

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div className="bg-[#1a2332] text-white p-4 md:p-6 rounded-2xl shadow-xl border border-slate-700">
      <div className="mb-6">
        <label className="block text-[9px] md:text-[10px] uppercase font-black text-blue-400 mb-1.5 tracking-wider">Nome Comercial do Item</label>
        <div className="relative">
          <input 
            type="text"
            value={inputs.nomeProduto}
            onChange={(e) => setInputs(prev => ({ ...prev, nomeProduto: e.target.value }))}
            placeholder="Ex: Porcelanato Delta 60x60 Bege"
            className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-4 py-3 text-sm outline-none focus:border-blue-500 transition-all placeholder:text-slate-700 font-bold text-blue-50 shadow-inner"
          />
          <div className="absolute right-3 top-1/2 -translate-y-1/2 opacity-20">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-6">
        <div className="group">
          <label className="block text-[9px] uppercase font-black text-slate-400 mb-1.5 tracking-wider">Origem</label>
          <div className="relative">
            <select 
              value={inputs.ufOrigem}
              onChange={(e) => handleUfChange('ufOrigem', e.target.value)}
              className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-3 py-2.5 text-xs font-bold outline-none focus:border-blue-500 transition-colors cursor-pointer appearance-none"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla}</option>)}
            </select>
          </div>
        </div>
        <div className="group">
          <label className="block text-[9px] uppercase font-black text-slate-400 mb-1.5 tracking-wider">Destino</label>
          <div className="relative">
            <select 
              value={inputs.ufDestino}
              onChange={(e) => handleUfChange('ufDestino', e.target.value)}
              className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-3 py-2.5 text-xs font-bold outline-none focus:border-blue-500 transition-colors cursor-pointer appearance-none"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="mb-2 relative" ref={suggestionRef}>
        <label className="block text-[9px] uppercase font-black text-slate-400 mb-1.5 tracking-wider">NCM Classificação</label>
        <div className="relative">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setShowSuggestions(true);
            }}
            onFocus={() => setShowSuggestions(true)}
            placeholder="Buscar NCM..."
            className="w-full bg-[#0f172a] border border-slate-600 rounded-xl pl-10 pr-4 py-2.5 text-xs outline-none focus:border-blue-500 transition-colors placeholder:text-slate-600 font-mono"
          />
          <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
          </div>
        </div>

        {showSuggestions && (
          <div className="absolute z-50 w-full mt-1 bg-[#1e293b] border border-slate-600 rounded-xl shadow-2xl max-h-48 overflow-y-auto">
            {filteredNcms.map((ncm) => (
              <div 
                key={ncm.codigo}
                onClick={() => selectNcm(ncm)}
                className="px-4 py-3 hover:bg-blue-600 cursor-pointer border-b border-slate-700/50 last:border-0 transition-colors group"
              >
                <div className="flex items-center justify-between">
                  <span className="text-xs font-black text-blue-300 group-hover:text-white">{ncm.codigo}</span>
                  <span className="text-[8px] bg-slate-700 px-1.5 py-0.5 rounded font-black text-slate-300">MVA: {ncm.mvaOriginal}%</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default FiscalHeader;

import React from 'react';
import { SimulationResults, SimulationInputs } from '../types.ts';
