const MetricCard: React.FC<{ label: string; value: string; subValue?: string; delta?: string; color?: string }> = ({ label, value, subValue, delta, color = "blue" }) => (
  <div className="bg-white p-4 md:p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-between transition-transform active:scale-[0.98]">
    <p className="text-[10px] md:text-sm text-slate-500 font-black uppercase tracking-widest mb-1">{label}</p>
    <div>
      <h3 className={`text-xl md:text-2xl font-black text-slate-800 tracking-tight`}>{value}</h3>
      {subValue && <p className="text-[9px] md:text-xs text-slate-400 font-bold uppercase mt-1 tracking-tighter">{subValue}</p>}
    </div>
    {delta && (
      <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-lg mt-3 w-fit tracking-widest ${
        color === 'red' ? 'bg-red-50 text-red-600' : 
        color === 'green' ? 'bg-green-50 text-green-600' : 
        'bg-blue-50 text-blue-600'
      }`}>
        {delta}
      </span>
    )}
  </div>
);

const PriceBreakdown: React.FC<{ results: SimulationResults; inputs: SimulationInputs }> = ({ results, inputs }) => {
  const total = results.precoVendaAlvo;
  if (!total) return null;

  const custoPerc = (results.custoFinal / total) * 100;
  const impostoPerc = (results.impostosTotais / total) * 100;
  const margemPerc = (results.margemAbsoluta / total) * 100;

  return (
    <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm mt-8">
      <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Composição Analítica do Preço</h3>
      <div className="flex h-12 w-full rounded-2xl overflow-hidden shadow-inner bg-slate-100">
        <div style={{ width: `${custoPerc}%` }} className="bg-slate-800 h-full transition-all duration-500" title="Custo Líquido"></div>
        <div style={{ width: `${impostoPerc}%` }} className="bg-red-500 h-full transition-all duration-500" title="Impostos Totais"></div>
        <div style={{ width: `${margemPerc}%` }} className="bg-green-500 h-full transition-all duration-500" title="Lucro Líquido"></div>
      </div>
      <div className="grid grid-cols-3 gap-4 mt-6">
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-slate-800"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Custo</span>
          </div>
          <span className="text-sm font-black text-slate-800">{custoPerc.toFixed(1)}%</span>
        </div>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-red-500"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Fisco</span>
          </div>
          <span className="text-sm font-black text-red-600">{impostoPerc.toFixed(1)}%</span>
        </div>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-green-500"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Lucro</span>
          </div>
          <span className="text-sm font-black text-green-600">{margemPerc.toFixed(1)}%</span>
        </div>
      </div>
    </div>
  );
};

