        return (
          <div className="h-full flex flex-col md:flex-row relative">
            <aside className={`${activeCalcTab === 'config' ? 'flex' : 'hidden md:flex'} w-full md:w-80 lg:w-[450px] bg-white border-r border-slate-200 flex-shrink-0 flex-col h-full z-10 shadow-sm transition-all duration-300`}>
