              <div className="max-w-6xl mx-auto w-full p-4 md:p-8">
                <div className="md:hidden flex gap-2 mb-6">
                   <button onClick={() => setActiveCalcTab('config')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border ${activeCalcTab === 'config' ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-slate-200 text-slate-400'}`}>Filtros</button>
                   <button onClick={() => setActiveCalcTab('results')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border ${activeCalcTab === 'results' ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-slate-200 text-slate-400'}`}>Ver Preço</button>
                </div>
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} />
