        <div style={{ width: `${impostoPerc}%` }} className="bg-red-500 h-full transition-all duration-500" title="Impostos Totais"></div>
        <div style={{ width: `${margemPerc}%` }} className="bg-green-500 h-full transition-all duration-500" title="Lucro Líquido"></div>
      </div>
      <div className="grid grid-cols-3 gap-4 mt-6">
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-slate-800"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Custo</span>
          </div>
          <span className="text-sm font-black text-slate-800">{custoPerc.toFixed(1)}%</span>
        </div>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-red-500"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Fisco</span>
          </div>
          <span className="text-sm font-black text-red-600">{impostoPerc.toFixed(1)}%</span>
        </div>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-green-500"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Lucro</span>
          </div>
          <span className="text-sm font-black text-green-600">{margemPerc.toFixed(1)}%</span>
        </div>
      </div>
    </div>
  );
};

