import { SimulationInputs, SimulationResults } from '../types';

export const getInterstateRate = (origem: string, destino: string): number => {
  if (origem === destino) return 0;
  const sulSudeste = ['SP', 'RJ', 'MG', 'ES', 'PR', 'SC', 'RS'];
  const norteNordesteCentroOeste = ['AC', 'AL', 'AM', 'AP', 'BA', 'CE', 'DF', 'GO', 'MA', 'MS', 'MT', 'PA', 'PB', 'PE', 'PI', 'RN', 'RO', 'RR', 'SE', 'TO'];
  if (sulSudeste.includes(origem) && norteNordesteCentroOeste.includes(destino)) return 7;
  return 12;
};

export const calculateAdjustedMva = (mvaOriginal: number, alqInter: number, alqIntra: number): number => {
  if (alqInter === 0) return mvaOriginal;
  const mvaOriginalDecimal = mvaOriginal / 100;
  const alqInterDecimal = alqInter / 100;
  const alqIntraDecimal = alqIntra / 100;
  const adjusted = ((1 + mvaOriginalDecimal) * (1 - alqInterDecimal) / (1 - alqIntraDecimal)) - 1;
  return adjusted * 100;
};

export const calculateCosts = (inputs: SimulationInputs): SimulationResults => {
  const {
    valorCompra,
    ipiFrete,
    mva,
    icmsInternoDestino,
    icmsInterestadual,
    pisCofinsRate,
    excluirIcmsPis,
    pisCofinsVenda,
    comissaoVenda,
    icmsVenda,
    outrosCustosVariaveis,
    custosFixos,
    resultadoDesejado,
    mode,
    percReducaoBase
  } = inputs;

  const valorTotalNota = valorCompra + ipiFrete;
  const creditoIcmsEntrada = valorCompra * (icmsInterestadual / 100);

  let stAPagar = 0;
  let baseCalculoSt = 0;
  let icmsStBruto = 0;

  if (mode === 'substituido') {
    baseCalculoSt = valorTotalNota * (1 + mva / 100);
    icmsStBruto = baseCalculoSt * (icmsInternoDestino / 100);
    stAPagar = Math.max(0, icmsStBruto - creditoIcmsEntrada);
  }

  let basePisCofins = valorCompra;
  if (excluirIcmsPis) basePisCofins = valorCompra - creditoIcmsEntrada;
  const creditoPisCofinsValor = basePisCofins * (pisCofinsRate / 100);

  let custoFinal = 0;
  if (mode === 'substituido') {
    custoFinal = valorTotalNota + stAPagar - creditoPisCofinsValor;
  } else {
    custoFinal = valorTotalNota - creditoIcmsEntrada - creditoPisCofinsValor;
  }

  let icmsVendaEfetivo = icmsVenda;
  if (mode === 'reduzido') {
    icmsVendaEfetivo = icmsVenda * (1 - (percReducaoBase / 100));
  }

  const deducoesSemMargem = pisCofinsVenda + comissaoVenda + icmsVendaEfetivo + outrosCustosVariaveis + custosFixos;
  const totalDeducoesVendaPerc = deducoesSemMargem + resultadoDesejado;

  const precoVendaAlvo = totalDeducoesVendaPerc < 100 ? custoFinal / ((100 - totalDeducoesVendaPerc) / 100) : 0;
  const precoEquilibrio = deducoesSemMargem < 100 ? custoFinal / ((100 - deducoesSemMargem) / 100) : 0;

  const margemAbsoluta = precoVendaAlvo * (resultadoDesejado / 100);
  const impostosTotais = stAPagar + (precoVendaAlvo * (icmsVendaEfetivo / 100)) + (precoVendaAlvo * (pisCofinsVenda / 100));

  return {
    valorTotalNota,
    baseCalculoSt,
    icmsStBruto,
    creditoIcmsEntrada,
    stAPagar,
    basePisCofins,
    creditoPisCofinsValor,
    custoFinal,
    precoEquilibrio,
    precoVendaAlvo,
    totalDeducoesVendaPerc,
    icmsVendaEfetivo,
    margemAbsoluta,
    impostosTotais
  };
};

export const generatePriceMatrix = (custoFinal: number, inputs: SimulationInputs): any => {
  const { mode, percReducaoBase, icmsVenda } = inputs;
  const icmsVendaEfetivo = mode === 'reduzido' ? icmsVenda * (1 - (percReducaoBase / 100)) : icmsVenda;
  const baseDeducoes = inputs.pisCofinsVenda + inputs.comissaoVenda + icmsVendaEfetivo + inputs.outrosCustosVariaveis + inputs.custosFixos;

  const categorias = [
    { label: 'Comod.', margin: 8 },
    { label: 'Curva A', margin: 10 },
    { label: 'Curva B', margin: 11 },
    { label: 'Curva C', margin: 12 },
    { label: 'Produtos Técnicos', margin: 15 }
  ];

  const getPrice = (margin: number) => {
    const total = baseDeducoes + margin;
    return total < 100 ? custoFinal / ((100 - total) / 100) : 0;
  };

  return categorias.map(cat => {
    const basePrice = getPrice(cat.margin);
    return {
      label: cat.label,
      margin: cat.margin,
      levels: {
        A: basePrice * 0.95,
        B: basePrice,
        C: basePrice * 1.111,
        D: basePrice * 1.1765
      }
    };
  });
};

export const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
};

export const formatPercent = (val: number) => {
  return new Intl.NumberFormat('pt-BR', { style: 'percent', minimumFractionDigits: 2 }).format(val / 100);
};

import React, { useState, useRef, useEffect } from 'react';
import { SimulationInputs, NCMEntry } from '../types';
import { UF_LIST, NCM_DATABASE } from '../utils/ncmData';
import { getInterstateRate, calculateAdjustedMva } from '../utils/calculations';

interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const suggestionRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const currentNcm = NCM_DATABASE.find(n => n.codigo === inputs.ncmCodigo);
    if (currentNcm) {
      setSearchTerm(`${currentNcm.codigo} - ${currentNcm.descricao}`);
    }
  }, []);

  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const newOrigem = field === 'ufOrigem' ? val : inputs.ufOrigem;
    const newDestino = field === 'ufDestino' ? val : inputs.ufDestino;

    const origUf = UF_LIST.find(u => u.sigla === newOrigem);
    const destUf = UF_LIST.find(u => u.sigla === newDestino);

    if (origUf && destUf) {
      const interRate = getInterstateRate(origUf.sigla, destUf.sigla);
      const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf.icms);

      setInputs(prev => ({
        ...prev,
        [field]: val,
        icmsInterestadual: interRate,
        icmsInternoDestino: destUf.icms,
        icmsVenda: prev.mode !== 'substituido' ? destUf.icms : prev.icmsVenda,
        mva: adjMva
      }));
    }
  };

  const selectNcm = (ncm: NCMEntry) => {
    const interRate = inputs.icmsInterestadual;
    const adjMva = calculateAdjustedMva(ncm.mvaOriginal, interRate, inputs.icmsInternoDestino);

    setInputs(prev => ({
      ...prev,
      ncmCodigo: ncm.codigo,
      mvaOriginal: ncm.mvaOriginal,
      mva: adjMva,
      nomeProduto: ncm.descricao
    }));
    setSearchTerm(`${ncm.codigo} - ${ncm.descricao}`);
    setShowSuggestions(false);
  };

  const filteredNcms = NCM_DATABASE.filter(n => 
    n.codigo.toLowerCase().includes(searchTerm.toLowerCase()) || 
    n.descricao.toLowerCase().includes(searchTerm.toLowerCase())
  );

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <div className="bg-[#1a2332] text-white p-4 md:p-6 rounded-2xl shadow-xl border border-slate-700">
      <div className="mb-6">
        <label className="block text-[9px] md:text-[10px] uppercase font-black text-blue-400 mb-1.5 tracking-wider">Identificação do Item (Nome Comercial)</label>
        <input 
          type="text"
          value={inputs.nomeProduto}
          onChange={(e) => setInputs(prev => ({ ...prev, nomeProduto: e.target.value }))}
          placeholder="Ex: Piso Porcelanato Bege 60x60"
          className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-4 py-2.5 text-sm outline-none focus:border-blue-500 transition-colors placeholder:text-slate-700 font-medium"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 mb-6">
        <div className="group">
          <label className="block text-[9px] md:text-[10px] uppercase font-black text-slate-400 mb-1.5 tracking-wider group-focus-within:text-blue-400 transition-colors">UF de Origem</label>
          <div className="relative">
            <select 
              value={inputs.ufOrigem}
              onChange={(e) => handleUfChange('ufOrigem', e.target.value)}
              className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-blue-500 transition-colors cursor-pointer appearance-none"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.nome} ({uf.sigla})</option>)}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
            </div>
          </div>
        </div>
        <div className="group">
          <label className="block text-[9px] md:text-[10px] uppercase font-black text-slate-400 mb-1.5 tracking-wider group-focus-within:text-blue-400 transition-colors">UF de Destino</label>
          <div className="relative">
            <select 
              value={inputs.ufDestino}
              onChange={(e) => handleUfChange('ufDestino', e.target.value)}
              className="w-full bg-[#0f172a] border border-slate-600 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-blue-500 transition-colors cursor-pointer appearance-none"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.nome} ({uf.sigla})</option>)}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
            </div>
          </div>
        </div>
      </div>

      <div className="mb-6 relative" ref={suggestionRef}>
        <label className="block text-[9px] md:text-[10px] uppercase font-black text-slate-400 mb-1.5 tracking-wider">Classificação NCM 2025</label>
        <div className="relative">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setShowSuggestions(true);
            }}
            onFocus={() => setShowSuggestions(true)}
            placeholder="Pesquisar NCM..."
            className="w-full bg-[#0f172a] border border-slate-600 rounded-xl pl-10 pr-4 py-2.5 text-sm outline-none focus:border-blue-500 transition-colors placeholder:text-slate-600"
          />
          <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
          </div>
        </div>

        {showSuggestions && (
          <div className="absolute z-50 w-full mt-1 bg-[#1e293b] border border-slate-600 rounded-xl shadow-2xl max-h-60 overflow-y-auto custom-scrollbar">
            {filteredNcms.length > 0 ? (
              filteredNcms.map((ncm) => (
                <div 
                  key={ncm.codigo}
                  onClick={() => selectNcm(ncm)}
                  className="px-4 py-3 hover:bg-blue-600 cursor-pointer border-b border-slate-700/50 last:border-0 transition-colors group active:bg-blue-700"
                >
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-black text-blue-300 group-hover:text-white">{ncm.codigo}</span>
                    <span className="text-[9px] bg-slate-700 px-2 py-0.5 rounded font-black text-slate-300 group-hover:bg-blue-500">MVA: {ncm.mvaOriginal}%</span>
                  </div>
                  <div className="text-[11px] text-slate-400 group-hover:text-blue-100 mt-1 line-clamp-1">{ncm.descricao}</div>
                </div>
              ))
            ) : (
              <div className="px-4 py-8 text-center text-slate-500 text-[10px] font-bold uppercase tracking-widest italic">
                Nenhum resultado
              </div>
            )}
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4 border-t border-slate-700/50">
        <div className="space-y-2">
          <h4 className="text-[9px] md:text-[10px] font-black text-blue-400 uppercase tracking-widest">ICMS Interestadual</h4>
          <div className="flex justify-between items-center bg-[#0f172a] p-2 rounded-lg border border-slate-700/50">
            <span className="text-[10px] text-slate-400 font-bold uppercase">{inputs.ufOrigem} → {inputs.ufDestino}</span>
            <span className="text-sm font-black text-blue-300">{inputs.icmsInterestadual}%</span>
          </div>
        </div>
        <div className="space-y-2">
          <h4 className="text-[9px] md:text-[10px] font-black text-orange-400 uppercase tracking-widest">MVA Ajustada (2025)</h4>
          <div className="flex justify-between items-center bg-[#0f172a] p-2 rounded-lg border border-slate-700/50">
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">Cálculo Dinâmico</span>
            <span className="text-sm font-black text-orange-500">{inputs.mva.toFixed(2).replace('.', ',')}%</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FiscalHeader;

import React from 'react';
import { SimulationResults, SimulationInputs } from '../types';
import { formatCurrency, formatPercent } from '../utils/calculations';

interface ResultsTableProps {
  results: SimulationResults;
  priceMatrix: any[];
  inputs: SimulationInputs;
}

const MetricCard: React.FC<{ label: string; value: string; subValue?: string; delta?: string; color?: string }> = ({ label, value, subValue, delta, color = "blue" }) => (
  <div className="bg-white p-4 md:p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col justify-between transition-transform active:scale-[0.98]">
    <p className="text-[10px] md:text-sm text-slate-500 font-black uppercase tracking-widest mb-1">{label}</p>
    <div>
      <h3 className={`text-xl md:text-2xl font-black text-slate-800 tracking-tight`}>{value}</h3>
      {subValue && <p className="text-[9px] md:text-xs text-slate-400 font-bold uppercase mt-1 tracking-tighter">{subValue}</p>}
    </div>
    {delta && (
      <span className={`text-[9px] font-black uppercase px-2 py-1 rounded-lg mt-3 w-fit tracking-widest ${
        color === 'red' ? 'bg-red-50 text-red-600' : 
        color === 'green' ? 'bg-green-50 text-green-600' : 
        'bg-blue-50 text-blue-600'
      }`}>
        {delta}
      </span>
    )}
  </div>
);

const PriceBreakdown: React.FC<{ results: SimulationResults; inputs: SimulationInputs }> = ({ results, inputs }) => {
  const total = results.precoVendaAlvo;
  if (!total) return null;

  const custoPerc = (results.custoFinal / total) * 100;
  const impostoPerc = (results.impostosTotais / total) * 100;
  const margemPerc = (results.margemAbsoluta / total) * 100;

  return (
    <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm mt-8">
      <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Composição Analítica do Preço</h3>
      <div className="flex h-12 w-full rounded-2xl overflow-hidden shadow-inner bg-slate-100">
        <div style={{ width: `${custoPerc}%` }} className="bg-slate-800 h-full transition-all duration-500" title="Custo Líquido"></div>
        <div style={{ width: `${impostoPerc}%` }} className="bg-red-500 h-full transition-all duration-500" title="Impostos Totais"></div>
        <div style={{ width: `${margemPerc}%` }} className="bg-green-500 h-full transition-all duration-500" title="Lucro Líquido"></div>
      </div>
      <div className="grid grid-cols-3 gap-4 mt-6">
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-slate-800"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Custo</span>
          </div>
          <span className="text-sm font-black text-slate-800">{custoPerc.toFixed(1)}%</span>
        </div>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-red-500"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Fisco</span>
          </div>
          <span className="text-sm font-black text-red-600">{impostoPerc.toFixed(1)}%</span>
        </div>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 rounded-full bg-green-500"></div>
            <span className="text-[9px] font-black text-slate-500 uppercase">Lucro</span>
          </div>
          <span className="text-sm font-black text-green-600">{margemPerc.toFixed(1)}%</span>
        </div>
      </div>
    </div>
  );
};

const ResultsTable: React.FC<ResultsTableProps> = ({ results, priceMatrix, inputs }) => {
  const pisCofinsValor = results.precoVendaAlvo * (inputs.pisCofinsVenda / 100);
  const comissaoValor = results.precoVendaAlvo * (inputs.comissaoVenda / 100);
  const icmsVendaValor = results.precoVendaAlvo * (results.icmsVendaEfetivo / 100);
  const outrosVariaveisValor = results.precoVendaAlvo * (inputs.outrosCustosVariaveis / 100);
  const custosFixosValor = results.precoVendaAlvo * (inputs.custosFixos / 100);
  const margemValor = results.precoVendaAlvo * (inputs.resultadoDesejado / 100);

  const totalCustoVenda = pisCofinsValor + comissaoValor + icmsVendaValor + outrosVariaveisValor + custosFixosValor + margemValor;

  const exportToWhatsApp = () => {
    const nomeExibicao = inputs.nomeProduto.trim() || `Item NCM ${inputs.ncmCodigo}`;
    const text = `*SIMULAÇÃO FISCAL - TAGWAY*%0A%0A` +
      `*Item:* ${nomeExibicao}%0A` +
      `*NCM:* ${inputs.ncmCodigo}%0A` +
      `*Rota:* ${inputs.ufOrigem} ➔ ${inputs.ufDestino}%0A%0A` +
      `*Custo Líquido:* ${formatCurrency(results.custoFinal)}%0A` +
      `*Margem Alvo:* ${inputs.resultadoDesejado}%%0A` +
      `----------------------------%0A` +
      `*PREÇO DE VENDA:* ${formatCurrency(results.precoVendaAlvo)}%0A` +
      `----------------------------%0A%0A` +
      `_Gerado por Tagway Technology 2025_`;
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  return (
    <div className="space-y-6 md:space-y-8 pb-20">
      <div className="hidden md:grid grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard label="Total NF" value={formatCurrency(results.valorTotalNota)} subValue="Base NF-e" />
        {inputs.mode === 'substituido' ? (
          <MetricCard label="ICMS-ST" value={formatCurrency(results.stAPagar)} delta="Débito ST" color="red" />
        ) : (
          <MetricCard label="Crédito ICMS" value={formatCurrency(results.creditoIcmsEntrada)} delta="Ativo" color="green" />
        )}
        <MetricCard label="Créd. PIS/COF" value={formatCurrency(results.creditoPisCofinsValor)} delta="Ativo" color="green" />
        <MetricCard label="CUSTO LÍQ." value={formatCurrency(results.custoFinal)} delta="Base Venda" color="blue" />
      </div>

      <div className="bg-white rounded-3xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-slate-100 p-4 flex justify-between items-center px-6">
          <span className="font-black text-slate-800 uppercase tracking-[0.2em] text-[10px]">Detalhamento de Saída</span>
          <button 
            onClick={exportToWhatsApp}
            className="bg-green-500 text-white px-3 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest hover:bg-green-600 transition-colors flex items-center gap-2 shadow-lg shadow-green-500/20"
          >
            <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.245 2.248 3.481 5.236 3.48 8.417-.003 6.557-5.338 11.892-11.893 11.892-1.997-.001-3.951-.5-5.688-1.448l-6.305 1.652zm6.599-3.835c1.544.917 3.51 1.403 5.316 1.404h.002c5.451 0 9.886-4.435 9.889-9.886.002-2.642-1.029-5.126-2.902-7c-1.874-1.874-4.359-2.905-7.002-2.907h-.002c-5.451 0-9.886 4.436-9.889 9.888 0 1.875.522 3.706 1.512 5.31l-.994 3.635 3.725-.977z"/></svg>
            Compartilhar
          </button>
        </div>
        <div className="p-4 md:p-6">
          <div className="grid grid-cols-1 md:grid-cols-2 md:gap-x-10 mb-4">
            {[
              { label: 'PIS / COF (Saída)', val: pisCofinsValor, red: false },
              { label: `ICMS Venda ${inputs.mode === 'reduzido' ? '(Efetivo)' : ''}`, val: icmsVendaValor, red: inputs.mode === 'reduzido' },
              { label: 'Comissão de Venda', val: comissaoValor, red: false },
              { label: 'Custos Fixos Op.', val: custosFixosValor, red: false },
              { label: 'Resultado Líquido Alvo', val: margemValor, red: false, indigo: true },
              { label: 'Total Deduções', val: totalCustoVenda, red: true, bold: true },
            ].map((item, i) => (
              <div key={i} className="flex justify-between items-center border-b border-slate-100 py-3">
                <span className={`text-[10px] font-bold uppercase tracking-tight ${item.red && !item.indigo ? 'text-red-500' : item.indigo ? 'text-indigo-600' : 'text-slate-500'}`}>
