          <div className="inline-flex items-center justify-center w-20 h-20 bg-indigo-600 rounded-[2.5rem] shadow-2xl shadow-indigo-500/40 mb-8 animate-pulse">
             <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
          </div>
          <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic mb-3">Tagway</h1>
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.3em]">Fiscal Intelligence Platform 2025</p>
        </div>

        <div className="bg-[#161d2f]/60 backdrop-blur-xl border border-white/5 rounded-[3rem] p-10 shadow-3xl">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Identificador</label>
              <input
                type="text"
                required
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full bg-[#0b0f1a] border border-white/5 rounded-2xl py-4 px-6 text-white placeholder:text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-bold"
                placeholder="Ex: admin"
              />
            </div>

            <div>
              <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Senha de Acesso</label>
              <input
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-[#0b0f1a] border border-white/5 rounded-2xl py-4 px-6 text-white placeholder:text-slate-700 focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-bold"
                placeholder="••••••••"
              />
            </div>

            {error && (
              <div className="bg-rose-500/10 border border-rose-500/20 text-rose-400 text-[10px] font-black uppercase tracking-widest py-3 px-4 rounded-xl text-center">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-900 text-white font-black py-5 rounded-2xl shadow-xl shadow-indigo-500/20 transition-all uppercase tracking-[0.2em] text-xs flex items-center justify-center gap-3 active:scale-95"
            >
              {isLoading ? (
                <div className="w-5 h-5 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
              ) : (
                'Entrar no Painel'
              )}
