const supabaseAnonKey = 'sb_publishable_Vi0uwwpt4Ztos2NzKgdN9w_z8Vt0WS7';

/**
 * Configuração otimizada para ambientes sandboxed (como previews de IDEs).
 * O erro de BroadcastChannel ocorre porque o browser bloqueia APIs de cross-tab 
 * em contextos que ele considera "inseguros" ou restritos.
 */
export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    storageKey: 'tagway-auth-token',
    // Removemos a dependência de BroadcastChannel/LockManager se o ambiente falhar
    storage: window.localStorage, 
  }
});

