import React, { useState } from 'react';
import { SimulationInputs } from '../types';
import { NCM_DATABASE, UF_LIST } from '../utils/ncmData';
import { calculateAdjustedMva, getInterstateRate } from '../utils/calculations';

interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {
  const [showNcmSearch, setShowNcmSearch] = useState(false);

  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const newOrigem = field === 'ufOrigem' ? val : inputs.ufOrigem;
    const newDestino = field === 'ufDestino' ? val : inputs.ufDestino;
    const destUf = UF_LIST.find(u => u.sigla === newDestino);
    const interRate = getInterstateRate(newOrigem, newDestino);
    const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf?.icms || 18);

    setInputs(prev => ({
      ...prev,
      [field]: val,
      icmsInterestadual: interRate,
      icmsInternoDestino: destUf?.icms || 18,
      mva: adjMva
    }));
  };

  return (
    <div className="bg-[#0f172a] rounded-2xl p-5 text-white space-y-4 shadow-xl border border-slate-800 relative">
      <div>
        <label className="text-[8px] font-black text-blue-400 uppercase tracking-[0.2em] mb-1.5 block">Nome Comercial / Produto</label>
        <input 
          type="text" 
          value={inputs.nomeProduto}
          onChange={(e) => setInputs(prev => ({...prev, nomeProduto: e.target.value}))}
          placeholder="Ex: Piso Porcelanato 60x60"
          className="w-full bg-slate-800/50 border border-slate-700 rounded-lg px-3 py-2 text-xs font-bold focus:border-blue-500 outline-none"
        />
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1">
          <label className="text-[8px] font-black text-slate-500 uppercase">Origem</label>
          <select 
            value={inputs.ufOrigem} 
            onChange={(e) => handleUfChange('ufOrigem', e.target.value)}
            className="w-full bg-slate-800 border border-slate-700 rounded-lg px-2 py-1.5 text-xs font-black outline-none"
          >
            {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla} - {uf.nome}</option>)}
          </select>
        </div>
        <div className="space-y-1">
          <label className="text-[8px] font-black text-slate-500 uppercase">Destino</label>
          <select 
            value={inputs.ufDestino} 
            onChange={(e) => handleUfChange('ufDestino', e.target.value)}
            className="w-full bg-slate-800 border border-slate-700 rounded-lg px-2 py-1.5 text-xs font-black outline-none"
          >
            {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla} - {uf.nome}</option>)}
          </select>
        </div>
      </div>

      <div className="space-y-1">
        <label className="text-[8px] font-black text-slate-500 uppercase">Classificação NCM</label>
        <div className="relative">
          <input 
            type="text" 
            readOnly
            value={`${inputs.ncmCodigo} - ${inputs.nomeProduto}`}
            onClick={() => setShowNcmSearch(!showNcmSearch)}
            className="w-full bg-slate-800 border border-slate-700 rounded-lg px-8 py-2 text-[10px] font-bold cursor-pointer"
          />
          <svg className="w-3.5 h-3.5 absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        </div>
      </div>

      <div className="flex justify-between items-center pt-2 border-t border-slate-800/50">
        <div>
          <p className="text-[7px] font-black text-slate-500 uppercase">Interestadual</p>
          <p className="text-[10px] font-black text-blue-400">{inputs.ufOrigem} → {inputs.ufDestino} <span className="ml-2">{inputs.icmsInterestadual}%</span></p>
        </div>
        <div className="text-right">
          <p className="text-[7px] font-black text-slate-500 uppercase">MVA Ajustada 2025</p>
          <p className="text-[10px] font-black text-amber-500 italic uppercase">Recálculo Dinâmico <span className="ml-2">{inputs.mva.toFixed(2)}%</span></p>
        </div>
      </div>
    </div>
  );
};

