  const [profile, setProfile] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [mainTab, setMainTab] = useState<'calculadora' | 'catalogo' | 'historico'>('calculadora');
  const [isSaving, setIsSaving] = useState(false);
  const [savedSimulations, setSavedSimulations] = useState<any[]>([]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) fetchProfile(session.user.id);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchProfile(session.user.id);
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId: string) => {
    const { data } = await supabase.from('perfis').select('*').eq('id', userId).maybeSingle();
    if (data) setProfile(data);
  };

  const fetchHistory = async () => {
    const { data } = await supabase.from('simulacoes').select('*').order('created_at', { ascending: false });
    if (data) setSavedSimulations(data);
  };

  const handleSave = async () => {
    if (!session) return;
    setIsSaving(true);
    await supabase.from('simulacoes').insert([{ 
      user_id: session.user.id, 
      nome_produto: inputs.nomeProduto || 'Simulação ' + new Date().toLocaleDateString(), 
      dados: inputs 
    }]);
    setIsSaving(false);
    alert('Simulação salva no histórico!');
