                <svg className="w-3 h-3 cursor-pointer" fill="currentColor" viewBox="0 0 24 24" onClick={() => handleChange('resultadoDesejado', Math.max(0, inputs.resultadoDesejado - 0.5))}><path d="M7 10l5 5 5-5z"/></svg>
             </div>
