        </div>
      </div>

      {/* Matriz de Margens (Botões Interativos) */}
      <div className="space-y-3 pt-4 border-t border-slate-100 pb-10">
        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">— Matriz de Margens</label>
        <div className="space-y-2">
          {marginOptions.map(item => {
            const isActive = inputs.resultadoDesejado === item.val;
            return (
              <button 
                key={item.label} 
                onClick={() => handleChange('resultadoDesejado', item.val)}
                className={`w-full flex items-center justify-between p-3.5 rounded-xl border transition-all ${
                  isActive 
                  ? 'bg-slate-900 border-blue-500 shadow-lg ring-1 ring-blue-500/30' 
                  : 'bg-[#0f172a] border-slate-800 hover:border-slate-700 active:scale-[0.98]'
                }`}
              >
                 <span className={`text-[9px] font-black uppercase tracking-tighter ${isActive ? 'text-blue-400' : 'text-slate-300'}`}>
                   {item.label}
                 </span>
                 <div className="flex items-center gap-2">
                    {isActive && <div className="w-1 h-1 bg-blue-500 rounded-full animate-pulse"></div>}
                    <span className={`text-[11px] font-mono font-bold px-2 py-0.5 rounded ${
                      isActive ? 'text-white bg-blue-600' : 'text-blue-400 bg-blue-400/10'
                    }`}>
                      {item.val}%
                    </span>
                 </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

