import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import Login from './components/Login';
import { SimulationInputs } from './types';
import { calculateCosts, generatePriceMatrix } from './utils/calculations';
import { supabase } from './lib/supabase';

const defaultInputs: SimulationInputs = {
  nomeProduto: '',
  valorCompra: 100.00,
  ipiFrete: 0.00,
  mva: 32.00,
  mvaOriginal: 32.00,
  icmsInternoDestino: 18.00,
  icmsInterestadual: 12.00,
  ufOrigem: 'SP',
  ufDestino: 'RJ',
  ncmCodigo: '2523.29.10',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.25,
  comissaoVenda: 0.0,
  icmsVenda: 18.00,
  outrosCustosVariaveis: 0.00,
  custosFixos: 15.00,
  resultadoDesejado: 8.00,
  tipoProduto: 'comod',
  mode: 'substituido',
  percReducaoBase: 0,
  simulationMode: 'buyToSell',
  precoVendaDesejado: 0
};

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [profile, setProfile] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [mainTab, setMainTab] = useState<'calculadora' | 'catalogo' | 'meus-produtos'>('calculadora');
  const [isSaving, setIsSaving] = useState(false);
  const [savedSimulations, setSavedSimulations] = useState<any[]>([]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) fetchProfile(session.user.id);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchProfile(session.user.id);
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId: string) => {
    const { data } = await supabase.from('perfis').select('*').eq('id', userId).maybeSingle();
    if (data) setProfile(data);
  };

  const fetchMyProducts = async () => {
    const { data } = await supabase.from('simulacoes').select('*').order('created_at', { ascending: false });
    if (data) setSavedSimulations(data);
  };

  const handleSave = async () => {
    if (!session) return;
    setIsSaving(true);
    const { error } = await supabase.from('simulacoes').insert([{ 
      user_id: session.user.id, 
      nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
      dados: inputs 
    }]);

    setIsSaving(false);
    if (error) {
      alert('Erro ao salvar produto.');
    } else {
      alert('Produto salvo com sucesso!');
    }
  };

  const handleDeleteProduct = async (id: string) => {
    if (!confirm('Tem certeza que deseja remover este produto?')) return;
    const { error } = await supabase.from('simulacoes').delete().eq('id', id);
    if (!error) {
      setSavedSimulations(prev => prev.filter(p => p.id !== id));
    } else {
      alert('Erro ao excluir produto.');
    }
  };

  if (!session) return <Login onLoginSuccess={setSession} />;

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  return (
    <div className="h-screen w-full flex bg-[#f1f5f9] overflow-hidden text-slate-900 font-sans">
      {/* Sidebar de Navegação Lateral - Ultra Slim */}
      <aside className="w-[70px] bg-[#0f172a] flex flex-col items-center py-6 gap-8 border-r border-slate-800 shrink-0">
        <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg">
          <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
        </div>
        <nav className="flex flex-col gap-4">
          <button onClick={() => setMainTab('calculadora')} title="Calculadora" className={`p-3 rounded-lg transition-all ${mainTab === 'calculadora' ? 'bg-blue-600/20 text-blue-400' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
          </button>
          <button onClick={() => setMainTab('catalogo')} title="Base NCM" className={`p-3 rounded-lg transition-all ${mainTab === 'catalogo' ? 'bg-blue-600/20 text-blue-400' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
          </button>
          <button onClick={() => { setMainTab('meus-produtos'); fetchMyProducts(); }} title="Meus Produtos" className={`p-3 rounded-lg transition-all ${mainTab === 'meus-produtos' ? 'bg-blue-600/20 text-blue-400' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4"/></svg>
          </button>
        </nav>
        <button onClick={() => supabase.auth.signOut()} className="mt-auto p-3 text-slate-500 hover:text-rose-400">
           <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
        </button>
      </aside>

      <main className="flex-1 flex overflow-hidden">
        {mainTab === 'calculadora' ? (
          <>
            {/* Painel de Configuração Lateral */}
            <div className="w-[320px] border-r border-slate-200 bg-white flex flex-col h-full overflow-hidden">
              <div className="flex-1 overflow-y-auto custom-scrollbar p-5 space-y-6">
                 <div className="flex items-center justify-between mb-2">
                    <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Configuração Fiscal</h2>
                    <button 
                      onClick={handleSave} 
                      disabled={isSaving}
                      className="text-[9px] font-black bg-emerald-50 text-emerald-600 px-3 py-1.5 rounded uppercase tracking-tighter hover:bg-emerald-100 disabled:opacity-50"
                    >
                      {isSaving ? 'Gravando...' : 'Salvar Produto'}
                    </button>
                 </div>

                 <FiscalHeader inputs={inputs} setInputs={setInputs} />
                 <div className="h-px bg-slate-100 w-full"></div>
                 <Sidebar inputs={inputs} setInputs={setInputs} />
              </div>
            </div>

            {/* Dashboard Principal */}
            <div className="flex-1 bg-[#f8fafc] overflow-y-auto custom-scrollbar">
              <div className="p-8 max-w-[1400px] mx-auto space-y-8">
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} />
              </div>
            </div>
          </>
        ) : mainTab === 'catalogo' ? (
          <div className="flex-1 p-10 overflow-y-auto">
            <ProductsView onSelectNcm={(ncm) => { 
              setInputs(prev => ({...prev, ncmCodigo: ncm.codigo, mvaOriginal: ncm.mvaOriginal, nomeProduto: ncm.descricao})); 
              setMainTab('calculadora'); 
            }} />
          </div>
        ) : (
          <div className="flex-1 p-10 overflow-y-auto bg-slate-50">
            <div className="max-w-5xl mx-auto">
              <div className="flex justify-between items-end mb-8">
                <div>
                  <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter">Meus Produtos</h2>
                  <p className="text-xs text-slate-500 font-bold uppercase tracking-[0.2em] mt-1">Acervo de simulações e itens salvos</p>
                </div>
                <div className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase">
                  {savedSimulations.length} Itens Salvos
                </div>
              </div>

              <div className="grid grid-cols-1 gap-3">
                {savedSimulations.length > 0 ? (
                  savedSimulations.map(sim => (
                    <div key={sim.id} className="bg-white p-5 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm hover:shadow-md transition-shadow group">
                      <div className="flex items-center gap-6">
                        <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center text-slate-400 group-hover:text-blue-500 transition-colors">
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>
                        </div>
                        <div>
                          <h3 className="font-black text-slate-800 text-lg">{sim.nome_produto}</h3>
                          <div className="flex items-center gap-3 mt-1">
                            <p className="text-[10px] text-slate-400 uppercase font-bold">{new Date(sim.created_at).toLocaleDateString()} às {new Date(sim.created_at).toLocaleTimeString()}</p>
                            <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
                            <span className="text-[10px] text-blue-500 font-black uppercase tracking-tighter">{sim.dados.ufOrigem} ➔ {sim.dados.ufDestino}</span>
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button 
                          onClick={() => { setInputs(sim.dados); setMainTab('calculadora'); }} 
                          className="bg-slate-900 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-600 transition-colors"
                        >
                          Carregar
                        </button>
                        <button 
                          onClick={() => handleDeleteProduct(sim.id)} 
                          className="p-2.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"
                        >
