    const { data, error } = await supabase
      .from('simulacoes')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error("Erro ao buscar produtos:", error);
    } else {
      setSavedSimulations(data || []);
    }
  };

  const handleSave = async () => {
    if (!session) return;

    // LIMITADOR DE 100 PRODUTOS
    if (savedSimulations.length >= 100) {
      alert('Limite de 100 produtos atingido. Por favor, remova alguns itens em "Meus Produtos" para salvar novos.');
      return;
    }

    setIsSaving(true);
    const { error } = await supabase.from('simulacoes').insert([{ 
      user_id: session.user.id, 
      nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
      dados: inputs 
    }]);

    setIsSaving(false);
    if (error) {
      alert('Erro ao salvar produto: ' + error.message);
