                          <h3 className="font-black text-slate-800 text-xl tracking-tight">{sim.nome_produto}</h3>
                          <div className="flex items-center gap-4 mt-1.5">
                            <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">
                              {new Date(sim.created_at).toLocaleDateString()}
                            </span>
                            <span className="w-1.5 h-1.5 bg-slate-200 rounded-full"></span>
                            <span className="text-[10px] text-blue-600 font-black uppercase tracking-tighter bg-blue-50 px-2 py-0.5 rounded-md">
                              {sim.dados.ufOrigem} ➔ {sim.dados.ufDestino}
                            </span>
                            <span className="text-[10px] text-slate-500 font-bold bg-slate-100 px-2 py-0.5 rounded-md uppercase">
                              {sim.dados.mode === 'substituido' ? 'ST' : 'Tributado'}
                            </span>
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        <button 
                          onClick={() => { setInputs(sim.dados); setMainTab('calculadora'); setConfigCollapsed(false); }} 
                          className="bg-slate-900 text-white px-7 py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest hover:bg-blue-600 shadow-lg transition-all active:scale-95"
                        >
                          Carregar
                        </button>
                        <button 
                          onClick={() => handleDeleteProduct(sim.id)} 
                          className="p-3 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all"
                          title="Excluir Produto"
                        >
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        </button>
                      </div>
                    </div>
                  ))
