import React, { useState } from 'react';
import { SimulationInputs } from '../types';
import { NCM_DATABASE, UF_LIST } from '../utils/ncmData';
import { calculateAdjustedMva, getInterstateRate } from '../utils/calculations';

interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {
  const [showNcmSearch, setShowNcmSearch] = useState(false);

  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const newOrigem = field === 'ufOrigem' ? val : inputs.ufOrigem;
    const newDestino = field === 'ufDestino' ? val : inputs.ufDestino;
    const destUf = UF_LIST.find(u => u.sigla === newDestino);
    const interRate = getInterstateRate(newOrigem, newDestino);
    const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf?.icms || 18);

    setInputs(prev => ({
      ...prev,
      [field]: val,
      icmsInterestadual: interRate,
      icmsInternoDestino: destUf?.icms || 18,
      mva: adjMva
    }));
  };

  return (
    <div className="bg-[#0f172a] rounded-2xl p-5 text-white space-y-5 shadow-2xl border border-slate-800 relative overflow-hidden">
      {/* Background Accent */}
      <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 rounded-full -mr-16 -mt-16 pointer-events-none"></div>

      {/* Primary Row: Identity */}
      <div className="grid grid-cols-1 gap-4">
        <div className="grid grid-cols-12 gap-3">
          <div className="col-span-5 space-y-1.5">
            <label className="text-[8px] font-black text-blue-400 uppercase tracking-[0.2em]">Classificação NCM</label>
            <div className="relative group">
              <input 
                type="text" 
                readOnly
                value={inputs.ncmCodigo}
                onClick={() => setShowNcmSearch(!showNcmSearch)}
                className="w-full bg-slate-800/80 border border-slate-700 rounded-xl px-9 py-2.5 text-xs font-black cursor-pointer group-hover:border-blue-500 transition-all text-blue-100"
              />
              <svg className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/>
              </svg>
            </div>
          </div>

          <div className="col-span-7 space-y-1.5">
            <label className="text-[8px] font-black text-slate-500 uppercase tracking-[0.2em]">Nome do Produto</label>
            <input 
              type="text" 
              value={inputs.nomeProduto}
              onChange={(e) => setInputs(prev => ({...prev, nomeProduto: e.target.value}))}
              placeholder="Descrição comercial..."
              className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-2.5 text-xs font-bold focus:border-blue-500 outline-none transition-all placeholder:text-slate-600"
            />
          </div>
        </div>
      </div>

      {/* Secondary Row: Logistics */}
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-1.5">
          <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest">UF Origem</label>
          <div className="relative">
            <select 
              value={inputs.ufOrigem} 
              onChange={(e) => handleUfChange('ufOrigem', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-[11px] font-black outline-none appearance-none cursor-pointer focus:ring-1 focus:ring-blue-500/50"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla} — {uf.nome}</option>)}
            </select>
            <svg className="w-3 h-3 absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
          </div>
        </div>
        <div className="space-y-1.5">
          <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest">UF Destino</label>
          <div className="relative">
            <select 
              value={inputs.ufDestino} 
              onChange={(e) => handleUfChange('ufDestino', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3 py-2 text-[11px] font-black outline-none appearance-none cursor-pointer focus:ring-1 focus:ring-blue-500/50"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla} — {uf.nome}</option>)}
            </select>
            <svg className="w-3 h-3 absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
          </div>
        </div>
      </div>

      {/* Footer: Intelligence Data */}
      <div className="flex justify-between items-center pt-4 border-t border-slate-800/80">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-blue-500/10 rounded-lg">
             <svg className="w-3.5 h-3.5 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"/></svg>
          </div>
          <div>
            <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest">ICMS Operação</p>
            <p className="text-[10px] font-black text-blue-400 font-mono">{inputs.icmsInterestadual.toFixed(1)}% <span className="text-slate-600 font-normal ml-1">Interestadual</span></p>
          </div>
        </div>

        <div className="text-right flex flex-col items-end">
          <div className="flex items-center gap-2 mb-0.5">
            <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse"></span>
            <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest">MVA Ajustada</p>
          </div>
          <p className="text-[12px] font-black text-amber-500 font-mono tracking-tighter">
            {inputs.mva.toFixed(2)}%
          </p>
        </div>
      </div>
    </div>
  );
};

export default FiscalHeader;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import Login from './components/Login';
import { SimulationInputs } from './types';
import { calculateCosts, generatePriceMatrix } from './utils/calculations';
import { supabase } from './lib/supabase';

const defaultInputs: SimulationInputs = {
  nomeProduto: '',
  valorCompra: 100.00,
  ipiFrete: 0.00,
  mva: 32.00,
  mvaOriginal: 32.00,
  icmsInternoDestino: 18.00,
  icmsInterestadual: 12.00,
  ufOrigem: 'SP',
  ufDestino: 'RJ',
  ncmCodigo: '2523.29.10',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.25,
  comissaoVenda: 0.0,
  icmsVenda: 18.00,
  outrosCustosVariaveis: 0.00,
  custosFixos: 15.00,
  resultadoDesejado: 8.00,
  tipoProduto: 'comod',
  mode: 'substituido',
  percReducaoBase: 0,
  simulationMode: 'buyToSell',
  precoVendaDesejado: 0
};

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [profile, setProfile] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [mainTab, setMainTab] = useState<'calculadora' | 'catalogo' | 'meus-produtos'>('calculadora');
  const [isSaving, setIsSaving] = useState(false);
  const [savedSimulations, setSavedSimulations] = useState<any[]>([]);
  const [configCollapsed, setConfigCollapsed] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) {
        fetchProfile(session.user.id);
        fetchMyProducts();
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) {
        fetchProfile(session.user.id);
        fetchMyProducts();
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (userId: string) => {
    const { data } = await supabase.from('perfis').select('*').eq('id', userId).maybeSingle();
    if (data) setProfile(data);
  };

  const fetchMyProducts = async () => {
    try {
      const { data, error } = await supabase
        .from('simulacoes')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setSavedSimulations(data || []);
    } catch (err) {
      console.error("Erro ao buscar produtos:", err);
    }
  };

  const handleSave = async () => {
    if (!session) return;

    // LIMITADOR DE 100 PRODUTOS
    if (savedSimulations.length >= 100) {
      alert('Limite atingido (100/100). Exclua itens antigos em "Meus Produtos" para salvar novos.');
      return;
    }

    setIsSaving(true);
    try {
      const { error } = await supabase.from('simulacoes').insert([{ 
        user_id: session.user.id, 
        nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
        dados: inputs 
      }]);

      if (error) throw error;

      alert('Simulação salva com sucesso!');
      await fetchMyProducts();
    } catch (err: any) {
      alert('Erro ao salvar: ' + err.message);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteProduct = async (id: string) => {
    if (!confirm('Deseja realmente apagar este produto da sua lista permanentemente?')) return;

    try {
      const { error } = await supabase
        .from('simulacoes')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setSavedSimulations(prev => prev.filter(p => p.id !== id));
    } catch (err: any) {
      console.error("Erro na exclusão:", err);
      alert('Não foi possível excluir o produto. Verifique sua conexão ou permissões.');
    }
  };

  if (!session) return <Login onLoginSuccess={setSession} />;

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  return (
    <div className="h-screen w-full flex bg-[#f1f5f9] overflow-hidden text-slate-900 font-sans">
      {/* Barra de Navegação Principal (Fixa) */}
      <aside className="w-[70px] bg-[#0f172a] flex flex-col items-center py-6 gap-8 border-r border-slate-800 shrink-0 z-50">
        <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg cursor-pointer transition-transform hover:scale-105 active:scale-95">
          <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
        </div>

        <nav className="flex flex-col gap-4">
          <button 
            onClick={() => setMainTab('calculadora')} 
            title="Calculadora" 
            className={`p-3 rounded-lg transition-all ${mainTab === 'calculadora' ? 'bg-blue-600/20 text-blue-400' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/50'}`}
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
          </button>

          <button 
            onClick={() => setMainTab('catalogo')} 
            title="Base NCM" 
            className={`p-3 rounded-lg transition-all ${mainTab === 'catalogo' ? 'bg-blue-600/20 text-blue-400' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/50'}`}
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>
          </button>

          <button 
            onClick={() => { setMainTab('meus-produtos'); fetchMyProducts(); }} 
            title="Meus Produtos" 
            className={`p-3 rounded-lg transition-all ${mainTab === 'meus-produtos' ? 'bg-blue-600/20 text-blue-400' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/50'}`}
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4"/></svg>
          </button>

          {/* NOVO: Botão de Expandir/Minimizar Barra Lateral de Configuração */}
          <div className="h-px bg-slate-800 my-2 mx-3"></div>
          <button 
            onClick={() => setConfigCollapsed(!configCollapsed)} 
            title={configCollapsed ? "Expandir Painel" : "Recolher Painel"}
            className={`p-3 rounded-lg transition-all ${!configCollapsed ? 'text-blue-400 bg-blue-400/10' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/50'}`}
          >
            <svg className={`w-6 h-6 transition-transform duration-500 ${configCollapsed ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 19l-7-7 7-7m8 14l-7-7 7-7"/>
            </svg>
          </button>
        </nav>

        <button onClick={() => supabase.auth.signOut()} className="mt-auto p-3 text-slate-500 hover:text-rose-400 transition-colors">
           <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
        </button>
      </aside>

      <main className="flex-1 flex overflow-hidden relative">
        {mainTab === 'calculadora' ? (
          <>
            {/* Painel de Configuração Lateral */}
            <div className={`transition-all duration-500 cubic-bezier(0.4, 0, 0.2, 1) bg-white border-r border-slate-200 h-full flex flex-col overflow-hidden ${configCollapsed ? 'w-0 opacity-0 invisible' : 'w-[320px] opacity-100 visible'}`}>
              <div className="flex-1 overflow-y-auto custom-scrollbar p-5 space-y-6 min-w-[320px]">
                 <div className="flex items-center justify-between mb-2">
                    <div className="flex flex-col">
                      <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Painel Fiscal</h2>
                      <span className="text-[8px] font-bold text-slate-300">{savedSimulations.length}/100 Salvos</span>
                    </div>
                    <button 
                      onClick={handleSave} 
                      disabled={isSaving}
                      className="text-[9px] font-black bg-blue-600 text-white px-4 py-2 rounded-xl uppercase tracking-tighter hover:bg-blue-700 disabled:opacity-50 transition-all shadow-lg shadow-blue-500/20"
                    >
                      {isSaving ? 'Gravando...' : 'Salvar'}
                    </button>
                 </div>
                 <FiscalHeader inputs={inputs} setInputs={setInputs} />
                 <div className="h-px bg-slate-100 w-full"></div>
                 <Sidebar inputs={inputs} setInputs={setInputs} />
              </div>
            </div>

            {/* Dashboard Principal */}
            <div className="flex-1 bg-[#f8fafc] overflow-y-auto custom-scrollbar">
              <div className="p-8 max-w-[1400px] mx-auto space-y-8">
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} />
              </div>
            </div>
          </>
        ) : mainTab === 'catalogo' ? (
          <div className="flex-1 p-10 overflow-y-auto">
            <ProductsView onSelectNcm={(ncm) => { 
              setInputs(prev => ({...prev, ncmCodigo: ncm.codigo, mvaOriginal: ncm.mvaOriginal, nomeProduto: ncm.descricao})); 
              setMainTab('calculadora'); 
              setConfigCollapsed(false);
            }} />
          </div>
        ) : (
          <div className="flex-1 p-10 overflow-y-auto bg-slate-50">
            <div className="max-w-5xl mx-auto">
              <div className="flex justify-between items-end mb-10">
                <div>
                  <h2 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter">Meus Produtos</h2>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-[0.3em] mt-1">Biblioteca de simulações ({savedSimulations.length}/100)</p>
                </div>
                <div className="bg-slate-900 text-white px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl">
                  {savedSimulations.length} Simulações
                </div>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {savedSimulations.length > 0 ? (
                  savedSimulations.map(sim => (
                    <div key={sim.id} className="bg-white p-6 rounded-[2rem] border border-slate-200 flex justify-between items-center shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all group">
                      <div className="flex items-center gap-8">
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-colors ${
                          sim.dados.mode === 'substituido' ? 'bg-blue-50 text-blue-600' : 'bg-emerald-50 text-emerald-600'
                        }`}>
                          <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>
                        </div>
                        <div>
                          <h3 className="font-black text-slate-800 text-xl tracking-tight">{sim.nome_produto}</h3>
                          <div className="flex items-center gap-4 mt-1.5">
                            <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">
                              {new Date(sim.created_at).toLocaleDateString()}
                            </span>
                            <span className="w-1.5 h-1.5 bg-slate-200 rounded-full"></span>
                            <span className="text-[10px] text-blue-600 font-black uppercase tracking-tighter bg-blue-50 px-2 py-0.5 rounded-md">
                              {sim.dados.ufOrigem} ➔ {sim.dados.ufDestino}
                            </span>
                            <span className="text-[10px] text-slate-500 font-bold bg-slate-100 px-2 py-0.5 rounded-md uppercase">
                              {sim.dados.mode === 'substituido' ? 'ST' : 'Tributado'}
                            </span>
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        <button 
                          onClick={() => { setInputs(sim.dados); setMainTab('calculadora'); setConfigCollapsed(false); }} 
                          className="bg-slate-900 text-white px-7 py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest hover:bg-blue-600 shadow-lg transition-all active:scale-95"
                        >
                          Carregar
                        </button>
                        <button 
                          onClick={() => handleDeleteProduct(sim.id)} 
                          className="p-3 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all"
                          title="Remover Simulação"
                        >
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        </button>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="bg-white border-2 border-dashed border-slate-200 rounded-[3rem] py-32 flex flex-col items-center justify-center text-center">
                    <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-8">
                      <svg className="w-12 h-12 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4"/></svg>
                    </div>
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Nenhum produto salvo</h3>
                    <p className="text-sm text-slate-400 mt-3 font-bold uppercase tracking-widest max-w-sm">
                      Salve suas simulações na aba da calculadora para acessá-las aqui rapidamente.
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

