            />
            <svg className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/>
            </svg>
          </div>
        </div>

        <div className="col-span-7 space-y-1.5">
          <label className="text-[8px] font-black text-slate-500 uppercase tracking-[0.2em]">Nome Comercial</label>
          <input 
            type="text" 
            value={inputs.nomeProduto}
            onChange={(e) => setInputs(prev => ({...prev, nomeProduto: e.target.value}))}
            placeholder="Ex: Piso Porcelanato..."
            className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-2.5 text-xs font-bold focus:border-blue-500 outline-none transition-all placeholder:text-slate-600"
