import React from 'react';
import { SimulationInputs } from '../types';
import { UF_LIST } from '../utils/ncmData';
import { calculateAdjustedMva, getInterstateRate } from '../utils/calculations';

interface FiscalHeaderProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
}

const FiscalHeader: React.FC<FiscalHeaderProps> = ({ inputs, setInputs }) => {
  const handleUfChange = (field: 'ufOrigem' | 'ufDestino', val: string) => {
    const newOrigem = field === 'ufOrigem' ? val : inputs.ufOrigem;
    const newDestino = field === 'ufDestino' ? val : inputs.ufDestino;
    const destUf = UF_LIST.find(u => u.sigla === newDestino);
    const interRate = getInterstateRate(newOrigem, newDestino);
    const adjMva = calculateAdjustedMva(inputs.mvaOriginal, interRate, destUf?.icms || 18);

    setInputs(prev => ({
      ...prev,
      [field]: val,
      icmsInterestadual: interRate,
      icmsInternoDestino: destUf?.icms || 18,
      mva: adjMva
    }));
  };

  return (
    <div className="bg-[#0f172a] rounded-3xl p-6 text-white space-y-6 shadow-2xl relative overflow-hidden ring-1 ring-slate-800">
      {/* Visual Glitch/Style */}
      <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/10 rounded-full blur-3xl -mr-16 -mt-16"></div>

      {/* Row 1: Identification */}
      <div className="grid grid-cols-1 gap-5">
        <div className="space-y-2">
          <label className="text-[9px] font-black text-blue-400 uppercase tracking-[0.25em]">Cesta NCM</label>
          <div className="flex items-center bg-slate-800/80 border border-slate-700 rounded-2xl px-4 py-3 group hover:border-blue-500 transition-all cursor-default">
            <span className="text-sm font-black text-blue-100 font-mono">{inputs.ncmCodigo}</span>
            <div className="ml-auto w-2 h-2 rounded-full bg-blue-500 animate-pulse"></div>
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-[9px] font-black text-slate-500 uppercase tracking-[0.25em]">Referência do Item</label>
          <input 
            type="text" 
            value={inputs.nomeProduto}
            onChange={(e) => setInputs(prev => ({...prev, nomeProduto: e.target.value}))}
            placeholder="Ex: Porcelanato Retificado"
            className="w-full bg-slate-800/40 border border-slate-700 rounded-2xl px-5 py-3.5 text-xs font-bold focus:border-blue-500 outline-none transition-all placeholder:text-slate-600"
          />
        </div>
      </div>

      {/* Row 2: Origin/Destiny */}
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest text-center block">Origem</label>
          <div className="relative">
            <select 
              value={inputs.ufOrigem} 
              onChange={(e) => handleUfChange('ufOrigem', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-4 py-3 text-xs font-black outline-none appearance-none cursor-pointer focus:ring-2 focus:ring-blue-500/20 transition-all"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla}</option>)}
            </select>
            <svg className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
          </div>
        </div>
        <div className="space-y-2">
          <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest text-center block">Destino</label>
          <div className="relative">
            <select 
              value={inputs.ufDestino} 
              onChange={(e) => handleUfChange('ufDestino', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-4 py-3 text-xs font-black outline-none appearance-none cursor-pointer focus:ring-2 focus:ring-blue-500/20 transition-all"
            >
              {UF_LIST.map(uf => <option key={uf.sigla} value={uf.sigla}>{uf.sigla}</option>)}
            </select>
            <svg className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"/></svg>
          </div>
        </div>
      </div>

      {/* Row 3: Live Stats Dashboard */}
      <div className="grid grid-cols-2 gap-px bg-slate-800/50 rounded-2xl overflow-hidden border border-slate-800">
         <div className="bg-slate-900/80 p-4 text-center">
            <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">ICMS Inter</p>
            <p className="text-sm font-black text-blue-400 font-mono tracking-tighter">{inputs.icmsInterestadual.toFixed(1)}%</p>
         </div>
         <div className="bg-slate-900/80 p-4 text-center">
            <p className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">MVA Ajustada</p>
            <p className="text-sm font-black text-amber-500 font-mono tracking-tighter">{inputs.mva.toFixed(2)}%</p>
         </div>
      </div>
    </div>
  );
};

