import { SimulationInputs, SimulationResults } from '../types';

export const getInterstateRate = (origem: string, destino: string): number => {
  if (origem === destino) return 0;
  const sulSudeste = ['SP', 'RJ', 'MG', 'ES', 'PR', 'SC', 'RS'];
  const norteNordesteCentroOeste = ['AC', 'AL', 'AM', 'AP', 'BA', 'CE', 'DF', 'GO', 'MA', 'MS', 'MT', 'PA', 'PB', 'PE', 'PI', 'RN', 'RO', 'RR', 'SE', 'TO'];
  if (sulSudeste.includes(origem) && norteNordesteCentroOeste.includes(destino)) return 7;
  return 12;
};

export const calculateAdjustedMva = (mvaOriginal: number, alqInter: number, alqIntra: number): number => {
  if (alqInter === 0 || alqInter >= alqIntra) return mvaOriginal;
  const mvaOriginalDecimal = mvaOriginal / 100;
  const alqInterDecimal = alqInter / 100;
  const alqIntraDecimal = alqIntra / 100;
  const adjusted = ((1 + mvaOriginalDecimal) * (1 - alqInterDecimal) / (1 - alqIntraDecimal)) - 1;
  return adjusted * 100;
};

export const calculateCosts = (inputs: SimulationInputs): SimulationResults => {
  const {
    valorCompra,
    ipiFrete,
    mva,
    icmsInternoDestino,
    icmsInterestadual,
    pisCofinsRate,
    excluirIcmsPis,
    pisCofinsVenda,
    comissaoVenda,
    icmsVenda,
    outrosCustosVariaveis,
    custosFixos,
    resultadoDesejado,
    mode,
    percReducaoBase
  } = inputs;

  // 1. Definição das Bases de Cálculo
  const valorTotalNota = valorCompra + ipiFrete;

  // O ICMS Próprio (Dedução do ST) geralmente incide sobre (Valor Produto + Frete), mas NÃO sobre IPI 
  // exceto quando a venda é para consumidor final. Aqui assumimos operação B2B (Revenda).
  const baseIcmsProprio = valorCompra; 
  const valorIcmsProprio = baseIcmsProprio * (icmsInterestadual / 100);

  let stAPagar = 0;
  let baseCalculoSt = 0;
  let icmsStBruto = 0;

  if (mode === 'substituido') {
    // Base ST = (Valor Mercadoria + IPI + Frete + Outras Despesas) * (1 + MVA)
    baseCalculoSt = valorTotalNota * (1 + mva / 100);
    icmsStBruto = baseCalculoSt * (icmsInternoDestino / 100);

    // CORREÇÃO: O ST a pagar é o imposto bruto menos o ICMS da operação própria (saída do fornecedor)
    stAPagar = Math.max(0, icmsStBruto - valorIcmsProprio);
  }

  // 2. Créditos de Entrada para o Comprador (PIS/COFINS)
  // Base de PIS/COFINS monofásico ou crédito normal
  let basePisCofins = valorCompra;
  if (excluirIcmsPis) basePisCofins = valorCompra - valorIcmsProprio;
  const creditoPisCofinsValor = basePisCofins * (pisCofinsRate / 100);

  // 3. Determinação do Custo Final Líquido
  let custoFinal = 0;
  if (mode === 'substituido') {
    // ST é custo se pago na entrada. Crédito de ICMS não existe pois a saída será isenta.
    custoFinal = valorTotalNota + stAPagar - creditoPisCofinsValor;
  } else {
    // Regime normal: Crédito de ICMS abate o custo
    custoFinal = valorTotalNota - valorIcmsProprio - creditoPisCofinsValor;
  }

  // 4. Alíquota de Saída Efetiva do Contribuinte
  let icmsVendaEfetivo = icmsVenda;
  if (mode === 'substituido') {
    // No regime ST, a saída é desonerada (CST 60/CSOSN 500)
    icmsVendaEfetivo = 0;
  } else if (mode === 'reduzido') {
    icmsVendaEfetivo = icmsVenda * (1 - (percReducaoBase / 100));
  }

  // 5. Cálculo de Markup e Preço de Venda (Inside Price)
  const deducoesFixasPerc = pisCofinsVenda + comissaoVenda + icmsVendaEfetivo + outrosCustosVariaveis + custosFixos;
  const divisor = (100 - (deducoesFixasPerc + resultadoDesejado)) / 100;

  const precoVendaAlvo = divisor > 0 ? custoFinal / divisor : 0;
  const precoEquilibrio = (100 - deducoesFixasPerc) > 0 ? custoFinal / ((100 - deducoesFixasPerc) / 100) : 0;

  const margemAbsoluta = precoVendaAlvo * (resultadoDesejado / 100);
  const impostosTotais = stAPagar + (precoVendaAlvo * (icmsVendaEfetivo / 100)) + (precoVendaAlvo * (pisCofinsVenda / 100));

  return {
    valorTotalNota,
    baseCalculoSt,
    icmsStBruto,
    creditoIcmsEntrada: valorIcmsProprio,
    stAPagar,
    basePisCofins,
    creditoPisCofinsValor,
    custoFinal,
    precoEquilibrio,
    precoVendaAlvo,
    totalDeducoesVendaPerc: deducoesFixasPerc + resultadoDesejado,
    icmsVendaEfetivo,
    margemAbsoluta,
    impostosTotais
  };
};

export const generatePriceMatrix = (custoFinal: number, inputs: SimulationInputs): any => {
  const { mode, percReducaoBase, icmsVenda } = inputs;

  let icmsVendaEfetivo = icmsVenda;
  if (mode === 'substituido') icmsVendaEfetivo = 0;
  else if (mode === 'reduzido') icmsVendaEfetivo = icmsVenda * (1 - (percReducaoBase / 100));

  const baseDeducoes = inputs.pisCofinsVenda + inputs.comissaoVenda + icmsVendaEfetivo + inputs.outrosCustosVariaveis + inputs.custosFixos;

  const categorias = [
    { label: 'Estratégico', margin: 8 },
    { label: 'Curva A', margin: 10 },
    { label: 'Curva B', margin: 12 },
    { label: 'Curva C', margin: 15 },
    { label: 'Serviço/Espec.', margin: 20 }
  ];

  const getPrice = (margin: number) => {
    const total = baseDeducoes + margin;
    return total < 100 ? custoFinal / ((100 - total) / 100) : 0;
  };

  return categorias.map(cat => {
    const basePrice = getPrice(cat.margin);
    return {
      label: cat.label,
      margin: cat.margin,
      levels: {
        A: basePrice * 0.95,
        B: basePrice,
        C: basePrice * 1.05,
        D: basePrice * 1.15
      }
    };
  });
};

export const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
};

export const formatPercent = (val: number) => {
  return new Intl.NumberFormat('pt-BR', { style: 'percent', minimumFractionDigits: 2 }).format(val / 100);
};

