/**
 * Fallback storage in memory for environments where localStorage is blocked
 * (common in iframes or specific browser security settings).
 */
const memoryStorage: Record<string, string> = {};

const safeStorage = {
  getItem: (key: string): string | null => {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return memoryStorage[key] || null;
    }
  },
  setItem: (key: string, value: string): void => {
    try {
      window.localStorage.setItem(key, value);
    } catch {
      memoryStorage[key] = value;
    }
  },
  removeItem: (key: string): void => {
    try {
      window.localStorage.removeItem(key);
    } catch {
      delete memoryStorage[key];
    }
  }
};

/**
 * Custom Lock implementation to avoid 'SecurityError' and 'this.lock is not a function'
 * in restricted environments like Vercel previews or iframes.
 */
const customLock = {
  acquire: async <T>(name: string, callback: () => Promise<T>): Promise<T> => {
    // Simply execute the callback as a pass-through for restricted environments
    return await callback();
  }
};

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    storage: safeStorage as any,
    // Providing the lock as an object with an acquire method is the standard way
    // to override the default navigator.locks implementation.
    lock: customLock as any
  }
});

