    if (!currentSession) return;
    try {
      const { data, error } = await supabase
        .from('simulacoes')
        .select('*')
        .order('created_at', { ascending: false });
      if (!error) setSavedSimulations(data || []);
    } catch (err) {
      console.error('Erro ao buscar produtos:', err);
    }
  };

  const handleSave = async () => {
    if (!session) return;
    setIsSaving(true);
    try {
      const { error } = await supabase.from('simulacoes').insert([{ 
        user_id: session.user.id, 
        nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
        dados: inputs 
      }]);

      if (!error) {
        alert('Produto salvo com sucesso!');
        await fetchMyProducts();
        setActiveTab('meus-produtos');
      } else {
        throw error;
      }
    } catch (err) {
      alert('Erro ao salvar produto. Verifique se a tabela "simulacoes" existe no Supabase.');
      console.error(err);
    } finally {
      setIsSaving(false);
    }
