      setSession(session);
      if (session) fetchMyProducts();
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event: string, session: any) => {
      setSession(session);
      if (session) fetchMyProducts(session);
    });

    return () => subscription.unsubscribe();
