  const fetchMyProducts = async (currentSession = session) => {
    if (!currentSession) return;
    try {
      const { data, error } = await supabase
        .from('simulacoes')
        .select('*')
        .order('created_at', { ascending: false });
      if (!error) setSavedSimulations(data || []);
      else console.error('Supabase fetch error:', error.message);
    } catch (err: any) {
      console.error('Erro ao buscar produtos:', err.message || err);
    }
  };

  const handleSave = async () => {
    if (!session) return;
    setIsSaving(true);
    try {
      const { error } = await supabase.from('simulacoes').insert([{ 
        user_id: session.user.id, 
        nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
        dados: inputs 
      }]);

      if (!error) {
        alert('Produto salvo com sucesso!');
        await fetchMyProducts();
        setActiveTab('meus-produtos');
      } else {
        throw error;
      }
    } catch (err: any) {
      const errorMessage = err?.message || 'Erro desconhecido ao salvar.';
      alert(`Falha ao salvar: ${errorMessage}`);
      console.error('Save error details:', err);
