/**
 * Polyfill definitivo para o Web Locks API.
 * O erro 'this.lock is not a function' ocorre porque o SDK do Supabase tenta acessar
 * navigator.locks.acquire(name, [options], callback).
 */
const lockMock = {
  acquire: async (name: string, optionsOrCallback: any, callback?: any) => {
    // Se o segundo argumento for a função, usa ela. Se não, usa o terceiro (assinatura nativa).
    const actualCallback = typeof optionsOrCallback === 'function' ? optionsOrCallback : callback;
    if (typeof actualCallback === 'function') {
      return await actualCallback();
    }
    return Promise.resolve();
  }
};

if (typeof window !== 'undefined') {
  try {
    // Tenta injetar via defineProperty para contornar restrições de escrita no navigator
    if (!window.navigator.locks) {
      Object.defineProperty(window.navigator, 'locks', {
        value: lockMock,
        writable: true,
        configurable: true
      });
    }
  } catch (e) {
    // Fallback agressivo caso defineProperty falhe
    try {
      (window.navigator as any).locks = lockMock;
    } catch (e2) {
      console.warn("Ambiente extremamente restrito: não foi possível injetar navigator.locks.");
    }
  }
}

const memoryStorage: Record<string, string> = {};

const safeStorage = {
  getItem: (key: string): string | null => {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return memoryStorage[key] || null;
    }
  },
  setItem: (key: string, value: string): void => {
    try {
      window.localStorage.setItem(key, value);
    } catch {
      memoryStorage[key] = value;
    }
  },
  removeItem: (key: string): void => {
    try {
      window.localStorage.removeItem(key);
    } catch {
      delete memoryStorage[key];
    }
  }
};

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    storage: safeStorage as any,
    // Passagem direta para o cliente Auth como redundância
    lock: lockMock as any,
    // Importante: Desativar broadcast evita erros de segurança de canal em iframes
    broadcast: false
  }
});

