/**
 * Polyfill Definitivo para Web Locks API
 * Resolve o erro 'this.lock is not a function' em iframes e ambientes de preview.
 */
const mockLock = {
  acquire: async (name: string, optionsOrCallback: any, callback?: any) => {
    // A assinatura nativa é (nome, opções, callback) ou (nome, callback)
    const fn = typeof optionsOrCallback === 'function' ? optionsOrCallback : callback;
    if (typeof fn === 'function') {
      return await fn();
    }
    return Promise.resolve();
  }
};

if (typeof window !== 'undefined') {
  // Força a injeção no navegador antes de qualquer inicialização
  try {
    if (!window.navigator.locks) {
      Object.defineProperty(window.navigator, 'locks', {
        value: mockLock,
        writable: false,
        configurable: true
      });
    }
  } catch (e) {
    // Fallback se o navegador bloquear o Object.defineProperty no navigator
    (window.navigator as any).locks = mockLock;
  }
}

// Armazenamento em memória para fallback caso o localStorage falhe
const memoryStorage: Record<string, string> = {};

const safeStorage = {
  getItem: (key: string): string | null => {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return memoryStorage[key] || null;
    }
  },
  setItem: (key: string, value: string): void => {
    try {
      window.localStorage.setItem(key, value);
    } catch {
      memoryStorage[key] = value;
    }
  },
  removeItem: (key: string): void => {
    try {
      window.localStorage.removeItem(key);
    } catch {
      delete memoryStorage[key];
    }
  }
};

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    storage: safeStorage as any,
    // Força o uso do mock de lock diretamente na configuração do cliente
    lock: mockLock as any,
    // Desativar broadcast evita erros de segurança em iframes/cross-domain
    broadcast: false
  }
});

