/**
 * Polyfill Híbrido para Web Locks API
 * Resolve o erro 'this.lock is not a function' que ocorre quando o ambiente
 * (iframe/preview) bloqueia navigator.locks.
 */
const createLockMock = () => {
  const acquire = async (name: string, optsOrCallback: any, callback?: any) => {
    const fn = typeof optsOrCallback === 'function' ? optsOrCallback : callback;
    if (typeof fn === 'function') {
      try {
        return await fn();
      } catch (e) {
        console.warn('Erro na execução do lock mock:', e);
        return Promise.resolve();
      }
    }
    return Promise.resolve();
  };

  // Retorna um objeto que também pode ter a propriedade acquire (dupla compatibilidade)
  return { acquire };
};

if (typeof window !== 'undefined') {
  try {
    const nav = window.navigator as any;
    if (!nav.locks || typeof nav.locks.acquire !== 'function') {
      const mock = createLockMock();
      Object.defineProperty(nav, 'locks', {
        value: mock,
        configurable: true,
        writable: true
      });
    }
  } catch (e) {
    console.error('Falha ao injetar polyfill de locks:', e);
  }
}

const memoryStorage: Record<string, string> = {};

const safeStorage = {
  getItem: (key: string): string | null => {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return memoryStorage[key] || null;
    }
  },
  setItem: (key: string, value: string): void => {
    try {
      window.localStorage.setItem(key, value);
    } catch {
      memoryStorage[key] = value;
    }
  },
  removeItem: (key: string): void => {
    try {
      window.localStorage.removeItem(key);
    } catch {
      delete memoryStorage[key];
    }
  }
};

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    storage: safeStorage as any,
    // Desativamos broadcast para evitar SecurityErrors em iframes
    broadcast: false,
    // O SDK pegará o navigator.locks polyfilled automaticamente
  }
});

