/**
 * Implementação customizada de Lock para o Supabase Auth.
 * Isso substitui o navigator.locks nativo que falha em ambientes restritos (iframes/previews).
 */
const customLock = {
  async acquire(name: string, callback: () => Promise<any>) {
    // Simula o comportamento do Web Lock executando a função imediatamente
    // já que em ambientes single-tab/preview a concorrência de sessão é mínima.
    try {
      return await callback();
    } catch (e) {
      console.error('Erro no lock customizado:', e);
      throw e;
    }
  }
};

// Polyfill global por segurança (redundância)
if (typeof window !== 'undefined') {
  try {
    const nav = window.navigator as any;
    if (!nav.locks) {
      Object.defineProperty(nav, 'locks', {
        value: customLock,
        configurable: true,
        writable: true
      });
    }
  } catch (e) {
    // Silencioso se falhar a injeção global
  }
}

const memoryStorage: Record<string, string> = {};

const safeStorage = {
  getItem: (key: string): string | null => {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return memoryStorage[key] || null;
    }
  },
  setItem: (key: string, value: string): void => {
    try {
      window.localStorage.setItem(key, value);
    } catch {
      memoryStorage[key] = value;
    }
  },
  removeItem: (key: string): void => {
    try {
      window.localStorage.removeItem(key);
    } catch {
      delete memoryStorage[key];
    }
  }
};

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    storage: safeStorage as any,
    // CRUCIAL: Passar o lock customizado diretamente aqui
    // Isso evita que o GoTrue (Supabase Auth) tente usar o this.lock interno que falha
    lock: customLock as any,
    // Desativar broadcast evita SecurityErrors em ambientes cross-domain
    broadcast: false,
  }
});

