/**
 * Polyfill de Lock robusto para ambientes restritos.
 * Alguns SDKs chamam .acquire(), outros tentam invocar o lock diretamente.
 */
const makeMockLock = () => {
  const lockFn = async (name: string, optionsOrCallback: any, callback?: any) => {
    const fn = typeof optionsOrCallback === 'function' ? optionsOrCallback : callback;
    return typeof fn === 'function' ? fn() : Promise.resolve();
  };
  // Adiciona o método acquire à função para compatibilidade total
  (lockFn as any).acquire = lockFn;
  return lockFn;
};

const mockLock = makeMockLock();

// Tenta injetar no navigator para o caso de scripts externos tentarem usar
if (typeof window !== 'undefined') {
  try {
    if (!window.navigator.locks) {
      Object.defineProperty(window.navigator, 'locks', {
        value: mockLock,
        writable: false,
        configurable: true
      });
    }
  } catch (e) {
    // Falha silenciosa se o navigator estiver congelado
  }
}

const memoryStorage: Record<string, string> = {};

const safeStorage = {
  getItem: (key: string): string | null => {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return memoryStorage[key] || null;
    }
  },
  setItem: (key: string, value: string): void => {
    try {
      window.localStorage.setItem(key, value);
    } catch {
      memoryStorage[key] = value;
    }
  },
  removeItem: (key: string): void => {
    try {
      window.localStorage.removeItem(key);
    } catch {
      delete memoryStorage[key];
    }
  }
};

