  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    storage: safeStorage as any,
    // CRUCIAL: Passar o mock de lock diretamente para o GoTrue
    lock: mockLock as any,
    // CRUCIAL: Desativar explicitamente o broadcast para evitar o erro de BroadcastChannel
    broadcast: false,
  }
});

