/**
 * Polyfill de Lock padrão Web Locks API.
 * Fornecer um objeto com .acquire() é a forma mais compatível de contornar o erro 'this.lock'.
 */
const customLock = {
  async acquire(name: string, optionsOrCallback: any, callback?: any) {
    const fn = typeof optionsOrCallback === 'function' ? optionsOrCallback : callback;
    if (typeof fn === 'function') {
      return fn();
    }
    return Promise.resolve();
  }
};

// Injeção global para redundância em scripts de terceiros
if (typeof window !== 'undefined') {
  try {
    const nav = window.navigator as any;
    if (!nav.locks) {
      Object.defineProperty(nav, 'locks', {
        value: customLock,
        configurable: true,
        writable: true
      });
    }
  } catch (e) {
    // Falha silenciosa se o ambiente bloquear defineProperty no navigator
  }
}

const memoryStorage: Record<string, string> = {};

/**
 * Storage resiliente que evita SecurityError: The operation is insecure.
 */
const safeStorage = {
  getItem: (key: string): string | null => {
    try {
      return window.localStorage.getItem(key);
    } catch {
      return memoryStorage[key] || null;
    }
  },
  setItem: (key: string, value: string): void => {
    try {
      window.localStorage.setItem(key, value);
    } catch {
      memoryStorage[key] = value;
    }
  },
  removeItem: (key: string): void => {
    try {
      window.localStorage.removeItem(key);
    } catch {
      delete memoryStorage[key];
    }
  }
};

