  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
    storage: safeStorage as any,
    // Define explicitamente o lock como o objeto customizado
    lock: customLock as any,
    // Desativa broadcast para evitar erro de canal inseguro em iframes
    broadcast: false,
  },
  global: {
    // Adiciona headers extras se necessário para evitar bloqueios de CORS em alguns ambientes
    headers: { 'x-application-name': 'tagway-pro' }
  }
});

