import React, { useState, useMemo } from 'react';
import { CostItem, VariableCostItem } from '../types';
import { formatCurrency } from '../utils/calculations';

const OverheadView: React.FC = () => {
  const [faturamento, setFaturamento] = useState<number>(50000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>([
    { id: '1', descricao: 'Aluguel e Condomínio', valor: 2500 },
    { id: '2', descricao: 'Folha de Pagamento', valor: 8000 },
    { id: '3', descricao: 'Software e Cloud', valor: 450 }
  ]);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>([
    { id: '1', descricao: 'Impostos (DAS/Simples)', percentual: 12 },
    { id: '2', descricao: 'Taxas de Cartão/Split', percentual: 2.5 }
  ]);

  // Cálculos Financeiros
  const totalFixed = useMemo(() => fixedCosts.reduce((acc, curr) => acc + curr.valor, 0), [fixedCosts]);
  const totalVarPerc = useMemo(() => variableCosts.reduce((acc, curr) => acc + curr.percentual, 0), [variableCosts]);

  const totalVarValue = (faturamento * totalVarPerc) / 100;
  const margemContribuicaoValue = faturamento - totalVarValue;
  const margemContribuicaoPerc = faturamento > 0 ? (margemContribuicaoValue / faturamento) * 100 : 0;

  const lucroLiquido = margemContribuicaoValue - totalFixed;
  const lucroPerc = faturamento > 0 ? (lucroLiquido / faturamento) * 100 : 0;

  // Ponto de Equilíbrio = Custos Fixos / % Margem de Contribuição
  const pontoEquilibrio = margemContribuicaoPerc > 0 ? totalFixed / (margemContribuicaoPerc / 100) : 0;

  const addFixed = () => setFixedCosts([...fixedCosts, { id: Math.random().toString(), descricao: 'Novo Custo Fixo', valor: 0 }]);
  const removeFixed = (id: string) => setFixedCosts(fixedCosts.filter(c => c.id !== id));

  const addVar = () => setVariableCosts([...variableCosts, { id: Math.random().toString(), descricao: 'Novo Custo Variável', percentual: 0 }]);
  const removeVar = (id: string) => setVariableCosts(variableCosts.filter(c => c.id !== id));

  return (
    <div className="max-w-6xl mx-auto space-y-8 pb-20 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-slate-200 pb-8">
        <div className="space-y-1">
          <h2 className="text-3xl lg:text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Estrutura de Overhead</h2>
          <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Análise de Viabilidade Operacional e Break-even</p>
        </div>
        <div className="w-full md:w-64 bg-black p-4 rounded-2xl shadow-xl shadow-black/10 text-white ring-1 ring-white/10">
          <label className="block text-[8px] font-black text-white/40 uppercase tracking-widest mb-1">Faturamento Mensal Alvo</label>
          <input 
            type="number" 
            value={faturamento} 
            onChange={(e) => setFaturamento(parseFloat(e.target.value) || 0)}
            className="w-full bg-transparent text-2xl font-black font-mono outline-none text-emerald-400"
          />
        </div>
      </header>

      {/* KPI Section */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <KPICard label="Total Custos Fixos" value={totalFixed} sub="Peso na Operação" />
        <KPICard label="Margem de Contr." value={margemContribuicaoValue} sub={`${margemContribuicaoPerc.toFixed(1)}% do Fat.`} color="text-blue-600" />
        <KPICard label="Ponto Equilíbrio" value={pontoEquilibrio} sub="Meta de Sobrevivência" color="text-amber-500" />
        <KPICard label="Resultado Final" value={lucroLiquido} sub={`${lucroPerc.toFixed(1)}% Margem Líquida`} color={lucroLiquido >= 0 ? 'text-emerald-500' : 'text-rose-500'} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Custos Fixos */}
        <section className="bg-white rounded-3xl border border-slate-200 p-6 md:p-8 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-sm font-black text-slate-900 uppercase tracking-widest">1. Custos Fixos (Mensais)</h3>
            <button onClick={addFixed} className="bg-slate-100 hover:bg-black hover:text-white p-2 rounded-xl transition-all">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
            </button>
          </div>
          <div className="space-y-3">
            {fixedCosts.map((item) => (
              <div key={item.id} className="flex gap-3 items-center group">
                <input 
                  className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:border-black transition-all"
                  value={item.descricao}
                  onChange={(e) => setFixedCosts(fixedCosts.map(c => c.id === item.id ? {...c, descricao: e.target.value} : c))}
                />
                <input 
                  type="number"
                  className="w-32 bg-slate-50 border border-slate-100 rounded-xl px-4 py-2 text-xs font-black font-mono outline-none focus:border-black transition-all"
                  value={item.valor}
                  onChange={(e) => setFixedCosts(fixedCosts.map(c => c.id === item.id ? {...c, valor: parseFloat(e.target.value) || 0} : c))}
                />
                <button onClick={() => removeFixed(item.id)} className="p-2 text-slate-200 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                </button>
              </div>
            ))}
          </div>
        </section>

        {/* Custos Variáveis */}
        <section className="bg-white rounded-3xl border border-slate-200 p-6 md:p-8 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-sm font-black text-slate-900 uppercase tracking-widest">2. Custos Variáveis (%)</h3>
            <button onClick={addVar} className="bg-slate-100 hover:bg-black hover:text-white p-2 rounded-xl transition-all">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
            </button>
          </div>
          <div className="space-y-3">
            {variableCosts.map((item) => (
              <div key={item.id} className="flex gap-3 items-center group">
                <input 
                  className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-4 py-2 text-xs font-bold outline-none focus:border-black transition-all"
                  value={item.descricao}
                  onChange={(e) => setVariableCosts(variableCosts.map(c => c.id === item.id ? {...c, descricao: e.target.value} : c))}
                />
                <div className="relative">
                  <input 
                    type="number"
                    className="w-24 bg-slate-50 border border-slate-100 rounded-xl px-4 py-2 text-xs font-black font-mono outline-none focus:border-black transition-all"
                    value={item.percentual}
                    onChange={(e) => setVariableCosts(variableCosts.map(c => c.id === item.id ? {...c, percentual: parseFloat(e.target.value) || 0} : c))}
                  />
                  <span className="absolute right-3 top-2 text-[8px] font-black text-slate-300">%</span>
                </div>
                <button onClick={() => removeVar(item.id)} className="p-2 text-slate-200 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                </button>
              </div>
            ))}
          </div>
        </section>
      </div>

      {/* Break-even visualization */}
      <section className="bg-black rounded-[2.5rem] p-8 md:p-12 text-white shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 rounded-full blur-3xl -mr-32 -mt-32"></div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="space-y-4 max-w-md">
            <h3 className="text-2xl font-black italic tracking-tighter uppercase leading-none">Análise de<br/>Ponto de Equilíbrio</h3>
            <p className="text-white/40 text-sm font-medium">Seu faturamento atual de {formatCurrency(faturamento)} representa <span className="text-white font-bold">{((faturamento/pontoEquilibrio)*100).toFixed(1)}%</span> do necessário para cobrir todos os custos fixos.</p>
          </div>
          <div className="text-center md:text-right">
             <span className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30">Volume Crítico Mensal</span>
             <div className="text-4xl md:text-6xl font-black font-mono tracking-tighter mt-2 text-amber-400">{formatCurrency(pontoEquilibrio)}</div>
          </div>
        </div>
      </section>
    </div>
  );
};

