import React, { useState, useMemo } from 'react';
import { CostItem, VariableCostItem } from '../types';
import { formatCurrency } from '../utils/calculations';

const OverheadView: React.FC = () => {
  const [faturamento, setFaturamento] = useState<number>(100000);
  const [expandedFixed, setExpandedFixed] = useState<string[]>(['PESSOAL / RH']);
  const [expandedVar, setExpandedVar] = useState<string[]>(['IMPOSTOS SOBRE VENDAS']);

  // --- DATABASE INICIAL: CUSTOS FIXOS ---
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>([
    { id: 'f1', categoria: 'PESSOAL / RH', descricao: 'Salários administrativos', valor: 12000 },
    { id: 'f2', categoria: 'PESSOAL / RH', descricao: 'Pró-labore dos sócios', valor: 8000 },
    { id: 'f3', categoria: 'PESSOAL / RH', descricao: 'Encargos (INSS/FGTS)', valor: 4500 },
    { id: 'f4', categoria: 'ESTRUTURA / OCUPAÇÃO', descricao: 'Aluguel do objeto', valor: 3500 },
    { id: 'f5', categoria: 'ESTRUTURA / OCUPAÇÃO', descricao: 'Condomínio', valor: 800 },
    { id: 'f6', categoria: 'UTILIDADES', descricao: 'Energia elétrica', valor: 600 },
    { id: 'f7', categoria: 'UTILIDADES', descricao: 'Link dedicado / Internet', valor: 350 },
    { id: 'f8', categoria: 'TECNOLOGIA / TI', descricao: 'Sistema ERP', valor: 1200 },
    { id: 'f9', categoria: 'SERVIÇOS TERCEIRIZADOS', descricao: 'Contabilidade', valor: 1100 },
  ]);

  // --- DATABASE INICIAL: CUSTOS VARIÁVEIS ---
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>([
    { id: 'v1', categoria: 'IMPOSTOS SOBRE VENDAS', descricao: 'Simples Nacional (%)', percentual: 12 },
    { id: 'v2', categoria: 'CUSTO DO PRODUTO / SERVIÇO', descricao: 'CMV (Custo Mercadoria)', percentual: 45 },
    { id: 'v3', categoria: 'COMERCIAL / VENDAS', descricao: 'Comissão de Time', percentual: 2 },
    { id: 'v4', categoria: 'MEIOS DE PAGAMENTO', descricao: 'Taxa de Cartão', percentual: 2.5 },
    { id: 'v5', categoria: 'LOGÍSTICA', descricao: 'Frete sobre vendas', percentual: 3 },
  ]);

  // Grupos Fixos
  const fixedCategories = [
    'PESSOAL / RH', 'ESTRUTURA / OCUPAÇÃO', 'UTILIDADES', 'TECNOLOGIA / TI', 
    'SERVIÇOS TERCEIRIZADOS', 'DESPESAS ADMINISTRATIVAS', 'IMPOSTOS E TAXAS FIXAS', 
    'FINANCEIRO', 'DEPRECIAÇÃO/AMORTIZAÇÃO', 'SOLUÇÃO DE MARKETING'
  ];

  // Grupos Variáveis
  const variableCategories = [
    'IMPOSTOS SOBRE VENDAS', 'CUSTO DO PRODUTO / SERVIÇO', 'LOGÍSTICA', 
    'COMERCIAL / VENDAS', 'MEIOS DE PAGAMENTO', 'VARIÁVEL DE MARKETING', 
    'FINANCEIRO VARIÁVEL', 'OUTROS CUSTOS VARIÁVEIS'
  ];

  // Cálculos Financeiros
  const totalFixed = useMemo(() => fixedCosts.reduce((acc, curr) => acc + curr.valor, 0), [fixedCosts]);
  const totalVarPerc = useMemo(() => variableCosts.reduce((acc, curr) => acc + curr.percentual, 0), [variableCosts]);
  const totalVarValue = (faturamento * totalVarPerc) / 100;
  const margemContribuicaoValue = faturamento - totalVarValue;
  const margemContribuicaoPerc = faturamento > 0 ? (margemContribuicaoValue / faturamento) * 100 : 0;
  const lucroLiquido = margemContribuicaoValue - totalFixed;
  const pontoEquilibrio = margemContribuicaoPerc > 0 ? totalFixed / (margemContribuicaoPerc / 100) : 0;

  // Handlers
  const toggleFixed = (cat: string) => setExpandedFixed(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  const toggleVar = (cat: string) => setExpandedVar(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);

  const addFixed = (cat: string) => setFixedCosts([...fixedCosts, { id: Math.random().toString(), categoria: cat, descricao: 'Nova Despesa', valor: 0 }]);
  const addVar = (cat: string) => setVariableCosts([...variableCosts, { id: Math.random().toString(), categoria: cat, descricao: 'Novo Custo', percentual: 0 }]);

  return (
    <div className="max-w-7xl mx-auto space-y-8 pb-32 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-slate-200 pb-10">
        <div className="space-y-2">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 bg-black rounded-2xl flex items-center justify-center text-white shadow-xl">
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
             </div>
             <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Controlador de Overhead</h2>
          </div>
          <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] ml-1">Engenharia de Custos & Gestão Financeira Empresarial</p>
        </div>
        <div className="w-full md:w-80 bg-white p-6 rounded-[2rem] shadow-2xl shadow-black/5 border border-slate-200 group focus-within:border-black transition-all">
          <label className="block text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2 group-focus-within:text-black transition-colors">Faturamento Mensal Estimado</label>
          <div className="flex items-center gap-3">
            <span className="text-2xl font-black text-slate-300">R$</span>
            <input 
              type="number" 
              value={faturamento} 
              onChange={(e) => setFaturamento(parseFloat(e.target.value) || 0)}
              className="w-full bg-transparent text-4xl font-black font-mono outline-none text-slate-900 tracking-tighter"
            />
          </div>
        </div>
      </header>

      {/* Financial Health Dashboard */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <KPICard label="Custos Fixos" value={totalFixed} sub="Custo de Existência" color="text-slate-900" />
        <KPICard label="Margem de Contribuição" value={margemContribuicaoValue} sub={`${margemContribuicaoPerc.toFixed(1)}% de Sobra`} color="text-blue-600" />
        <KPICard label="Resultado Líquido" value={lucroLiquido} sub={`${((lucroLiquido/faturamento)*100).toFixed(1)}% Margem Final`} color={lucroLiquido >= 0 ? 'text-emerald-500' : 'text-rose-500'} />
        <KPICard label="Break-Even (Meta)" value={pontoEquilibrio} sub="Faturamento para Zero" color="text-amber-500" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 items-start">

        {/* COLUNA: DESPESAS FIXAS */}
        <div className="space-y-4">
          <div className="flex items-center justify-between px-4 mb-2">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Despesas Fixas</h3>
            <span className="text-[10px] font-black text-slate-900 bg-slate-100 px-3 py-1 rounded-full">{formatCurrency(totalFixed)}</span>
          </div>

          <div className="space-y-2">
            {fixedCategories.map(cat => (
              <AccordionItem 
                key={cat} 
                title={cat} 
                isOpen={expandedFixed.includes(cat)} 
                onToggle={() => toggleFixed(cat)}
                count={fixedCosts.filter(c => c.categoria === cat).length}
              >
                <div className="space-y-3 p-4 bg-slate-50/50">
                  {fixedCosts.filter(c => c.categoria === cat).map(item => (
                    <div key={item.id} className="flex gap-4 items-center group">
                      <div className="flex-1">
                         <input 
                           className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:border-black transition-all"
                           value={item.descricao}
                           onChange={(e) => setFixedCosts(fixedCosts.map(c => c.id === item.id ? {...c, descricao: e.target.value} : c))}
                         />
                      </div>
                      <div className="w-32 relative">
                         <span className="absolute left-3 top-2.5 text-[8px] font-black text-slate-300">R$</span>
                         <input 
                           type="number"
                           className="w-full bg-white border border-slate-200 rounded-xl pl-8 pr-4 py-2.5 text-xs font-black font-mono outline-none focus:border-black transition-all"
                           value={item.valor}
                           onChange={(e) => setFixedCosts(fixedCosts.map(c => c.id === item.id ? {...c, valor: parseFloat(e.target.value) || 0} : c))}
                         />
                      </div>
                      <button onClick={() => setFixedCosts(fixedCosts.filter(c => c.id !== item.id))} className="text-slate-300 hover:text-rose-500 transition-colors">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                      </button>
                    </div>
                  ))}
                  <button onClick={() => addFixed(cat)} className="w-full py-2 border-2 border-dashed border-slate-200 rounded-xl text-[9px] font-black uppercase text-slate-400 hover:border-black hover:text-black transition-all">
                    Adicionar em {cat}
                  </button>
                </div>
              </AccordionItem>
            ))}
          </div>
        </div>

        {/* COLUNA: DESPESAS VARIÁVEIS */}
        <div className="space-y-4">
          <div className="flex items-center justify-between px-4 mb-2">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Despesas Variáveis</h3>
            <span className="text-[10px] font-black text-blue-600 bg-blue-50 px-3 py-1 rounded-full">{totalVarPerc.toFixed(2)}% do Faturamento</span>
          </div>

          <div className="space-y-2">
            {variableCategories.map(cat => (
              <AccordionItem 
                key={cat} 
                title={cat} 
                isOpen={expandedVar.includes(cat)} 
                onToggle={() => toggleVar(cat)}
                count={variableCosts.filter(v => v.categoria === cat).length}
                variant="blue"
              >
                <div className="space-y-3 p-4 bg-blue-50/20">
                  {variableCosts.filter(v => v.categoria === cat).map(item => (
                    <div key={item.id} className="flex gap-4 items-center group">
                      <div className="flex-1">
                         <input 
                           className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:border-blue-500 transition-all"
                           value={item.descricao}
                           onChange={(e) => setVariableCosts(variableCosts.map(c => c.id === item.id ? {...c, descricao: e.target.value} : c))}
                         />
                      </div>
                      <div className="w-24 relative">
                         <input 
                           type="number"
                           className="w-full bg-white border border-slate-200 rounded-xl pr-6 pl-4 py-2.5 text-xs font-black font-mono outline-none focus:border-blue-500 transition-all text-right"
                           value={item.percentual}
                           onChange={(e) => setVariableCosts(variableCosts.map(c => c.id === item.id ? {...c, percentual: parseFloat(e.target.value) || 0} : c))}
                         />
                         <span className="absolute right-3 top-2.5 text-[10px] font-black text-slate-300">%</span>
                      </div>
                      <button onClick={() => setVariableCosts(variableCosts.filter(c => c.id !== item.id))} className="text-slate-300 hover:text-rose-500 transition-colors">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                      </button>
                    </div>
                  ))}
                  <button onClick={() => addVar(cat)} className="w-full py-2 border-2 border-dashed border-blue-100 rounded-xl text-[9px] font-black uppercase text-blue-300 hover:border-blue-500 hover:text-blue-500 transition-all">
                    Adicionar em {cat}
                  </button>
                </div>
              </AccordionItem>
            ))}
          </div>
        </div>

      </div>

      {/* Break-even visualization */}
