  { id: 'v7-4', categoria: 'FINANCEIRO VARIÁVEL', descricao: 'Estornos / Chargebacks', percentual: 0 },

  // 8. OUTROS CUSTOS VARIÁVEIS
  { id: 'v8-1', categoria: 'OUTROS CUSTOS VARIÁVEIS', descricao: 'Royalties', percentual: 0 },
