import React, { useState, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import OverheadView from './components/OverheadView';
import ConfiguracaoView from './components/ConfiguracaoView';
import AdminView from './components/AdminView';
import Login from './components/Login';
import { SimulationInputs, CostItem, VariableCostItem } from './types';
import { calculateCosts, generatePriceMatrix, getInterstateRate } from './utils/calculations';
import { supabase } from './lib/supabase';
import { UF_LIST } from './utils/ncmData';

const defaultInputs: SimulationInputs = {
  nomeProduto: 'Exemplo Planilha Ref',
  valorCompra: 100.00,
  ipiPerc: 0.65,
  freteValor: 5.88,
  mva: 81.32,
  mvaOriginal: 81.32,
  icmsInternoDestino: 20.50,
  icmsInterestadual: 7.00,
  icmsCreditoMercadoria: 7.00,
  icmsCreditoFrete: 7.00,
  ufOrigem: 'SP',
  ufDestino: 'SP',
  ncmCodigo: '6907',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.25,
  comissaoVenda: 0.0,
  icmsVenda: 20.50,
  outrosCustosVariaveis: 0.00,
  custosFixos: 20.00,
  resultadoDesejado: 8.00,
  mode: 'substituido',
  percReducaoBase: 0,
  simulationMode: 'buyToSell',
  precoVendaDesejado: 0
};

const defaultFixedCosts: CostItem[] = [
  { id: 'f1-1', categoria: 'PESSOAL / RH', descricao: 'Salários administrativos', valor: 5000 },
  { id: 'f1-2', categoria: 'PESSOAL / RH', descricao: 'Pró-labore dos sócios', valor: 2000 },
  { id: 'f2-1', categoria: 'ESTRUTURA / OCUPAÇÃO', descricao: 'Aluguel do imóvel', valor: 2500 },
];

const defaultVariableCosts: VariableCostItem[] = [
  { id: 'v1-4', categoria: 'IMPOSTOS SOBRE VENDAS', descricao: 'PIS e COFINS Saída', percentual: 9.25 },
];

type Tab = 'calculadora' | 'catalogo' | 'meus-produtos' | 'overhead' | 'configuracao' | 'master';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isSaving, setIsSaving] = useState(false);
  const [savedSimulations, setSavedSimulations] = useState<any[]>([]);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);

  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>(defaultFixedCosts);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>(defaultVariableCosts);
  const [isAutoSync, setIsAutoSync] = useState(false);

  useEffect(() => {
    if (isAutoSync) {
      const totalFixed = fixedCosts.reduce((acc, curr) => acc + curr.valor, 0);
      const totalVarPerc = variableCosts.reduce((acc, curr) => acc + curr.percentual, 0);
      const fixedPercOnFat = faturamento > 0 ? (totalFixed / faturamento) * 100 : 0;
      const totalOverheadWeight = Math.floor((fixedPercOnFat + totalVarPerc) * 100) / 100;
      if (Math.abs(inputs.custosFixos - totalOverheadWeight) > 0.001) {
        setInputs(prev => ({ ...prev, custosFixos: totalOverheadWeight }));
      }
    }
  }, [faturamento, fixedCosts, variableCosts, isAutoSync, inputs.custosFixos]);

  useEffect(() => {
    let mounted = true;
    const init = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      if (mounted) {
        setSession(currentSession);
        if (currentSession) {
          await Promise.all([
            fetchMyProducts(currentSession),
            fetchOverheadConfig(currentSession),
            fetchUserProfile(currentSession)
          ]);
        }
        setIsInitialized(true);
      }
    };
    init();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, newSession) => {
      if (mounted) {
        setSession(newSession);
        if (newSession) {
          fetchMyProducts(newSession);
          fetchOverheadConfig(newSession);
          fetchUserProfile(newSession);
        } else {
          setUserProfile(null);
          setActiveTab('calculadora');
        }
      }
    });

    return () => { mounted = false; subscription.unsubscribe(); };
  }, []);

  const fetchUserProfile = async (userSession: any) => {
    if (!userSession?.user?.id) return;

    try {
      let { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .eq('user_id', userSession.user.id)
        .maybeSingle();

      if (!data && !error) {
        // Cria perfil se não existir
        const { data: newData, error: insertError } = await supabase
          .from('user_configs')
          .insert([{ 
            user_id: userSession.user.id, 
            email: userSession.user.email,
            nome_completo: userSession.user.user_metadata?.full_name || 'Usuário',
            is_admin: false,
            status: 'ativo'
          }])
          .select()
          .single();

        if (!insertError) data = newData;
      }

      if (data) {
        setUserProfile(data);
        // Atualiza inputs baseado nas preferências do usuário
        if (data.uf_padrao_destino || data.margem_padrao) {
          setInputs(prev => {
            const newUfDestino = data.uf_padrao_destino || prev.ufDestino;
            const destUf = UF_LIST.find(u => u.sigla === newUfDestino);
            const interRate = getInterstateRate(prev.ufOrigem, newUfDestino);

            return { 
              ...prev, 
              ufDestino: newUfDestino,
              icmsInternoDestino: destUf?.icms || prev.icmsInternoDestino,
              icmsInterestadual: interRate,
              resultadoDesejado: data.margem_padrao || prev.resultadoDesejado
            };
          });
        }
      }
    } catch (err) {
      console.error('Erro ao carregar perfil:', err);
    }
  };

  const fetchOverheadConfig = async (userSession: any) => {
    try {
      const { data } = await supabase.from('overhead_configs').select('*').eq('user_id', userSession.user.id).maybeSingle();
      if (data) {
        if (data.faturamento) setFaturamento(Number(data.faturamento));
        if (data.fixed_costs) setFixedCosts(data.fixed_costs);
        if (data.variable_costs) setVariableCosts(data.variable_costs);
        if (data.is_auto_sync !== undefined) setIsAutoSync(!!data.is_auto_sync);
      }
    } catch (e) { console.warn('Overhead default.'); }
  };

  const fetchMyProducts = async (currentSession = session) => {
    if (!currentSession?.user?.id) return;
    const { data } = await supabase.from('simulacoes').select('*').eq('user_id', currentSession.user.id).order('created_at', { ascending: false });
    if (data) setSavedSimulations(data);
  };

  const handleSave = async () => {
    if (!session?.user?.id) return;
    setIsSaving(true);
    try {
      const { error } = await supabase.from('simulacoes').insert([{ 
        user_id: session.user.id, 
        nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
        dados: inputs 
      }]);
      if (error) throw error;
      alert('Simulação salva com sucesso!');
      await fetchMyProducts();
      setActiveTab('meus-produtos');
    } catch (err: any) { alert('Erro: ' + err.message); } finally { setIsSaving(false); }
  };

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  if (!isInitialized) return null;
  if (!session) return <Login onLoginSuccess={setSession} />;

  // LOGICA DE BLOQUEIO TOTAL
  if (userProfile?.status === 'bloqueado' && !userProfile?.is_admin) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-slate-900 p-8">
        <div className="max-w-md w-full bg-white rounded-[3rem] p-10 text-center space-y-8 shadow-2xl border border-white/10 animate-slide-up">
          <div className="w-20 h-20 bg-rose-100 text-rose-600 rounded-3xl flex items-center justify-center mx-auto shadow-xl">
             <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m0 0v3m0-3h3m-3 0H9m12 1a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
          </div>
          <div className="space-y-4">
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">Acesso Bloqueado</h2>
            <p className="text-slate-500 font-bold text-sm leading-relaxed">Seu acesso ao sistema foi suspenso temporariamente por questões administrativas.</p>
          </div>
          <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Central de Suporte</p>
             <p className="text-xl font-black text-slate-900 font-mono">(75) 98323-1773</p>
          </div>
          <button onClick={() => supabase.auth.signOut()} className="w-full bg-slate-900 text-white py-4 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-black transition-all">Sair do Sistema</button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-full flex flex-col lg:flex-row bg-[#f8fafc] overflow-hidden text-slate-900 relative">

      {/* BANNER DE ATUALIZAÇÃO */}
      {userProfile?.status === 'atualizando' && (
        <div className="absolute top-0 left-0 w-full bg-blue-600 text-white z-[200] px-6 py-2 flex items-center justify-center gap-3 shadow-lg">
           <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
           <span className="text-[10px] font-black uppercase tracking-widest">Aviso: O sistema está em manutenção programada. Algumas funções podem apresentar bugs momentâneos.</span>
        </div>
      )}

      <aside className={`bg-black flex lg:flex-col transition-all duration-300 z-[100] border-t lg:border-t-0 lg:border-r border-white/5 shadow-2xl ${sidebarCollapsed ? 'lg:w-[80px]' : 'lg:w-[280px]'} fixed bottom-0 left-0 w-full lg:relative lg:h-screen h-[70px] lg:h-auto`}>
        <div className="hidden lg:flex p-8 mb-6 items-center justify-between">
          <div className="flex items-center gap-4 overflow-hidden">
            <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center shrink-0 border border-white/10 shadow-lg"><svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg></div>
            {!sidebarCollapsed && <div className="flex flex-col leading-none"><span className="text-white font-black tracking-tighter text-2xl italic uppercase">Tagway</span><span className="text-[9px] font-black text-white/30 uppercase tracking-[0.2em] mt-1">Intelligence</span></div>}
          </div>
        </div>
        <nav className="flex-1 flex lg:flex-col items-center lg:items-stretch justify-start lg:px-4 lg:space-y-2 p-1 overflow-x-auto lg:overflow-x-visible no-scrollbar">
          <MenuButton active={activeTab === 'calculadora'} onClick={() => setActiveTab('calculadora')} label="Calculadora" collapsed={sidebarCollapsed} icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/>
          <MenuButton active={activeTab === 'catalogo'} onClick={() => setActiveTab('catalogo')} label="Catálogo" collapsed={sidebarCollapsed} icon="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/>
          <MenuButton active={activeTab === 'meus-produtos'} onClick={() => setActiveTab('meus-produtos')} label="Meus Produtos" collapsed={sidebarCollapsed} icon="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/>
          <MenuButton active={activeTab === 'overhead'} onClick={() => setActiveTab('overhead')} label="Overhead" collapsed={sidebarCollapsed} icon="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 002 2h2a2 2 0 002-2"/>
          <MenuButton active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Ajustes" collapsed={sidebarCollapsed} icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/>
          {userProfile?.is_admin === true && (
            <MenuButton active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" collapsed={sidebarCollapsed} icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04M12 2.944v10m0 0a2 2 0 100 4 2 2 0 000-4z"/>
          )}
        </nav>
      </aside>

      <main className="flex-1 overflow-hidden flex flex-col relative pb-[70px] lg:pb-0">
        <div className="absolute top-12 right-8 z-[90] hidden md:flex items-center gap-4 animate-slide-up">
           <div className="glass-card border border-slate-200/50 px-5 py-2.5 rounded-2xl flex items-center gap-3 shadow-xl shadow-black/5">
              <div className={`w-2 h-2 rounded-full animate-pulse ${userProfile?.status === 'ativo' ? 'bg-emerald-500' : 'bg-blue-500'}`}></div>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-800">
                {userProfile?.is_admin ? 'MASTER' : 'USUÁRIO'}, {userProfile?.nome_completo?.split(' ')[0] || 'Operador'}
              </span>
           </div>
        </div>

        {activeTab === 'calculadora' && (
          <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
            <div className="w-full lg:w-[380px] border-b lg:border-b-0 lg:border-r border-slate-200 bg-white overflow-y-auto custom-scrollbar p-6 pt-0 space-y-8 shadow-inner">
              <div className="flex items-center justify-between sticky top-0 bg-white/95 backdrop-blur-sm z-30 -mx-6 px-6 py-5 border-b border-slate-100 mb-6">
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Parâmetros</h2>
                <button onClick={handleSave} disabled={isSaving} className="bg-black hover:bg-slate-800 text-white text-[9px] font-black uppercase px-6 py-2.5 rounded-xl transition-all shadow-xl shadow-black/10">{isSaving ? 'Gravando...' : 'Salvar'}</button>
              </div>
              <div className="space-y-8">
                <FiscalHeader inputs={inputs} setInputs={setInputs}/>
                <Sidebar inputs={inputs} setInputs={setInputs} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
              </div>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-8 lg:p-12">
              <div className="max-w-5xl mx-auto animate-slide-up"><ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs}/></div>
            </div>
          </div>
        )}

        {activeTab === 'configuracao' && (
          <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50">
            <ConfiguracaoView userId={session?.user?.id} />
          </div>
        )}

        {activeTab === 'master' && userProfile?.is_admin && (
          <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50">
            <AdminView />
          </div>
        )}

        {activeTab === 'overhead' && (
          <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50">
            <OverheadView faturamento={faturamento} setFaturamento={setFaturamento} fixedCosts={fixedCosts} setFixedCosts={setFixedCosts} variableCosts={variableCosts} setVariableCosts={setVariableCosts} userId={session?.user?.id} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
          </div>
        )}
        {activeTab === 'catalogo' && <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-white"><ProductsView onSelectNcm={(ncm) => { setInputs(prev => ({...prev, ncmCodigo: ncm.codigo, mvaOriginal: ncm.mvaOriginal, nomeProduto: ncm.descricao})); setActiveTab('calculadora'); }}/></div>}
        {activeTab === 'meus-produtos' && <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50"><div className="max-w-4xl mx-auto space-y-8"><header className="border-b border-slate-200 pb-8"><h2 className="text-3xl lg:text-4xl font-black text-slate-900 tracking-tighter uppercase italic leading-tight">Meus Produtos</h2></header><div className="grid gap-4">{savedSimulations.map(sim => (<div key={sim.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] flex flex-col md:flex-row md:items-center justify-between gap-6 hover:shadow-2xl transition-all group hover:border-black"><div className="flex items-center gap-6"><div className="w-14 h-14 bg-slate-50 text-slate-400 rounded-2xl flex items-center justify-center shrink-0 group-hover:bg-black group-hover:text-white transition-all shadow-sm"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg></div><div><h4 className="font-black text-slate-800 tracking-tight text-lg truncate">{sim.nome_produto}</h4><span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{new Date(sim.created_at).toLocaleDateString('pt-BR')}</span></div></div><button onClick={() => { setInputs(sim.dados); setActiveTab('calculadora'); }} className="bg-black text-white px-8 py-3.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all shadow-lg">Abrir Cálculo</button></div>))}</div></div></div>}
      </main>
    </div>
  );
};

interface MenuButtonProps { active: boolean; onClick: () => void; icon: string; label: string; collapsed: boolean; }
const MenuButton: React.FC<MenuButtonProps> = ({ active, onClick, icon, label, collapsed }) => (
  <button onClick={onClick} className={`flex flex-col lg:flex-row items-center lg:w-full gap-2 lg:gap-4 p-3 lg:p-4 lg:rounded-2xl transition-all relative group shrink-0 ${active ? 'bg-white text-black lg:shadow-xl' : 'text-white/40 hover:text-white lg:hover:bg-white/10'}`}>
    <div className="w-6 h-6 flex items-center justify-center shrink-0">
      <svg className={`w-5 h-5 shrink-0 transition-colors ${active ? 'text-black' : 'text-white/40 group-hover:text-white'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={icon}/></svg>
    </div>
    {!collapsed && <span className="text-[9px] lg:text-[11px] font-black uppercase tracking-[0.1em] lg:tracking-[0.15em] whitespace-nowrap">{label}</span>}
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
  created_at: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [aiRequest, setAiRequest] = useState('');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      console.log('Iniciando busca de usuários...');
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        console.error('Erro detalhado do Supabase:', error);

        // Constrói uma mensagem amigável e técnica ao mesmo tempo
        let msg = 'Erro desconhecido ao acessar banco de dados.';
        if (error.message) msg = error.message;
        if (error.code === '42501') msg = 'Permissão Negada (RLS). Verifique as políticas de segurança no Supabase.';

        alert(`Erro ao buscar usuários:\n\nCódigo: ${error.code}\nStatus: ${error.status}\nMensagem: ${msg}`);
        return;
      }

      if (data) {
        console.log(`Sucesso: ${data.length} usuários carregados.`);
        setUsers(data as UserProfile[]);
      }
    } catch (err: any) {
      console.error('Erro de exceção:', err);
      alert(`Erro inesperado no sistema: ${err.message || JSON.stringify(err)}`);
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          email: user.email,
          empresa_nome: user.empresa_nome,
          regime_tributario: user.regime_tributario,
          status: user.status
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert('Usuário atualizado com sucesso!');
      fetchUsers();
    } catch (err: any) {
      alert('Erro ao atualizar: ' + (err.message || 'Erro desconhecido'));
    } finally {
      setIsUpdating(null);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.senha || !newUser.nome) {
      alert('Preencha os campos obrigatórios (Nome, E-mail e Senha).');
      return;
    }

    setIsRegistering(true);
    try {
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: newUser.email,
        password: newUser.senha,
      });

      if (authError) throw authError;

      if (authData.user) {
        const { error: configError } = await supabase.from('user_configs').insert({
          user_id: authData.user.id,
          nome_completo: newUser.nome,
          email: newUser.email,
          empresa_nome: newUser.empresa,
          regime_tributario: newUser.regime,
          uf_padrao_destino: 'SP',
          is_admin: false,
          status: 'ativo'
        });

        if (configError) throw configError;

        alert('Usuário cadastrado com sucesso!');
        setNewUser({ nome: '', email: '', senha: '', empresa: '', regime: 'Real' });
        fetchUsers();
      }
    } catch (err: any) {
      alert('Erro ao cadastrar: ' + (err.message || JSON.stringify(err)));
    } finally {
      setIsRegistering(false);
    }
  };

  const toggleAccordion = (userId: string) => {
    setExpandedUserId(expandedUserId === userId ? null : userId);
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-20 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 pb-8">
        <div>
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 text-white p-2 rounded-lg shadow-lg shadow-purple-500/20">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04M12 2.944v10m0 0a2 2 0 100 4 2 2 0 000-4z"/>
              </svg>
            </div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Master Control</h2>
          </div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Painel de Administração Global</p>
        </div>
        <button onClick={fetchUsers} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-sm active:scale-95">
          Atualizar Lista
        </button>
      </header>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Painel Lateral de Cadastro */}
        <div className="xl:col-span-1">
          <section className="bg-white rounded-[2.5rem] p-8 border border-slate-200 shadow-xl space-y-6 sticky top-8">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Novo Acesso</h3>
            <form onSubmit={handleCreateUser} className="space-y-4">
              <AdminInput label="Nome Completo" value={newUser.nome} onChange={(v) => setNewUser({...newUser, nome: v})} />
              <AdminInput label="E-mail (Login)" type="email" value={newUser.email} onChange={(v) => setNewUser({...newUser, email: v})} />
              <AdminInput label="Senha" type="password" value={newUser.senha} onChange={(v) => setNewUser({...newUser, senha: v})} />
              <AdminInput label="Empresa" value={newUser.empresa} onChange={(v) => setNewUser({...newUser, empresa: v})} />
              <button 
                type="submit"
                disabled={isRegistering}
                className="w-full bg-black text-white py-4 rounded-xl font-black uppercase tracking-widest text-[10px] shadow-xl hover:bg-slate-800 transition-all disabled:opacity-50"
              >
                {isRegistering ? 'Processando...' : 'Criar Conta Enterprise'}
              </button>
            </form>
          </section>
        </div>

        {/* Lista de Usuários em Sanfona */}
        <div className="xl:col-span-2 space-y-6">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Usuários Cadastrados ({users.length})</h3>

          <div className="space-y-3">
            {users.map(user => (
              <div key={user.user_id} className={`bg-white border rounded-[2rem] overflow-hidden transition-all duration-300 ${expandedUserId === user.user_id ? 'border-black shadow-2xl scale-[1.01]' : 'border-slate-200 shadow-sm hover:border-slate-300'}`}>
                {/* Cabeçalho do Accordion */}
                <button 
                  onClick={() => toggleAccordion(user.user_id)}
                  className={`w-full flex items-center justify-between p-6 text-left transition-colors ${expandedUserId === user.user_id ? 'bg-slate-50' : 'hover:bg-slate-50/50'}`}
                >
                  <div className="flex items-center gap-4">
                    <div className={`w-3 h-3 rounded-full ${user.status === 'ativo' ? 'bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)]' : user.status === 'atualizando' ? 'bg-blue-500' : 'bg-rose-500'}`}></div>
                    <div>
                      <h4 className="font-black text-slate-900 tracking-tight leading-none mb-1">{user.nome_completo || 'Sem Nome'}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{user.email}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-6">
                    <div className="hidden md:block text-right">
                       <span className="text-[9px] font-black text-slate-300 uppercase block leading-none mb-1">Status Atual</span>
                       <span className={`text-[10px] font-black uppercase italic ${user.status === 'ativo' ? 'text-emerald-500' : user.status === 'atualizando' ? 'text-blue-500' : 'text-rose-500'}`}>{user.status}</span>
                    </div>
                    <svg className={`w-5 h-5 text-slate-300 transition-transform ${expandedUserId === user.user_id ? 'rotate-180 text-black' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7"/>
                    </svg>
                  </div>
                </button>

                {/* Conteúdo Expansível (Edição Manual) */}
                <div className={`transition-all duration-500 overflow-hidden ${expandedUserId === user.user_id ? 'max-h-[1000px] opacity-100' : 'max-h-0 opacity-0'}`}>
                  <div className="p-8 border-t border-slate-100 space-y-8">
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <AdminInput label="Nome Completo" value={user.nome_completo} onChange={(v) => updateUserInState(user.user_id, 'nome_completo', v)} />
                        <AdminInput label="E-mail de Acesso" value={user.email} onChange={(v) => updateUserInState(user.user_id, 'email', v)} />
                        <AdminInput label="Empresa / Organização" value={user.empresa_nome} onChange={(v) => updateUserInState(user.user_id, 'empresa_nome', v)} />

                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime Tributário</label>
                          <select 
                            value={user.regime_tributario}
                            onChange={(e) => updateUserInState(user.user_id, 'regime_tributario', e.target.value)}
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-black outline-none focus:border-black appearance-none"
                          >
                            <option value="Real">Lucro Real</option>
                            <option value="Presumido">Lucro Presumido</option>
                            <option value="Simples">Simples Nacional</option>
                          </select>
                        </div>
                     </div>

                     <div className="space-y-4">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 block">Controle de Status do Sistema</label>
                        <div className="grid grid-cols-3 gap-3">
                           <StatusButton 
                              label="ATIVO" 
                              active={user.status === 'ativo'} 
                              onClick={() => updateUserInState(user.user_id, 'status', 'ativo')}
                              color="emerald"
                           />
                           <StatusButton 
                              label="ATUALIZANDO" 
                              active={user.status === 'atualizando'} 
                              onClick={() => updateUserInState(user.user_id, 'status', 'atualizando')}
                              color="blue"
                           />
                           <StatusButton 
                              label="BLOQUEADO" 
                              active={user.status === 'bloqueado'} 
                              onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')}
                              color="rose"
                           />
                        </div>
                        <p className="text-[9px] font-bold text-slate-400 italic px-1">
                          {user.status === 'ativo' && "✓ Acesso total e sem restrições liberado."}
                          {user.status === 'atualizando' && "⚠ Banner de manutenção será exibido ao usuário."}
                          {user.status === 'bloqueado' && "✖ O usuário não poderá utilizar nenhuma função do app."}
                        </p>
                     </div>

                     <div className="pt-6 border-t border-slate-50 flex justify-end gap-3">
                        <button 
                          onClick={() => handleUpdateUser(user)}
                          disabled={isUpdating === user.user_id}
                          className="bg-black text-white px-10 py-3 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-slate-800 transition-all active:scale-95 disabled:opacity-50"
                        >
                          {isUpdating === user.user_id ? 'Gravando Dados...' : 'Salvar Alterações'}
                        </button>
                     </div>
                  </div>
                </div>
              </div>
            ))}

            {users.length === 0 && (
              <div className="text-center py-20 bg-slate-100 rounded-[2rem] border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-black uppercase text-xs tracking-widest">Nenhum usuário encontrado na base.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

interface AdminInputProps {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  placeholder?: string;
}

const AdminInput: React.FC<AdminInputProps> = ({ label, value, onChange, type = 'text', placeholder }) => (
  <div className="space-y-1.5">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type={type}
      value={value || ''}
      placeholder={placeholder}
      onChange={(e) => onChange(e.target.value)}
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:border-black transition-all"
    />
  </div>
);

interface StatusButtonProps {
  label: string;
  active: boolean;
  onClick: () => void;
  color: 'emerald' | 'blue' | 'rose';
}

const StatusButton: React.FC<StatusButtonProps> = ({ label, active, onClick, color }) => {
  const styles = {
    emerald: active ? 'bg-emerald-500 text-white border-emerald-500 shadow-lg shadow-emerald-500/20' : 'bg-white text-slate-400 border-slate-100 hover:border-emerald-200 hover:text-emerald-500',
    blue: active ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-600/20' : 'bg-white text-slate-400 border-slate-100 hover:border-blue-200 hover:text-blue-500',
    rose: active ? 'bg-rose-600 text-white border-rose-600 shadow-lg shadow-rose-600/20' : 'bg-white text-slate-400 border-slate-100 hover:border-rose-200 hover:text-rose-500',
  };

  return (
    <button 
      type="button"
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      className={`py-3 rounded-xl border-2 font-black uppercase text-[9px] tracking-widest transition-all ${styles[color]}`}
    >
      {label}
    </button>
  );
};

export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import ResultsTable from './components/ResultsTable';
import FiscalHeader from './components/FiscalHeader';
import ProductsView from './components/ProductsView';
import OverheadView from './components/OverheadView';
import ConfiguracaoView from './components/ConfiguracaoView';
import AdminView from './components/AdminView';
import Login from './components/Login';
import { SimulationInputs, CostItem, VariableCostItem } from './types';
import { calculateCosts, generatePriceMatrix, getInterstateRate } from './utils/calculations';
import { supabase } from './lib/supabase';
import { UF_LIST } from './utils/ncmData';

const defaultInputs: SimulationInputs = {
  nomeProduto: 'Exemplo Planilha Ref',
  valorCompra: 100.00,
  ipiPerc: 0.65,
  freteValor: 5.88,
  mva: 81.32,
  mvaOriginal: 81.32,
  icmsInternoDestino: 20.50,
  icmsInterestadual: 7.00,
  icmsCreditoMercadoria: 7.00,
  icmsCreditoFrete: 7.00,
  ufOrigem: 'SP',
  ufDestino: 'SP',
  ncmCodigo: '6907',
  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.25,
  comissaoVenda: 0.0,
  icmsVenda: 20.50,
  outrosCustosVariaveis: 0.00,
  custosFixos: 20.00,
  resultadoDesejado: 8.00,
  mode: 'substituido',
  percReducaoBase: 0,
  simulationMode: 'buyToSell',
  precoVendaDesejado: 0
};

const defaultFixedCosts: CostItem[] = [
  { id: 'f1-1', categoria: 'PESSOAL / RH', descricao: 'Salários administrativos', valor: 5000 },
  { id: 'f1-2', categoria: 'PESSOAL / RH', descricao: 'Pró-labore dos sócios', valor: 2000 },
  { id: 'f2-1', categoria: 'ESTRUTURA / OCUPAÇÃO', descricao: 'Aluguel do imóvel', valor: 2500 },
];

const defaultVariableCosts: VariableCostItem[] = [
  { id: 'v1-4', categoria: 'IMPOSTOS SOBRE VENDAS', descricao: 'PIS e COFINS Saída', percentual: 9.25 },
];

type Tab = 'calculadora' | 'catalogo' | 'meus-produtos' | 'overhead' | 'configuracao' | 'master';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isSaving, setIsSaving] = useState(false);
  const [savedSimulations, setSavedSimulations] = useState<any[]>([]);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);

  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>(defaultFixedCosts);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>(defaultVariableCosts);
  const [isAutoSync, setIsAutoSync] = useState(false);

  useEffect(() => {
    if (isAutoSync) {
      const totalFixed = fixedCosts.reduce((acc, curr) => acc + curr.valor, 0);
      const totalVarPerc = variableCosts.reduce((acc, curr) => acc + curr.percentual, 0);
      const fixedPercOnFat = faturamento > 0 ? (totalFixed / faturamento) * 100 : 0;
      const totalOverheadWeight = Math.floor((fixedPercOnFat + totalVarPerc) * 100) / 100;
      if (Math.abs(inputs.custosFixos - totalOverheadWeight) > 0.001) {
        setInputs(prev => ({ ...prev, custosFixos: totalOverheadWeight }));
      }
    }
  }, [faturamento, fixedCosts, variableCosts, isAutoSync, inputs.custosFixos]);

  useEffect(() => {
    let mounted = true;
    const init = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      if (mounted) {
        setSession(currentSession);
        if (currentSession) {
          await Promise.all([
            fetchMyProducts(currentSession),
            fetchOverheadConfig(currentSession),
            fetchUserProfile(currentSession)
          ]);
        }
        setIsInitialized(true);
      }
    };
    init();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, newSession) => {
      if (mounted) {
        setSession(newSession);
        if (newSession) {
          fetchMyProducts(newSession);
          fetchOverheadConfig(newSession);
          fetchUserProfile(newSession);
        } else {
          setUserProfile(null);
          setActiveTab('calculadora');
        }
      }
    });

    return () => { mounted = false; subscription.unsubscribe(); };
  }, []);

  const fetchUserProfile = async (userSession: any) => {
    if (!userSession?.user?.id) return;

    try {
      let { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .eq('user_id', userSession.user.id)
        .maybeSingle();

      if (!data && !error) {
        // Cria perfil se não existir
        const { data: newData, error: insertError } = await supabase
          .from('user_configs')
          .insert([{ 
            user_id: userSession.user.id, 
            email: userSession.user.email,
            nome_completo: userSession.user.user_metadata?.full_name || 'Usuário',
            is_admin: false,
            status: 'ativo'
          }])
          .select()
          .single();

        if (!insertError) data = newData;
      }

      if (data) {
        setUserProfile(data);
        // Atualiza inputs baseado nas preferências do usuário
        if (data.uf_padrao_destino || data.margem_padrao) {
          setInputs(prev => {
            const newUfDestino = data.uf_padrao_destino || prev.ufDestino;
            const destUf = UF_LIST.find(u => u.sigla === newUfDestino);
            const interRate = getInterstateRate(prev.ufOrigem, newUfDestino);

            return { 
              ...prev, 
              ufDestino: newUfDestino,
              icmsInternoDestino: destUf?.icms || prev.icmsInternoDestino,
              icmsInterestadual: interRate,
              resultadoDesejado: data.margem_padrao || prev.resultadoDesejado
            };
          });
        }
      }
    } catch (err) {
      console.error('Erro ao carregar perfil:', err);
    }
  };

  const fetchOverheadConfig = async (userSession: any) => {
    try {
      const { data } = await supabase.from('overhead_configs').select('*').eq('user_id', userSession.user.id).maybeSingle();
      if (data) {
        if (data.faturamento) setFaturamento(Number(data.faturamento));
        if (data.fixed_costs) setFixedCosts(data.fixed_costs);
        if (data.variable_costs) setVariableCosts(data.variable_costs);
        if (data.is_auto_sync !== undefined) setIsAutoSync(!!data.is_auto_sync);
      }
    } catch (e) { console.warn('Overhead default.'); }
  };

  const fetchMyProducts = async (currentSession = session) => {
    if (!currentSession?.user?.id) return;
    const { data } = await supabase.from('simulacoes').select('*').eq('user_id', currentSession.user.id).order('created_at', { ascending: false });
    if (data) setSavedSimulations(data);
  };

  const handleSave = async () => {
    if (!session?.user?.id) return;
    setIsSaving(true);
    try {
      const { error } = await supabase.from('simulacoes').insert([{ 
        user_id: session.user.id, 
        nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
        dados: inputs 
      }]);
      if (error) throw error;
      alert('Simulação salva com sucesso!');
      await fetchMyProducts();
      setActiveTab('meus-produtos');
    } catch (err: any) { alert('Erro: ' + err.message); } finally { setIsSaving(false); }
  };

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  if (!isInitialized) return null;
  if (!session) return <Login onLoginSuccess={setSession} />;

  // LOGICA DE BLOQUEIO TOTAL
  if (userProfile?.status === 'bloqueado' && !userProfile?.is_admin) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-slate-900 p-8">
        <div className="max-w-md w-full bg-white rounded-[3rem] p-10 text-center space-y-8 shadow-2xl border border-white/10 animate-slide-up">
          <div className="w-20 h-20 bg-rose-100 text-rose-600 rounded-3xl flex items-center justify-center mx-auto shadow-xl">
             <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m0 0v3m0-3h3m-3 0H9m12 1a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
          </div>
          <div className="space-y-4">
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">Acesso Bloqueado</h2>
            <p className="text-slate-500 font-bold text-sm leading-relaxed">Seu acesso ao sistema foi suspenso temporariamente por questões administrativas.</p>
          </div>
          <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200">
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Central de Suporte</p>
             <p className="text-xl font-black text-slate-900 font-mono">(75) 98323-1773</p>
          </div>
          <button onClick={() => supabase.auth.signOut()} className="w-full bg-slate-900 text-white py-4 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-black transition-all">Sair do Sistema</button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-full flex flex-col lg:flex-row bg-[#f8fafc] overflow-hidden text-slate-900 relative">

      {/* BANNER DE ATUALIZAÇÃO */}
      {userProfile?.status === 'atualizando' && (
        <div className="absolute top-0 left-0 w-full bg-blue-600 text-white z-[200] px-6 py-2 flex items-center justify-center gap-3 shadow-lg">
           <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
           <span className="text-[10px] font-black uppercase tracking-widest">Aviso: O sistema está em manutenção programada. Algumas funções podem apresentar bugs momentâneos.</span>
        </div>
      )}

      <aside className={`bg-black flex lg:flex-col transition-all duration-300 z-[100] border-t lg:border-t-0 lg:border-r border-white/5 shadow-2xl ${sidebarCollapsed ? 'lg:w-[80px]' : 'lg:w-[280px]'} fixed bottom-0 left-0 w-full lg:relative lg:h-screen h-[70px] lg:h-auto`}>
        <div className="hidden lg:flex p-8 mb-6 items-center justify-between">
          <div className="flex items-center gap-4 overflow-hidden">
            <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center shrink-0 border border-white/10 shadow-lg"><svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z"/></svg></div>
            {!sidebarCollapsed && <div className="flex flex-col leading-none"><span className="text-white font-black tracking-tighter text-2xl italic uppercase">Tagway</span><span className="text-[9px] font-black text-white/30 uppercase tracking-[0.2em] mt-1">Intelligence</span></div>}
          </div>
        </div>
        <nav className="flex-1 flex lg:flex-col items-center lg:items-stretch justify-start lg:px-4 lg:space-y-2 p-1 overflow-x-auto lg:overflow-x-visible no-scrollbar">
          <MenuButton active={activeTab === 'calculadora'} onClick={() => setActiveTab('calculadora')} label="Calculadora" collapsed={sidebarCollapsed} icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/>
          <MenuButton active={activeTab === 'catalogo'} onClick={() => setActiveTab('catalogo')} label="Catálogo" collapsed={sidebarCollapsed} icon="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/>
          <MenuButton active={activeTab === 'meus-produtos'} onClick={() => setActiveTab('meus-produtos')} label="Meus Produtos" collapsed={sidebarCollapsed} icon="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"/>
          <MenuButton active={activeTab === 'overhead'} onClick={() => setActiveTab('overhead')} label="Overhead" collapsed={sidebarCollapsed} icon="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 002 2h2a2 2 0 002-2"/>
          <MenuButton active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Ajustes" collapsed={sidebarCollapsed} icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/>
          {!!userProfile?.is_admin && (
            <MenuButton active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" collapsed={sidebarCollapsed} icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04M12 2.944v10m0 0a2 2 0 100 4 2 2 0 000-4z"/>
          )}
        </nav>
      </aside>

      <main className="flex-1 overflow-hidden flex flex-col relative pb-[70px] lg:pb-0">
        <div className="absolute top-12 right-8 z-[90] hidden md:flex items-center gap-4 animate-slide-up">
           <div className="glass-card border border-slate-200/50 px-5 py-2.5 rounded-2xl flex items-center gap-3 shadow-xl shadow-black/5">
              <div className={`w-2 h-2 rounded-full animate-pulse ${userProfile?.status === 'ativo' ? 'bg-emerald-500' : 'bg-blue-500'}`}></div>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-800">
                {userProfile?.is_admin ? 'MASTER' : 'USUÁRIO'}, {userProfile?.nome_completo?.split(' ')[0] || 'Operador'}
              </span>
           </div>
        </div>

        {activeTab === 'calculadora' && (
          <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
            <div className="w-full lg:w-[380px] border-b lg:border-b-0 lg:border-r border-slate-200 bg-white overflow-y-auto custom-scrollbar p-6 pt-0 space-y-8 shadow-inner">
              <div className="flex items-center justify-between sticky top-0 bg-white/95 backdrop-blur-sm z-30 -mx-6 px-6 py-5 border-b border-slate-100 mb-6">
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Parâmetros</h2>
                <button onClick={handleSave} disabled={isSaving} className="bg-black hover:bg-slate-800 text-white text-[9px] font-black uppercase px-6 py-2.5 rounded-xl transition-all shadow-xl shadow-black/10">{isSaving ? 'Gravando...' : 'Salvar'}</button>
              </div>
              <div className="space-y-8">
                <FiscalHeader inputs={inputs} setInputs={setInputs}/>
                <Sidebar inputs={inputs} setInputs={setInputs} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
              </div>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar bg-[#f8fafc] p-4 md:p-8 lg:p-12">
              <div className="max-w-5xl mx-auto animate-slide-up"><ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs}/></div>
            </div>
          </div>
        )}

        {activeTab === 'configuracao' && (
          <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50">
            <ConfiguracaoView userId={session?.user?.id} />
          </div>
        )}

        {activeTab === 'master' && !!userProfile?.is_admin && (
          <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50">
            <AdminView />
          </div>
        )}

        {activeTab === 'overhead' && (
          <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50">
            <OverheadView faturamento={faturamento} setFaturamento={setFaturamento} fixedCosts={fixedCosts} setFixedCosts={setFixedCosts} variableCosts={variableCosts} setVariableCosts={setVariableCosts} userId={session?.user?.id} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
          </div>
        )}
        {activeTab === 'catalogo' && <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-white"><ProductsView onSelectNcm={(ncm) => { setInputs(prev => ({...prev, ncmCodigo: ncm.codigo, mvaOriginal: ncm.mvaOriginal, nomeProduto: ncm.descricao})); setActiveTab('calculadora'); }}/></div>}
        {activeTab === 'meus-produtos' && <div className="flex-1 p-6 md:p-12 overflow-y-auto custom-scrollbar bg-slate-50"><div className="max-w-4xl mx-auto space-y-8"><header className="border-b border-slate-200 pb-8"><h2 className="text-3xl lg:text-4xl font-black text-slate-900 tracking-tighter uppercase italic leading-tight">Meus Produtos</h2></header><div className="grid gap-4">{savedSimulations.map(sim => (<div key={sim.id} className="bg-white border border-slate-200 p-6 rounded-[2rem] flex flex-col md:flex-row md:items-center justify-between gap-6 hover:shadow-2xl transition-all group hover:border-black"><div className="flex items-center gap-6"><div className="w-14 h-14 bg-slate-50 text-slate-400 rounded-2xl flex items-center justify-center shrink-0 group-hover:bg-black group-hover:text-white transition-all shadow-sm"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg></div><div><h4 className="font-black text-slate-800 tracking-tight text-lg truncate">{sim.nome_produto}</h4><span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{new Date(sim.created_at).toLocaleDateString('pt-BR')}</span></div></div><button onClick={() => { setInputs(sim.dados); setActiveTab('calculadora'); }} className="bg-black text-white px-8 py-3.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-800 transition-all shadow-lg">Abrir Cálculo</button></div>))}</div></div></div>}
      </main>
    </div>
  );
};

