              <div className={`w-2 h-2 rounded-full animate-pulse ${userProfile?.status === 'ativo' ? 'bg-emerald-500' : userProfile?.status === 'atualizando' ? 'bg-blue-500' : 'bg-rose-500'}`}></div>
