const supabaseAnonKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InB2aXN5dWhoeXJ1dXhyeWx6cHFyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NjczOTQ2NDEsImV4cCI6MjA4Mjk3MDY0MX0.NGc5ws9ERsgDzelKYMiDZFA34MSyPiwn10agfQU1OnQ';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('nome_completo', { ascending: true });

      if (error) throw error;
      if (data) {
        setUsers(data as UserProfile[]);
      }
    } catch (err: any) {
      setErrorMessage(err.message || 'Erro ao carregar usuários.');
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          email: user.email,
          empresa_nome: user.empresa_nome,
          regime_tributario: user.regime_tributario,
          status: user.status
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert('Usuário atualizado!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro na atualização: ${err.message}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const handleDeleteUser = async (userId: string, userName: string) => {
    const confirmation = window.prompt(`ATENÇÃO: Você vai apagar todos os dados de "${userName}".\nPara confirmar, digite EXCLUIR no campo abaixo:`);

    if (confirmation !== 'EXCLUIR') {
      if (confirmation !== null) alert('Operação cancelada. Você precisa digitar EXCLUIR.');
      return;
    }

    setIsDeleting(userId);
    try {
      // 1. Apagar dados dependentes (simulações e overhead)
      // Usamos .select() para garantir que a query seja executada e possamos ver se houve erro de permissão
      await supabase.from('simulacoes').delete().eq('user_id', userId);
      await supabase.from('overhead_configs').delete().eq('user_id', userId);

      // 2. Apagar o perfil principal
      const { error, count } = await supabase
        .from('user_configs')
        .delete({ count: 'exact' })
        .eq('user_id', userId);

      if (error) throw error;

      if (count === 0) {
        throw new Error('O banco de dados recusou a exclusão. Verifique as Políticas de Segurança (RLS) no console do Supabase para permitir que Admins deletem outras linhas.');
      }

      alert(`Sucesso! O acesso de ${userName} foi removido.`);
      setExpandedUserId(null);
      fetchUsers();
    } catch (err: any) {
      console.error('Erro na exclusão:', err);
      alert(`FALHA NA EXCLUSÃO: ${err.message}`);

      // Fallback: Se não puder deletar, tenta pelo menos bloquear e limpar o nome
      const fallback = window.confirm("Não foi possível remover a linha do banco por questões de segurança. Deseja aplicar um BLOQUEIO TOTAL e limpar os dados da conta em vez de excluir?");
      if (fallback) {
        await supabase.from('user_configs').update({
          status: 'bloqueado',
          nome_completo: 'ACESSO REMOVIDO',
          empresa_nome: 'LICENÇA CANCELADA'
        }).eq('user_id', userId);
        fetchUsers();
      }
    } finally {
      setIsDeleting(null);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.senha || !newUser.nome) {
      alert('Preencha os campos obrigatórios.');
      return;
    }

    setIsRegistering(true);
    const tempClient = createClient(supabaseUrl, supabaseAnonKey, {
      auth: { persistSession: false, autoRefreshToken: false }
