        alert('OPERADOR CRIADO!');
        setNewUser({ nome: '', email: '', senha: '', empresa: '', regime: 'Real' });
        fetchUsers();
      }
    } catch (err: any) {
      alert(`Erro no cadastro: ${err.message}`);
    } finally {
      setIsRegistering(false);
    }
  };

