    const currentSession = await supabase.auth.getSession();
    const currentUserId = currentSession.data.session?.user.id;

    if (userId === currentUserId) {
      alert("Você não pode apagar sua própria conta Master!");
      return;
    }

    const confirmation = window.prompt(`ATENÇÃO: Você vai apagar todos os dados de "${userName}".\nPara confirmar, digite o nome do usuário abaixo:`);

