  };

  const handleSave = async () => {
    if (!session?.user?.id) return;
    setIsSaving(true);
    try {
      const { error } = await supabase.from('simulacoes').insert([{ 
        user_id: session.user.id, 
        nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
        dados: inputs 
      }]);
      if (error) throw error;
      alert('Simulação salva!');
      await fetchMyProducts();
      setActiveTab('meus-produtos');
    } catch (err: any) { 
      alert('Erro ao salvar: ' + stringifyError(err)); 
    } finally { 
      setIsSaving(false); 
    }
  };

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  if (!isInitialized) return null;

  const isMaster = session?.user?.email === MASTER_EMAIL;

  if (session && profileError && !userProfile && !isMaster) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-[#0f172a] p-8 fixed inset-0 z-[5000]">
        <div className="max-w-md w-full bg-white rounded-[3rem] p-10 text-center space-y-8 shadow-2xl animate-slide-up">
          <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-3xl flex items-center justify-center mx-auto shadow-xl">
             <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
          </div>
          <div className="space-y-4">
            <h2 className="text-2xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">Acesso Bloqueado</h2>
            <div className="bg-slate-50 p-6 rounded-2xl text-[11px] font-mono text-slate-500 break-words text-left border border-slate-100 max-h-64 overflow-y-auto custom-scrollbar leading-relaxed">
               <span className="text-slate-400 font-bold block mb-2 uppercase text-[9px] tracking-widest text-center border-b border-slate-200 pb-2 mb-3">Relatório Técnico</span>
