  { id: 'v1-4', categoria: 'IMPOSTOS SOBRE VENDAS', descricao: 'PIS e COFINS Saída', percentual: 9.25 },
];

type Tab = 'calculadora' | 'catalogo' | 'meus-produtos' | 'overhead' | 'configuracao' | 'master';

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isSaving, setIsSaving] = useState(false);
  const [savedSimulations, setSavedSimulations] = useState<any[]>([]);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);
  const [profileError, setProfileError] = useState<string | null>(null);

  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>(defaultFixedCosts);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>(defaultVariableCosts);
  const [isAutoSync, setIsAutoSync] = useState(false);

  // Extrator de Erro de Nível Industrial - Impede o [object Object]
  const stringifyError = (err: any): string => {
    if (err == null) return 'Erro não especificado (nulo)';
    if (typeof err === 'string') return err;

    try {
      // 1. Caso o erro venha aninhado (ex: de uma resposta de fetch)
      if (err.error && typeof err.error !== 'function') {
        return stringifyError(err.error);
      }

      // 2. Extração direta de propriedades conhecidas (mesmo as não-enumeráveis de Error)
      const code = err.code || err.status || err.statusCode || '';
      const message = err.message || err.error_description || err.details || err.hint || err.msg;

      if (typeof message === 'string' && message.trim().length > 0) {
        return code ? `[Erro ${code}] ${message}` : message;
      }

      // 3. Inspeção de propriedades internas para objetos Error nativos
      const allProps = Object.getOwnPropertyNames(err);
      const collected: Record<string, any> = {};
      allProps.forEach(key => {
        const val = err[key];
        if (typeof val === 'string' || typeof val === 'number') {
          collected[key] = val;
        }
      });

      if (collected.message) return collected.message;

      // 4. Serialização via JSON como último recurso (evitando o [object Object])
      const jsonStr = JSON.stringify(collected);
      if (jsonStr !== '{}') return `Falha Técnica: ${jsonStr}`;

      // 5. Fallback Final - Verifica se String(err) retorna algo útil
      const finalStr = String(err);
      if (finalStr === '[object Object]') {
        return `Erro Indeterminado: Objeto técnico recebido sem mensagem legível. Chaves: ${Object.keys(err).join(', ')}`;
      }
      return finalStr;
    } catch (e) {
      return 'Erro Crítico na serialização da falha. Verifique o console do desenvolvedor.';
    }
  };

  useEffect(() => {
    let mounted = true;
    const init = async () => {
      try {
        const { data: { session: currentSession } } = await supabase.auth.getSession();
        if (mounted) {
          setSession(currentSession);
          if (currentSession) {
            await fetchUserProfile(currentSession);
            await Promise.all([
              fetchMyProducts(currentSession),
              fetchOverheadConfig(currentSession)
            ]).catch(() => {});
          }
          setIsInitialized(true);
        }
      } catch (e) {
        if (mounted) setIsInitialized(true);
      }
    };
    init();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, newSession) => {
      if (mounted) {
        setSession(newSession);
        if (newSession) {
          fetchUserProfile(newSession);
          fetchMyProducts(newSession);
          fetchOverheadConfig(newSession);
        } else {
          setUserProfile(null);
          setProfileError(null);
        }
      }
    });
    return () => { mounted = false; subscription.unsubscribe(); };
  }, []);

  const fetchUserProfile = async (userSession: any) => {
    if (!userSession?.user?.id) return;
    setProfileError(null); 
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .eq('user_id', userSession.user.id)
        .maybeSingle();

      if (error) throw error;

      if (!data) {
        if (userSession.user.email === MASTER_EMAIL) {
          const { data: upsertedData, error: upsertError } = await supabase
            .from('user_configs')
            .upsert({
              user_id: userSession.user.id,
              email: userSession.user.email,
              nome_completo: 'Master Admin',
              is_admin: true,
              status: 'ativo',
              regime_tributario: 'Real',
              empresa_nome: 'Tagway Technology'
            }, { onConflict: 'user_id' })
            .select()
            .single();

          if (upsertError) throw upsertError;
          setUserProfile(upsertedData);
        } else {
          setProfileError('ACESSO NEGADO: Seu e-mail não foi localizado na base de usuários ativos. Entre em contato com tagwaytw@gmail.com.');
        }
      } else {
        setUserProfile(data);
      }
    } catch (err: any) {
      console.error('DUMP TÉCNICO DO ERRO DE PERFIL:', err);
      setProfileError(stringifyError(err));
    }
  };

  const fetchOverheadConfig = async (userSession: any) => {
    try {
      const { data } = await supabase.from('overhead_configs').select('*').eq('user_id', userSession.user.id).maybeSingle();
      if (data) {
        if (data.faturamento) setFaturamento(Number(data.faturamento));
        if (data.fixed_costs) setFixedCosts(data.fixed_costs);
        if (data.variable_costs) setVariableCosts(data.variable_costs);
        if (data.is_auto_sync !== undefined) setIsAutoSync(!!data.is_auto_sync);
      }
    } catch (e) {}
  };

  const fetchMyProducts = async (currentSession = session) => {
    if (!currentSession?.user?.id) return;
    try {
      const { data } = await supabase.from('simulacoes').select('*').eq('user_id', currentSession.user.id).order('created_at', { ascending: false });
      if (data) setSavedSimulations(data);
    } catch (e) {}
  };

  const handleSave = async () => {
    if (!session?.user?.id) return;
    setIsSaving(true);
    try {
      const { error } = await supabase.from('simulacoes').insert([{ 
        user_id: session.user.id, 
        nome_produto: inputs.nomeProduto || 'Produto Sem Nome', 
        dados: inputs 
      }]);
      if (error) throw error;
      alert('Simulação salva!');
      await fetchMyProducts();
