// Função global de utilidade para garantir que erros nunca sejam [object Object]
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro indefinido';
  if (typeof err === 'string') return err;

  // 1. Prioridade para mensagens diretas
  const msg = err.message || err.msg || (err.error && err.error.message) || err.error_description || err.details || err.hint;
  if (msg && typeof msg === 'string') return msg;

  // 2. Tenta extrair propriedades de erro padrão mesmo que não sejam enumeráveis
  try {
    const info: any = {};
    const props = ['message', 'code', 'status', 'statusCode', 'details', 'hint'];
    props.forEach(p => {
      if (err[p]) info[p] = err[p];
    });

    if (Object.keys(info).length > 0) {
      if (info.message) return info.message;
      return JSON.stringify(info);
    }

    // 3. Serialização completa de segurança
    const serialized = JSON.stringify(err);
    if (serialized && serialized !== '{}') return serialized;
  } catch (e) {
    // Ignora erro na serialização
  }

  // 4. Fallback final
  const final = String(err);
  return final === '[object Object]' ? 'Falha técnica desconhecida. Verifique a conexão ou permissões.' : final;
};

