// Função global de utilidade ultra-resiliente para evitar [object Object]
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro não identificado (nulo/indefinido)';
  if (typeof err === 'string') return err;

  // Recursão para erros aninhados do Supabase
  if (err.error && typeof err.error !== 'function') return stringifyError(err.error);

  try {
    // 1. Tenta pegar a mensagem direta de propriedades comuns
    const msg = err.message || err.msg || err.error_description || err.details || err.hint;
    if (typeof msg === 'string' && msg.trim().length > 0) return msg;

    // 2. Tenta inspecionar propriedades ocultas (non-enumerable) como .message em Error nativos
    const allProps = Object.getOwnPropertyNames(err);
    const commonKeys = ['message', 'code', 'status', 'statusCode', 'details', 'hint', 'msg'];

    for (const key of commonKeys) {
      if (err[key] && typeof err[key] === 'string' && err[key].trim().length > 0) {
        return err[key];
      }
    }

    // 3. Tenta serializar o que encontrar de útil
    const objInfo: any = {};
    allProps.forEach(p => {
      const val = err[p];
      if (typeof val === 'string' || typeof val === 'number' || typeof val === 'boolean') {
        objInfo[p] = val;
      }
    });

    if (Object.keys(objInfo).length > 0) {
      if (objInfo.message) return objInfo.message;
      return JSON.stringify(objInfo);
    }
  } catch (e) {
    // Ignora erro de processamento
  }

  // 4. Fallback final via String()
  const final = String(err);
  if (final === '[object Object]') {
    return `Falha técnica complexa (Chaves: ${Object.keys(err).join(', ') || 'nenhuma'}). Verifique o console do navegador para o dump do objeto.`;
  }
  return final;
};

