/**
 * Função Definitiva para Extração de Mensagem de Erro.
 * Impede o aparecimento de "[object Object]" na UI.
 */
export const stringifyError = (err: any): string => {
  if (err === null) return 'Erro nulo';
  if (err === undefined) return 'Erro indefinido';
  if (typeof err === 'string') return err;

  // Recursão para o padrão Supabase { error: { message: ... } }
  if (err && typeof err === 'object' && err.error && typeof err.error !== 'function') {
    return stringifyError(err.error);
  }

  try {
    // 1. Busca por propriedades conhecidas em qualquer nível do objeto
    const candidates = [
      err.message, err.msg, err.error_description, err.details, 
      err.hint, err.code, err.status, err.statusText
    ];

    for (const val of candidates) {
      if (typeof val === 'string' && val.trim().length > 0) return val;
      if (typeof val === 'number') return `Erro ${val}`;
    }

    // 2. Tenta inspecionar propriedades ocultas (non-enumerable) de Error nativos
    const allProps = Object.getOwnPropertyNames(err);
    for (const key of ['message', 'details', 'hint', 'code']) {
      if (allProps.includes(key)) {
        const val = err[key];
        if (typeof val === 'string' && val.trim().length > 0) return val;
      }
    }

    // 3. Tenta serializar o objeto para JSON de forma segura (sem circularidade)
    const seen = new WeakSet();
    const json = JSON.stringify(err, (key, value) => {
      if (typeof value === "object" && value !== null) {
        if (seen.has(value)) return "[Circular]";
        seen.add(value);
      }
      return value;
    }, 2);

    if (json && json !== '{}') return `Falha técnica: ${json}`;

    // 4. Último recurso: Descrever a estrutura do objeto
    const keys = Object.keys(err);
    if (keys.length > 0) return `Erro indefinido (Propriedades do objeto: ${keys.join(', ')})`;

  } catch (e) {
    // Falhou até a tentativa de serializar
  }

  // 5. Fallback absoluto
  const str = String(err);
  return str === '[object Object]' ? 'Falha técnica complexa detectada. Verifique o console.' : str;
};

