/**
 * Função de tratamento de erro ultra-resiliente.
 * Garante que NUNCA apareça [object Object] na interface.
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro desconhecido (nulo)';
  if (typeof err === 'string') return err;

  // Caso o erro venha do Supabase no formato { error: { message: ... } }
  if (err.error && typeof err.error !== 'function') {
    return stringifyError(err.error);
  }

  let message = '';

  try {
    // 1. Tenta extrair propriedades comuns de erro
    const commonProps = ['message', 'msg', 'error_description', 'details', 'hint', 'code'];
    for (const prop of commonProps) {
      if (err[prop] && typeof err[prop] === 'string' && err[prop].trim().length > 0) {
        message = err[prop];
        break;
      }
    }

    // 2. Se falhar, inspeciona propriedades não-enumeráveis (comum em objetos Error nativos)
    if (!message) {
      const allProps = Object.getOwnPropertyNames(err);
      if (allProps.includes('message') && typeof err.message === 'string') {
        message = err.message;
      }
    }

    // 3. Se ainda assim for um objeto sem mensagem clara, serializa como JSON
    if (!message || message === '[object Object]') {
      const seen = new WeakSet();
      const json = JSON.stringify(err, (key, value) => {
        if (typeof value === "object" && value !== null) {
          if (seen.has(value)) return "[Circular]";
          seen.add(value);
        }
        return value;
      }, 2);

      if (json && json !== '{}') {
        message = `Detalhes Técnicos: ${json}`;
      }
    }
  } catch (e) {
    message = 'Erro ao processar mensagem técnica.';
  }

  // 4. Fallback final absoluto
  const finalStr = message || String(err);
  return finalStr === '[object Object]' 
    ? 'Falha crítica de comunicação ou permissão. Verifique o console do navegador.' 
    : finalStr;
};

