/**
 * Função de Diagnóstico de Erros Ultra-Resiliente.
 * Garante que NUNCA apareça [object Object] na interface.
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro desconhecido (vazio)';
  if (typeof err === 'string') return err;

  // Caso o erro venha do Supabase no formato { error: { message: ... } }
  if (err.error && typeof err.error !== 'function') {
    return stringifyError(err.error);
  }

  let output = '';

  try {
    // 1. Tenta propriedades conhecidas de erro
    const message = err.message || err.msg || err.error_description || err.error || err.code;
    if (typeof message === 'string' && message.length > 0) {
      output = message;
    } else {
      // 2. Tenta serializar o objeto para ver o conteúdo real
      const json = JSON.stringify(err);
      if (json && json !== '{}') {
        output = json;
      }
    }
  } catch (e) {
    output = 'Falha ao processar detalhes técnicos do erro.';
  }

  const finalStr = output || String(err);
  return finalStr === '[object Object]' ? 'Erro de comunicação interna. Verifique a conexão ou se as tabelas existem no Supabase.' : finalStr;
};

