/**
 * Função de Diagnóstico de Erros Blindada.
 * Extrai a mensagem real de objetos de erro complexos (Supabase, Auth, etc).
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro nulo ou indefinido';
  if (typeof err === 'string') return err;

  // Se for um erro do Supabase ou similar com propriedade 'error'
  if (err.error && typeof err.error === 'object') return stringifyError(err.error);

  // Campos comuns em objetos de erro
  const message = err.message || err.msg || err.error_description || err.details || err.hint || err.code || err.statusText;

  if (typeof message === 'string' && message.trim().length > 0) {
    return message;
  }

  // Tenta converter para JSON caso seja um objeto sem campos de texto óbvios
  try {
    const json = JSON.stringify(err);
    if (json && json !== '{}') return json;
  } catch (e) {
    // Falha na serialização
  }

  // Fallback final listando as chaves se for um objeto
  if (typeof err === 'object') {
    const keys = Object.keys(err).join(', ');
    return `Erro técnico (chaves: ${keys || 'nenhuma'}). Verifique o console do navegador.`;
  }

  return String(err);
};

