 */
export const stringifyError = (err: any): string => {
  if (!err) return 'Erro desconhecido';
  if (typeof err === 'string') return err;

  // Tenta extrair mensagem de erro padrão do Supabase/Auth
  const msg = err.message || err.msg || err.error_description || err.details;
  if (msg && typeof msg === 'string') return msg;

  // Se for um objeto com propriedade 'error' (ex: { error: { message: '...' } })
  if (err.error) return stringifyError(err.error);

  // Se ainda for um objeto, tenta converter para JSON para vermos o que tem dentro
  try {
    const str = JSON.stringify(err, null, 2);
    if (str === '{}') return err.toString();
    return str;
  } catch (e) {
    return String(err);
  }
};

