/**
 * stringifyError v4.0 - Ultra Robust Error Extraction
 * Prevents [object Object] by checking for common error fields and using fallback serialization.
 */
export const stringifyError = (err: any): string => {
  if (!err) return 'Erro desconhecido (vazio)';
  if (typeof err === 'string') return err;

  // Handle native Error objects (message property is non-enumerable in JSON.stringify)
  if (err instanceof Error) return err.message;

  // If it's a Supabase error object, it might have a nested 'error' property
  const errorObj = err.error && typeof err.error === 'object' ? err.error : err;

  // Priority list of common error message fields
  const message = errorObj.message || 
                  errorObj.msg || 
                  errorObj.error_description || 
                  errorObj.details || 
                  errorObj.hint || 
                  errorObj.code || 
                  errorObj.statusText;

  if (typeof message === 'string' && message.trim().length > 0) {
    return message;
  }

  // If we have an error code, use it
  if (errorObj.code) return `Erro técnico: Código ${errorObj.code}`;

  // Try JSON serialization as a last resort for complex objects
  try {
    const str = JSON.stringify(err);
    if (str && str !== '{}') return str;
  } catch (e) {
    // Serialization failed
  }

  // If everything else fails, return the string representation but check for [object Object]
  const finalFallback = String(err);
  return finalFallback === '[object Object]' 
    ? 'Erro de sistema não serializável. Verifique as tabelas do banco de dados e as políticas de segurança (RLS).' 
    : finalFallback;
};

