/**
 * stringifyError v5.0 - Resiliência Extrema contra [object Object]
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro desconhecido (nulo/indefinido)';
  if (typeof err === 'string') return err;

  // Lista de candidatos a mensagem dentro do objeto
  const candidates = [
    err.message,
    err.msg,
    err.error_description,
    err.error?.message,
    err.details,
    err.hint,
    err.code,
    (err instanceof Error) ? err.message : null
  ];

  for (const cand of candidates) {
    if (typeof cand === 'string' && cand.trim().length > 0) {
      return cand;
    }
  }

  // Tenta serializar se for um objeto desconhecido
  if (typeof err === 'object') {
    try {
      const json = JSON.stringify(err);
      if (json && json !== '{}') return json;
    } catch (e) {}
  }

  const finalStr = String(err);
  return finalStr === '[object Object]' 
    ? 'Falha técnica não serializável. Geralmente indica erro de RLS (permissão) ou tabela inexistente no Supabase.' 
    : finalStr;
};

