/**
 * stringifyError v6.0 - Detecção Profunda
 * Resolve o problema de [object Object] extraindo propriedades até de objetos Error nativos.
 */
export const stringifyError = (err: any): string => {
  try {
    if (err == null) return 'Erro desconhecido (nulo/indefinido)';
    if (typeof err === 'string') return err;

    // Se for um objeto, tentamos extrair campos comuns de erro do Supabase/Postgrest
    const msg = err.message || 
                err.msg || 
                err.error?.message || 
                err.error_description || 
                err.details || 
                err.hint || 
                err.code;

    if (typeof msg === 'string' && msg.trim().length > 0) return msg;

    // Se ainda for um objeto, usamos Object.getOwnPropertyNames para pegar propriedades 
    // que o JSON.stringify ignora em objetos de erro (como 'message')
    if (typeof err === 'object') {
      const keys = Object.getOwnPropertyNames(err);
      if (keys.length > 0) {
        const extracted: any = {};
        keys.forEach(k => { extracted[k] = err[k]; });

        // Se após extrair tivermos uma mensagem, retornamos ela
        if (extracted.message) return extracted.message;

        const json = JSON.stringify(extracted);
        if (json !== '{}') return json;
      }
    }

    const finalStr = String(err);
    return finalStr === '[object Object]' 
      ? 'Erro técnico não serializável. Verifique se a tabela existe ou se as permissões de acesso (RLS) estão corretas no banco de dados.' 
      : finalStr;
  } catch (e) {
    return 'Falha crítica ao processar mensagem de erro.';
  }
};

