/**
 * stringifyError v8.0 - Garantia Total de Retorno de String
 * Extrai mensagens de erro de objetos complexos (Supabase, Postgrest, Error)
 * e garante que NUNCA retorne um objeto que cause [object Object] no React.
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro desconhecido';
  if (typeof err === 'string') return err;

  let message = '';

  try {
    // 1. Tenta extrair mensagem de propriedades comuns
    if (err.message) {
      message = typeof err.message === 'string' ? err.message : JSON.stringify(err.message);
    } else if (err.error?.message) {
      message = typeof err.error.message === 'string' ? err.error.message : JSON.stringify(err.error.message);
    } else if (err.error_description) {
      message = String(err.error_description);
    } else if (err.msg) {
      message = String(err.msg);
    }

    // 2. Adiciona detalhes técnicos se disponíveis (PostgrestError)
    if (err.details && typeof err.details === 'string' && !message.includes(err.details)) {
      message = message ? `${message} | Detalhes: ${err.details}` : err.details;
    }

    if (err.hint && typeof err.hint === 'string' && !message.includes(err.hint)) {
      message = message ? `${message} | Dica: ${err.hint}` : err.hint;
    }

    if (message) return message;

    // 3. Fallback para propriedades não enumeráveis (objetos Error nativos)
    const ownProps = Object.getOwnPropertyNames(err);
    if (ownProps.includes('message') && typeof (err as any).message === 'string') {
      return (err as any).message;
    }

    // 4. Fallback final: Serialização JSON ou String coerciva
    const json = JSON.stringify(err);
    if (json && json !== '{}') return json;
  } catch (e) {
    // Falha silenciosa no processamento
  }

  const finalStr = String(err);
  return finalStr === '[object Object]' 
    ? 'Erro técnico complexo (Verifique RLS/Permissões no console do navegador).' 
    : finalStr;
};

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
