/**
 * stringifyError v9.0 - Serialização Profunda
 * Garante que erros de banco de dados (Supabase) e erros nativos 
 * nunca apareçam como [object Object].
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro nulo ou indefinido';
  if (typeof err === 'string') return err;

  try {
    // 1. Tenta extrair mensagens legíveis de estruturas conhecidas
    if (err.message && typeof err.message === 'string') return err.message;
    if (err.error_description && typeof err.error_description === 'string') return err.error_description;
    if (err.error && typeof err.error === 'string') return err.error;

    // 2. Tratamento específico para PostgrestError (Supabase)
    if (err.code || err.details || err.hint) {
      return [
        err.message || 'Erro de Banco de Dados',
        err.details ? `Detalhes: ${err.details}` : null,
        err.hint ? `Dica: ${err.hint}` : null,
        err.code ? `(Código: ${err.code})` : null
      ].filter(Boolean).join(' | ');
    }

    // 3. Força a serialização de propriedades não-enumeráveis (como 'message' em Errors nativos)
    const allProps = Object.getOwnPropertyNames(err);
    if (allProps.length > 0) {
      const plainObj: any = {};
      allProps.forEach(key => {
        plainObj[key] = err[key];
      });

      // Se após a extração tivermos uma mensagem legível, use-a
      if (plainObj.message && typeof plainObj.message === 'string') return plainObj.message;

      const json = JSON.stringify(plainObj, null, 2);
      if (json && json !== '{}') return json;
    }

  } catch (e) {
    // Fallback se a serialização falhar
  }

  const finalStr = String(err);
  return finalStr === '[object Object]' 
    ? 'Erro técnico complexo. Verifique a conexão com o banco ou permissões de RLS.' 
    : finalStr;
};

