/**
 * stringifyError v10.0 - O Fim do [object Object]
 * Uma função de tratamento de erro ultra-agressiva que garante retorno de string legível.
 */
export const stringifyError = (err: any): string => {
  if (err === null || err === undefined) return 'Erro desconhecido (nulo/indefinido)';
  if (typeof err === 'string') return err;
  if (typeof err === 'number' || typeof err === 'boolean') return String(err);

  try {
    // 1. Extração de propriedades comuns de erro
    if (typeof err === 'object') {
      const parts: string[] = [];

      // Captura mensagem principal
      const msg = err.message || err.error_description || err.error || err.msg;
      if (msg && typeof msg === 'string') parts.push(msg);

      // Detalhes do Supabase/Postgrest
      if (err.details && typeof err.details === 'string') parts.push(`Detalhes: ${err.details}`);
      if (err.hint && typeof err.hint === 'string') parts.push(`Dica: ${err.hint}`);
      if (err.code) parts.push(`Cód: ${err.code}`);

      if (parts.length > 0) return parts.join(' | ');

      // 2. Serialização JSON segura (lidando com referências circulares)
      const cache = new Set();
      const json = JSON.stringify(err, (key, value) => {
        if (typeof value === 'object' && value !== null) {
          if (cache.has(value)) return '[Circular]';
          cache.add(value);
        }
        return value;
      }, 2);

      if (json && json !== '{}') return json;
    }
  } catch (e) {
    // Falha silenciosa na serialização
  }

  // 3. Fallback final absoluto
  const fallback = String(err);
  if (fallback === '[object Object]') {
    return 'Falha de Permissão ou Conexão: O banco de dados recusou a solicitação (RLS). Verifique o console do navegador para detalhes técnicos.';
  }
  return fallback;
};

