/**
 * stringifyError v11.0 - Resiliência Total
 * Extrai mensagens de erro mesmo quando o Supabase retorna objetos complexos.
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro desconhecido';
  if (typeof err === 'string') return err;

  try {
    // 1. Erros do Supabase/Postgrest têm estrutura específica
    if (err.message && typeof err.message === 'string') {
      let msg = err.message;
      if (err.details) msg += ` | Detalhes: ${err.details}`;
      if (err.hint) msg += ` | Dica: ${err.hint}`;
      if (err.code) msg += ` (Cód: ${err.code})`;
      return msg;
    }

    // 2. Erros de Auth do Supabase
    if (err.error_description) return err.error_description;
    if (err.error && typeof err.error === 'string') return err.error;

    // 3. Serialização profunda para evitar [object Object]
    const allProps = Object.getOwnPropertyNames(err);
    if (allProps.length > 0) {
      const obj: any = {};
      allProps.forEach(key => { obj[key] = err[key]; });
      if (obj.message) return obj.message;
      return JSON.stringify(obj);
    }
  } catch (e) {
    // Fallback
  }

  const str = String(err);
  return str === '[object Object]' ? 'Erro técnico de banco de dados. Verifique as permissões de RLS no Supabase.' : str;
};

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
