 * para garantir que mensagens do Supabase/Postgrest fiquem visíveis.
 */
export const stringifyError = (err: any): string => {
  if (err == null) return 'Erro nulo ou indefinido.';
  if (typeof err === 'string') return err;

  try {
    // 1. Caso seja um objeto, extraímos todas as propriedades escondidas (como 'message')
    const allProps = Object.getOwnPropertyNames(err);
    const errObj: any = {};
    allProps.forEach(key => { errObj[key] = err[key]; });

    // 2. Tenta retornar a mensagem mais amigável primeiro
    const bestMessage = errObj.message || errObj.error_description || errObj.error || errObj.msg;

    // 3. Monta detalhes técnicos se existirem
    const details = [];
    if (errObj.details) details.push(`Detalhes: ${errObj.details}`);
    if (errObj.hint) details.push(`Dica: ${errObj.hint}`);
    if (errObj.code) details.push(`Cód: ${errObj.code}`);

    if (bestMessage) {
      return details.length > 0 ? `${bestMessage} (${details.join(' | ')})` : bestMessage;
    }

    // 4. Se não achou nada, serializa o objeto completo extraído
    const json = JSON.stringify(errObj, null, 2);
    if (json && json !== '{}') return json;

  } catch (e) {
    // Falha silenciosa
  }

  // Fallback absoluto
  const str = String(err);
  return str === '[object Object]' ? 'Erro técnico complexo (Verifique Console do Navegador).' : str;
};

