/**
 * stringifyError v13.0 - A Prova de Falhas
 * Garante que NENHUM erro apareça como [object Object].
 */
export const stringifyError = (err: any): string => {
  if (err === null || err === undefined) return 'Erro desconhecido (vazio)';
  if (typeof err === 'string') return err;

  try {
    // Se for um erro do Supabase/Postgrest
    if (err.message && typeof err.message === 'string') {
      let m = err.message;
      if (err.details) m += ` | Detalhes: ${err.details}`;
      if (err.code) m += ` (Código: ${err.code})`;
      return m;
    }

    // Se for um objeto genérico, força a extração de propriedades
    const props = Object.getOwnPropertyNames(err);
    if (props.length > 0) {
      const plain: any = {};
      props.forEach(p => { plain[p] = err[p]; });
      if (plain.message) return plain.message;
      return JSON.stringify(plain, null, 1);
    }

    // Fallback JSON
    const json = JSON.stringify(err);
    if (json && json !== '{}') return json;

  } catch (e) {
    // Erro na serialização
  }

  return String(err) === '[object Object]' 
    ? 'Erro de permissão RLS ou Conexão Recusada pelo Banco de Dados.' 
    : String(err);
};

