      <div className="h-screen w-full flex items-center justify-center bg-[#0f172a] p-8 fixed inset-0 z-[5000]">
        <div className="max-w-md w-full bg-white rounded-[3rem] p-10 text-center space-y-8 shadow-2xl animate-slide-up border border-slate-200">
