/**
 * stringifyError v14.0 - Diagnóstico Real
 * Extrai a mensagem de erro real do Supabase para evitar o [object Object].
 */
export const stringifyError = (err: any): string => {
  if (!err) return 'Erro desconhecido';
  if (typeof err === 'string') return err;

  try {
    // Tratamento específico para erros do Supabase/Postgrest
    if (err.message && typeof err.message === 'string') {
      let msg = err.message;
      if (err.details && err.details !== 'null') msg += ` | Detalhes: ${err.details}`;
      if (err.code) msg += ` (Cód: ${err.code})`;
      return msg;
    }

    // Se for um objeto, tenta extrair propriedades conhecidas
    const keys = Object.getOwnPropertyNames(err);
    if (keys.length > 0) {
      const obj: any = {};
      keys.forEach(k => { obj[k] = err[k]; });
      return obj.message || JSON.stringify(obj);
    }
  } catch (e) {
    // Fallback
  }

  const s = String(err);
  return s === '[object Object]' ? 'Falha de comunicação com o banco de dados (RLS ou Tabela Inexistente).' : s;
};

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isSaving, setIsSaving] = useState(false);
  const [savedSimulations, setSavedSimulations] = useState<any[]>([]);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);
  const [profileError, setProfileError] = useState<string | null>(null);

  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>(defaultFixedCosts);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>(defaultVariableCosts);
  const [isAutoSync, setIsAutoSync] = useState(false);

  useEffect(() => {
    let mounted = true;
    const init = async () => {
      try {
        const { data: { session: currentSession } } = await supabase.auth.getSession();
        if (mounted) {
          setSession(currentSession);
          if (currentSession) {
            await fetchUserProfile(currentSession);
            await Promise.all([
              fetchMyProducts(currentSession),
              fetchOverheadConfig(currentSession)
            ]).catch(() => {});
          }
          setIsInitialized(true);
        }
      } catch (e) {
        if (mounted) setIsInitialized(true);
      }
    };
    init();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, newSession) => {
      if (mounted) {
        setSession(newSession);
        if (newSession) {
          fetchUserProfile(newSession);
          fetchMyProducts(newSession);
          fetchOverheadConfig(newSession);
        } else {
          setUserProfile(null);
          setProfileError(null);
        }
      }
    });
    return () => { mounted = false; subscription.unsubscribe(); };
  }, []);

  const fetchUserProfile = async (userSession: any) => {
    if (!userSession?.user?.id) return;
    setProfileError(null); 
    try {
      // BUSCA RESTRITA: Sem upsert automático.
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .eq('user_id', userSession.user.id)
        .maybeSingle();

      if (error) {
        throw error;
      }

      if (!data) {
        // Se não encontrar na tabela, BLOQUEIA.
        setProfileError(`ACESSO NEGADO: O e-mail ${userSession.user.email} não está autorizado a usar este sistema. Entre em contato com o administrador.`);
        setUserProfile(null);
      } else {
        setUserProfile(data);
      }
    } catch (err: any) {
      console.error('ERRO AO BUSCAR PERFIL:', err);
      setProfileError(stringifyError(err));
