/**
 * stringifyError v16.0 - Diagnóstico Blindado
 * Extrai a mensagem real mesmo que o objeto seja complexo ou circular.
 */
export const stringifyError = (err: any): string => {
  if (!err) return 'Erro desconhecido';
  if (typeof err === 'string') return err;

  // Se for um erro do Supabase/Postgrest
  if (err.message && typeof err.message === 'string') {
    let detail = '';
    if (err.details) detail += `\nDetalhe: ${err.details}`;
    if (err.hint) detail += `\nDica: ${err.hint}`;
    if (err.code) detail += `\nCódigo SQL: ${err.code}`;
    return `${err.message}${detail}`;
  }

  // Fallback para objetos sem .message
  try {
    const keys = Object.keys(err);
    if (keys.length > 0) {
      return keys.map(k => `${k}: ${err[k]}`).join('\n');
    }
    return JSON.stringify(err);
  } catch (e) {
    return String(err);
  }
};

