/**
 * stringifyError v17.0 - Diagnóstico Total
 * Projetado para nunca retornar '[object Object]'
 */
export const stringifyError = (err: any): string => {
  if (!err) return 'Erro desconhecido';
  if (typeof err === 'string') return err;

  // Se for uma instância de Error (ex: new Error())
  if (err instanceof Error) {
    return `${err.name}: ${err.message}`;
  }

  // Se for um objeto (comum no Supabase)
  if (typeof err === 'object') {
    // Tenta extrair campos conhecidos de erro do Postgrest/Supabase
    const msg = err.message || err.error_description || err.error || err.msg;
    const details = err.details || err.detail;
    const hint = err.hint;
    const code = err.code || err.status;

    if (msg || details || hint || code) {
      return [
        msg ? `Mensagem: ${msg}` : null,
        details ? `Detalhes: ${details}` : null,
        hint ? `Dica: ${hint}` : null,
        code ? `Código: ${code}` : null
      ]
      .filter(Boolean)
      .join('\n');
    }

    // Fallback: Tenta converter o objeto em JSON
    try {
      const json = JSON.stringify(err, null, 2);
      if (json === '{}') {
        // Se o JSON vier vazio, lista as chaves manualmente (evita propriedades não enumeráveis)
        const keys = Object.getOwnPropertyNames(err);
        if (keys.length > 0) {
          return keys.map(k => `${k}: ${String((err as any)[k])}`).join('\n');
        }
      } else {
        return json;
      }
    } catch (e) {
      // Se falhar JSON (ex: referência circular), tenta listar o que der
      return `Falha ao serializar objeto de erro. Tipo: ${typeof err}. Chaves: ${Object.keys(err).join(', ')}`;
    }
  }

  // Último recurso
  return String(err);
};

