  pisCofinsRate: 9.25,
  excluirIcmsPis: true,
  pisCofinsVenda: 9.25,
  comissaoVenda: 0.0,
  icmsVenda: 20.50,
  outrosCustosVariaveis: 0.00,
  custosFixos: 20.00,
  resultadoDesejado: 8.00,
  mode: 'substituido',
  percReducaoBase: 0,
  simulationMode: 'buyToSell',
  precoVendaDesejado: 0
};

type Tab = 'calculadora' | 'catalogo' | 'meus-produtos' | 'overhead' | 'resumo-fiscal' | 'configuracao' | 'master' | 
           'logistica' | 'estoque' | 'metas' | 'dre' | 'caixa' | 'ia';

export const stringifyError = (err: any): string => {
  if (!err) return 'Erro desconhecido';
  if (typeof err === 'string') return err;
  const msg = err.message || err.error_description || err.error || err.msg;
  return msg || JSON.stringify(err);
};

// Componente BrainIcon - Lado Esquerdo Orgânico, Lado Direito Digital
const BrainIcon = () => (
  <svg className="w-8 h-8 shrink-0" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="sidebar_grad" x1="0%" y1="0%" x2="100%" y2="0%">
