          <MenuButton active={activeTab === 'caixa'} onClick={() => setActiveTab('caixa')} label="Fluxo de Caixa" collapsed={sidebarCollapsed} icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" isDev />
