           <div className="glass-card border border-white/10 px-6 py-3 rounded-2xl flex items-center gap-4 shadow-xl">
              <div className={`w-2 h-2 rounded-full animate-pulse ${userProfile?.status === 'ativo' || isMaster ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
              <div className="flex flex-col">
                <span className="text-[10px] font-black uppercase tracking-widest text-white leading-none mb-1">{userProfile?.nome_completo || (isMaster ? 'Master Admin' : 'Operador')}</span>
                <span className="text-[8px] font-bold text-white/40 uppercase tracking-widest">{userProfile?.empresa_nome || 'Tagway Cloud'}</span>
              </div>
