import React, { useState } from 'react';
import { supabase } from '../lib/supabase';

interface LoginProps {
  onLoginSuccess: (session: any) => void;
}

// Representação fiel da Logo com cores exatas: Laranja #FF6600 e Roxo #8200AD
const TagwayBrainIcon = ({ size = "w-24 h-24" }: { size?: string }) => (
