  isAutoSync, setIsAutoSync
}) => {
  const [expandedFixed, setExpandedFixed] = useState<string[]>(['PESSOAL / RH']);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<string | null>(null);

  // Fallback para a lista técnica de 26% caso o banco esteja vazio
  useEffect(() => {
    if (fixedCosts.length === 0 && faturamento > 0) {
      const defaultList: CostItem[] = [
        { id: 'f1', categoria: 'PESSOAL / RH', descricao: 'Salários e Encargos', valor: faturamento * 0.12 },
        { id: 'f2', categoria: 'ESTRUTURA / OCUPAÇÃO', descricao: 'Aluguel e Condomínio', valor: faturamento * 0.05 },
        { id: 'f3', categoria: 'SOLUÇÃO DE MARKETING', descricao: 'Publicidade e Branding', valor: faturamento * 0.03 },
        { id: 'f4', categoria: 'TECNOLOGIA / TI', descricao: 'Sistemas e Cloud', valor: faturamento * 0.02 },
        { id: 'f5', categoria: 'DESPESAS ADMINISTRATIVAS', descricao: 'Contabilidade e Materiais', valor: faturamento * 0.02 },
        { id: 'f6', categoria: 'FINANCEIRO', descricao: 'Taxas e Tarifas Fixas', valor: faturamento * 0.02 },
      ];
      setFixedCosts(defaultList);
    }
  }, [faturamento, fixedCosts.length]);

  const totalFixed = useMemo(() => fixedCosts.reduce((acc, curr) => acc + curr.valor, 0), [fixedCosts]);
  const fixedPercOnFat = faturamento > 0 ? (totalFixed / faturamento) * 100 : 0;

  const handleSaveConfig = async () => {
    if (!userId) return;
    setIsSaving(true);
    try {
      const { error } = await supabase.from('overhead_configs').upsert({
        user_id: userId,
        faturamento: Number(faturamento),
        fixed_costs: fixedCosts,
        variable_costs: variableCosts,
        is_auto_sync: !!isAutoSync
      }, { onConflict: 'user_id' });
      if (error) throw error;
      setLastSaved(new Date().toLocaleTimeString());
      alert('Configurações salvas e sincronizadas!');
    } catch (e) { alert('Erro ao salvar no banco de dados.'); } finally { setIsSaving(false); }
  };

  const toggleFixed = (cat: string) => {
    setExpandedFixed(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  };

  const addFixedItem = (cat: string) => {
    const newItem: CostItem = {
      id: Math.random().toString(36).substr(2, 9),
      categoria: cat,
      descricao: 'Novo Item',
      valor: 0
    };
    setFixedCosts([...fixedCosts, newItem]);
    if (!expandedFixed.includes(cat)) setExpandedFixed([...expandedFixed, cat]);
  };

  const removeFixedItem = (id: string) => {
    setFixedCosts(fixedCosts.filter(c => c.id !== id));
  };

  const updateFixedItem = (id: string, field: keyof CostItem, value: any) => {
    setFixedCosts(fixedCosts.map(c => c.id === id ? { ...c, [field]: value } : c));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 pb-32 animate-slide-up">
      <header className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 border-b border-slate-200 pb-10">
        <div className="space-y-4">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 bg-black rounded-2xl flex items-center justify-center text-white shadow-xl">
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1"/></svg>
             </div>
             <div>
               <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">Custo Fixo & Overhead</h2>
               <div className="flex items-center gap-3 mt-2">
                 <button onClick={handleSaveConfig} disabled={isSaving} className="bg-emerald-500 text-white text-[9px] font-black uppercase px-4 py-2 rounded-lg transition-all shadow-lg active:scale-95 disabled:opacity-50">
                   {isSaving ? 'Salvando...' : 'Sincronizar Cloud'}
                 </button>
                 {lastSaved && <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Último backup: {lastSaved}</span>}
               </div>
             </div>
          </div>
        </div>

        <div className="flex gap-4">
          <div className="w-64 bg-white p-5 rounded-[2rem] shadow-xl border border-slate-200">
            <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Faturamento Mensal (Ref)</label>
            <div className="flex items-baseline gap-2">
              <span className="text-xl font-black text-slate-300 italic">R$</span>
              <input type="number" value={faturamento} onChange={(e) => setFaturamento(parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-3xl font-black font-mono outline-none text-slate-900 tracking-tighter" />
            </div>
          </div>
          <div className="w-64 bg-black p-5 rounded-[2rem] shadow-2xl text-white">
            <label className="block text-[8px] font-black text-white/40 uppercase tracking-widest mb-1">Impacto no Preço (%)</label>
            <div className="flex items-baseline gap-2">
              <span className="text-4xl font-black font-mono tracking-tighter text-emerald-400">
                {fixedPercOnFat.toFixed(2)}%
              </span>
              <span className="text-[10px] font-black text-white/20 uppercase">Peso</span>
            </div>
          </div>
        </div>
      </header>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <KPIBox label="Total Custos Fixos" value={totalFixed} color="text-slate-900" />
        <KPIBox label="Peso s/ Venda" value={fixedPercOnFat} isPerc color="text-blue-600" />
        <KPIBox label="Target Sugerido" value={26} isPerc color="text-slate-400" />
        <KPIBox label="Status Operacional" value={fixedPercOnFat > 30 ? 'CRÍTICO' : 'SAUDÁVEL'} isText color={fixedPercOnFat > 30 ? 'text-rose-500' : 'text-emerald-500'} />
      </div>

      {/* Accordion Model (Sanfona) */}
      <div className="space-y-3">
        <div className="flex justify-between items-center px-4 mb-4">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Estrutura Detalhada</h3>
          <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest italic">Ajuste os valores para recalcular o overhead automaticamente</span>
        </div>

        <div className="grid grid-cols-1 gap-3">
          {FIXED_CATEGORIES.map(cat => {
            const items = fixedCosts.filter(c => c.categoria === cat);
            const catTotal = items.reduce((a, b) => a + b.valor, 0);
            const isOpen = expandedFixed.includes(cat);

            return (
              <div key={cat} className={`border rounded-2xl overflow-hidden transition-all ${isOpen ? 'border-slate-300 shadow-xl' : 'border-slate-100 shadow-sm'}`}>
                <button 
                  onClick={() => toggleFixed(cat)}
                  className={`w-full flex items-center justify-between p-5 transition-colors ${isOpen ? 'bg-slate-900 text-white' : 'bg-white text-slate-900 hover:bg-slate-50'}`}
                >
                  <div className="flex items-center gap-4">
                    <span className="text-[11px] font-black uppercase tracking-widest">{cat}</span>
                    <span className={`text-[8px] font-black px-2 py-0.5 rounded ${isOpen ? 'bg-white/20' : 'bg-slate-100'}`}>
                      {items.length} ITENS
                    </span>
                  </div>
                  <div className="flex items-center gap-6">
                    <span className={`text-[10px] font-black font-mono ${isOpen ? 'text-emerald-400' : 'text-slate-400'}`}>
                      {formatCurrency(catTotal)}
                    </span>
                    <svg className={`w-5 h-5 transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7"/></svg>
                  </div>
                </button>

                {isOpen && (
                  <div className="p-6 bg-slate-50/50 space-y-4 animate-slide-up">
                    {items.map(item => (
                      <div key={item.id} className="flex gap-4 items-center group">
                        <div className="flex-1">
                          <input 
                            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-black transition-all"
                            value={item.descricao}
                            onChange={(e) => updateFixedItem(item.id, 'descricao', e.target.value)}
                            placeholder="Descrição do custo..."
                          />
                        </div>
                        <div className="w-40 relative">
                          <span className="absolute left-3 top-3.5 text-[9px] font-black text-slate-300 uppercase">R$</span>
                          <input 
                            type="number"
                            className="w-full bg-white border border-slate-200 rounded-xl pl-9 pr-4 py-3 text-xs font-black font-mono outline-none focus:border-black transition-all"
                            value={item.valor}
                            onChange={(e) => updateFixedItem(item.id, 'valor', parseFloat(e.target.value) || 0)}
                          />
                        </div>
                        <button 
                          onClick={() => removeFixedItem(item.id)}
                          className="p-3 text-slate-300 hover:text-rose-500 transition-colors"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        </button>
                      </div>
                    ))}

                    <button 
                      onClick={() => addFixedItem(cat)}
                      className="w-full py-3 border-2 border-dashed border-slate-200 rounded-xl text-[10px] font-black text-slate-400 uppercase tracking-widest hover:border-slate-400 hover:text-slate-600 transition-all flex items-center justify-center gap-2"
                    >
                      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg>
                      Adicionar Item em {cat}
                    </button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

const KPIBox = ({ label, value, color, isPerc = false, isText = false }: any) => (
  <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm hover:shadow-2xl transition-all overflow-hidden relative">
    <div className="relative z-10">
      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1 block">{label}</span>
      <span className={`text-2xl font-black font-mono ${color || 'text-slate-800'} tracking-tighter block truncate`}>
        {isText ? value : (isPerc ? `${value.toFixed(2)}%` : formatCurrency(value))}
      </span>
    </div>
    <div className="absolute -bottom-4 -right-4 w-12 h-12 bg-slate-50 rounded-full opacity-50"></div>
  </div>
);

export default OverheadView;

