  { cat: '9. DEPRECIAÇÃO/AMORTIZAÇÃO', items: ['Depreciação de máquinas', 'Depreciação de veículos', 'Depreciação de computadores', 'Depreciação de móveis', 'Amortização de softwares', 'Amortização de marcas e patentes'] },
