import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { formatCurrency } from '../utils/calculations';

interface SavedSimulation {
  id: string;
  nome_produto: string;
  inputs: any;
  results: any;
  created_at: string;
}

const MyProductsView: React.FC<{ onSelect: (sim: SavedSimulation) => void }> = ({ onSelect }) => {
  const [simulations, setSimulations] = useState<SavedSimulation[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchSimulations();
  }, []);

  const fetchSimulations = async () => {
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      const { data } = await supabase
        .from('saved_simulations')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });
      if (data) setSimulations(data);
    }
    setIsLoading(false);
  };

  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm('Excluir simulação permanentemente?')) return;
    const { error } = await supabase.from('saved_simulations').delete().eq('id', id);
    if (!error) setSimulations(prev => prev.filter(s => s.id !== id));
  };

  if (isLoading) return <div className="text-center py-20 animate-pulse">Carregando itens...</div>;

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      <div className="border-b border-slate-200 pb-8">
        <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Meus Itens</h2>
        <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Simulações Arquivadas</p>
      </div>

      {simulations.length === 0 ? (
        <div className="py-20 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200">
          <p className="text-slate-400 font-black uppercase text-xs tracking-widest">Nenhuma simulação salva ainda.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {simulations.map(sim => (
            <div 
              key={sim.id}
              onClick={() => onSelect(sim)}
              className="bg-white border border-slate-200 rounded-[2rem] p-6 hover:border-black transition-all group cursor-pointer shadow-sm hover:shadow-xl"
            >
              <div className="flex justify-between items-start mb-4">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  {new Date(sim.created_at).toLocaleDateString('pt-BR')}
                </span>
                <button onClick={(e) => handleDelete(sim.id, e)} className="p-2 text-slate-200 hover:text-rose-500 transition-colors">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                </button>
              </div>

              <h3 className="text-lg font-black text-slate-900 tracking-tight leading-tight line-clamp-2 mb-4">
                {sim.nome_produto}
              </h3>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-3 rounded-xl border border-slate-100">
                  <span className="text-[8px] font-black text-slate-400 uppercase block">Venda Alvo</span>
                  <span className="text-sm font-black text-slate-900 font-mono">{formatCurrency(sim.results.precoVendaAlvo)}</span>
                </div>
                <div className="bg-emerald-50 p-3 rounded-xl border border-emerald-100">
                  <span className="text-[8px] font-black text-emerald-600 uppercase block">Lucro Net</span>
                  <span className="text-sm font-black text-emerald-600 font-mono">{sim.inputs.resultadoDesejado}%</span>
                </div>
              </div>

              <div className="mt-6 pt-4 border-t border-slate-50 flex items-center justify-between">
                <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Rota: {sim.inputs.ufOrigem} → {sim.inputs.ufDestino}</span>
                <span className="text-[9px] font-black text-black uppercase group-hover:underline">Abrir →</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
