                            step="0.01"
                            className="w-full bg-white border border-slate-200 rounded-xl pl-8 pr-2 py-2 text-xs font-black font-mono outline-none focus:border-black" 
                            value={item.valor === 0 ? '' : item.valor} 
                            onChange={(e) => {
                               const v = e.target.value === '' ? 0 : parseFloat(e.target.value);
                               updateFixed(item.id, { valor: v });
