  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isMobileSheetOpen, setIsMobileSheetOpen] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);
  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>([]);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>([]);
  const [isAutoSync, setIsAutoSync] = useState(false);
  const [isSavingSim, setIsSavingSim] = useState(false);

  const isMaster = useMemo(() => session?.user?.email === MASTER_EMAIL, [session]);

  useEffect(() => {
    const init = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      setSession(currentSession);
      if (currentSession) {
        const { data } = await supabase.from('user_configs').select('*').eq('user_id', currentSession.user.id).maybeSingle();
        if (data) setUserProfile(data);
        const { data: oh } = await supabase.from('overhead_configs').select('*').eq('user_id', currentSession.user.id).maybeSingle();
        if (oh) {
          setFaturamento(oh.faturamento || 100000);
          setFixedCosts(oh.fixed_costs || []);
          setVariableCosts(oh.variable_costs || []);
          setIsAutoSync(!!oh.is_auto_sync);
        }
      }
      setIsInitialized(true);
    };
    init();
  }, []);

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  useEffect(() => {
    if (isAutoSync && faturamento > 0) {
      const totalF = fixedCosts.reduce((a, b) => a + b.valor, 0);
      const totalV = variableCosts.reduce((a, b) => a + b.percentual, 0);
      const percFixed = (totalF / faturamento) * 100;
      setInputs(prev => ({
        ...prev,
        custosFixos: Number(percFixed.toFixed(2)),
        outrosCustosVariaveis: Number(totalV.toFixed(2))
      }));
    }
  }, [fixedCosts, variableCosts, faturamento, isAutoSync]);

  const handleReset = () => {
    setInputs(prev => ({
      ...prev,
      nomeProduto: '',
      telefone: '',
      valorCompra: 0,
      ipiPerc: 0,
      freteValor: 0,
      ncmCodigo: '',
      mva: 0,
      mvaOriginal: 0,
    }));
  };

  const handleSaveSimulation = async () => {
    if (!session) {
      alert('Sessão expirada. Faça login novamente.');
      return;
    }

    setIsSavingSim(true);
    try {
      const { error } = await supabase.from('saved_simulations').insert([{
        user_id: session.user.id,
        nome_produto: inputs.nomeProduto || 'Sem Nome',
        inputs: JSON.parse(JSON.stringify(inputs)),
        results: JSON.parse(JSON.stringify(results))
      }]);

      if (error) {
        if (error.message?.includes('schema cache') || error.message?.includes('not found')) {
           alert('ERRO: A tabela "saved_simulations" não foi encontrada no banco. Por favor, execute o script SQL de criação no seu painel do Supabase.');
        } else {
           throw new Error(error.message);
        }
      } else {
        alert('Simulação arquivada com sucesso!');
      }
    } catch (e: any) {
      console.error('Erro ao salvar simulação:', e);
      alert('Erro ao salvar: ' + (e.message || 'Falha técnica. Verifique sua rede.'));
    } finally {
      setIsSavingSim(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    window.location.reload();
  };

  if (!isInitialized) return null;
  if (!session) return <Login onLoginSuccess={setSession} />;

  return (
    <div className="flex h-screen w-full bg-[#000000] overflow-hidden text-slate-900">
      {/* Desktop Aside */}
      <aside className="hidden lg:flex w-[280px] h-full flex-col border-r border-white/5 p-6 overflow-y-auto custom-scrollbar">
        <div className="mb-10"><TagwayHorizontalLogo className="h-7 w-auto" /></div>
        <nav className="flex-1 space-y-1">
          <DesktopMenuButton active={activeTab === 'calculadora'} onClick={() => setActiveTab('calculadora')} label="Calculadora" icon="M3 12h18M3 6h18M3 18h18" />
          <DesktopMenuButton active={activeTab === 'meus-produtos'} onClick={() => setActiveTab('meus-produtos')} label="Meus Itens" icon="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
          <DesktopMenuButton active={activeTab === 'resumo-fiscal'} onClick={() => setActiveTab('resumo-fiscal')} label="Análise Fisco" icon="M9 17v-2m3 2v-4m3 2v-6m-8-2h8a2 2 0 012 2v9a2 2 0 01-2 2H7a2 2 0 01-2-2V5a2 2 0 012-2z" />
          <DesktopMenuButton active={activeTab === 'catalogo'} onClick={() => setActiveTab('catalogo')} label="NCM 2025" icon="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          <DesktopMenuButton active={activeTab === 'overhead'} onClick={() => setActiveTab('overhead')} label="Overhead" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" />
          <DesktopMenuButton active={activeTab === 'jarvis'} onClick={() => setActiveTab('jarvis')} label="Jarvis AI" icon="M13 10V3L4 14h7v7l9-11h-7z" isAi />

          <div className="pt-4 pb-2 text-[9px] font-black text-white/20 uppercase tracking-widest pl-4">Ecossistema (Dev)</div>
          <DesktopMenuButton active={activeTab === 'logistica'} onClick={() => setActiveTab('logistica')} label="Logística" icon="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" isDev />
          <DesktopMenuButton active={activeTab === 'estoque'} onClick={() => setActiveTab('estoque')} label="Estoque" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-14v4m0 0l8 4m-8-4l-8 4m8 5v3" isDev />
          <DesktopMenuButton active={activeTab === 'metas'} onClick={() => setActiveTab('metas')} label="Metas" icon="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" isDev />
          <DesktopMenuButton active={activeTab === 'dre'} onClick={() => setActiveTab('dre')} label="DRE Real" icon="M11 3.055A9.001 9.001 0 1020.945 13H11V3.055z" isDev />
          <DesktopMenuButton active={activeTab === 'caixa'} onClick={() => setActiveTab('caixa')} label="Fluxo Caixa" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" isDev />

          <div className="pt-6">
            <DesktopMenuButton active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Configuração" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
            {isMaster && <DesktopMenuButton active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944" />}
          </div>
        </nav>
        <button onClick={handleLogout} className="mt-auto p-4 text-rose-500 font-black uppercase text-[10px] tracking-widest hover:bg-rose-500/10 rounded-xl transition-all border border-rose-500/20">Sair</button>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 bg-[#f8fafc] lg:rounded-l-[3rem] shadow-2xl overflow-hidden flex flex-col">
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 lg:p-12 pb-32 lg:pb-12">
          {activeTab === 'calculadora' && (
            <div className="flex flex-col lg:flex-row gap-8 lg:gap-12 max-w-[1600px] mx-auto animate-slide-up">
              <div className="w-full lg:w-80 space-y-6 shrink-0">
                <FiscalHeader inputs={inputs} setInputs={setInputs} />
                <Sidebar inputs={inputs} setInputs={setInputs} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
                <button 
                  onClick={handleSaveSimulation} 
                  disabled={isSavingSim}
                  className="w-full bg-emerald-600 text-white py-4 rounded-xl font-black uppercase text-[11px] tracking-widest shadow-xl hover:bg-emerald-700 transition-all flex items-center justify-center gap-2"
                >
                  {isSavingSim ? 'Gravando...' : 'Arquivar Item'}
                </button>
              </div>
              <div className="flex-1">
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} onReset={handleReset} />
              </div>
            </div>
          )}

          {activeTab === 'meus-produtos' && <MyProductsView onSelect={(sim) => { setInputs(sim.inputs); setActiveTab('calculadora'); }} />}
          {activeTab === 'resumo-fiscal' && <ResumoFiscalView results={results} inputs={inputs} />}
          {activeTab === 'catalogo' && <ProductsView onSelectNcm={(n) => { setInputs(p => ({...p, ...n, nomeProduto: n.descricao})); setActiveTab('calculadora'); }} />}
          {activeTab === 'overhead' && <OverheadView faturamento={faturamento} setFaturamento={setFaturamento} fixedCosts={fixedCosts} setFixedCosts={setFixedCosts} variableCosts={variableCosts} setVariableCosts={setVariableCosts} userId={session?.user?.id} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />}
          {activeTab === 'jarvis' && <AIView results={results} inputs={inputs} />}
          {activeTab === 'configuracao' && <ConfiguracaoView userId={session?.user?.id} />}
          {activeTab === 'master' && <AdminView />}

          {/* Módulos em Desenvolvimento */}
          {['logistica', 'estoque', 'metas', 'dre', 'caixa'].includes(activeTab) && (
            <ComingSoonView 
              title={activeTab.toUpperCase()} 
              desc="Este módulo está passando por homologação de regras fiscais 2025/2026." 
              icon={
                activeTab === 'logistica' ? "M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" :
                activeTab === 'estoque' ? "M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-14v4m0 0l8 4m-8-4l-8 4m8 5v3" :
                activeTab === 'metas' ? "M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" :
                "M11 3.055A9.001 9.001 0 1020.945 13H11V3.055z"
              }
              date="Q4 2026"
            />
          )}
        </div>
      </main>

      {/* Mobile Bottom Dock */}
      <nav className="lg:hidden mobile-dock fixed bottom-6 left-6 right-6 h-[72px] rounded-[2rem] flex items-center gap-2 overflow-x-auto no-scrollbar px-6 z-[100] shadow-2xl bg-white border border-slate-100">
        <MobileDockItem active={activeTab === 'calculadora'} onClick={() => setActiveTab('calculadora')} label="Calc" icon="M3 12h18M3 6h18M3 18h18" />
        <MobileDockItem active={activeTab === 'meus-produtos'} onClick={() => setActiveTab('meus-produtos')} label="Meus" icon="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
        <MobileDockItem active={activeTab === 'resumo-fiscal'} onClick={() => setActiveTab('resumo-fiscal')} label="Fisco" icon="M9 17v-2m3 2v-4m3 2v-6m-8-2h8a2 2 0 012 2v9a2 2 0 01-2 2H7a2 2 0 01-2-2V5a2 2 0 012-2z" />
        <MobileDockItem active={activeTab === 'jarvis'} onClick={() => setActiveTab('jarvis')} label="Jarvis" icon="M13 10V3L4 14h7v7l9-11h-7z" isAi />
        <MobileDockItem active={activeTab === 'logistica'} onClick={() => setActiveTab('logistica')} label="Log" icon="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" isDev />
        <MobileDockItem active={activeTab === 'estoque'} onClick={() => setActiveTab('estoque')} label="Est" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-14v4m0 0l8 4m-8-4l-8 4m8 5v3" isDev />
        <MobileDockItem active={activeTab === 'metas'} onClick={() => setActiveTab('metas')} label="Meta" icon="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" isDev />
        <MobileDockItem active={activeTab === 'dre'} onClick={() => setActiveTab('dre')} label="DRE" icon="M11 3.055A9.001 9.001 0 1020.945 13H11V3.055z" isDev />
        <MobileDockItem active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Ajuste" icon="M4 6h16M4 12h16m-7 6h7" />
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { SimulationInputs } from '../types';

interface SidebarProps {
  inputs: SimulationInputs;
  setInputs: React.Dispatch<React.SetStateAction<SimulationInputs>>;
  isAutoSync: boolean;
  setIsAutoSync: (val: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ inputs, setInputs, isAutoSync, setIsAutoSync }) => {
  const [collapsed, setCollapsed] = useState<string[]>([]);

  const toggleCollapse = (id: string) => {
    setCollapsed(prev => 
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  const handleChange = (field: keyof SimulationInputs, value: any) => {
    const textFields = ['mode', 'ufOrigem', 'ufDestino', 'nomeProduto', 'ncmCodigo', 'simulationMode', 'telefone'];
    setInputs(prev => ({
      ...prev,
      [field]: textFields.includes(field) 
        ? value 
        : (typeof value === 'string' ? parseFloat(value.replace(',', '.')) || 0 : value),
    }));
  };

  return (
    <div className="space-y-6">
      {/* Identificação do Cliente */}
      <section className="space-y-3">
        <SidebarHeader 
          label="Identificação do Cliente" 
          isCollapsed={collapsed.includes('identificacao')} 
          onToggle={() => toggleCollapse('identificacao')} 
        />
        {!collapsed.includes('identificacao') && (
          <div className="grid grid-cols-1 gap-3 animate-slide-up">
            <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm focus-within:ring-2 focus-within:ring-black/5 focus-within:border-black transition-all group">
              <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 group-focus-within:text-black transition-colors">Telefone do Cliente</label>
              <input 
                type="text" 
                value={inputs.telefone || ''} 
                onChange={(e) => handleChange('telefone', e.target.value)}
                placeholder="(00) 00000-0000"
                className="w-full text-lg font-black text-slate-800 font-mono outline-none bg-transparent placeholder:text-slate-200" 
              />
            </div>
          </div>
        )}
      </section>

      {/* Regime Selector */}
      <section className="space-y-3">
        <SidebarHeader 
          label="Regime de Operação" 
          isCollapsed={collapsed.includes('regime')} 
          onToggle={() => toggleCollapse('regime')} 
        />
        {!collapsed.includes('regime') && (
          <div className="grid grid-cols-1 gap-2 animate-slide-up">
            {[
              { id: 'substituido', label: 'Substituição (ST)', sub: 'Saída Desonerada' },
              { id: 'tributado', label: 'Tributado', sub: 'Débito e Crédito' },
              { id: 'reduzido', label: 'Base Reduzida', sub: 'Benefício Fiscal' },
            ].map(mode => (
              <button
                key={mode.id}
                onClick={() => handleChange('mode', mode.id)}
                className={`text-left p-4 rounded-xl border transition-all flex flex-col gap-0.5 ${
                  inputs.mode === mode.id 
                  ? 'bg-black border-black text-white shadow-xl shadow-black/10' 
                  : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'
                }`}
              >
                <span className="text-[11px] font-black uppercase tracking-tight">{mode.label}</span>
                <span className={`text-[8px] font-bold uppercase opacity-50 ${inputs.mode === mode.id ? 'text-white' : 'text-slate-400'}`}>{mode.sub}</span>
              </button>
            ))}
          </div>
        )}
      </section>

      {/* Costs Inputs */}
      <section className="space-y-3">
        <SidebarHeader 
          label="Valores de Aquisição" 
          isCollapsed={collapsed.includes('costs')} 
          onToggle={() => toggleCollapse('costs')} 
        />
        {!collapsed.includes('costs') && (
          <div className="grid grid-cols-1 gap-3 animate-slide-up">
            <InputGroup label="Valor Líquido (R$)" value={inputs.valorCompra} onChange={(v: string) => handleChange('valorCompra', v)} />
            <div className="grid grid-cols-2 gap-3">
              <InputGroup label="IPI (%)" value={inputs.ipiPerc} onChange={(v: string) => handleChange('ipiPerc', v)} />
              <InputGroup label="Frete (R$)" value={inputs.freteValor} onChange={(v: string) => handleChange('freteValor', v)} />
            </div>

            <div className="p-4 bg-blue-50/50 rounded-xl border border-blue-100 space-y-3">
              <span className="text-[8px] font-black text-blue-400 uppercase tracking-widest block">Créditos de Entrada (Fixos)</span>
              <div className="grid grid-cols-2 gap-3">
                <InputGroup label="ICMS Merc (%)" value={inputs.icmsCreditoMercadoria} onChange={(v: string) => handleChange('icmsCreditoMercadoria', v)} />
                <InputGroup label="ICMS Frete (%)" value={inputs.icmsCreditoFrete} onChange={(v: string) => handleChange('icmsCreditoFrete', v)} />
              </div>
              <InputGroup label="PIS/COFINS Créd (%)" value={inputs.pisCofinsRate} onChange={(v: string) => handleChange('pisCofinsRate', v)} />
            </div>
          </div>
        )}
      </section>

      {/* Operating Expenses */}
      <section className="space-y-3">
        <SidebarHeader 
          label="Despesas Operacionais" 
          isCollapsed={collapsed.includes('expenses')} 
          onToggle={() => toggleCollapse('expenses')} 
        />
        {!collapsed.includes('expenses') && (
          <div className="grid grid-cols-1 gap-3 animate-slide-up">
            <InputGroup label="Comissão (%)" value={inputs.comissaoVenda} onChange={(v: string) => handleChange('comissaoVenda', v)} />

            <div className={`rounded-xl p-4 shadow-inner relative group overflow-hidden border-2 transition-all ${isAutoSync ? 'bg-blue-50/50 border-dashed border-blue-100' : 'bg-white border-slate-200 border-solid shadow-sm'}`}>
              <div className="flex justify-between items-center mb-2">
                <label className={`block text-[8px] font-black uppercase tracking-widest ${isAutoSync ? 'text-blue-500' : 'text-slate-400'}`}>Overhead / Fixo (%)</label>

                <div className="flex bg-slate-200/50 p-0.5 rounded-lg">
                  <button 
                    onClick={() => setIsAutoSync(false)}
                    className={`px-2 py-1 rounded-md text-[7px] font-black uppercase transition-all ${!isAutoSync ? 'bg-white text-black shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    M
                  </button>
                  <button 
                    onClick={() => setIsAutoSync(true)}
                    className={`px-2 py-1 rounded-md text-[7px] font-black uppercase transition-all ${isAutoSync ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    A
                  </button>
                </div>
              </div>

              <div className="flex items-center gap-2">
                <input 
                  type="number" 
                  readOnly={isAutoSync}
                  value={inputs.custosFixos} 
                  onChange={(e) => handleChange('custosFixos', e.target.value)}
                  className={`w-full text-lg font-black font-mono bg-transparent outline-none transition-all ${isAutoSync ? 'text-blue-600 cursor-default' : 'text-slate-900 cursor-text'}`} 
                />
                <span className={`text-[10px] font-black ${isAutoSync ? 'text-blue-300' : 'text-slate-300'}`}>%</span>
              </div>
            </div>
          </div>
        )}
      </section>

      {/* Margem Final */}
      <section className="bg-black rounded-2xl p-6 text-white shadow-2xl shadow-black/20 ring-1 ring-white/10 space-y-4">
        <div className="flex justify-between items-center">
          <label className="text-[9px] font-black uppercase tracking-widest text-white/40">Margem Líquida Alvo</label>
          <span className="text-[8px] font-black text-emerald-400 bg-emerald-400/10 px-2 py-0.5 rounded uppercase">Meta</span>
        </div>
        <div className="flex items-center gap-4">
          <input 
            type="number" 
            value={inputs.resultadoDesejado} 
            onChange={(e) => handleChange('resultadoDesejado', e.target.value)}
            className="w-full bg-transparent text-5xl font-black font-mono outline-none border-none p-0 tracking-tighter" 
          />
          <div className="flex flex-col gap-1 shrink-0">
             <button onClick={() => handleChange('resultadoDesejado', inputs.resultadoDesejado + 0.5)} className="p-2 bg-white/10 rounded-lg hover:bg-white/20 transition-all"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M7 14l5-5 5 5z"/></svg></button>
             <button onClick={() => handleChange('resultadoDesejado', Math.max(0, inputs.resultadoDesejado - 0.5))} className="p-2 bg-white/10 rounded-lg hover:bg-white/20 transition-all"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M7 10l5 5 5-5z"/></svg></button>
          </div>
        </div>
      </section>
    </div>
  );
};

const SidebarHeader = ({ label, isCollapsed, onToggle }: any) => (
  <button 
    onClick={onToggle}
    className="w-full flex items-center justify-between text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 hover:text-slate-600 transition-colors group"
  >
    {label}
    <div className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${isCollapsed ? 'bg-slate-100' : 'bg-black text-white'}`}>
      <svg className={`w-3 h-3 transition-transform ${isCollapsed ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
      </svg>
    </div>
  </button>
);

const InputGroup = ({ label, value, onChange }: { label: string, value: number, onChange: (v: string) => void }) => (
  <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm focus-within:ring-2 focus-within:ring-black/5 focus-within:border-black transition-all group">
    <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 group-focus-within:text-black transition-colors">{label}</label>
    <input 
      type="number" 
      step="0.01"
