      prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]
    );
  };

  const handlePrint = () => window.print();

  const handleShare = async () => {
    const shareMessage = `*📊 SIMULAÇÃO FISCAL TAGWAY*\n` +
      `----------------------------------\n` +
      `*Item:* ${inputs.nomeProduto || 'Produto não identificado'}\n` +
