import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setErrorMessage(null);
    try {
      // Busca direta sem filtros complexos para testar RLS
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) {
        if (error.message?.includes('infinite recursion')) {
          setErrorMessage("ERRO CRÍTICO DE BANCO: Loop de recursão detectado. Por favor, execute o script SQL 'Nuclear' enviado para limpar as políticas RLS.");
        } else {
          throw error;
        }
      }
      if (data) {
        setUsers(data as UserProfile[]);
      }
    } catch (err: any) {
      setErrorMessage(err.message || 'Erro ao conectar com o banco de dados.');
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          email: user.email,
          empresa_nome: user.empresa_nome,
          regime_tributario: user.regime_tributario,
          status: user.status
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert('Configurações atualizadas!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro ao salvar: ${err.message}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.senha || !newUser.nome) {
      alert('Campos obrigatórios: Nome, E-mail e Senha.');
      return;
    }

    setIsRegistering(true);
    setErrorMessage(null);

    try {
      // 1. Criar Usuário no Auth do Supabase
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: newUser.email,
        password: newUser.senha,
        options: {
          data: {
            full_name: newUser.nome,
            company: newUser.empresa
          }
        }
      });

      if (authError) throw authError;

      if (authData.user) {
        // 2. Criar Perfil na user_configs
        const { error: configError } = await supabase.from('user_configs').insert([
          {
            user_id: authData.user.id,
            nome_completo: newUser.nome,
            email: newUser.email,
            empresa_nome: newUser.empresa,
            regime_tributario: newUser.regime,
            is_admin: false,
            status: 'ativo'
          }
        ]);

        if (configError) throw configError;

        alert('OPERADOR CADASTRADO COM SUCESSO!\n\nNota: Se o e-mail de confirmação estiver ativo no Supabase, o usuário precisará confirmar antes de logar.');
        setNewUser({ nome: '', email: '', senha: '', empresa: '', regime: 'Real' });
        fetchUsers();
      }
    } catch (err: any) {
      const msg = err.message || 'Erro desconhecido';
      if (msg.includes('infinite recursion')) {
        setErrorMessage("ERRO DE RECURSÃO: O banco de dados impediu o cadastro. Rode o script SQL de correção no painel do Supabase.");
      } else {
        alert(`FALHA NO CADASTRO: ${msg}`);
      }
    } finally {
      setIsRegistering(false);
    }
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-20 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 pb-8">
        <div>
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 text-white p-2 rounded-lg shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944"/></svg>
            </div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Master Control</h2>
          </div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Central de Operadores TAGWAY</p>
        </div>
        <button onClick={fetchUsers} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">
          Sincronizar Lista
        </button>
      </header>

      {errorMessage && (
        <div className="bg-rose-50 border border-rose-200 p-6 rounded-3xl animate-bounce">
          <p className="text-rose-600 font-black uppercase text-[10px] tracking-widest mb-2">Erro Detectado:</p>
          <p className="text-rose-800 text-xs font-bold">{errorMessage}</p>
        </div>
      )}

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Formulário de Cadastro */}
        <div className="xl:col-span-1">
          <section className="bg-white rounded-[2.5rem] p-8 border border-slate-200 shadow-xl space-y-6 sticky top-8">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Novo Operador</h3>

            <form onSubmit={handleCreateUser} className="space-y-4">
              <AdminInput label="Nome Completo" value={newUser.nome} onChange={(v) => setNewUser({...newUser, nome: v})} />
              <AdminInput label="E-mail" type="email" value={newUser.email} onChange={(v) => setNewUser({...newUser, email: v})} />
              <AdminInput label="Senha de Acesso" type="password" value={newUser.senha} onChange={(v) => setNewUser({...newUser, senha: v})} />
              <AdminInput label="Empresa" value={newUser.empresa} onChange={(v) => setNewUser({...newUser, empresa: v})} />

              <div className="space-y-1.5">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime Padrão</label>
                <select 
                  value={newUser.regime}
                  onChange={(e) => setNewUser({...newUser, regime: e.target.value as any})}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-black outline-none focus:border-purple-500"
                >
                  <option value="Real">Lucro Real</option>
                  <option value="Presumido">Lucro Presumido</option>
                  <option value="Simples">Simples Nacional</option>
                </select>
              </div>

              <button 
                type="submit" 
                disabled={isRegistering} 
                className="w-full bg-black text-white py-4 rounded-xl font-black uppercase tracking-widest text-[10px] shadow-xl hover:bg-slate-800 disabled:opacity-50 transition-all btn-touch"
              >
                {isRegistering ? 'Processando...' : 'Liberar Acesso'}
              </button>
            </form>
          </section>
        </div>

        {/* Lista de Usuários */}
        <div className="xl:col-span-2 space-y-6">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Usuários Cadastrados ({users.length})</h3>
          <div className="space-y-3">
            {users.map(user => (
              <div key={user.user_id} className={`bg-white border rounded-[2rem] overflow-hidden transition-all duration-300 ${expandedUserId === user.user_id ? 'border-black shadow-2xl' : 'border-slate-200 shadow-sm'}`}>
                <button 
                  onClick={() => setExpandedUserId(expandedUserId === user.user_id ? null : user.user_id)} 
                  className="w-full flex items-center justify-between p-6 text-left hover:bg-slate-50 transition-colors"
                >
                  <div className="flex items-center gap-4">
                    <div className={`w-3 h-3 rounded-full ${user.status === 'ativo' ? 'bg-emerald-500' : user.status === 'atualizando' ? 'bg-blue-500' : 'bg-rose-500'}`}></div>
                    <div>
                      <h4 className="font-black text-slate-900 tracking-tight leading-none mb-1">{user.nome_completo || 'Sem Nome'}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{user.email}</p>
                    </div>
                  </div>
                  <svg className={`w-5 h-5 text-slate-300 transition-transform ${expandedUserId === user.user_id ? 'rotate-180 text-black' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7"/></svg>
                </button>

                {expandedUserId === user.user_id && (
                  <div className="p-8 border-t border-slate-100 space-y-8 animate-slide-up">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <AdminInput label="Nome" value={user.nome_completo} onChange={(v) => updateUserInState(user.user_id, 'nome_completo', v)} />
                      <AdminInput label="Empresa" value={user.empresa_nome} onChange={(v) => updateUserInState(user.user_id, 'empresa_nome', v)} />
                      <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime Fiscal</label>
                        <select 
                          value={user.regime_tributario}
                          onChange={(e) => updateUserInState(user.user_id, 'regime_tributario', e.target.value)}
                          className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-black outline-none"
                        >
                          <option value="Real">Lucro Real</option>
                          <option value="Presumido">Lucro Presumido</option>
                          <option value="Simples">Simples Nacional</option>
                        </select>
                      </div>
                      <div className="space-y-1.5">
                        <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Status de Acesso</label>
                        <div className="flex gap-2">
                           <button onClick={() => updateUserInState(user.user_id, 'status', 'ativo')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase border ${user.status === 'ativo' ? 'bg-emerald-500 text-white border-emerald-500' : 'bg-white text-slate-400 border-slate-200'}`}>Ativo</button>
                           <button onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase border ${user.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600' : 'bg-white text-slate-400 border-slate-200'}`}>Bloqueado</button>
                        </div>
                      </div>
                    </div>

                    <div className="pt-6 border-t border-slate-50 flex justify-end">
                      <button 
                        onClick={() => handleUpdateUser(user)} 
                        disabled={isUpdating === user.user_id} 
                        className="bg-black text-white px-10 py-3 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl disabled:opacity-50 transition-all active:scale-95"
                      >
                        {isUpdating === user.user_id ? 'Salvando...' : 'Aplicar Alterações'}
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

const AdminInput = ({ label, value, onChange, type = 'text' }: any) => (
  <div className="space-y-1.5">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type={type} 
      value={value || ''} 
      onChange={(e) => onChange(e.target.value)} 
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:border-black transition-all" 
    />
  </div>
);

export default AdminView;

