export default AdminView;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setErrorMessage(null);
    try {
      // O Master deve conseguir ver todos se o SQL de permissão estiver correto
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) throw error;

      if (data) {
        setUsers(data as UserProfile[]);
      }
    } catch (err: any) {
      console.error("Erro ao buscar usuários:", err);
      setErrorMessage(err.message || 'Erro ao carregar lista de operadores.');
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          regime_tributario: user.regime_tributario,
          status: user.status
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert('Operador atualizado!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro na atualização: ${err.message}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.senha || !newUser.nome) {
      alert('Preencha os campos obrigatórios.');
      return;
    }

    setIsRegistering(true);
    setErrorMessage(null);

    try {
      // 1. Criar no Authentication
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: newUser.email.trim(),
        password: newUser.senha,
        options: {
          data: {
            full_name: newUser.nome,
            company: newUser.empresa
          }
        }
      });

      if (authError) throw authError;

      if (authData.user) {
        // 2. Inserir na tabela user_configs
        // IMPORTANTE: Se o SQL de Master não for rodado, isso aqui falha por RLS!
        const { error: configError } = await supabase.from('user_configs').insert([
          {
            user_id: authData.user.id,
            nome_completo: newUser.nome,
            email: newUser.email.trim(),
            empresa_nome: newUser.empresa,
            regime_tributario: newUser.regime,
            is_admin: false,
            status: 'ativo'
          }
        ]);

        if (configError) {
          // Se falhou aqui, o usuário existe no Auth mas não no BD
          throw new Error(`Usuário criado no Auth, mas falha ao gravar perfil: ${configError.message}`);
        }

        alert('OPERADOR CADASTRADO E LIBERADO!');
        setNewUser({ nome: '', email: '', senha: '', empresa: '', regime: 'Real' });
        fetchUsers();
      }
    } catch (err: any) {
      setErrorMessage(`FALHA: ${err.message}`);
    } finally {
      setIsRegistering(false);
    }
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-20 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 pb-8">
        <div>
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 text-white p-2 rounded-lg shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944"/></svg>
            </div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Master Control</h2>
          </div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Gestão de Operadores de Sistema</p>
        </div>
        <div className="flex gap-2">
          <button onClick={fetchUsers} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">
            Recarregar Lista
          </button>
        </div>
      </header>

      {errorMessage && (
        <div className="bg-rose-50 border border-rose-200 p-6 rounded-[2rem] shadow-lg animate-slide-up">
          <div className="flex items-start gap-4">
            <div className="bg-rose-500 text-white p-2 rounded-lg">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            </div>
            <div>
              <p className="text-rose-600 font-black uppercase text-[10px] tracking-widest mb-1">Erro de Sincronização</p>
              <p className="text-rose-800 text-sm font-bold leading-relaxed">{errorMessage}</p>
              <p className="text-rose-600/60 text-[9px] font-black uppercase mt-2">Dica: Rode o Script SQL de Permissões Master no Painel Supabase.</p>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Formulário */}
        <div className="xl:col-span-1">
          <section className="bg-white rounded-[2.5rem] p-8 border border-slate-200 shadow-xl space-y-6 sticky top-8">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Liberar Novo Operador</h3>

            <form onSubmit={handleCreateUser} className="space-y-4">
              <AdminInput label="Nome do Operador" value={newUser.nome} onChange={(v: string) => setNewUser({...newUser, nome: v})} />
              <AdminInput label="E-mail Corporativo" type="email" value={newUser.email} onChange={(v: string) => setNewUser({...newUser, email: v})} />
              <AdminInput label="Senha de Acesso" type="password" value={newUser.senha} onChange={(v: string) => setNewUser({...newUser, senha: v})} />
              <AdminInput label="Empresa / Filial" value={newUser.empresa} onChange={(v: string) => setNewUser({...newUser, empresa: v})} />

              <div className="space-y-1.5">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime Fiscal Padrão</label>
                <select 
                  value={newUser.regime}
                  onChange={(e) => setNewUser({...newUser, regime: e.target.value as any})}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-black outline-none focus:border-black"
                >
                  <option value="Real">Lucro Real</option>
                  <option value="Presumido">Lucro Presumido</option>
                  <option value="Simples">Simples Nacional</option>
                </select>
              </div>

              <button 
                type="submit" 
                disabled={isRegistering} 
                className="w-full bg-black text-white py-4 rounded-xl font-black uppercase tracking-widest text-[10px] shadow-xl hover:bg-slate-800 disabled:opacity-50 transition-all active:scale-[0.98]"
              >
                {isRegistering ? 'Processando...' : 'Liberar Acesso'}
              </button>
            </form>
          </section>
        </div>

        {/* Lista de Liberados */}
        <div className="xl:col-span-2 space-y-6">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Operadores com Acesso ({users.length})</h3>
          <div className="space-y-3">
            {users.length === 0 ? (
              <div className="bg-white border border-dashed border-slate-200 p-16 rounded-[2rem] text-center">
                <div className="text-4xl mb-4 opacity-10">👥</div>
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Nenhum operador sincronizado no banco de dados.</p>
              </div>
            ) : (
              users.map(user => (
                <div key={user.user_id} className={`bg-white border rounded-[2.5rem] overflow-hidden transition-all duration-300 ${expandedUserId === user.user_id ? 'border-black shadow-2xl' : 'border-slate-100 shadow-sm'}`}>
                  <button 
                    onClick={() => setExpandedUserId(expandedUserId === user.user_id ? null : user.user_id)} 
                    className="w-full flex items-center justify-between p-7 text-left hover:bg-slate-50 transition-colors"
                  >
                    <div className="flex items-center gap-5">
                      <div className={`w-3 h-3 rounded-full ${user.status === 'ativo' ? 'bg-emerald-500' : 'bg-rose-500'} shadow-[0_0_10px_rgba(16,185,129,0.3)]`}></div>
                      <div>
                        <h4 className="font-black text-slate-900 tracking-tight leading-none mb-1">{user.nome_completo || 'Sem Identificação'}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{user.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                       <span className="text-[8px] font-black text-slate-300 uppercase bg-slate-100 px-2 py-1 rounded">{user.regime_tributario}</span>
                       <svg className={`w-5 h-5 text-slate-300 transition-transform ${expandedUserId === user.user_id ? 'rotate-180 text-black' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7"/></svg>
                    </div>
                  </button>

                  {expandedUserId === user.user_id && (
                    <div className="p-10 border-t border-slate-50 bg-slate-50/30 space-y-8 animate-slide-up">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <AdminInput label="Nome Completo" value={user.nome_completo} onChange={(v: string) => updateUserInState(user.user_id, 'nome_completo', v)} />
                        <AdminInput label="Empresa Filiada" value={user.empresa_nome} onChange={(v: string) => updateUserInState(user.user_id, 'empresa_nome', v)} />

                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime de Operação</label>
                          <select 
                            value={user.regime_tributario}
                            onChange={(e) => updateUserInState(user.user_id, 'regime_tributario', e.target.value)}
                            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-black outline-none"
                          >
                            <option value="Real">Lucro Real</option>
                            <option value="Presumido">Lucro Presumido</option>
                            <option value="Simples">Simples Nacional</option>
                          </select>
                        </div>

                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Status do Acesso</label>
                          <div className="flex gap-2">
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'ativo')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'ativo' ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Ativo</button>
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Bloqueado</button>
                          </div>
                        </div>
                      </div>

                      <div className="pt-6 border-t border-slate-100 flex justify-end">
                        <button 
                          onClick={() => handleUpdateUser(user)} 
                          disabled={isUpdating === user.user_id} 
                          className="bg-black text-white px-12 py-4 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-2xl disabled:opacity-50 transition-all hover:bg-slate-800 active:scale-95"
                        >
                          {isUpdating === user.user_id ? 'Gravando...' : 'Aplicar Alterações'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const AdminInput = ({ label, value, onChange, type = 'text' }: any) => (
  <div className="space-y-1.5">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type={type} 
      value={value || ''} 
      onChange={(e) => onChange(e.target.value)} 
      className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-black transition-all" 
    />
  </div>
);

export default AdminView;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const parseError = (err: any): string => {
    if (typeof err === 'string') return err;
    if (err && err.message) return err.message;
    if (err && typeof err === 'object') {
      try {
        return JSON.stringify(err);
      } catch {
        return 'Erro desconhecido (Objeto não serializável)';
      }
    }
    return 'Ocorreu um erro inesperado.';
  };

  const fetchUsers = async () => {
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) throw error;

      if (data) {
        setUsers(data as UserProfile[]);
      }
    } catch (err: any) {
      console.error("Erro ao buscar usuários:", err);
      const msg = parseError(err);

      if (msg.toLowerCase().includes('infinite recursion') || msg.toLowerCase().includes('policy')) {
        setErrorMessage("ERRO DE PERMISSÃO (RLS): O Master não tem permissão para ler a tabela. Rode o SQL 'MASTER CONTROL' no painel do Supabase.");
      } else {
        setErrorMessage(`Falha na sincronização: ${msg}`);
      }
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          regime_tributario: user.regime_tributario,
          status: user.status
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert('Configurações salvas!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro ao atualizar: ${parseError(err)}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.senha || !newUser.nome) {
      alert('Preencha os campos obrigatórios.');
      return;
    }

    setIsRegistering(true);
    setErrorMessage(null);

    try {
      // 1. Criar no Authentication
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: newUser.email.trim(),
        password: newUser.senha,
        options: {
          data: {
            full_name: newUser.nome,
            company: newUser.empresa
          }
        }
      });

      if (authError) throw authError;

      if (authData.user) {
        // 2. Inserir na tabela user_configs
        const { error: configError } = await supabase.from('user_configs').insert([
          {
            user_id: authData.user.id,
            nome_completo: newUser.nome,
            email: newUser.email.trim(),
            empresa_nome: newUser.empresa,
            regime_tributario: newUser.regime,
            is_admin: false,
            status: 'ativo'
          }
        ]);

        if (configError) {
          throw new Error(`Auth criado, mas erro no BD: ${configError.message}`);
        }

        alert('OPERADOR CRIADO COM SUCESSO!');
        setNewUser({ nome: '', email: '', senha: '', empresa: '', regime: 'Real' });
        fetchUsers();
      }
    } catch (err: any) {
      const msg = parseError(err);
      if (msg.includes("already registered")) {
        setErrorMessage("ESTE E-MAIL JÁ EXISTE: Vá em 'Authentication -> Users' no Supabase, exclua este e-mail e tente novamente.");
      } else {
        setErrorMessage(`FALHA NO CADASTRO: ${msg}`);
      }
    } finally {
      setIsRegistering(false);
    }
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-20 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 pb-8">
        <div>
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 text-white p-2 rounded-lg shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944"/></svg>
            </div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Master Control</h2>
          </div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Central de Gestão de Operadores</p>
        </div>
        <button onClick={fetchUsers} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">
          Sincronizar Lista
        </button>
      </header>

      {errorMessage && (
        <div className="bg-rose-50 border border-rose-200 p-8 rounded-[2rem] shadow-xl animate-slide-up">
          <div className="flex items-start gap-5">
            <div className="bg-rose-500 text-white p-3 rounded-2xl shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            </div>
            <div className="flex-1 space-y-4">
              <div>
                <p className="text-rose-600 font-black uppercase text-[11px] tracking-widest mb-1">Ação Requerida:</p>
                <p className="text-rose-900 text-sm font-bold leading-relaxed">{errorMessage}</p>
              </div>

              {errorMessage.includes("RLS") && (
                <div className="bg-white/50 p-4 rounded-xl border border-rose-100 space-y-2">
                  <p className="text-[10px] font-black text-slate-400 uppercase">Instrução SQL Corretiva:</p>
                  <code className="block text-[10px] font-mono bg-slate-900 text-emerald-400 p-3 rounded-lg overflow-x-auto whitespace-pre">
{`CREATE POLICY "Master Control" ON user_configs 
FOR ALL TO authenticated 
USING ( (auth.jwt() ->> 'email') = 'tagwaytw@gmail.com' );`}
                  </code>
                </div>
              )}

              <button onClick={() => setErrorMessage(null)} className="text-[9px] font-black uppercase text-rose-500 underline">Dispensar Aviso</button>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-1">
          <section className="bg-white rounded-[2.5rem] p-8 border border-slate-200 shadow-xl space-y-6 sticky top-8">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Liberar Novo Operador</h3>

            <form onSubmit={handleCreateUser} className="space-y-4">
              <AdminInput label="Nome Completo" value={newUser.nome} onChange={(v: string) => setNewUser({...newUser, nome: v})} />
              <AdminInput label="E-mail" type="email" value={newUser.email} onChange={(v: string) => setNewUser({...newUser, email: v})} />
              <AdminInput label="Senha" type="password" value={newUser.senha} onChange={(v: string) => setNewUser({...newUser, senha: v})} />
              <AdminInput label="Empresa" value={newUser.empresa} onChange={(v: string) => setNewUser({...newUser, empresa: v})} />

              <div className="space-y-1.5">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime Fiscal</label>
                <select 
                  value={newUser.regime}
                  onChange={(e) => setNewUser({...newUser, regime: e.target.value as any})}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-black outline-none focus:border-black"
                >
                  <option value="Real">Lucro Real</option>
                  <option value="Presumido">Lucro Presumido</option>
                  <option value="Simples">Simples Nacional</option>
                </select>
              </div>

              <button 
                type="submit" 
                disabled={isRegistering} 
                className="w-full bg-black text-white py-4 rounded-xl font-black uppercase tracking-widest text-[10px] shadow-xl hover:bg-slate-800 disabled:opacity-50 transition-all active:scale-95"
              >
                {isRegistering ? 'Processando...' : 'Cadastrar Operador'}
              </button>
            </form>
          </section>
        </div>

        <div className="xl:col-span-2 space-y-6">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Operadores Ativos ({users.length})</h3>
          <div className="space-y-3">
            {users.length === 0 ? (
              <div className="bg-white border border-dashed border-slate-200 p-16 rounded-[2rem] text-center space-y-4">
                <div className="text-5xl opacity-10">👥</div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Nenhum operador encontrado no banco de dados.</p>
                  <p className="text-[9px] text-slate-200 font-bold uppercase tracking-tighter italic">Certifique-se de que os perfis foram criados na tabela 'user_configs'</p>
                </div>
              </div>
            ) : (
              users.map(user => (
                <div key={user.user_id} className={`bg-white border rounded-[2rem] overflow-hidden transition-all duration-300 ${expandedUserId === user.user_id ? 'border-black shadow-2xl scale-[1.01]' : 'border-slate-100 shadow-sm'}`}>
                  <button 
                    onClick={() => setExpandedUserId(expandedUserId === user.user_id ? null : user.user_id)} 
                    className="w-full flex items-center justify-between p-7 text-left hover:bg-slate-50 transition-colors"
                  >
                    <div className="flex items-center gap-5">
                      <div className={`w-3 h-3 rounded-full ${user.status === 'ativo' ? 'bg-emerald-500' : 'bg-rose-500'} shadow-lg`}></div>
                      <div>
                        <h4 className="font-black text-slate-900 tracking-tight leading-none mb-1">{user.nome_completo || 'Sem Nome'}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{user.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                       <span className="text-[8px] font-black text-slate-300 uppercase bg-slate-50 px-2 py-1 rounded">{user.regime_tributario}</span>
                       <svg className={`w-5 h-5 text-slate-300 transition-transform ${expandedUserId === user.user_id ? 'rotate-180 text-black' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7"/></svg>
                    </div>
                  </button>

                  {expandedUserId === user.user_id && (
                    <div className="p-8 border-t border-slate-50 bg-slate-50/30 space-y-8 animate-slide-up">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <AdminInput label="Nome" value={user.nome_completo} onChange={(v: string) => updateUserInState(user.user_id, 'nome_completo', v)} />
                        <AdminInput label="Empresa" value={user.empresa_nome} onChange={(v: string) => updateUserInState(user.user_id, 'empresa_nome', v)} />

                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Status de Acesso</label>
                          <div className="flex gap-2">
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'ativo')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'ativo' ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Ativo</button>
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Bloqueado</button>
                          </div>
                        </div>
                      </div>

                      <div className="pt-6 border-t border-slate-100 flex justify-end">
                        <button 
                          onClick={() => handleUpdateUser(user)} 
                          disabled={isUpdating === user.user_id} 
                          className="bg-black text-white px-12 py-4 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-2xl disabled:opacity-50 transition-all hover:bg-slate-800 active:scale-95"
                        >
                          {isUpdating === user.user_id ? 'Salvando...' : 'Aplicar Alterações'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

