export default AdminView;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  /**
   * Garante que o erro seja convertido em uma string legível, 
   * evitando a exibição de "[object Object]".
   */
  const formatError = (err: any): string => {
    if (typeof err === 'string') return err;
    if (err?.message) return err.message;
    if (err?.details) return `${err.message}: ${err.details}`;
    if (err?.hint) return `${err.message} (Dica: ${err.hint})`;
    try {
      return JSON.stringify(err);
    } catch {
      return 'Erro desconhecido ao processar resposta do servidor.';
    }
  };

  const fetchUsers = async () => {
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) {
        // Trata erro retornado pelo Supabase (PostgrestError)
        const msg = formatError(error);
        console.error("Detalhes do erro Supabase:", error);

        if (msg.toLowerCase().includes('infinite recursion') || msg.toLowerCase().includes('policy')) {
          setErrorMessage("BLOQUEIO DE SEGURANÇA (RLS): O banco de dados recusou o acesso. Você deve rodar o Script SQL 'Master Control' no Dashboard do Supabase.");
        } else {
          setErrorMessage(`Erro de Sincronização: ${msg}`);
        }
        return;
      }

      if (data) {
        setUsers(data as UserProfile[]);
        // Se a lista estiver vazia mas não houver erro, pode ser RLS filtrando tudo
        if (data.length === 0) {
          console.warn("A consulta retornou 0 resultados. Verifique se as políticas RLS permitem que este usuário veja os registros.");
        }
      }
    } catch (err: any) {
      console.error("Falha catastrófica ao buscar usuários:", err);
      setErrorMessage(`Falha de conexão: ${formatError(err)}`);
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          regime_tributario: user.regime_tributario,
          status: user.status
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert('Alterações salvas com sucesso!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro ao salvar: ${formatError(err)}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.senha || !newUser.nome) {
      alert('Preencha os campos obrigatórios (Nome, E-mail e Senha).');
      return;
    }

    setIsRegistering(true);
    setErrorMessage(null);

    try {
      // 1. Criar no Authentication do Supabase
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: newUser.email.trim(),
        password: newUser.senha,
        options: {
          data: {
            full_name: newUser.nome,
            company: newUser.empresa
          }
        }
      });

      if (authError) throw authError;

      if (authData.user) {
        // 2. Inserir perfil na tabela user_configs
        const { error: configError } = await supabase.from('user_configs').insert([
          {
            user_id: authData.user.id,
            nome_completo: newUser.nome,
            email: newUser.email.trim(),
            empresa_nome: newUser.empresa,
            regime_tributario: newUser.regime,
            is_admin: false,
            status: 'ativo'
          }
        ]);

        if (configError) {
          throw new Error(`A conta foi criada, mas o perfil no banco falhou: ${formatError(configError)}`);
        }

        alert('OPERADOR CADASTRADO E LIBERADO!');
        setNewUser({ nome: '', email: '', senha: '', empresa: '', regime: 'Real' });
        fetchUsers();
      }
    } catch (err: any) {
      const msg = formatError(err);
      if (msg.includes("already registered")) {
        setErrorMessage("ESTE E-MAIL JÁ ESTÁ EM USO: Remova o usuário no painel 'Authentication' do Supabase para cadastrar novamente.");
      } else {
        setErrorMessage(`FALHA NO CADASTRO: ${msg}`);
      }
    } finally {
      setIsRegistering(false);
    }
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-20 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 pb-8">
        <div>
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 text-white p-2 rounded-lg shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944"/></svg>
            </div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Master Control</h2>
          </div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Gestão de Identidade e Acessos</p>
        </div>
        <button onClick={fetchUsers} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">
          Sincronizar Banco de Dados
        </button>
      </header>

      {errorMessage && (
        <div className="bg-rose-50 border border-rose-200 p-8 rounded-[2rem] shadow-xl animate-slide-up">
          <div className="flex items-start gap-5">
            <div className="bg-rose-500 text-white p-3 rounded-2xl shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            </div>
            <div className="flex-1 space-y-4">
              <div>
                <p className="text-rose-600 font-black uppercase text-[11px] tracking-widest mb-1">Aviso Crítico:</p>
                <p className="text-rose-900 text-sm font-bold leading-relaxed">{errorMessage}</p>
              </div>

              {errorMessage.includes("RLS") && (
                <div className="bg-white/50 p-5 rounded-2xl border border-rose-100 space-y-3">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Procedimento de Correção:</p>
                  <ol className="text-[10px] font-bold text-slate-600 space-y-1 list-decimal ml-4">
                    <li>Acesse o dashboard do Supabase.</li>
                    <li>Vá em 'SQL Editor' e crie uma 'New Query'.</li>
                    <li>Cole o script de permissão Master enviado anteriormente.</li>
                    <li>Clique em 'Run'.</li>
                  </ol>
                </div>
              )}

              <button onClick={() => setErrorMessage(null)} className="text-[9px] font-black uppercase text-rose-500 underline">Fechar Notificação</button>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-1">
          <section className="bg-white rounded-[2.5rem] p-8 border border-slate-200 shadow-xl space-y-6 sticky top-8">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">Liberar Novo Operador</h3>

            <form onSubmit={handleCreateUser} className="space-y-4">
              <AdminInput label="Nome Completo" value={newUser.nome} onChange={(v: string) => setNewUser({...newUser, nome: v})} />
              <AdminInput label="E-mail Corporativo" type="email" value={newUser.email} onChange={(v: string) => setNewUser({...newUser, email: v})} />
              <AdminInput label="Senha de Acesso" type="password" value={newUser.senha} onChange={(v: string) => setNewUser({...newUser, senha: v})} />
              <AdminInput label="Empresa Filiada" value={newUser.empresa} onChange={(v: string) => setNewUser({...newUser, empresa: v})} />

              <div className="space-y-1.5">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime Fiscal Padrão</label>
                <select 
                  value={newUser.regime}
                  onChange={(e) => setNewUser({...newUser, regime: e.target.value as any})}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-black outline-none focus:border-black"
                >
                  <option value="Real">Lucro Real</option>
                  <option value="Presumido">Lucro Presumido</option>
                  <option value="Simples">Simples Nacional</option>
                </select>
              </div>

              <button 
                type="submit" 
                disabled={isRegistering} 
                className="w-full bg-black text-white py-4 rounded-xl font-black uppercase tracking-widest text-[10px] shadow-xl hover:bg-slate-800 disabled:opacity-50 transition-all active:scale-95"
              >
                {isRegistering ? 'Sincronizando...' : 'Liberar Operador'}
              </button>
            </form>
          </section>
        </div>

        <div className="xl:col-span-2 space-y-6">
          <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] px-4">Operadores Sincronizados ({users.length})</h3>
          <div className="space-y-3">
            {users.length === 0 ? (
              <div className="bg-white border border-dashed border-slate-200 p-20 rounded-[3rem] text-center space-y-4">
                <div className="text-6xl opacity-10">👥</div>
                <div className="space-y-2">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest leading-relaxed">Nenhum operador visível no momento.</p>
                  <p className="text-[9px] text-slate-300 font-bold uppercase tracking-tighter">Isto geralmente indica que as políticas de segurança (RLS) estão ativas e impedindo a listagem global.</p>
                </div>
              </div>
            ) : (
              users.map(user => (
                <div key={user.user_id} className={`bg-white border rounded-[2.5rem] overflow-hidden transition-all duration-300 ${expandedUserId === user.user_id ? 'border-black shadow-2xl scale-[1.01]' : 'border-slate-100 shadow-sm'}`}>
                  <button 
                    onClick={() => setExpandedUserId(expandedUserId === user.user_id ? null : user.user_id)} 
                    className="w-full flex items-center justify-between p-7 text-left hover:bg-slate-50 transition-colors"
                  >
                    <div className="flex items-center gap-5">
                      <div className={`w-3 h-3 rounded-full ${user.status === 'ativo' ? 'bg-emerald-500' : 'bg-rose-500'} shadow-lg`}></div>
                      <div>
                        <h4 className="font-black text-slate-900 tracking-tight leading-none mb-1">{user.nome_completo || 'Operador sem Nome'}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{user.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                       <span className="text-[8px] font-black text-slate-300 uppercase bg-slate-50 px-2 py-1 rounded">{user.regime_tributario}</span>
                       <svg className={`w-5 h-5 text-slate-300 transition-transform ${expandedUserId === user.user_id ? 'rotate-180 text-black' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7"/></svg>
                    </div>
                  </button>

                  {expandedUserId === user.user_id && (
                    <div className="p-8 border-t border-slate-50 bg-slate-50/30 space-y-8 animate-slide-up">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <AdminInput label="Identificação Completa" value={user.nome_completo} onChange={(v: string) => updateUserInState(user.user_id, 'nome_completo', v)} />
                        <AdminInput label="Empresa de Atuação" value={user.empresa_nome} onChange={(v: string) => updateUserInState(user.user_id, 'empresa_nome', v)} />

                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime de Operação</label>
                          <select 
                            value={user.regime_tributario}
                            onChange={(e) => updateUserInState(user.user_id, 'regime_tributario', e.target.value)}
                            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-black outline-none focus:border-black"
                          >
                            <option value="Real">Lucro Real</option>
                            <option value="Presumido">Lucro Presumido</option>
                            <option value="Simples">Simples Nacional</option>
                          </select>
                        </div>

                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Situação da Conta</label>
                          <div className="flex gap-2">
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'ativo')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'ativo' ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Ativa</button>
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Bloqueada</button>
                          </div>
                        </div>
                      </div>

                      <div className="pt-6 border-t border-slate-100 flex justify-end">
                        <button 
                          onClick={() => handleUpdateUser(user)} 
                          disabled={isUpdating === user.user_id} 
                          className="bg-black text-white px-12 py-4 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-2xl disabled:opacity-50 transition-all hover:bg-slate-800 active:scale-95"
                        >
                          {isUpdating === user.user_id ? 'Processando...' : 'Confirmar Alterações'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

