  const formatError = (err: any): string => {
    if (!err) return 'Erro desconhecido.';
    if (typeof err === 'string') return err;
    if (err.message && (err.details || err.hint || err.code)) {
      let parts = [err.message];
      if (err.details) parts.push(`Detalhes: ${err.details}`);
      if (err.hint) parts.push(`Dica: ${err.hint}`);
      if (err.code) parts.push(`Código: ${err.code}`);
      return parts.join(' | ');
    }
    if (err instanceof Error) return err.message;
    try {
      const stringified = JSON.stringify(err);
      return stringified === '{}' ? (err.message || String(err)) : stringified;
    } catch {
      return String(err);
    }
  };

  const fetchUsers = async () => {
    setErrorMessage(null);
    setIsRecursionError(false);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) {
        const msg = formatError(error);
        console.error("Erro detalhado Supabase:", msg);

        // Verifica especificamente pelo erro de recursão (42P17)
        if (msg.includes('infinite recursion') || error.code === '42P17') {
          setIsRecursionError(true);
          setErrorMessage("ERRO DE RECURSÃO INFINITA (42P17): As políticas RLS do seu banco de dados estão mal configuradas e entrando em loop. O banco travou o acesso para se proteger.");
        } else if (msg.toLowerCase().includes('policy')) {
          setErrorMessage("BLOQUEIO DE SEGURANÇA (RLS): O banco recusou o acesso. Verifique se você rodou o Script SQL de 'Master Control'.");
        } else {
          setErrorMessage(`Erro de Sincronização: ${msg}`);
        }
        return;
      }

      if (data) {
        setUsers(data as UserProfile[]);
      }
    } catch (err: any) {
      console.error("Falha de conexão:", err);
      setErrorMessage(`Falha de conexão: ${formatError(err)}`);
    }
