              </div>
            ) : (
              users.map(user => (
                <div key={user.user_id} className={`bg-white border rounded-[2.5rem] overflow-hidden transition-all duration-300 ${expandedUserId === user.user_id ? 'border-black shadow-2xl scale-[1.01]' : 'border-slate-100 shadow-sm'}`}>
                  <button 
                    onClick={() => setExpandedUserId(expandedUserId === user.user_id ? null : user.user_id)} 
                    className="w-full flex items-center justify-between p-7 text-left hover:bg-slate-50 transition-colors"
                  >
                    <div className="flex items-center gap-5">
                      <div className={`w-3 h-3 rounded-full ${user.status === 'ativo' ? 'bg-emerald-500' : 'bg-rose-500'} shadow-lg`}></div>
                      <div>
                        <h4 className="font-black text-slate-900 tracking-tight leading-none mb-1">{user.nome_completo || 'Sem Nome'}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{user.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                       <span className="text-[8px] font-black text-slate-300 uppercase bg-slate-50 px-2 py-1 rounded">{user.regime_tributario}</span>
                       <svg className={`w-5 h-5 text-slate-300 transition-transform ${expandedUserId === user.user_id ? 'rotate-180 text-black' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7"/></svg>
                    </div>
                  </button>

                  {expandedUserId === user.user_id && (
                    <div className="p-8 border-t border-slate-50 bg-slate-50/30 space-y-8 animate-slide-up">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <AdminInput label="Nome" value={user.nome_completo} onChange={(v: string) => updateUserInState(user.user_id, 'nome_completo', v)} />
                        <AdminInput label="Empresa" value={user.empresa_nome} onChange={(v: string) => updateUserInState(user.user_id, 'empresa_nome', v)} />
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime</label>
                          <select 
                            value={user.regime_tributario}
                            onChange={(e) => updateUserInState(user.user_id, 'regime_tributario', e.target.value)}
                            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-black outline-none focus:border-black"
                          >
                            <option value="Real">Lucro Real</option>
                            <option value="Presumido">Lucro Presumido</option>
                            <option value="Simples">Simples Nacional</option>
                          </select>
                        </div>
                        <div className="space-y-1.5">
                          <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Status</label>
                          <div className="flex gap-2">
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'ativo')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'ativo' ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Ativo</button>
                             <button onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200'}`}>Bloqueado</button>
                          </div>
                        </div>
                      </div>
                      <div className="pt-6 border-t border-slate-100 flex justify-end">
                        <button 
                          onClick={() => handleUpdateUser(user)} 
                          disabled={isUpdating === user.user_id} 
                          className="bg-black text-white px-12 py-4 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-2xl disabled:opacity-50 transition-all hover:bg-slate-800 active:scale-95"
                        >
                          {isUpdating === user.user_id ? 'Salvando...' : 'Aplicar Alterações'}
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

