  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);
  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>([]);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>([]);
  const [isAutoSync, setIsAutoSync] = useState(false);
  const [isSavingSim, setIsSavingSim] = useState(false);
  const [isDbLocked, setIsDbLocked] = useState(false);

  const isMaster = useMemo(() => {
    return session?.user?.email?.toLowerCase() === MASTER_EMAIL.toLowerCase();
  }, [session]);

  useEffect(() => {
    const init = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      setSession(currentSession);

      if (currentSession) {
        try {
          // Tentativa resiliente de carregar o perfil
          const { data, error } = await supabase.from('user_configs').select('*').eq('user_id', currentSession.user.id).maybeSingle();

          if (error) {
             console.error("Erro detectado na carga do perfil:", error.message);
             if (error.code === '42P17' || error.message.includes('recursion')) {
                setIsDbLocked(true);
             }
          }
          if (data) setUserProfile(data);

          const { data: oh, error: ohError } = await supabase.from('overhead_configs').select('*').eq('user_id', currentSession.user.id).maybeSingle();
          if (oh) {
            setFaturamento(oh.faturamento || 100000);
            setFixedCosts(oh.fixed_costs || []);
            setVariableCosts(oh.variable_costs || []);
            setIsAutoSync(!!oh.is_auto_sync);
          }
        } catch (e) {
          console.warn("Falha de infraestrutura: Banco de dados inacessível.");
        }
      }
      setIsInitialized(true);
    };
    init();
  }, []);

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  useEffect(() => {
    if (isAutoSync && faturamento > 0) {
      const totalF = fixedCosts.reduce((a, b) => a + b.valor, 0);
      const totalV = variableCosts.reduce((a, b) => a + b.percentual, 0);
      const percFixed = (totalF / faturamento) * 100;
      setInputs(prev => ({
        ...prev,
        custosFixos: Number(percFixed.toFixed(2)),
        outrosCustosVariaveis: Number(totalV.toFixed(2))
      }));
    }
  }, [fixedCosts, variableCosts, faturamento, isAutoSync]);

  const handleReset = () => {
    setInputs(prev => ({
      ...prev,
      nomeProduto: '',
      valorCompra: 0,
      ipiPerc: 0,
      freteValor: 0,
      ncmCodigo: '',
      mva: 0,
      mvaOriginal: 0,
    }));
  };

  const handleSaveSimulation = async () => {
    if (!session) {
      alert('Sessão expirada. Faça login novamente.');
      return;
    }

    setIsSavingSim(true);
    try {
      const { error } = await supabase.from('saved_simulations').insert([{
        user_id: session.user.id,
        nome_produto: inputs.nomeProduto || 'Sem Nome',
        inputs: JSON.parse(JSON.stringify(inputs)),
        results: JSON.parse(JSON.stringify(results))
      }]);

      if (error) throw new Error(error.message);
      alert('Simulação arquivada com sucesso!');
    } catch (e: any) {
      console.error('Erro ao salvar simulação:', e);
      alert('Erro ao salvar: ' + (e.message || 'Falha técnica.'));
    } finally {
      setIsSavingSim(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    window.location.reload();
  };

  if (!isInitialized) return null;
  if (!session) return <Login onLoginSuccess={setSession} />;

  return (
    <div className="flex h-screen w-full bg-[#000000] overflow-hidden text-slate-900">
      {/* Alerta Global Master se o Banco estiver Travado */}
      {isDbLocked && isMaster && activeTab !== 'master' && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[999] w-[90%] max-w-lg bg-amber-500 text-white p-5 rounded-3xl shadow-2xl flex items-center justify-between border border-white/20 animate-slide-up">
           <div className="flex items-center gap-4">
             <div className="bg-white/20 p-2 rounded-xl">
                <svg className="w-5 h-5 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
             </div>
             <p className="text-[10px] font-black uppercase tracking-widest leading-none">Atenção Master: Erro 42P17 detectado no banco.</p>
           </div>
           <button onClick={() => setActiveTab('master')} className="bg-white text-amber-600 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest">Reparar Agora</button>
        </div>
      )}

      {/* Desktop Sidebar */}
      <aside className={`hidden lg:flex flex-col border-r border-white/5 p-6 transition-all duration-300 ease-in-out relative ${isSidebarCollapsed ? 'w-[100px]' : 'w-[280px]'} h-full overflow-y-auto custom-scrollbar`}>
        <div className="mb-10 flex items-center justify-between">
          {!isSidebarCollapsed ? <TagwayHorizontalLogo className="h-7 w-auto" /> : <CompactLogo />}
          <button 
            onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
            className="p-2 text-white/20 hover:text-white transition-colors"
          >
            <svg className={`w-4 h-4 transition-transform ${isSidebarCollapsed ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 19l-7-7 7-7m8 14l-7-7 7-7" />
            </svg>
          </button>
        </div>

        <nav className="flex-1 space-y-1">
          <DesktopMenuButton active={activeTab === 'calculadora'} onClick={() => setActiveTab('calculadora')} label="Calculadora" icon="M3 12h18M3 6h18M3 18h18" collapsed={isSidebarCollapsed} />
          <DesktopMenuButton active={activeTab === 'meus-produtos'} onClick={() => setActiveTab('meus-produtos')} label="Meus Itens" icon="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" collapsed={isSidebarCollapsed} />
          <DesktopMenuButton active={activeTab === 'resumo-fiscal'} onClick={() => setActiveTab('resumo-fiscal')} label="Análise Fisco" icon="M9 17v-2m3 2v-4m3 2v-6m-8-2h8a2 2 0 012 2v9a2 2 0 01-2 2H7a2 2 0 01-2-2V5a2 2 0 012-2z" collapsed={isSidebarCollapsed} />
          <DesktopMenuButton active={activeTab === 'catalogo'} onClick={() => setActiveTab('catalogo')} label="NCM 2025" icon="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" collapsed={isSidebarCollapsed} />
          <DesktopMenuButton active={activeTab === 'overhead'} onClick={() => setActiveTab('overhead')} label="Overhead" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" collapsed={isSidebarCollapsed} />
          <DesktopMenuButton active={activeTab === 'jarvis'} onClick={() => setActiveTab('jarvis')} label="Jarvis AI" icon="M13 10V3L4 14h7v7l9-11h-7z" isAi collapsed={isSidebarCollapsed} />

          <div className="pt-6">
            <DesktopMenuButton active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Configuração" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" collapsed={isSidebarCollapsed} />
            {isMaster && <DesktopMenuButton active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944" collapsed={isSidebarCollapsed} />}
          </div>
        </nav>
        <button onClick={handleLogout} className="mt-auto p-4 text-rose-500 font-black uppercase text-[10px] tracking-widest hover:bg-rose-500/10 rounded-xl transition-all border border-rose-500/20">
          {isSidebarCollapsed ? 'X' : 'Sair'}
        </button>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 bg-[#f8fafc] lg:rounded-l-[3rem] shadow-2xl overflow-hidden flex flex-col">
        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 lg:p-12 pb-32 lg:pb-12">
          {activeTab === 'calculadora' && (
            <div className="flex flex-col lg:flex-row gap-8 lg:gap-12 max-w-[1600px] mx-auto animate-slide-up">
              <div className="w-full lg:w-80 space-y-6 shrink-0">
                <FiscalHeader inputs={inputs} setInputs={setInputs} />
                <Sidebar inputs={inputs} setInputs={setInputs} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
                <button 
                  onClick={handleSaveSimulation} 
                  disabled={isSavingSim}
                  className="w-full bg-emerald-600 text-white py-4 rounded-xl font-black uppercase text-[11px] tracking-widest shadow-xl hover:bg-emerald-700 transition-all flex items-center justify-center gap-2"
                >
                  {isSavingSim ? 'Gravando...' : 'Arquivar Item'}
                </button>
              </div>
              <div className="flex-1">
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} onReset={handleReset} />
              </div>
            </div>
          )}

          {activeTab === 'meus-produtos' && <MyProductsView onSelect={(sim) => { setInputs(sim.inputs); setActiveTab('calculadora'); }} />}
          {activeTab === 'resumo-fiscal' && <ResumoFiscalView results={results} inputs={inputs} />}
          {activeTab === 'catalogo' && <ProductsView onSelectNcm={(n) => { setInputs(p => ({...p, ...n, nomeProduto: n.descricao})); setActiveTab('calculadora'); }} />}
          {activeTab === 'overhead' && <OverheadView faturamento={faturamento} setFaturamento={setFaturamento} fixedCosts={fixedCosts} setFixedCosts={setFixedCosts} variableCosts={variableCosts} setVariableCosts={setVariableCosts} userId={session?.user?.id} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />}
          {activeTab === 'jarvis' && <AIView results={results} inputs={inputs} />}
          {activeTab === 'configuracao' && <ConfiguracaoView userId={session?.user?.id} />}
          {activeTab === 'master' && <AdminView />}
        </div>
      </main>

      {/* Mobile Bottom Dock */}
      <nav className="lg:hidden mobile-dock fixed bottom-4 left-4 right-4 h-[72px] rounded-[2rem] flex items-center gap-1 overflow-x-auto no-scrollbar px-4 z-[100] shadow-2xl bg-white border border-slate-100 flex-nowrap">
        <MobileDockItem active={activeTab === 'calculadora'} onClick={() => setActiveTab('calculadora')} label="Calc" icon="M3 12h18M3 6h18M3 18h18" />
        <MobileDockItem active={activeTab === 'meus-produtos'} onClick={() => setActiveTab('meus-produtos')} label="Meus" icon="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
        <MobileDockItem active={activeTab === 'resumo-fiscal'} onClick={() => setActiveTab('resumo-fiscal')} label="Fisco" icon="M9 17v-2m3 2v-4m3 2v-6m-8-2h8a2 2 0 012 2v9a2 2 0 01-2 2H7a2 2 0 01-2-2V5a2 2 0 012-2z" />
        <MobileDockItem active={activeTab === 'overhead'} onClick={() => setActiveTab('overhead')} label="Custos" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" />
        <MobileDockItem active={activeTab === 'jarvis'} onClick={() => setActiveTab('jarvis')} label="Jarvis" icon="M13 10V3L4 14h7v7l9-11h-7z" isAi />
        <MobileDockItem active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Perfil" icon="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
        {isMaster && (
          <MobileDockItem active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944" />
        )}
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isRecursionError, setIsRecursionError] = useState(false);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const formatError = (err: any): string => {
    if (!err) return 'Erro desconhecido.';
    if (typeof err === 'string') return err;
    if (err.message && (err.details || err.hint || err.code)) {
      let parts = [err.message];
      if (err.details) parts.push(`Detalhes: ${err.details}`);
      if (err.hint) parts.push(`Dica: ${err.hint}`);
      if (err.code) parts.push(`Código: ${err.code}`);
      return parts.join(' | ');
    }
    return err.message || String(err);
  };

  const fetchUsers = async () => {
    setErrorMessage(null);
    setIsRecursionError(false);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) {
        const msg = formatError(error);
        console.error("Erro detectado no banco:", msg);

        // Detecção específica de Recursão Infinita (Código 42P17)
        if (msg.toLowerCase().includes('infinite recursion') || error.code === '42P17') {
          setIsRecursionError(true);
          setErrorMessage("ALERTA DE SEGURANÇA (42P17): Suas políticas RLS estão em loop infinito. O banco bloqueou o acesso para evitar queda do servidor.");
        } else if (msg.toLowerCase().includes('policy') || error.code === '42501') {
          setErrorMessage("ACESSO NEGADO (RLS): Permissão insuficiente no banco de dados.");
        } else {
          setErrorMessage(`Falha na sincronização: ${msg}`);
        }
        return;
      }

      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(`Erro fatal de conexão: ${formatError(err)}`);
    }
  };

  const copyRepairScript = () => {
    const repairSql = `-- SCRIPT DE REPARO DEFINITIVO - TAGWAY TECHNOLOGY
-- Este script desativa as políticas recursivas e instala o controle via JWT (Token)

-- 1. Remover políticas problemáticas que causam recursão
DROP POLICY IF EXISTS "Master Control" ON user_configs;
DROP POLICY IF EXISTS "master_access" ON user_configs;
DROP POLICY IF EXISTS "master_access_v2" ON user_configs;
DROP POLICY IF EXISTS "master_bypass_recursion" ON user_configs;
DROP POLICY IF EXISTS "master_bypass_recursion_v3" ON user_configs;
DROP POLICY IF EXISTS "user_configs_self_view" ON user_configs;
DROP POLICY IF EXISTS "user_configs_master_all" ON user_configs;

-- 2. Criar Política MASTER BLINDADA (Usa o e-mail do token de login, não consulta a tabela)
CREATE POLICY "master_bypass_recursion_final" ON user_configs 
FOR ALL TO authenticated 
USING ( (auth.jwt() ->> 'email') = 'tagwaytw@gmail.com' );

-- 3. Criar Política de Usuário Comum (Visualizar apenas o próprio ID)
CREATE POLICY "user_self_access_final" ON user_configs 
FOR SELECT TO authenticated 
USING ( auth.uid() = user_id );

-- 4. Garantir RLS ativa
ALTER TABLE user_configs ENABLE ROW LEVEL SECURITY;`;

    navigator.clipboard.writeText(repairSql);
    alert("Script de reparo copiado! Vá ao SQL Editor do Supabase, cole e execute.");
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          regime_tributario: user.regime_tributario,
          status: user.status
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert('Alterações salvas!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro ao salvar: ${formatError(err)}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.senha || !newUser.nome) {
      alert('Preencha os campos obrigatórios.');
      return;
    }

    setIsRegistering(true);
    try {
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: newUser.email.trim(),
        password: newUser.senha,
        options: { data: { full_name: newUser.nome, company: newUser.empresa } }
      });

      if (authError) throw authError;

      if (authData.user) {
        const { error: configError } = await supabase.from('user_configs').insert([{
          user_id: authData.user.id,
          nome_completo: newUser.nome,
          email: newUser.email.trim(),
          empresa_nome: newUser.empresa,
          regime_tributario: newUser.regime,
          is_admin: false,
          status: 'ativo'
        }]);

        if (configError) throw configError;
        alert('OPERADOR CADASTRADO!');
        setNewUser({ nome: '', email: '', senha: '', empresa: '', regime: 'Real' });
        fetchUsers();
      }
    } catch (err: any) {
      alert(`FALHA NO CADASTRO: ${formatError(err)}`);
    } finally {
      setIsRegistering(false);
    }
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-20 animate-slide-up">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 border-b border-slate-200 pb-8">
        <div>
          <div className="flex items-center gap-3">
            <div className="bg-purple-600 text-white p-2 rounded-lg shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944"/></svg>
            </div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Master Control</h2>
          </div>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Gestão de Identidade e Acessos</p>
        </div>
        <button onClick={fetchUsers} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">
          Sincronizar Banco
        </button>
      </header>

      {errorMessage && (
        <div className={`border p-8 rounded-[2rem] shadow-2xl animate-slide-up ${isRecursionError ? 'bg-amber-50 border-amber-300' : 'bg-rose-50 border-rose-200'}`}>
          <div className="flex items-start gap-5">
            <div className={`text-white p-3 rounded-2xl shadow-lg ${isRecursionError ? 'bg-amber-500' : 'bg-rose-500'}`}>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            </div>
            <div className="flex-1 space-y-4">
              <div>
                <p className={`font-black uppercase text-[11px] tracking-widest mb-1 ${isRecursionError ? 'text-amber-600' : 'text-rose-600'}`}>
                  {isRecursionError ? 'DIAGNÓSTICO: Recursão Infinita em RLS' : 'Aviso do Sistema:'}
                </p>
                <p className={`text-sm font-bold leading-relaxed ${isRecursionError ? 'text-amber-900' : 'text-rose-900'}`}>{errorMessage}</p>
              </div>

              {isRecursionError && (
                <div className="bg-white/80 p-6 rounded-2xl border border-amber-200 space-y-4 shadow-inner">
                  <div className="flex items-center justify-between border-b border-amber-100 pb-3">
                    <p className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Procedimento de Resgate (SQL Editor):</p>
                    <button 
                      onClick={copyRepairScript}
                      className="bg-amber-600 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-amber-700 transition-all flex items-center gap-2 shadow-lg"
                    >
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"/></svg>
                      Copiar Script de Reparo
                    </button>
                  </div>
                  <div className="bg-slate-900 p-4 rounded-xl">
                    <pre className="text-[9px] font-mono text-emerald-400 overflow-x-auto whitespace-pre-wrap leading-relaxed opacity-90">
