import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  regime_tributario: string;
  status: 'ativo' | 'atualizando' | 'bloqueado';
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [expandedUserId, setExpandedUserId] = useState<string | null>(null);
  const [isRegistering, setIsRegistering] = useState(false);
  const [isUpdating, setIsUpdating] = useState<string | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isRecursionError, setIsRecursionError] = useState(false);
  const [newUser, setNewUser] = useState({
    nome: '',
    email: '',
    senha: '',
    empresa: '',
    regime: 'Real' as 'Simples' | 'Presumido' | 'Real'
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setErrorMessage(null);
    setIsRecursionError(false);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) {
        if (error.code === '42P17' || error.message.includes('recursion')) {
          setIsRecursionError(true);
          setErrorMessage("ERRO CRÍTICO 42P17: Recursão Infinita Detectada. Suas regras de segurança (RLS) entraram em loop.");
        } else {
          setErrorMessage(`Erro: ${error.message}`);
        }
        return;
      }
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(`Falha na conexão.`);
    }
  };

  const copyRepairScript = () => {
    const repairSql = `-- SCRIPT DE REPARO TAGWAY (ANTI-RECURSÃO)
-- 1. Desativa RLS temporariamente para limpar o lixo
ALTER TABLE user_configs DISABLE ROW LEVEL SECURITY;

-- 2. Deleta TODAS as políticas que estão causando o loop
DROP POLICY IF EXISTS "Master Control" ON user_configs;
DROP POLICY IF EXISTS "master_access" ON user_configs;
DROP POLICY IF EXISTS "master_access_v2" ON user_configs;
DROP POLICY IF EXISTS "master_bypass_recursion" ON user_configs;
DROP POLICY IF EXISTS "user_configs_self_view" ON user_configs;
DROP POLICY IF EXISTS "user_configs_master_all" ON user_configs;

-- 3. Cria a política MASTER "BLINDADA" (Usa o e-mail do Token JWT, sem consultar a tabela)
CREATE POLICY "master_bypass_recursion_final" ON user_configs 
FOR ALL TO authenticated 
USING ( (auth.jwt() ->> 'email') = 'tagwaytw@gmail.com' );

-- 4. Cria a política de USUÁRIO (Apenas ver seu próprio registro)
CREATE POLICY "user_self_view" ON user_configs 
FOR SELECT TO authenticated 
USING ( auth.uid() = user_id );

-- 5. Reativa a segurança com as regras limpas
ALTER TABLE user_configs ENABLE ROW LEVEL SECURITY;`;

    navigator.clipboard.writeText(repairSql);
    alert("Script de reparo copiado! Vá ao SQL Editor do Supabase, cole e execute o comando.");
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase.from('user_configs').update({
        nome_completo: user.nome_completo,
        empresa_nome: user.empresa_nome,
        status: user.status
      }).eq('user_id', user.user_id);
      if (error) throw error;
      alert('Salvo!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro: ${err.message}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-20 animate-slide-up">
      <header className="flex items-center justify-between border-b border-slate-200 pb-8">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Master Control</h2>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Reparo e Gestão de Acessos</p>
        </div>
        <button onClick={fetchUsers} className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">
          Sincronizar Banco
        </button>
      </header>

      {errorMessage && (
        <div className={`border p-8 rounded-[2.5rem] shadow-2xl animate-slide-up ${isRecursionError ? 'bg-amber-50 border-amber-300' : 'bg-rose-50 border-rose-200'}`}>
          <div className="flex items-start gap-6">
            <div className={`text-white p-4 rounded-2xl shadow-lg ${isRecursionError ? 'bg-amber-500 animate-pulse' : 'bg-rose-500'}`}>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
            </div>
            <div className="flex-1 space-y-4">
              <h4 className="text-lg font-black text-slate-900 uppercase">Falha Crítica Detectada</h4>
              <p className="text-sm font-bold text-slate-600 leading-relaxed">{errorMessage}</p>

              {isRecursionError && (
                <div className="bg-white/80 p-6 rounded-2xl border border-amber-200 space-y-4">
                  <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest">Procedimento de Resgate:</p>
                  <button onClick={copyRepairScript} className="bg-amber-600 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-amber-700 transition-all flex items-center gap-2 shadow-lg">
                    Copiar Script de Reparo SQL
                  </button>
                  <p className="text-[9px] text-slate-500 italic">Após copiar, cole no SQL Editor do Supabase e execute.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {users.map(user => (
          <div key={user.user_id} className="bg-white border border-slate-200 rounded-[2.5rem] p-8 hover:border-black transition-all shadow-sm">
            <div className="flex justify-between items-start mb-6">
               <div>
                 <h3 className="text-xl font-black text-slate-900 tracking-tight">{user.nome_completo || 'Sem Nome'}</h3>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{user.email}</p>
               </div>
               <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase ${user.status === 'ativo' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                 {user.status}
               </div>
            </div>

            <div className="grid grid-cols-1 gap-4 mb-6">
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Empresa</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold outline-none focus:border-black" value={user.empresa_nome || ''} onChange={(e) => updateUserInState(user.user_id, 'empresa_nome', e.target.value)} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => updateUserInState(user.user_id, 'status', 'ativo')} className={`py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'ativo' ? 'bg-black text-white border-black' : 'bg-white text-slate-400 border-slate-200'}`}>Ativar</button>
                <button onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')} className={`py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600' : 'bg-white text-slate-400 border-slate-200'}`}>Bloquear</button>
              </div>
            </div>

            <button onClick={() => handleUpdateUser(user)} disabled={isUpdating === user.user_id} className="w-full bg-slate-900 text-white py-4 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-black transition-all shadow-xl disabled:opacity-50">
              {isUpdating === user.user_id ? 'Salvando...' : 'Atualizar Operador'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

