        } else {
          setErrorMessage(`Erro ao carregar usuários: ${error.message}`);
        }
        return;
      }
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(`Falha na conexão.`);
    }
  };

  const copyRepairScript = () => {
    const repairSql = `-- SCRIPT DE REPARO TAGWAY (CORREÇÃO DE RECURSÃO)
