  const [isRecursionError, setIsRecursionError] = useState(false);

  useEffect(() => {
    fetchUsers();
  }, []);

  const formatErrorMessage = (error: any): string => {
    if (!error) return 'Erro desconhecido';

    // Se for um erro do Supabase/Postgrest
    if (typeof error === 'object') {
      const message = error.message || error.details || error.hint || (error.toString && error.toString() !== '[object Object]' ? error.toString() : null);
      if (message) return message;

      // Fallback para JSON mas tratando objetos Error que não serializam bem
      try {
        const json = JSON.stringify(error);
        return json === '{}' ? 'Erro de permissão ou conexão (Objeto vazio)' : json;
      } catch (e) {
        return 'Erro de estrutura de dados irreconhecível';
      }
    }
    return String(error);
  };

  const fetchUsers = async () => {
    setErrorMessage(null);
    setIsRecursionError(false);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*');

      if (error) {
        const errorDetails = formatErrorMessage(error);
        const errorCode = error.code || 'UNK';

        console.error("Erro detalhado do banco:", error);

        if (errorCode === '42P17' || errorDetails.toLowerCase().includes('recursion') || errorDetails.toLowerCase().includes('infinite')) {
          setIsRecursionError(true);
          setErrorMessage(`ERRO CRÍTICO 42P17: Recursão detectada. Suas políticas RLS criaram um loop infinito. O banco de dados foi bloqueado para segurança.`);
        } else {
          setErrorMessage(`Falha na consulta (Código ${errorCode}): ${errorDetails}`);
        }
        return;
      }
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(`Erro de exceção: ${formatErrorMessage(err)}`);
    }
  };

  const copyRepairScript = () => {
    const repairSql = `-- SCRIPT DE REPARO TAGWAY (ANTI-RECURSÃO)
-- 1. Desativar RLS temporariamente para limpeza profunda
ALTER TABLE user_configs DISABLE ROW LEVEL SECURITY;

-- 2. Remover TODAS as políticas antigas que podem estar em conflito
DROP POLICY IF EXISTS "Master Control" ON user_configs;
DROP POLICY IF EXISTS "master_access" ON user_configs;
DROP POLICY IF EXISTS "master_access_v2" ON user_configs;
DROP POLICY IF EXISTS "master_bypass_recursion" ON user_configs;
DROP POLICY IF EXISTS "master_bypass_recursion_final" ON user_configs;
DROP POLICY IF EXISTS "master_bypass_recursion_final_v4" ON user_configs;
DROP POLICY IF EXISTS "master_bypass_recursion_final_v5" ON user_configs;
DROP POLICY IF EXISTS "master_rule_fixed_v5" ON user_configs;
DROP POLICY IF EXISTS "master_view_all" ON user_configs;
DROP POLICY IF EXISTS "user_configs_self_view" ON user_configs;
DROP POLICY IF EXISTS "user_view_self" ON user_configs;

-- 3. Criar Política MASTER "BLINDADA"
-- Esta regra olha o e-mail no token de login (JWT), nunca a tabela, matando a recursão.
CREATE POLICY "master_rule_fixed_v6" ON user_configs 
FOR ALL TO authenticated 
USING ( (auth.jwt() ->> 'email') = 'tagwaytw@gmail.com' );

-- 4. Criar Política de Usuário (Ver apenas si mesmo)
CREATE POLICY "user_rule_self_v6" ON user_configs 
FOR SELECT TO authenticated 
USING ( auth.uid() = user_id );

-- 5. Reativar RLS com as regras limpas
ALTER TABLE user_configs ENABLE ROW LEVEL SECURITY;`;

    navigator.clipboard.writeText(repairSql);
    alert("SCRIPT DE REPARO COPIADO!\n\nVá ao SQL Editor do Supabase, cole este código e execute (Run).");
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsUpdating(user.user_id);
    try {
      const { error } = await supabase.from('user_configs').update({
        nome_completo: user.nome_completo,
        empresa_nome: user.empresa_nome,
        status: user.status
      }).eq('user_id', user.user_id);
      if (error) throw error;
      alert('Perfil do operador atualizado!');
      fetchUsers();
    } catch (err: any) {
      alert(`Erro ao salvar: ${formatErrorMessage(err)}`);
    } finally {
      setIsUpdating(null);
    }
  };

  const updateUserInState = (userId: string, field: keyof UserProfile, value: any) => {
    setUsers(prev => prev.map(u => u.user_id === userId ? { ...u, [field]: value } : u));
  };

  return (
