        </div>
        <div className="flex gap-2">
           <button onClick={copyRepairScript} className="bg-amber-100 hover:bg-amber-200 text-amber-700 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2 border border-amber-200">
