        .from('user_configs')
        .select('*');

      if (error) {
        const errorDetails = formatErrorMessage(error);
        const errorCode = error.code || 'UNK';
        if (errorCode === '42P17' || errorDetails.toLowerCase().includes('recursion')) {
          setIsRecursionError(true);
          setErrorMessage(`ERRO DE INFRAESTRUTURA (42P17): O banco de dados está em conflito de permissões (Loop RLS).`);
        } else {
          setErrorMessage(`Erro ao carregar dados: ${errorDetails}`);
        }
        return;
      }
      if (data) setUsers(data as UserProfile[]);
