            </div>
            <div className="space-y-4 mb-6">
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Empresa</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-black" value={user.empresa_nome || ''} onChange={(e) => updateUserInState(user.user_id, 'empresa_nome', e.target.value)} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => updateUserInState(user.user_id, 'status', 'ativo')} className={`py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'ativo' ? 'bg-black text-white border-black' : 'bg-white text-slate-400 border-slate-200'}`}>Ativar</button>
                <button onClick={() => updateUserInState(user.user_id, 'status', 'bloqueado')} className={`py-3 rounded-xl text-[9px] font-black uppercase border transition-all ${user.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600' : 'bg-white text-slate-400 border-slate-200'}`}>Bloquear</button>
              </div>
            </div>
            <button onClick={() => handleUpdateUser(user)} disabled={isUpdating === user.user_id} className="w-full bg-slate-900 text-white py-4 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-black transition-all shadow-xl disabled:opacity-50">
              {isUpdating === user.user_id ? 'Processando...' : 'Aplicar Alterações Master'}
