  );
};

export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado';
  telefone?: string;
  is_admin: boolean;
  created_at?: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);

  // Form para novo usuário
  const [newUser, setNewUser] = useState({
    email: '',
    nome_completo: '',
    empresa_nome: '',
    user_id: '' // No Supabase, o ideal é que o ID venha do Auth, mas aqui permitimos o pre-cadastro
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(err.message || 'Erro ao conectar ao banco master.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateUser = async () => {
    if (!newUser.email || !newUser.nome_completo) return alert("E-mail e Nome são obrigatórios.");

    try {
      const { error } = await supabase.from('user_configs').insert([{
        ...newUser,
        status: 'ativo',
        is_admin: false
      }]);

      if (error) throw error;
      alert("Operador pré-cadastrado com sucesso!");
      setIsAdding(false);
      setNewUser({ email: '', nome_completo: '', empresa_nome: '', user_id: '' });
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao criar: " + err.message);
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert("Perfil atualizado!");
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao atualizar: " + err.message);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm("⚠️ ATENÇÃO: Esta ação removerá o perfil do operador permanentemente. Continuar?")) return;
    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
    } catch (err: any) {
      alert("Erro ao deletar: " + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const stats = useMemo(() => ({
    total: users.length,
    ativos: users.filter(u => u.status === 'ativo').length,
    bloqueados: users.filter(u => u.status === 'bloqueado').length
  }), [users]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      {/* HEADER MASTER */}
      <header className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 bg-slate-900 p-10 rounded-[3rem] text-white shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-600/20 blur-[120px] rounded-full"></div>
        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-2">
            <div className="bg-indigo-500 p-2.5 rounded-xl shadow-lg">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
            </div>
            <h2 className="text-4xl font-black tracking-tighter uppercase italic">Comando Master</h2>
          </div>
          <p className="text-white/40 text-[10px] font-black uppercase tracking-widest">Gestão de Infraestrutura de Dados e Acessos</p>
        </div>

        <div className="flex gap-4 relative z-10">
          <StatBox label="Operadores" value={stats.total} />
          <StatBox label="Ativos" value={stats.ativos} color="text-emerald-400" />
          <StatBox label="Bloqueios" value={stats.bloqueados} color="text-rose-400" />
        </div>
      </header>

      {/* FERRAMENTAS */}
      <div className="flex flex-col md:flex-row gap-4 items-stretch">
        <div className="flex-1 relative">
          <input 
            type="text" 
            placeholder="Pesquisar por nome, e-mail ou empresa..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border border-slate-200 rounded-2xl px-6 py-4 pl-14 text-sm font-bold shadow-sm focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all"
          />
          <svg className="w-6 h-6 absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-indigo-700 transition-all shadow-xl flex items-center justify-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
          Adicionar Operador
        </button>
      </div>

      {/* LISTAGEM DE USUÁRIOS */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {isLoading ? (
          <div className="col-span-full py-20 text-center opacity-30 animate-pulse text-xs font-black uppercase tracking-widest italic">Sincronizando privilégios...</div>
        ) : filteredUsers.length > 0 ? filteredUsers.map(user => (
          <div key={user.user_id} className={`bg-white border p-8 rounded-[2.5rem] transition-all group relative overflow-hidden ${user.status === 'bloqueado' ? 'opacity-60 border-rose-100' : 'hover:border-indigo-600 hover:shadow-2xl shadow-sm border-slate-100'}`}>
            <div className="flex justify-between items-start mb-6">
              <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 group-hover:bg-indigo-600 group-hover:text-white transition-all">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
              </div>
              <div className="flex flex-col items-end gap-2">
                <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest ${user.status === 'ativo' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                  {user.status}
                </span>
                <span className="text-[7px] text-slate-300 font-mono">{user.user_id.slice(0, 8)}...</span>
              </div>
            </div>

            <div className="space-y-1 mb-6">
              <h3 className="text-xl font-black text-slate-900 tracking-tighter leading-none truncate">{user.nome_completo || 'Sem Nome'}</h3>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{user.email}</p>
            </div>

            <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 mb-6 space-y-3">
              <div className="flex justify-between">
                <span className="text-[8px] font-black text-slate-400 uppercase">Empresa</span>
                <span className="text-[10px] font-black text-slate-700">{user.empresa_nome || 'Não informada'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[8px] font-black text-slate-400 uppercase">Telefone</span>
                <span className="text-[10px] font-black text-slate-700">{user.telefone || '--'}</span>
              </div>
            </div>

            <div className="flex gap-2">
              <button 
                onClick={() => setSelectedUser(user)}
                className="flex-1 bg-slate-900 text-white py-3 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-600 transition-all shadow-lg"
              >
                Gerenciar
              </button>
              <button 
                onClick={() => handleDeleteUser(user.user_id)}
                className="w-12 bg-white border border-slate-200 text-slate-300 hover:text-rose-500 hover:border-rose-100 py-3 rounded-xl flex items-center justify-center transition-all"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          </div>
        )) : (
          <div className="col-span-full py-40 text-center bg-white rounded-[3rem] border-2 border-dashed border-slate-200">
             <div className="text-5xl mb-4 opacity-10">🔍</div>
             <p className="text-slate-400 font-black uppercase text-xs tracking-[0.3em]">Nenhum operador encontrado na rede.</p>
          </div>
        )}
      </div>

      {/* MODAL: ADICIONAR */}
      {isAdding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsAdding(false)}></div>
          <div className="relative bg-white w-full max-w-lg rounded-[2.5rem] p-10 shadow-2xl animate-slide-up">
            <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase mb-8 italic">Pré-cadastrar Operador</h3>
            <div className="space-y-5">
              <Input label="E-mail de Acesso" value={newUser.email} onChange={v => setNewUser({...newUser, email: v})} placeholder="exemplo@email.com" />
              <Input label="Nome Completo" value={newUser.nome_completo} onChange={v => setNewUser({...newUser, nome_completo: v})} placeholder="Nome do Operador" />
              <Input label="Nome da Empresa" value={newUser.empresa_nome} onChange={v => setNewUser({...newUser, empresa_nome: v})} placeholder="Empresa LTDA" />
              <Input label="ID do Usuário (Opcional)" value={newUser.user_id} onChange={v => setNewUser({...newUser, user_id: v})} placeholder="UUID do Auth Supabase" />

              <div className="pt-6 flex gap-4">
                <button onClick={() => setIsAdding(false)} className="flex-1 py-4 text-[10px] font-black uppercase text-slate-400 hover:text-slate-900 transition-all">Cancelar</button>
                <button onClick={handleCreateUser} className="flex-[2] bg-indigo-600 text-white py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-indigo-700 transition-all">Confirmar Registro</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* MODAL: EDITAR / GERENCIAR */}
      {selectedUser && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setSelectedUser(null)}></div>
          <div className="relative bg-white w-full max-w-lg rounded-[2.5rem] p-10 shadow-2xl animate-slide-up">
            <div className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-900 tracking-tighter uppercase italic">Editar Perfil</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{selectedUser.email}</p>
              </div>
              <button onClick={() => setSelectedUser(null)} className="p-2 text-slate-200 hover:text-slate-900 transition-all">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="space-y-5">
              <Input label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
              <Input label="Empresa" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />
              <Input label="Telefone" value={selectedUser.telefone || ''} onChange={v => setSelectedUser({...selectedUser, telefone: v})} />

              <div className="space-y-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Status do Acesso</label>
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})}
                    className={`py-4 rounded-xl text-[10px] font-black uppercase border transition-all ${selectedUser.status === 'ativo' ? 'bg-emerald-600 text-white border-emerald-600 shadow-lg' : 'bg-slate-50 border-slate-200 text-slate-400'}`}
                  >
                    Ativo
                  </button>
                  <button 
                    onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})}
                    className={`py-4 rounded-xl text-[10px] font-black uppercase border transition-all ${selectedUser.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600 shadow-lg' : 'bg-slate-50 border-slate-200 text-slate-400'}`}
                  >
                    Bloqueado
                  </button>
                </div>
              </div>

              <div className="pt-8">
                <button onClick={() => handleUpdateUser(selectedUser)} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-black transition-all">
                  Salvar Alterações Master
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatBox = ({ label, value, color }: { label: string, value: number, color?: string }) => (
  <div className="bg-white/5 border border-white/10 p-5 rounded-2xl min-w-[120px]">
    <span className="text-[8px] font-black text-white/30 uppercase tracking-[0.2em] block mb-1">{label}</span>
    <span className={`text-2xl font-black font-mono tracking-tighter ${color || 'text-white'}`}>{value.toString().padStart(2, '0')}</span>
  </div>
);

const Input = ({ label, value, onChange, placeholder = "" }: { label: string, value: string, onChange: (v: string) => void, placeholder?: string }) => (
  <div className="space-y-1.5">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type="text" 
      value={value}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-4 text-sm font-bold outline-none focus:border-indigo-600 transition-all"
    />
  </div>
);

