      setIsLoading(false);
    }
  };

  const handleCreateUser = async () => {
    if (!newUser.email || !newUser.nome_completo) return alert("E-mail e Nome são obrigatórios.");

    try {
      // Limpeza de payload para evitar erro de UUID (string vazia não é UUID)
      const payload: any = {
        email: newUser.email.trim(),
        nome_completo: newUser.nome_completo.trim(),
        empresa_nome: newUser.empresa_nome.trim(),
        status: 'ativo',
        is_admin: false
      };

      if (newUser.user_id && newUser.user_id.trim() !== "") {
        payload.user_id = newUser.user_id.trim();
      }

      const { error } = await supabase.from('user_configs').insert([payload]);

      if (error) throw error;
      alert("Operador cadastrado com sucesso!");
      setIsAdding(false);
      setNewUser({ email: '', nome_completo: '', empresa_nome: '', user_id: '' });
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao criar: " + err.message);
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;

      // Lógica de senha (Simulação de Admin Auth ou via rpc se configurado)
      if (newPassword.length >= 6) {
        console.log(`Solicitando alteração de senha para: ${user.email}`);
        // Nota: supabase.auth.admin.updateUserById exigiria chave service_role. 
        // Aqui notificamos que o processo de perfil foi ok.
        alert("Perfil atualizado! (Para alteração de senha, utilize o painel Auth ou solicite reset).");
      } else {
        alert("Perfil do operador atualizado com sucesso!");
      }

      setSelectedUser(null);
      setNewPassword('');
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao atualizar: " + err.message);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm("⚠️ ATENÇÃO CRÍTICA: Esta ação removerá o perfil do operador da base de dados permanentemente. Continuar?")) return;
    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
    } catch (err: any) {
      alert("Erro ao deletar: " + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const stats = useMemo(() => ({
    total: users.length,
    ativos: users.filter(u => u.status === 'ativo').length,
    bloqueados: users.filter(u => u.status === 'bloqueado').length
  }), [users]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      {/* HEADER MASTER COM DESIGN INDUSTRIAL */}
      <header className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 bg-black p-12 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden border border-white/10">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-indigo-600/10 blur-[150px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-4">
            <div className="bg-white/10 p-3 rounded-2xl border border-white/10">
              <svg className="w-8 h-8 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
            </div>
            <div>
              <h2 className="text-5xl font-black tracking-tighter uppercase italic leading-none">Controle Master</h2>
              <p className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.3em] mt-2">Tagway Technology Intelligence Unit</p>
            </div>
          </div>
        </div>

        <div className="flex gap-6 relative z-10">
          <StatBox label="Total Operadores" value={stats.total} />
          <StatBox label="Acessos Ativos" value={stats.ativos} color="text-emerald-400" />
          <StatBox label="Contas Bloqueadas" value={stats.bloqueados} color="text-rose-400" />
        </div>
      </header>

      {/* BARRA DE COMANDO */}
      <div className="flex flex-col md:flex-row gap-6 items-stretch">
        <div className="flex-1 relative">
          <input 
            type="text" 
            placeholder="Filtrar rede por e-mail, nome ou empresa..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[2rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all placeholder:text-slate-300"
          />
          <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-black text-white px-10 py-5 rounded-[2rem] font-black uppercase text-[11px] tracking-widest hover:bg-indigo-600 transition-all shadow-2xl flex items-center justify-center gap-3 active:scale-95"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg>
          Novo Operador
        </button>
      </div>

      {/* GRID DE OPERADORES */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {isLoading ? (
          <div className="col-span-full py-40 text-center">
             <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-6"></div>
             <p className="text-slate-400 font-black uppercase text-xs tracking-[0.4em]">Sincronizando Rede Master...</p>
          </div>
        ) : filteredUsers.length > 0 ? filteredUsers.map(user => (
          <div key={user.user_id} className={`bg-white border-2 p-10 rounded-[3rem] transition-all group relative overflow-hidden ${user.status === 'bloqueado' ? 'opacity-60 grayscale border-rose-100' : 'hover:border-black hover:shadow-2xl shadow-lg border-slate-50'}`}>
            <div className="flex justify-between items-start mb-8">
              <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 group-hover:bg-black group-hover:text-white transition-all shadow-inner">
                <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
              </div>
              <div className="flex flex-col items-end gap-2">
                <span className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest ${user.status === 'ativo' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                  {user.status}
                </span>
              </div>
            </div>

            <div className="space-y-1 mb-8">
              <h3 className="text-2xl font-black text-slate-900 tracking-tighter leading-none truncate">{user.nome_completo || 'Sem Identificação'}</h3>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest truncate">{user.email}</p>
            </div>

            <div className="bg-slate-50 p-6 rounded-[1.5rem] mb-8 space-y-4 border border-slate-100">
              <div className="flex justify-between items-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Empresa</span>
                <span className="text-[11px] font-black text-slate-700 italic truncate max-w-[120px]">{user.empresa_nome || 'N/A'}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Acesso desde</span>
                <span className="text-[10px] font-black text-slate-500 font-mono">
                  {user.created_at ? new Date(user.created_at).toLocaleDateString() : '--/--/----'}
                </span>
              </div>
            </div>

            <div className="flex gap-3">
              <button 
                onClick={() => setSelectedUser(user)}
                className="flex-1 bg-black text-white py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] hover:bg-indigo-600 transition-all shadow-xl"
              >
                Gerenciar
              </button>
              <button 
                onClick={() => handleDeleteUser(user.user_id)}
                className="w-14 bg-slate-50 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-2xl flex items-center justify-center transition-all border border-transparent hover:border-rose-100"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
              </button>
            </div>
          </div>
        )) : (
          <div className="col-span-full py-40 text-center bg-white rounded-[4rem] border-4 border-dashed border-slate-100">
             <div className="text-7xl mb-6 opacity-10 grayscale">📡</div>
             <p className="text-slate-400 font-black uppercase text-sm tracking-[0.5em]">Nenhum operador detectado na rede.</p>
          </div>
        )}
      </div>

      {/* MODAL MASTER: ADICIONAR */}
      {isAdding && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-sm">
          <div className="absolute inset-0" onClick={() => setIsAdding(false)}></div>
          <div className="relative bg-white w-full max-w-xl rounded-[3.5rem] p-12 shadow-2xl animate-slide-up border border-slate-100">
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase mb-10 italic">Registro de Operador</h3>
            <div className="space-y-6">
              <Input label="E-mail Corporativo" value={newUser.email} onChange={v => setNewUser({...newUser, email: v})} placeholder="exemplo@tagway.pro" />
              <Input label="Nome Completo" value={newUser.nome_completo} onChange={v => setNewUser({...newUser, nome_completo: v})} placeholder="Nome do Operador" />
              <Input label="Empresa / Grupo" value={newUser.empresa_nome} onChange={v => setNewUser({...newUser, empresa_nome: v})} placeholder="Empresa Associada" />
              <Input label="UUID Supabase (Opcional)" value={newUser.user_id} onChange={v => setNewUser({...newUser, user_id: v})} placeholder="Deixe vazio para auto-gerar" />

              <div className="pt-8 flex gap-4">
                <button onClick={() => setIsAdding(false)} className="flex-1 py-5 text-[11px] font-black uppercase text-slate-400 hover:text-slate-900 transition-all">Cancelar</button>
                <button onClick={handleCreateUser} className="flex-[2] bg-black text-white py-5 rounded-2xl font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Confirmar Registro</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* MODAL MASTER: GERENCIAR PERFIL */}
      {selectedUser && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
          <div className="absolute inset-0" onClick={() => setSelectedUser(null)}></div>
          <div className="relative bg-white w-full max-w-2xl rounded-[4rem] p-14 shadow-2xl animate-slide-up">
            <div className="flex justify-between items-start mb-12">
              <div>
                <h3 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">Gestão de Perfil</h3>
                <p className="text-[11px] font-black text-indigo-500 uppercase tracking-[0.3em] mt-3">Sessão: {selectedUser.email}</p>
              </div>
              <button onClick={() => setSelectedUser(null)} className="p-3 bg-slate-50 rounded-2xl text-slate-300 hover:text-black hover:bg-slate-100 transition-all">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>
            </div>

            <div className="grid grid-cols-2 gap-8 mb-10">
              <div className="space-y-6">
                <Input label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
                <Input label="Empresa / Unidade" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />
              </div>
              <div className="space-y-6">
                <Input label="Telefone Contato" value={selectedUser.telefone || ''} onChange={v => setSelectedUser({...selectedUser, telefone: v})} />
                <Input label="Senha Master (Reset)" type="password" value={newPassword} onChange={v => setNewPassword(v)} placeholder="Mínimo 6 dígitos" />
              </div>
            </div>

            <div className="space-y-4 mb-12">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Status do Privilégio</label>
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})}
                  className={`py-5 rounded-[1.5rem] text-[11px] font-black uppercase border-2 transition-all ${selectedUser.status === 'ativo' ? 'bg-emerald-600 text-white border-emerald-600 shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-400'}`}
                >
                  Liberar Acesso
                </button>
                <button 
                  onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})}
                  className={`py-5 rounded-[1.5rem] text-[11px] font-black uppercase border-2 transition-all ${selectedUser.status === 'bloqueado' ? 'bg-rose-600 text-white border-rose-600 shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-400'}`}
                >
                  Bloquear Acesso
                </button>
              </div>
            </div>

            <button onClick={() => handleUpdateUser(selectedUser)} className="w-full bg-black text-white py-6 rounded-[2rem] font-black uppercase text-[12px] tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all active:scale-[0.98]">
              Sobreescrever Perfil Master
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const StatBox = ({ label, value, color }: { label: string, value: number, color?: string }) => (
  <div className="bg-white/5 border border-white/10 p-6 rounded-[2rem] min-w-[160px] shadow-inner">
    <span className="text-[9px] font-black text-white/30 uppercase tracking-[0.2em] block mb-2">{label}</span>
    <span className={`text-4xl font-black font-mono tracking-tighter ${color || 'text-white'}`}>{value.toString().padStart(2, '0')}</span>
  </div>
);

const Input = ({ label, value, onChange, placeholder = "", type = "text" }: { label: string, value: string, onChange: (v: string) => void, placeholder?: string, type?: string }) => (
  <div className="space-y-2">
    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">{label}</label>
    <input 
      type={type} 
      value={value}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-black transition-all shadow-sm"
    />
  </div>
);

export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado';
  telefone?: string;
  is_admin: boolean;
  created_at?: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [newPassword, setNewPassword] = useState('');
  const [rlsStatus, setRlsStatus] = useState<{ canInsert: boolean | null }>({ canInsert: null });

  // Form para novo usuário
  const [newUser, setNewUser] = useState({
    email: '',
    nome_completo: '',
    empresa_nome: '',
    user_id: '' 
  });

  useEffect(() => {
    fetchUsers();
    checkPermissions();
  }, []);

  const checkPermissions = async () => {
    // Tenta uma inserção fake em modo dry-run ou checa via RPC se disponível.
    // Como teste simples, apenas logamos o status.
    console.log("Verificando privilégios Master...");
  };

  const fetchUsers = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      console.error("Erro ao listar:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateUser = async () => {
    if (!newUser.email || !newUser.nome_completo) return alert("E-mail e Nome são obrigatórios.");

    try {
      // payload sem user_id se estiver vazio para evitar erro de tipo UUID
      const payload: any = {
        email: newUser.email.trim().toLowerCase(),
        nome_completo: newUser.nome_completo.trim(),
        empresa_nome: newUser.empresa_nome.trim(),
        status: 'ativo',
        is_admin: false
      };

      if (newUser.user_id && newUser.user_id.trim() !== "") {
        payload.user_id = newUser.user_id.trim();
      }

      const { error } = await supabase.from('user_configs').insert([payload]);

      if (error) {
        if (error.message.includes('row-level security')) {
          throw new Error("⚠️ BLOQUEIO DE SEGURANÇA: Seu e-mail Master não tem permissão de INSERÇÃO no banco. Verifique as políticas RLS.");
        }
        throw error;
      }

      alert("🚀 Operador registrado com sucesso na rede Tagway.");
      setIsAdding(false);
      setNewUser({ email: '', nome_completo: '', empresa_nome: '', user_id: '' });
      fetchUsers();
    } catch (err: any) {
      alert(err.message);
      setRlsStatus({ canInsert: false });
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert("✅ Perfil sincronizado.");
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert("Erro RLS Update: " + err.message);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm("🚨 AÇÃO IRREVERSÍVEL: Remover este operador da infraestrutura?")) return;
    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
    } catch (err: any) {
      alert("Erro RLS Delete: " + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const stats = useMemo(() => ({
    total: users.length,
    ativos: users.filter(u => u.status === 'ativo').length,
    bloqueados: users.filter(u => u.status === 'bloqueado').length
  }), [users]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      {/* HEADER INDUSTRIAL MASTER */}
      <header className="bg-[#0a0a0a] p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-10">
          <div className="space-y-4">
            <div className="flex items-center gap-4">
               <div className="bg-indigo-500/20 p-3 rounded-2xl border border-indigo-500/20">
                  <svg className="w-8 h-8 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
               </div>
               <h2 className="text-5xl font-black tracking-tighter uppercase italic">Comando Master</h2>
            </div>
            <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] ml-1">Tagway Technology Core Control</p>
          </div>

          <div className="flex gap-6">
            <StatBox label="Operadores" value={stats.total} />
            <StatBox label="Online" value={stats.ativos} color="text-emerald-400" />
            <StatBox label="Offline" value={stats.bloqueados} color="text-rose-400" />
          </div>
        </div>

        {/* ALERTA DE RLS BLOQUEADO NO TOPO DO PAINEL */}
        {rlsStatus.canInsert === false && (
          <div className="mt-10 bg-rose-500/10 border border-rose-500/20 p-6 rounded-3xl flex items-center justify-between">
             <div className="flex items-center gap-4">
                <span className="text-2xl">🚧</span>
                <div>
                  <p className="text-rose-400 text-xs font-black uppercase">Segurança de Escrita Bloqueada</p>
                  <p className="text-[10px] text-rose-400/60 font-bold uppercase">Execute o SQL de permissão "INSERT" no Supabase para liberar o cadastro.</p>
                </div>
             </div>
             <button onClick={() => setRlsStatus({ canInsert: null })} className="text-rose-400/40 hover:text-rose-400 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
             </button>
          </div>
        )}
      </header>

      {/* CONTROLES */}
      <div className="flex flex-col md:flex-row gap-6 items-stretch">
        <div className="flex-1 relative">
          <input 
            type="text" 
            placeholder="Buscar por e-mail ou empresa..."
