export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado';
  telefone?: string;
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [newPassword, setNewPassword] = useState('');
  const [rlsStatus, setRlsStatus] = useState<{ canInsert: boolean | null }>({ canInsert: null });

  // Form para novo usuário
  const [newUser, setNewUser] = useState({
    email: '',
    nome_completo: '',
    empresa_nome: '',
    user_id: '' 
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('email', { ascending: true });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      console.error("Erro ao listar:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateUser = async () => {
    if (!newUser.email || !newUser.nome_completo) return alert("E-mail e Nome são obrigatórios.");

    try {
      // payload sem user_id se estiver vazio para evitar erro de tipo UUID
      const payload: any = {
        email: newUser.email.trim().toLowerCase(),
        nome_completo: newUser.nome_completo.trim(),
        empresa_nome: newUser.empresa_nome.trim(),
        status: 'ativo',
        is_admin: false
      };

      if (newUser.user_id && newUser.user_id.trim() !== "") {
        payload.user_id = newUser.user_id.trim();
      }

      const { error } = await supabase.from('user_configs').insert([payload]);

      if (error) {
        if (error.message.includes('row-level security')) {
          throw new Error("⚠️ BLOQUEIO DE SEGURANÇA: Seu e-mail Master não tem permissão de INSERÇÃO no banco. Verifique as políticas RLS.");
        }
        throw error;
      }

      alert("🚀 Operador registrado com sucesso na rede Tagway.");
      setIsAdding(false);
      setNewUser({ email: '', nome_completo: '', empresa_nome: '', user_id: '' });
      fetchUsers();
    } catch (err: any) {
      alert(err.message);
      setRlsStatus({ canInsert: false });
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert("✅ Perfil sincronizado.");
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert("Erro RLS Update: " + err.message);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm("🚨 AÇÃO IRREVERSÍVEL: Remover este operador da infraestrutura?")) return;
    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
    } catch (err: any) {
      alert("Erro RLS Delete: " + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const stats = useMemo(() => ({
    total: users.length,
    ativos: users.filter(u => u.status === 'ativo').length,
    bloqueados: users.filter(u => u.status === 'bloqueado').length
  }), [users]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      {/* HEADER INDUSTRIAL MASTER */}
      <header className="bg-[#0a0a0a] p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-10">
          <div className="space-y-4">
            <div className="flex items-center gap-4">
               <div className="bg-indigo-500/20 p-3 rounded-2xl border border-indigo-500/20">
                  <svg className="w-8 h-8 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
               </div>
               <h2 className="text-5xl font-black tracking-tighter uppercase italic">Comando Master</h2>
            </div>
            <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] ml-1">Tagway Technology Core Control</p>
          </div>

          <div className="flex gap-6">
            <StatBox label="Operadores" value={stats.total} />
            <StatBox label="Online" value={stats.ativos} color="text-emerald-400" />
            <StatBox label="Offline" value={stats.bloqueados} color="text-rose-400" />
          </div>
        </div>

        {/* ALERTA DE RLS BLOQUEADO NO TOPO DO PAINEL */}
        {rlsStatus.canInsert === false && (
