export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado';
  telefone?: string;
  is_admin: boolean;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [rlsStatus, setRlsStatus] = useState<{ canInsert: boolean | null }>({ canInsert: null });

  // Form para novo usuário
  const [newUser, setNewUser] = useState({
    email: '',
    nome_completo: '',
    empresa_nome: '',
    user_id: '' 
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('email', { ascending: true });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      console.error("Erro ao listar:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateUser = async () => {
    if (!newUser.email || !newUser.nome_completo) return alert("E-mail e Nome são obrigatórios.");

    try {
      // Se não houver ID, geramos um UUID aleatório para satisfazer a constraint NOT NULL do banco
      const generatedId = newUser.user_id.trim() !== "" 
        ? newUser.user_id.trim() 
        : crypto.randomUUID();

      const payload: any = {
        user_id: generatedId,
        email: newUser.email.trim().toLowerCase(),
        nome_completo: newUser.nome_completo.trim(),
        empresa_nome: newUser.empresa_nome.trim(),
        status: 'ativo',
        is_admin: false
      };

      const { error } = await supabase.from('user_configs').insert([payload]);

      if (error) {
        if (error.message.includes('row-level security')) {
          throw new Error("⚠️ BLOQUEIO RLS: Seu usuário não tem permissão de escrita. Verifique as políticas no Supabase.");
        }
        throw error;
      }

      alert("🚀 Operador registrado com sucesso!");
      setIsAdding(false);
      setNewUser({ email: '', nome_completo: '', empresa_nome: '', user_id: '' });
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao criar: " + err.message);
      setRlsStatus({ canInsert: false });
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;
      alert("✅ Perfil atualizado.");
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao atualizar: " + err.message);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm("🚨 REMOVER OPERADOR? Esta ação é definitiva.")) return;
    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
    } catch (err: any) {
      alert("Erro ao deletar: " + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const stats = useMemo(() => ({
    total: users.length,
    ativos: users.filter(u => u.status === 'ativo').length,
    bloqueados: users.filter(u => u.status === 'bloqueado').length
  }), [users]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      {/* HEADER MASTER */}
      <header className="bg-black p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-indigo-600/10 blur-[150px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-6">
            <div className="bg-indigo-600/20 p-4 rounded-3xl border border-indigo-500/20">
               <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"/></svg>
            </div>
            <div>
