             <StatBox label="Ativos" value={stats.ativos} color="text-emerald-400" />
             <StatBox label="Bloqueios" value={stats.bloqueados} color="text-rose-400" />
          </div>
        </div>
      </header>

      {/* SEARCH E BOTÃO ADICIONAR */}
      <div className="flex flex-col md:flex-row gap-6">
