            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[2rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all"
          />
