      <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] font-black tracking-widest">
                <th className="px-10 py-6">Operador / Cargo</th>
                <th className="px-10 py-6">Empresa</th>
                <th className="px-10 py-6">Nível de Acesso</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-right">Ação</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={5} className="p-20 text-center animate-pulse text-[10px] font-black uppercase text-slate-400">Escaneando Infraestrutura...</td></tr>
              ) : filteredUsers.map(user => (
                <tr key={user.user_id} className="hover:bg-slate-50 transition-all group cursor-pointer" onClick={() => setSelectedUser(user)}>
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-black group-hover:bg-black group-hover:text-white transition-all">
                          {user.nome_completo.charAt(0)}
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-900 tracking-tight leading-none">{user.nome_completo}</p>
                          <p className="text-[10px] font-black text-indigo-500 uppercase mt-1.5">{user.role || 'Operador Fiscal'}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <span className="text-[10px] font-black uppercase text-slate-400">{user.empresa_nome || 'Tagway Force'}</span>
                  </td>
                  <td className="px-10 py-6">
                    <span className="bg-slate-100 px-3 py-1 rounded-lg text-[9px] font-black uppercase text-slate-600">{user.access_level || 'Padrão'}</span>
                  </td>
                  <td className="px-10 py-6">
                     <StatusBadge status={user.status} />
                  </td>
                  <td className="px-10 py-6 text-right">
                     <button className="text-[9px] font-black uppercase tracking-widest text-slate-300 hover:text-black transition-all">Editar Perfil</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL: DETALHES E EDIÇÃO (SINCRONIZAÇÃO) */}
      {selectedUser && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
           <div className="bg-white w-full max-w-2xl rounded-[4rem] shadow-2xl overflow-hidden animate-slide-up">
              <header className="bg-black p-12 text-white flex justify-between items-center">
                 <div>
                    <h3 className="text-3xl font-black text-white tracking-tighter uppercase italic leading-none">Perfil Operacional</h3>
                    <p className="text-white/40 text-[9px] font-black uppercase tracking-widest mt-2">UUID: {selectedUser.user_id}</p>
                 </div>
                 <button onClick={() => setSelectedUser(null)} className="text-white/20 hover:text-white transition-all">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
              </header>

              <div className="p-12 space-y-8">
                 <div className="grid grid-cols-2 gap-8">
                    <AdminInput label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="Empresa" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />
                 </div>
                 <div className="grid grid-cols-2 gap-8">
                    <AdminInput label="Cargo / Role" value={selectedUser.role || ''} onChange={v => setSelectedUser({...selectedUser, role: v})} />
                    <AdminInput label="Nível de Acesso" value={selectedUser.access_level || ''} onChange={v => setSelectedUser({...selectedUser, access_level: v})} />
                 </div>

                 <div className="space-y-3">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Estado do Terminal</label>
                    <div className="grid grid-cols-3 gap-4">
                       <StatusButton 
                          label="Ativo" 
                          active={selectedUser.status === 'ativo'} 
                          onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})} 
                          color="bg-emerald-600" 
                       />
                       <StatusButton 
                          label="Manutenção" 
                          active={selectedUser.status === 'manutencao'} 
                          onClick={() => setSelectedUser({...selectedUser, status: 'manutencao'})} 
                          color="bg-amber-600" 
                       />
                       <StatusButton 
                          label="Bloqueado" 
                          active={selectedUser.status === 'bloqueado'} 
                          onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})} 
                          color="bg-rose-600" 
                       />
                    </div>
                 </div>

                 <div className="pt-6 flex gap-4">
                    <button 
                      onClick={() => handleDeleteUser(selectedUser.user_id)}
                      className="w-14 h-14 bg-rose-50 text-rose-200 hover:text-rose-600 rounded-2xl flex items-center justify-center transition-all border border-rose-100"
                    >
                       <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                    <button 
                       onClick={() => handleUpdateUser(selectedUser)}
                       disabled={isSyncing}
                       className="flex-1 bg-black text-white rounded-2xl font-black uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3"
                    >
                       <svg className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                       {isSyncing ? 'Sincronizando...' : 'Sincronizar Permissões'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* MODAL ADICIONAR */}
      {isAdding && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
           <div className="bg-white w-full max-w-xl rounded-[4rem] p-12 shadow-2xl animate-slide-up relative">
              <button onClick={() => setIsAdding(false)} className="absolute top-10 right-10 text-slate-300 hover:text-black">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>

              <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic mb-10">Novo Registro</h3>

              <div className="space-y-6">
                 <AdminInput label="E-mail Corporativo" value={newUser.email} onChange={v => setNewUser({...newUser, email: v})} placeholder="exemplo@tagway.pro" />
                 <AdminInput label="Nome Completo" value={newUser.nome_completo} onChange={v => setNewUser({...newUser, nome_completo: v})} placeholder="Nome do Operador" />
                 <AdminInput label="Empresa" value={newUser.empresa_nome} onChange={v => setNewUser({...newUser, empresa_nome: v})} placeholder="Unidade de Negócio" />
                 <AdminInput label="Cargo Inicial" value={newUser.role} onChange={v => setNewUser({...newUser, role: v})} />
                 <AdminInput label="User ID (Opcional)" value={newUser.user_id} onChange={v => setNewUser({...newUser, user_id: v})} placeholder="Deixe em branco para auto-gerar" />

                 <div className="pt-6">
                    <button onClick={handleCreateUser} className="w-full bg-black text-white py-5 rounded-2xl font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">
                      Finalizar Registro
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: string }) => {
  const styles: any = {
    ativo: 'bg-emerald-100 text-emerald-600',
    bloqueado: 'bg-rose-100 text-rose-600',
    manutencao: 'bg-amber-100 text-amber-600'
  };
  const labels: any = {
    ativo: 'Em Operação',
    bloqueado: 'Acesso Restrito',
    manutencao: 'Manutenção'
  };
  return (
    <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${styles[status]}`}>
      {labels[status]}
    </span>
  );
};

const StatusButton = ({ label, active, onClick, color }: any) => (
  <button 
    onClick={onClick}
    className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${active ? `${color} text-white border-transparent shadow-xl scale-105` : 'bg-slate-50 border-slate-100 text-slate-400 hover:border-slate-200'}`}
  >
    {label}
  </button>
);

const StatBox = ({ label, value, color }: any) => (
  <div className="bg-white/5 p-6 rounded-[1.5rem] border border-white/10 min-w-[120px] text-center">
    <span className="text-[9px] font-black text-white/30 uppercase tracking-[0.2em] block mb-1">{label}</span>
    <span className={`text-3xl font-black font-mono tracking-tighter ${color || 'text-white'}`}>{value}</span>
  </div>
);

const AdminInput = ({ label, value, onChange, placeholder }: any) => (
  <div className="space-y-2">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type="text" 
      value={value}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-black transition-all"
    />
  </div>
);

export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado' | 'manutencao';
  telefone?: string;
  is_admin: boolean;
  role?: string;
  access_level?: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  // Form para novo usuário
  const [newUser, setNewUser] = useState({
    email: '',
    nome_completo: '',
    empresa_nome: '',
    role: 'Operador Padrão',
    user_id: '' 
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('nome_completo', { ascending: true });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      console.error("Erro ao listar:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateUser = async () => {
    if (!newUser.email || !newUser.nome_completo) return alert("E-mail e Nome são obrigatórios.");

    try {
      const generatedId = newUser.user_id.trim() !== "" 
        ? newUser.user_id.trim() 
        : crypto.randomUUID();

      const payload: any = {
        user_id: generatedId,
        email: newUser.email.trim().toLowerCase(),
        nome_completo: newUser.nome_completo.trim(),
        empresa_nome: newUser.empresa_nome.trim(),
        role: newUser.role,
        status: 'ativo',
        is_admin: false
      };

      const { error } = await supabase.from('user_configs').insert([payload]);

      if (error) throw error;

      alert("🚀 Operador registrado com sucesso!");
      setIsAdding(false);
      setNewUser({ email: '', nome_completo: '', empresa_nome: '', role: 'Operador Padrão', user_id: '' });
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao criar: " + err.message);
    }
  };

  const handleUpdateUser = async (user: UserProfile) => {
    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          telefone: user.telefone,
          role: user.role,
          access_level: user.access_level
        })
        .eq('user_id', user.user_id);

      if (error) throw error;

      alert(`✅ Sincronização Concluída: Perfil de ${user.nome_completo} atualizado.`);
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao sincronizar: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm("🚨 AÇÃO CRÍTICA: Remover este operador permanentemente da rede?")) return;
    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
      setSelectedUser(null);
    } catch (err: any) {
      alert("Erro ao deletar: " + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.role?.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const stats = useMemo(() => ({
    total: users.length,
    ativos: users.filter(u => u.status === 'ativo').length,
    bloqueados: users.filter(u => u.status === 'bloqueado').length,
    manutencao: users.filter(u => u.status === 'manutencao').length
  }), [users]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      {/* HEADER MASTER CENTRAL */}
      <header className="bg-black p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-center gap-10">
          <div className="space-y-4">
            <div className="flex items-center gap-6">
               <div className="bg-indigo-500/20 p-4 rounded-3xl border border-indigo-500/20 shadow-inner">
                  <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
               </div>
               <div>
                 <h2 className="text-5xl font-black tracking-tighter uppercase italic leading-none">Controle de Rede</h2>
                 <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Tagway Intelligence Core Access</p>
               </div>
            </div>
          </div>

          <div className="flex gap-6">
            <StatBox label="Total" value={stats.total} />
            <StatBox label="Ativos" value={stats.ativos} color="text-emerald-400" />
            <StatBox label="Manutenção" value={stats.manutencao} color="text-amber-400" />
            <StatBox label="Restritos" value={stats.bloqueados} color="text-rose-400" />
          </div>
        </div>
      </header>

      {/* CONTROLES E BUSCA */}
      <div className="flex flex-col md:flex-row gap-6">
        <div className="flex-1 relative">
          <input 
            type="text" 
            placeholder="Pesquisar por nome, cargo ou e-mail..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[2.5rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all"
          />
          <svg className="w-6 h-6 absolute left-7 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-black text-white px-12 py-5 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-3"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg>
          Registrar Operador
        </button>
      </div>

      {/* TABELA DE USUÁRIOS */}
      <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] font-black tracking-widest italic">
                <th className="px-10 py-6">Operador / Cargo</th>
                <th className="px-10 py-6">Empresa</th>
                <th className="px-10 py-6">Acesso</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-right">Ação</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={5} className="p-32 text-center animate-pulse text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Escaneando Servidores...</td></tr>
              ) : filteredUsers.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Nenhum registro encontrado</td></tr>
              ) : filteredUsers.map(user => (
                <tr 
                  key={user.user_id} 
                  className="hover:bg-slate-50 transition-all group cursor-pointer" 
                  onClick={() => setSelectedUser(user)}
                >
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-5">
                       <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-black group-hover:bg-black group-hover:text-white transition-all">
                          {user.nome_completo?.charAt(0) || '?'}
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-900 tracking-tight leading-none">{user.nome_completo}</p>
                          <p className="text-[10px] font-black text-indigo-500 uppercase mt-2">{user.role || 'Sem Cargo'}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-[10px] font-black uppercase text-slate-400 italic">{user.empresa_nome || 'Unidade Independente'}</span>
                  </td>
                  <td className="px-10 py-7">
                    <span className="bg-slate-100 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase text-slate-600 tracking-widest">{user.access_level || 'Padrão'}</span>
                  </td>
                  <td className="px-10 py-7">
                     <StatusBadge status={user.status} />
                  </td>
                  <td className="px-10 py-7 text-right">
                     <div className="flex items-center justify-end gap-3">
                        <span className="text-[9px] font-black uppercase tracking-widest text-slate-300 group-hover:text-black transition-all">Gerenciar</span>
                        <svg className="w-4 h-4 text-slate-200 group-hover:text-black transition-all" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
                     </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL DE PERFIL OPERACIONAL (EDIÇÃO / SINCRONIZAÇÃO) */}
      {selectedUser && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
           <div className="bg-white w-full max-w-3xl rounded-[4rem] shadow-2xl overflow-hidden animate-slide-up">
              <header className="bg-black p-12 text-white flex justify-between items-center relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-emerald-500 to-rose-500"></div>
                 <div>
                    <h3 className="text-3xl font-black text-white tracking-tighter uppercase italic leading-none">Terminal do Operador</h3>
                    <p className="text-white/40 text-[9px] font-black uppercase tracking-widest mt-3">Identificação Global: {selectedUser.user_id}</p>
                 </div>
                 <button onClick={() => setSelectedUser(null)} className="text-white/20 hover:text-white transition-all bg-white/5 p-3 rounded-2xl">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
              </header>

              <div className="p-12 grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <AdminInput label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="Empresa de Atuação" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />
                    <AdminInput label="Telefone / Ramal" value={selectedUser.telefone || ''} onChange={v => setSelectedUser({...selectedUser, telefone: v})} />
                 </div>

                 <div className="space-y-6">
                    <AdminInput label="Cargo Operacional" value={selectedUser.role || ''} onChange={v => setSelectedUser({...selectedUser, role: v})} />
                    <AdminInput label="Nível de Acesso (Tier)" value={selectedUser.access_level || ''} onChange={v => setSelectedUser({...selectedUser, access_level: v})} />

                    <div className="space-y-3">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Estado de Conexão</label>
                       <div className="grid grid-cols-3 gap-3">
                          <StatusButton 
                             label="Ativo" 
                             active={selectedUser.status === 'ativo'} 
                             onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})} 
                             color="bg-emerald-600" 
                          />
                          <StatusButton 
                             label="Manutenção" 
                             active={selectedUser.status === 'manutencao'} 
                             onClick={() => setSelectedUser({...selectedUser, status: 'manutencao'})} 
                             color="bg-amber-600" 
                          />
                          <StatusButton 
                             label="Bloqueado" 
                             active={selectedUser.status === 'bloqueado'} 
                             onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})} 
                             color="bg-rose-600" 
                          />
                       </div>
                    </div>
                 </div>

                 <div className="lg:col-span-2 pt-10 flex gap-4 border-t border-slate-100">
                    <button 
                      onClick={() => handleDeleteUser(selectedUser.user_id)}
                      className="w-16 h-16 bg-rose-50 text-rose-300 hover:text-rose-600 rounded-3xl flex items-center justify-center transition-all border border-rose-100 active:scale-95"
                    >
                       <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                    <button 
                       onClick={() => handleUpdateUser(selectedUser)}
                       disabled={isSyncing}
                       className="flex-1 bg-black text-white rounded-3xl font-black uppercase text-[12px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50"
                    >
                       <svg className={`w-6 h-6 ${isSyncing ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                       {isSyncing ? 'Sincronizando Sistema...' : 'Sincronizar Permissões de Usuário'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* MODAL PARA NOVO CADASTRO */}
      {isAdding && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
           <div className="bg-white w-full max-w-xl rounded-[4rem] p-12 shadow-2xl animate-slide-up relative">
              <button onClick={() => setIsAdding(false)} className="absolute top-10 right-10 text-slate-300 hover:text-black transition-all">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>

              <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic mb-10">Novo Operador</h3>

              <div className="space-y-6">
                 <AdminInput label="E-mail Master / Corporativo" value={newUser.email} onChange={v => setNewUser({...newUser, email: v})} placeholder="exemplo@tagway.pro" />
                 <AdminInput label="Nome do Responsável" value={newUser.nome_completo} onChange={v => setNewUser({...newUser, nome_completo: v})} placeholder="Nome Completo" />
                 <AdminInput label="Unidade / Empresa" value={newUser.empresa_nome} onChange={v => setNewUser({...newUser, empresa_nome: v})} placeholder="Sede de Atuação" />
                 <AdminInput label="Cargo Inicial" value={newUser.role} onChange={v => setNewUser({...newUser, role: v})} />
                 <AdminInput label="User ID (Opcional)" value={newUser.user_id} onChange={v => setNewUser({...newUser, user_id: v})} placeholder="Auto-gerado se vazio" />

                 <div className="pt-6">
                    <button onClick={handleCreateUser} className="w-full bg-black text-white py-5 rounded-2xl font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-600 transition-all active:scale-95">
                      Confirmar Inclusão na Rede
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: string }) => {
  const styles: any = {
    ativo: 'bg-emerald-100 text-emerald-600',
    bloqueado: 'bg-rose-100 text-rose-600',
    manutencao: 'bg-amber-100 text-amber-600'
  };
  const labels: any = {
    ativo: 'Operando',
    bloqueado: 'Bloqueado',
    manutencao: 'Manutenção'
  };
  return (
    <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${styles[status] || styles.ativo}`}>
      {labels[status] || labels.ativo}
    </span>
  );
};

const StatusButton = ({ label, active, onClick, color }: any) => (
  <button 
    onClick={onClick}
    className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest border-2 transition-all ${active ? `${color} text-white border-transparent shadow-xl scale-105` : 'bg-slate-50 border-slate-100 text-slate-400 hover:border-slate-200 hover:text-slate-600'}`}
  >
    {label}
  </button>
);

const StatBox = ({ label, value, color }: any) => (
  <div className="bg-white/5 p-6 rounded-[2rem] border border-white/10 min-w-[130px] text-center shadow-inner">
    <span className="text-[9px] font-black text-white/30 uppercase tracking-[0.2em] block mb-2">{label}</span>
    <span className={`text-3xl font-black font-mono tracking-tighter ${color || 'text-white'}`}>{value}</span>
  </div>
);

const AdminInput = ({ label, value, onChange, placeholder }: any) => (
  <div className="space-y-2">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type="text" 
      value={value}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-black transition-all"
    />
  </div>
);

export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado' | 'manutencao';
  telefone?: string;
  is_admin: boolean;
  role?: string;
  access_level?: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [errorStatus, setErrorStatus] = useState<string | null>(null);

  // Form para novo usuário
  const [newUser, setNewUser] = useState({
    email: '',
    nome_completo: '',
    empresa_nome: '',
    role: 'Operador Padrão',
    user_id: '' 
  });

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorStatus(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('nome_completo', { ascending: true });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);

      if (data && data.length === 0) {
        setErrorStatus("Vazio: Verifique se as Políticas RLS no Supabase permitem que seu usuário veja outros registros.");
      }
    } catch (err: any) {
      console.error("Erro ao listar:", err.message);
      setErrorStatus(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateUser = async () => {
    if (!newUser.email || !newUser.nome_completo) return alert("E-mail e Nome são obrigatórios.");

    try {
      const generatedId = newUser.user_id.trim() !== "" 
        ? newUser.user_id.trim() 
        : crypto.randomUUID();

      const payload: any = {
        user_id: generatedId,
        email: newUser.email.trim().toLowerCase(),
        nome_completo: newUser.nome_completo.trim(),
        empresa_nome: newUser.empresa_nome.trim(),
        role: newUser.role,
        status: 'ativo',
        is_admin: false
      };

      const { error } = await supabase.from('user_configs').insert([payload]);
      if (error) throw error;

      alert("🚀 Operador registrado com sucesso!");
      setIsAdding(false);
      setNewUser({ email: '', nome_completo: '', empresa_nome: '', role: 'Operador Padrão', user_id: '' });
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao criar: " + err.message);
    }
  };

  const handleUpdateAndSync = async (user: UserProfile) => {
    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          telefone: user.telefone,
          role: user.role,
          access_level: user.access_level
        })
        .eq('user_id', user.user_id);

      if (error) throw error;

      alert(`✅ Sincronização Concluída: Perfil de ${user.nome_completo} atualizado com novo cargo e acesso.`);
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert("Erro ao sincronizar rede: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleDeleteUser = async (userId: string) => {
    if (!confirm("🚨 AÇÃO CRÍTICA: Remover este operador permanentemente?")) return;
    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
      setSelectedUser(null);
    } catch (err: any) {
      alert("Erro ao deletar: " + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.role && u.role.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [users, searchTerm]);

  const stats = useMemo(() => ({
    total: users.length,
    ativos: users.filter(u => u.status === 'ativo').length,
    manutencao: users.filter(u => u.status === 'manutencao').length,
    bloqueados: users.filter(u => u.status === 'bloqueado').length
  }), [users]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      {/* HEADER MASTER CENTRAL */}
      <header className="bg-black p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-center gap-10">
          <div className="space-y-4">
            <div className="flex items-center gap-6">
               <div className="bg-indigo-500/20 p-4 rounded-3xl border border-indigo-500/20 shadow-inner">
                  <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"/></svg>
               </div>
               <div>
                 <h2 className="text-5xl font-black tracking-tighter uppercase italic leading-none">Comando de Rede</h2>
                 <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Tagway Intelligence Control Unit</p>
               </div>
            </div>
          </div>

          <div className="flex gap-6">
            <StatBox label="Operadores" value={stats.total} />
            <StatBox label="Ativos" value={stats.ativos} color="text-emerald-400" />
            <StatBox label="Manutenção" value={stats.manutencao} color="text-amber-400" />
            <StatBox label="Restritos" value={stats.bloqueados} color="text-rose-400" />
          </div>
        </div>
      </header>

      {/* CONTROLES E BUSCA */}
      <div className="flex flex-col md:flex-row gap-6">
        <div className="flex-1 relative">
          <input 
            type="text" 
            placeholder="Filtrar por nome, cargo, e-mail..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[2.5rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all"
          />
          <svg className="w-6 h-6 absolute left-7 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-black text-white px-12 py-5 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-3"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4"/></svg>
          Registrar Operador
        </button>
      </div>

      {/* TABELA DE USUÁRIOS */}
      <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] font-black tracking-widest italic">
                <th className="px-10 py-6">Operador / Cargo</th>
                <th className="px-10 py-6">Empresa</th>
                <th className="px-10 py-6">Nível Acesso</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-right">Controle</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={5} className="p-32 text-center animate-pulse text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Escaneando Infraestrutura...</td></tr>
              ) : filteredUsers.length === 0 ? (
                <tr>
                   <td colSpan={5} className="p-32 text-center">
                      <div className="space-y-4">
                         <div className="text-5xl opacity-20">📡</div>
                         <p className="text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">{errorStatus || 'Nenhum operador detectado'}</p>
                         <button onClick={fetchUsers} className="text-[10px] font-black text-indigo-500 underline uppercase tracking-widest">Forçar Re-escaneamento</button>
                      </div>
                   </td>
                </tr>
              ) : filteredUsers.map(user => (
                <tr 
                  key={user.user_id} 
                  className="hover:bg-slate-50 transition-all group cursor-pointer" 
                  onClick={() => setSelectedUser(user)}
                >
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-5">
                       <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-black group-hover:bg-black group-hover:text-white transition-all">
                          {user.nome_completo?.charAt(0) || '?'}
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-900 tracking-tight leading-none group-hover:text-indigo-600 transition-colors">{user.nome_completo}</p>
                          <p className="text-[10px] font-black text-slate-400 uppercase mt-2 italic">{user.role || 'Sem Cargo Definido'}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-[10px] font-black uppercase text-slate-400">{user.empresa_nome || 'Unidade Independente'}</span>
                  </td>
                  <td className="px-10 py-7">
                    <span className="bg-slate-50 border border-slate-100 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase text-slate-600 tracking-widest">{user.access_level || 'Acesso Padrão'}</span>
                  </td>
                  <td className="px-10 py-7">
                     <StatusBadge status={user.status} />
                  </td>
                  <td className="px-10 py-7 text-right">
                     <div className="flex items-center justify-end gap-3">
                        <span className="text-[9px] font-black uppercase tracking-widest text-slate-200 group-hover:text-black transition-all">Editar Perfil</span>
                        <svg className="w-4 h-4 text-slate-200 group-hover:text-black transition-all" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
                     </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL DE PERFIL: EDIÇÃO, STATUS E SINCRONIZAÇÃO */}
      {selectedUser && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
           <div className="bg-white w-full max-w-3xl rounded-[4rem] shadow-2xl overflow-hidden animate-slide-up">
              <header className="bg-black p-12 text-white flex justify-between items-center relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-amber-500 to-rose-500"></div>
                 <div>
                    <h3 className="text-3xl font-black text-white tracking-tighter uppercase italic leading-none">Terminal de Gestão</h3>
                    <p className="text-white/40 text-[9px] font-black uppercase tracking-widest mt-3">Operador ID: {selectedUser.user_id}</p>
                 </div>
                 <button onClick={() => setSelectedUser(null)} className="text-white/20 hover:text-white transition-all bg-white/5 p-3 rounded-2xl">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
              </header>

              <div className="p-12 grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <AdminInput label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="Empresa de Atuação" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />
                    <AdminInput label="E-mail de Rede" value={selectedUser.email} onChange={v => setSelectedUser({...selectedUser, email: v})} />
                 </div>

                 <div className="space-y-6">
                    <AdminInput label="Cargo (Role)" value={selectedUser.role || ''} onChange={v => setSelectedUser({...selectedUser, role: v})} placeholder="Ex: Diretor Financeiro" />
                    <AdminInput label="Nível de Acesso" value={selectedUser.access_level || ''} onChange={v => setSelectedUser({...selectedUser, access_level: v})} placeholder="Ex: Master, Nível 3..." />

                    <div className="space-y-3">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Estado Operacional</label>
                       <div className="grid grid-cols-3 gap-3">
                          <StatusButton 
                             label="Ativar" 
                             active={selectedUser.status === 'ativo'} 
                             onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})} 
                             color="bg-emerald-600" 
                          />
                          <StatusButton 
                             label="Manutenção" 
                             active={selectedUser.status === 'manutencao'} 
                             onClick={() => setSelectedUser({...selectedUser, status: 'manutencao'})} 
                             color="bg-amber-600" 
                          />
                          <StatusButton 
                             label="Bloquear" 
                             active={selectedUser.status === 'bloqueado'} 
                             onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})} 
                             color="bg-rose-600" 
                          />
                       </div>
                    </div>
                 </div>

                 <div className="lg:col-span-2 pt-10 flex gap-4 border-t border-slate-100">
                    <button 
                      onClick={() => handleDeleteUser(selectedUser.user_id)}
                      className="w-16 h-16 bg-rose-50 text-rose-300 hover:text-rose-600 rounded-3xl flex items-center justify-center transition-all border border-rose-100 active:scale-95"
                    >
                       <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                    </button>
                    <button 
                       onClick={() => handleUpdateAndSync(selectedUser)}
                       disabled={isSyncing}
                       className="flex-1 bg-black text-white rounded-3xl font-black uppercase text-[12px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50"
                    >
                       <svg className={`w-6 h-6 ${isSyncing ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                       {isSyncing ? 'Sincronizando Rede...' : 'Sincronizar Role e Acesso'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* MODAL ADICIONAR OPERADOR */}
      {isAdding && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
           <div className="bg-white w-full max-w-xl rounded-[4rem] p-12 shadow-2xl animate-slide-up relative">
              <button onClick={() => setIsAdding(false)} className="absolute top-10 right-10 text-slate-300 hover:text-black transition-all">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
              </button>

              <h3 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic mb-10">Novo Operador</h3>

              <div className="space-y-6">
                 <AdminInput label="E-mail Master / Corporativo" value={newUser.email} onChange={v => setNewUser({...newUser, email: v})} placeholder="exemplo@tagway.pro" />
                 <AdminInput label="Nome Completo" value={newUser.nome_completo} onChange={v => setNewUser({...newUser, nome_completo: v})} placeholder="Nome Responsável" />
                 <AdminInput label="Unidade / Empresa" value={newUser.empresa_nome} onChange={v => setNewUser({...newUser, empresa_nome: v})} placeholder="Sede de Atuação" />
                 <AdminInput label="Cargo Inicial" value={newUser.role} onChange={v => setNewUser({...newUser, role: v})} />
                 <AdminInput label="User ID (Opcional)" value={newUser.user_id} onChange={v => setNewUser({...newUser, user_id: v})} placeholder="UUID Manual ou deixe vazio" />

                 <div className="pt-6">
                    <button onClick={handleCreateUser} className="w-full bg-black text-white py-5 rounded-2xl font-black uppercase text-[11px] tracking-widest shadow-2xl hover:bg-indigo-600 transition-all active:scale-95">
                      Confirmar Inclusão na Rede
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: string }) => {
  const styles: any = {
    ativo: 'bg-emerald-100 text-emerald-600',
    bloqueado: 'bg-rose-100 text-rose-600',
    manutencao: 'bg-amber-100 text-amber-600 border border-amber-200'
