const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorMsg(null);
    try {
      // IMPORTANTE: Buscamos apenas em 'user_configs', NUNCA na tabela 'users' do auth
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('nome_completo', { ascending: true });

      if (error) {
        console.error("Erro Supabase:", error);
        setErrorMsg(error.message);
        return;
      }

      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMsg(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateAndSync = async (user: UserProfile) => {
    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          role: user.role,
          access_level: user.access_level,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;

      alert(`✅ Sincronização Realizada: ${user.nome_completo} atualizado.`);
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert("Erro na sincronização: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      u.email.toLowerCase().includes(searchTerm.toLowerCase()) || 
      u.nome_completo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.empresa_nome?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.role && u.role.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [users, searchTerm]);

  if (errorMsg && errorMsg.includes('permission denied')) {
    return (
      <div className="max-w-4xl mx-auto p-12 bg-white rounded-[3rem] border-2 border-dashed border-rose-200 text-center space-y-6 animate-slide-up">
        <div className="text-6xl">🔒</div>
        <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic">Acesso Negado à Rede</h2>
        <p className="text-slate-500 text-sm max-w-md mx-auto leading-relaxed">
          O banco de dados bloqueou a listagem de usuários. Isso acontece porque a <b>Política RLS</b> não reconhece seu e-mail como Master.
        </p>
        <div className="bg-slate-900 p-6 rounded-2xl text-left">
           <p className="text-emerald-400 text-[9px] font-black uppercase tracking-widest mb-3">Execute este SQL no Supabase para corrigir:</p>
           <code className="text-white text-[10px] font-mono break-all opacity-80 block">
             DROP POLICY IF EXISTS "Master Access" ON user_configs;<br/>
             CREATE POLICY "Master Access" ON user_configs FOR ALL USING (true);
           </code>
        </div>
        <button onClick={fetchUsers} className="bg-black text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-2xl">
          Tentar Re-conectar
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      <header className="bg-black p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-center">
          <div className="flex items-center gap-6">
             <div className="bg-indigo-500/20 p-4 rounded-3xl border border-indigo-500/20">
                <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
             </div>
             <div>
               <h2 className="text-5xl font-black tracking-tighter uppercase italic leading-none">Controle de Rede</h2>
               <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Tagway Global Management</p>
             </div>
          </div>
          <div className="flex gap-4 mt-8 lg:mt-0">
             <div className="bg-white/5 px-6 py-4 rounded-3xl border border-white/10 text-center">
                <span className="text-[8px] font-black text-white/30 uppercase block mb-1">Total Operadores</span>
                <span className="text-2xl font-black font-mono">{users.length}</span>
             </div>
          </div>
        </div>
      </header>

      <div className="relative">
        <input 
          type="text" 
          placeholder="Pesquisar por nome, empresa ou cargo..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white border-2 border-slate-100 rounded-[2.5rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all"
        />
        <svg className="w-6 h-6 absolute left-7 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
      </div>

      <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] font-black tracking-widest italic">
                <th className="px-10 py-6">Operador</th>
                <th className="px-10 py-6">Cargo</th>
                <th className="px-10 py-6">Empresa</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-right">Ação</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={5} className="p-32 text-center animate-pulse text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Lendo Servidores...</td></tr>
              ) : filteredUsers.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Nenhum registro encontrado</td></tr>
              ) : filteredUsers.map(user => (
                <tr 
                  key={user.user_id} 
                  className="hover:bg-slate-50 transition-all group cursor-pointer" 
                  onClick={() => setSelectedUser(user)}
                >
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-4">
                       <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-black group-hover:bg-black group-hover:text-white transition-all">
                          {user.nome_completo?.charAt(0)}
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-900 tracking-tight">{user.nome_completo}</p>
                          <p className="text-[10px] text-slate-400 italic">{user.email}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-[10px] font-black uppercase text-indigo-500 tracking-widest">{user.role || 'Operador'}</span>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-[10px] font-black uppercase text-slate-400 italic">{user.empresa_nome || 'Tagway'}</span>
                  </td>
                  <td className="px-10 py-7">
                     <StatusBadge status={user.status} />
                  </td>
                  <td className="px-10 py-7 text-right">
                     <svg className="w-5 h-5 text-slate-200 group-hover:text-black ml-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL DE GESTÃO DO OPERADOR */}
      {selectedUser && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/90 backdrop-blur-md">
           <div className="bg-white w-full max-w-3xl rounded-[4rem] shadow-2xl overflow-hidden animate-slide-up">
              <header className="bg-black p-12 text-white flex justify-between items-center relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-emerald-500 to-rose-500"></div>
                 <div>
                    <h3 className="text-3xl font-black uppercase italic leading-none">Perfil do Operador</h3>
                    <p className="text-white/40 text-[9px] font-black uppercase tracking-widest mt-3">ID Global: {selectedUser.user_id}</p>
                 </div>
                 <button onClick={() => setSelectedUser(null)} className="text-white/20 hover:text-white transition-all bg-white/5 p-3 rounded-2xl">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
              </header>

              <div className="p-12 grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <AdminInput label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="Empresa" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />
                    <AdminInput label="Cargo Operacional" value={selectedUser.role || ''} onChange={v => setSelectedUser({...selectedUser, role: v})} placeholder="Ex: Diretor, Vendedor..." />
                 </div>

                 <div className="space-y-6">
                    <AdminInput label="Nível de Acesso" value={selectedUser.access_level || ''} onChange={v => setSelectedUser({...selectedUser, access_level: v})} placeholder="Ex: Master, VIP, Nível 1" />
                    <AdminInput label="Telefone" value={selectedUser.telefone || ''} onChange={v => setSelectedUser({...selectedUser, telefone: v})} />

                    <div className="space-y-3">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Estado do Terminal</label>
                       <div className="grid grid-cols-3 gap-3">
                          <StatusButton label="Ativo" active={selectedUser.status === 'ativo'} onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})} color="bg-emerald-600" />
                          <StatusButton label="Manutenção" active={selectedUser.status === 'manutencao'} onClick={() => setSelectedUser({...selectedUser, status: 'manutencao'})} color="bg-amber-600" />
                          <StatusButton label="Bloqueado" active={selectedUser.status === 'bloqueado'} onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})} color="bg-rose-600" />
                       </div>
                    </div>
                 </div>

                 <div className="lg:col-span-2 pt-10 border-t border-slate-100">
                    <button 
                       onClick={() => handleUpdateAndSync(selectedUser)}
                       disabled={isSyncing}
                       className="w-full bg-black text-white py-6 rounded-3xl font-black uppercase text-[12px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50"
                    >
                       {isSyncing ? 'Sincronizando Sistema...' : 'Sincronizar Permissões'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: string }) => {
  const styles: any = { ativo: 'bg-emerald-100 text-emerald-600', bloqueado: 'bg-rose-100 text-rose-600', manutencao: 'bg-amber-100 text-amber-600' };
  const labels: any = { ativo: 'Conectado', bloqueado: 'Bloqueado', manutencao: 'Manutenção' };
  return (
    <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${styles[status] || styles.ativo}`}>
      {labels[status] || labels.ativo}
    </span>
  );
};

const StatusButton = ({ label, active, onClick, color }: any) => (
  <button onClick={onClick} className={`py-4 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 transition-all ${active ? `${color} text-white border-transparent shadow-xl` : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-slate-100'}`}>
    {label}
  </button>
);

const AdminInput = ({ label, value, onChange, placeholder }: any) => (
  <div className="space-y-2">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type="text" 
      value={value || ''}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-black transition-all"
    />
  </div>
);

export default AdminView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado' | 'manutencao';
  telefone?: string;
  is_admin: boolean;
  role?: string;
  access_level?: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [rawError, setRawError] = useState<any>(null);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorMessage(null);
    setRawError(null);
    try {
      // Nota: Tentamos buscar da tabela de metadados pública 'user_configs'
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('nome_completo', { ascending: true });

      if (error) {
        console.error("Erro Supabase:", error);
        setRawError(error);
        setErrorMessage(error.message || "Erro desconhecido ao acessar user_configs");
        return;
      }

      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      console.error("Exceção:", err);
      setErrorMessage(err.message || "Erro crítico de conexão");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateAndSync = async (user: UserProfile) => {
    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          role: user.role,
          access_level: user.access_level,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;

      alert(`✅ Sincronização Finalizada: ${user.nome_completo} agora é "${user.role || 'Operador'}".`);
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      alert("Erro na sincronização de rede: " + (err.message || JSON.stringify(err)));
    } finally {
      setIsSyncing(false);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
      (u.nome_completo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.empresa_nome || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.role || '').toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  // Se houver erro de permissão ou erro não identificado (que gerava o [object Object])
  if (errorMessage) {
    return (
      <div className="max-w-4xl mx-auto p-12 bg-white rounded-[4rem] border-2 border-slate-100 shadow-2xl animate-slide-up text-center space-y-8">
        <div className="w-24 h-24 bg-rose-100 rounded-[2rem] flex items-center justify-center text-rose-600 mx-auto">
          <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
        </div>

        <div className="space-y-3">
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">Diagnóstico Master</h2>
          <p className="text-rose-600 font-bold uppercase text-[10px] tracking-widest bg-rose-50 px-4 py-2 rounded-xl inline-block">
            Status: {errorMessage}
          </p>
        </div>

        <div className="bg-slate-900 p-8 rounded-[2.5rem] text-left relative group">
           <p className="text-emerald-400 text-[9px] font-black uppercase tracking-[0.3em] mb-4">Script de Reparo SQL (Execute no Supabase):</p>
           <div className="bg-black/50 p-6 rounded-2xl font-mono text-white/70 text-[10px] leading-relaxed break-all select-all cursor-copy">
             -- 1. Libera segurança da tabela<br/>
             ALTER TABLE user_configs ENABLE ROW LEVEL SECURITY;<br/><br/>
             -- 2. Remove bloqueios antigos<br/>
             DROP POLICY IF EXISTS "Master Full Access" ON user_configs;<br/><br/>
             -- 3. Cria regra definitiva para operadores autenticados<br/>
             CREATE POLICY "Master Full Access" ON user_configs<br/>
             FOR ALL<br/>
             TO authenticated<br/>
             USING (true);
           </div>
           <p className="mt-4 text-white/30 text-[8px] font-bold uppercase italic tracking-widest text-center">Atenção: A regra acima permite que qualquer usuário logado veja os demais. Use para diagnosticar.</p>
        </div>

        <div className="flex justify-center gap-4">
          <button onClick={() => window.location.reload()} className="bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest active:scale-95">Recarregar App</button>
          <button onClick={fetchUsers} className="bg-black text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95">Testar Conexão</button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      <header className="bg-black p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-center gap-10">
          <div className="flex items-center gap-6">
             <div className="bg-indigo-500/20 p-4 rounded-3xl border border-indigo-500/20">
                <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
             </div>
             <div>
               <h2 className="text-5xl font-black tracking-tighter uppercase italic leading-none">Controle Master</h2>
               <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Gestão de Operadores e Terminais</p>
             </div>
          </div>
          <div className="bg-white/5 px-10 py-6 rounded-[2.5rem] border border-white/10 text-center shadow-inner">
             <span className="text-[8px] font-black text-white/20 uppercase block mb-1">Rede Ativa</span>
             <span className="text-3xl font-black font-mono text-emerald-400">{users.length}</span>
          </div>
        </div>
      </header>

      <div className="relative">
        <input 
          type="text" 
          placeholder="Pesquisar por nome, empresa ou cargo operacional..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white border-2 border-slate-100 rounded-[2.5rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all"
        />
        <svg className="w-6 h-6 absolute left-7 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
      </div>

      <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] font-black tracking-widest italic">
                <th className="px-10 py-6">Operador</th>
                <th className="px-10 py-6">Cargo / Acesso</th>
                <th className="px-10 py-6">Empresa</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-right">Ação</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={5} className="p-32 text-center animate-pulse text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Sincronizando Banco de Dados...</td></tr>
              ) : filteredUsers.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Nenhum registro na rede</td></tr>
              ) : filteredUsers.map(user => (
                <tr 
                  key={user.user_id} 
                  className="hover:bg-slate-50 transition-all group cursor-pointer" 
                  onClick={() => setSelectedUser(user)}
                >
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-5">
                       <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-black group-hover:bg-black group-hover:text-white transition-all text-xl">
                          {user.nome_completo?.charAt(0) || '?'}
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-900 tracking-tight leading-none">{user.nome_completo || 'N/A'}</p>
                          <p className="text-[10px] font-bold text-slate-400 mt-2">{user.email}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <div className="space-y-1">
                      <span className="text-[10px] font-black uppercase text-indigo-500 tracking-widest block">{user.role || 'Operador'}</span>
                      <span className="text-[8px] font-black uppercase text-slate-300 tracking-widest">{user.access_level || 'Padrão'}</span>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-[10px] font-black uppercase text-slate-400 italic">{user.empresa_nome || 'Tagway Force'}</span>
                  </td>
