import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado' | 'manutencao';
  telefone?: string;
  is_admin: boolean;
  role?: string;
  access_level?: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [errorCode, setErrorCode] = useState<string | null>(null);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorMessage(null);
    setErrorCode(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('nome_completo', { ascending: true });

      if (error) {
        console.error("Erro Supabase Detalhado:", error);
        // Garante que a mensagem seja uma string, não um objeto
        const msg = typeof error === 'object' ? (error.message || JSON.stringify(error)) : String(error);
        setErrorMessage(msg);
        setErrorCode(error.code || 'UNKNOWN');
        return;
      }

      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      console.error("Exceção de Sistema:", err);
      setErrorMessage(err.message || "Falha crítica de conexão");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateAndSync = async (user: UserProfile) => {
    setIsSyncing(true);
    try {
      const { error } = await supabase
        .from('user_configs')
        .update({
          nome_completo: user.nome_completo,
          empresa_nome: user.empresa_nome,
          status: user.status,
          role: user.role,
          access_level: user.access_level,
          telefone: user.telefone
        })
        .eq('user_id', user.user_id);

      if (error) throw error;

      alert(`✅ Sincronização Finalizada: ${user.nome_completo} atualizado.`);
      setSelectedUser(null);
      fetchUsers();
    } catch (err: any) {
      const msg = typeof err === 'object' ? (err.message || JSON.stringify(err)) : String(err);
      alert("Erro na sincronização: " + msg);
    } finally {
      setIsSyncing(false);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
      (u.nome_completo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.empresa_nome || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.role || '').toLowerCase().includes(searchTerm.toLowerCase())
