             &nbsp;&nbsp;nome_completo text, empresa_nome text, email text,<br/>
             &nbsp;&nbsp;status text DEFAULT 'ativo', role text, access_level text,<br/>
             &nbsp;&nbsp;telefone text, is_admin boolean DEFAULT false<br/>
             );<br/><br/>
             -- 2. Limpa e reinicia segurança RLS<br/>
             ALTER TABLE user_configs ENABLE ROW LEVEL SECURITY;<br/>
             DROP POLICY IF EXISTS "Master Access" ON user_configs;<br/>
             CREATE POLICY "Master Access" ON user_configs FOR ALL TO authenticated USING (true);<br/><br/>
             -- 3. Garante permissão de leitura global<br/>
             GRANT ALL ON public.user_configs TO authenticated;
           </div>
        </div>

        <div className="flex justify-center gap-4 pt-4">
          <button onClick={() => window.location.reload()} className="bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest active:scale-95 transition-all">Recarregar</button>
          <button onClick={fetchUsers} className="bg-black text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Testar Agora</button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      <header className="bg-black p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col lg:flex-row justify-between items-center gap-10">
