                      <AdminInput 
                        label="UUID do Usuário (Supabase Auth ID)" 
                        value={selectedUser.user_id} 
                        onChange={v => setSelectedUser({...selectedUser, user_id: v})} 
                        placeholder="Cole o ID gerado no painel Auth"
                      />
                    )}
                    <AdminInput label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="E-mail de Login" value={selectedUser.email} onChange={v => setSelectedUser({...selectedUser, email: v})} type="email" />
                    <AdminInput label="Empresa Responsável" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />
                 </div>

                 <div className="space-y-6">
                    <AdminInput label="Cargo Operacional" value={selectedUser.role || ''} onChange={v => setSelectedUser({...selectedUser, role: v})} placeholder="Ex: Diretor, Gestor" />
                    <AdminInput label="Nível de Privilégios" value={selectedUser.access_level || ''} onChange={v => setSelectedUser({...selectedUser, access_level: v})} placeholder="Ex: Master, VIP, Restrito" />
                    <AdminInput label="WhatsApp / Fone" value={selectedUser.telefone || ''} onChange={v => setSelectedUser({...selectedUser, telefone: v})} />

                    <div className="space-y-3">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Estado do Acesso</label>
                       <div className="grid grid-cols-3 gap-3">
                          <StatusButton label="Ativo" active={selectedUser.status === 'ativo'} onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})} color="bg-emerald-600" />
                          <StatusButton label="Manutenção" active={selectedUser.status === 'manutencao'} onClick={() => setSelectedUser({...selectedUser, status: 'manutencao'})} color="bg-amber-600" />
                          <StatusButton label="Bloqueado" active={selectedUser.status === 'bloqueado'} onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})} color="bg-rose-600" />
                       </div>
                    </div>
                 </div>

                 <div className="lg:col-span-2 pt-10 border-t border-slate-100 flex gap-4">
                    <button 
                       onClick={handleSave}
                       disabled={isSyncing}
                       className="flex-1 bg-black text-white py-6 rounded-3xl font-black uppercase text-[12px] tracking-[0.2em] shadow-2xl hover:bg-emerald-600 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50"
                    >
                       {isSyncing ? 'Sincronizando Rede...' : isNewUser ? 'Cadastrar Operador na Nuvem' : 'Sincronizar Atualizações Master'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: { status: string }) => {
  const styles: any = { ativo: 'bg-emerald-100 text-emerald-600', bloqueado: 'bg-rose-100 text-rose-600', manutencao: 'bg-amber-100 text-amber-600 border border-amber-200' };
  const labels: any = { ativo: 'Conectado', bloqueado: 'Bloqueado', manutencao: 'Manutenção' };
  return (
    <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${styles[status] || styles.ativo}`}>
      {labels[status] || labels.ativo}
    </span>
  );
};

const StatusButton = ({ label, active, onClick, color }: any) => (
  <button onClick={onClick} className={`py-4 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 transition-all active:scale-95 ${active ? `${color} text-white border-transparent shadow-xl` : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-slate-100'}`}>
    {label}
  </button>
);

const AdminInput = ({ label, value, onChange, placeholder, type = 'text' }: any) => (
  <div className="space-y-2">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type={type} 
      value={value || ''}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-black transition-all"
    />
  </div>
);

export default AdminView;

