import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado' | 'manutencao';
  telefone?: string;
  is_admin: boolean;
  role?: string;
  access_level?: string;
  senha_acesso?: string; // Novo campo para senha visível pelo admin
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [errorCode, setErrorCode] = useState<string | null>(null);
  const [isNewUser, setIsNewUser] = useState(false);

  useEffect(() => {
    fetchUsers();
  }, []);

  const stats = useMemo(() => {
    const total = users.length;
    const ativos = users.filter(u => u.status === 'ativo').length;
    const bloqueados = users.filter(u => u.status === 'bloqueado').length;
    const manutencao = users.filter(u => u.status === 'manutencao').length;
    return { total, ativos, bloqueados, manutencao };
  }, [users]);

  const parseError = (error: any): string => {
    if (!error) return "Erro desconhecido";
    if (typeof error === 'string') return error;
    if (error.message) return error.message;
    try {
      return JSON.stringify(error);
    } catch {
      return "Erro estrutural de rede";
    }
  };

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorMessage(null);
    setErrorCode(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .order('nome_completo', { ascending: true });

      if (error) {
        console.error("Erro Supabase Detalhado:", error);
        setErrorMessage(parseError(error));
        setErrorCode(error.code || 'PGRST');
        return;
      }

      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(parseError(err));
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenAdd = () => {
    setIsNewUser(true);
    setSelectedUser({
      user_id: '',
      nome_completo: '',
      email: '',
      empresa_nome: '',
      status: 'ativo',
      is_admin: false,
      role: 'Operador',
      access_level: 'Nível 1',
      senha_acesso: ''
    });
  };

  const handleSave = async () => {
    if (!selectedUser) return;
    if (!selectedUser.user_id || !selectedUser.email) {
      alert("ID do Usuário e E-mail são obrigatórios.");
      return;
    }

    setIsSyncing(true);
    try {
      let error;
      if (isNewUser) {
        const { error: insError } = await supabase
          .from('user_configs')
          .insert([selectedUser]);
        error = insError;
      } else {
        const { error: updError } = await supabase
          .from('user_configs')
          .update({
            nome_completo: selectedUser.nome_completo,
            empresa_nome: selectedUser.empresa_nome,
            status: selectedUser.status,
            role: selectedUser.role,
            access_level: selectedUser.access_level,
            telefone: selectedUser.telefone,
            email: selectedUser.email,
            senha_acesso: selectedUser.senha_acesso
          })
          .eq('user_id', selectedUser.user_id);
        error = updError;
      }

      if (error) throw error;

      alert(`✅ Operação Finalizada: ${selectedUser.nome_completo || 'Registro'} sincronizado.`);
      setSelectedUser(null);
      setIsNewUser(false);
      fetchUsers();
    } catch (err: any) {
      alert("Falha na Sincronização: " + parseError(err));
    } finally {
      setIsSyncing(false);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
      (u.nome_completo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.empresa_nome || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.role || '').toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  if (errorMessage) {
    return (
      <div className="max-w-4xl mx-auto p-12 bg-white rounded-[4rem] border-2 border-slate-100 shadow-2xl animate-slide-up text-center space-y-8">
