          <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
        </div>
        <div className="space-y-3">
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">Falha de Rede Master</h2>
          <p className="text-rose-600 font-bold uppercase text-[10px] tracking-widest bg-rose-50 px-4 py-2 rounded-xl inline-block max-w-md break-words">
            {errorMessage}
          </p>

          <div className="bg-slate-900 p-8 rounded-[2.5rem] text-left mt-8">
             <p className="text-emerald-400 text-[9px] font-black uppercase tracking-[0.3em] mb-4">Script de Reparo (Senha Incluída):</p>
             <div className="bg-black/50 p-6 rounded-2xl font-mono text-white/70 text-[10px] leading-relaxed break-all select-all cursor-copy overflow-y-auto max-h-48 custom-scrollbar">
               ALTER TABLE public.user_configs ADD COLUMN IF NOT EXISTS senha_acesso text;<br/>
               -- Execute para atualizar a estrutura de dados master.
             </div>
          </div>
        </div>
        <button onClick={() => window.location.reload()} className="bg-black text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Recarregar Sistema</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      <header className="bg-black p-10 lg:p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col xl:flex-row justify-between items-center gap-10">
          <div className="flex items-center gap-6">
             <div className="bg-indigo-500/20 p-4 rounded-3xl border border-indigo-500/20">
                <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
             </div>
             <div>
               <h2 className="text-4xl lg:text-5xl font-black tracking-tighter uppercase italic leading-none">Controle Master</h2>
               <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Monitoramento Global de Operadores</p>
             </div>
          </div>

          <div className="flex flex-wrap justify-center gap-4">
            <StatBox label="Ativos" value={stats.ativos} color="text-emerald-400" />
            <StatBox label="Bloqueados" value={stats.bloqueados} color="text-rose-500" />
            <StatBox label="Manutenção" value={stats.manutencao} color="text-amber-400" />
            <div className="bg-white/10 px-8 py-5 rounded-[2rem] border border-white/20 text-center shadow-2xl backdrop-blur-md">
              <span className="text-[8px] font-black text-white/40 uppercase block mb-1 tracking-widest">Total Terminais</span>
              <span className="text-2xl lg:text-3xl font-black font-mono text-indigo-400">{stats.total}</span>
            </div>
          </div>

          <button 
            onClick={handleOpenAdd}
            className="bg-white text-black px-8 py-5 rounded-3xl font-black uppercase text-[11px] tracking-widest hover:bg-indigo-500 hover:text-white transition-all flex items-center gap-3 shadow-2xl active:scale-95 shrink-0"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
            Adicionar
          </button>
        </div>
      </header>

      <div className="relative">
        <input 
          type="text" 
          placeholder="Pesquisar operadores ativos, bloqueados ou em manutenção..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white border-2 border-slate-100 rounded-[2.5rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all"
        />
        <svg className="w-6 h-6 absolute left-7 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
      </div>

      <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] font-black tracking-widest italic">
                <th className="px-10 py-6">Operador</th>
