                <th className="px-10 py-6">Empresa</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-right">Ação</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={5} className="p-32 text-center animate-pulse text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Sincronizando Rede Global...</td></tr>
              ) : filteredUsers.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Nenhum operador registrado</td></tr>
              ) : filteredUsers.map(user => (
                <tr 
                  key={user.user_id} 
                  className="hover:bg-slate-50 transition-all group cursor-pointer" 
                  onClick={() => { setIsNewUser(false); setSelectedUser(user); }}
                >
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-5">
                       <div className="w-14 h-14 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-black group-hover:bg-black group-hover:text-white transition-all text-xl">
                          {user.nome_completo?.charAt(0) || '?'}
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-900 tracking-tight leading-none">{user.nome_completo || 'Terminal Anon'}</p>
