                    <p className="text-white/40 text-[9px] font-black uppercase tracking-widest mt-3">Sincronização de Banco Master</p>
                 </div>
                 <button onClick={() => { setSelectedUser(null); setIsNewUser(false); }} className="text-white/20 hover:text-white transition-all bg-white/5 p-4 rounded-2xl">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
              </header>

              <div className="p-12 grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    {isNewUser && (
                      <AdminInput 
                        label="UUID do Usuário (ID no Supabase Auth)" 
                        value={selectedUser.user_id} 
                        onChange={v => setSelectedUser({...selectedUser, user_id: v})} 
                        placeholder="Ex: 550e8400-e29b-41d4-a716..."
                      />
                    )}
                    <AdminInput label="Nome Completo" value={selectedUser.nome_completo} onChange={v => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="E-mail de Acesso" value={selectedUser.email} onChange={v => setSelectedUser({...selectedUser, email: v})} type="email" />
                    <AdminInput label="Empresa Vinculada" value={selectedUser.empresa_nome} onChange={v => setSelectedUser({...selectedUser, empresa_nome: v})} />

                    <div className="pt-4 border-t border-slate-100">
                      <AdminInput 
                        label="Senha de Acesso" 
                        value={selectedUser.senha_acesso || ''} 
                        onChange={v => setSelectedUser({...selectedUser, senha_acesso: v})} 
                        placeholder="Defina a senha do operador"
                      />
                      <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest mt-2 ml-1 animate-pulse">
                        ⚠️ OBS: Esta senha será utilizada pelo operador para login inicial. Ele poderá alterá-la no perfil.
                      </p>
                    </div>
                 </div>

                 <div className="space-y-6">
                    <AdminInput label="Cargo Operacional" value={selectedUser.role || ''} onChange={v => setSelectedUser({...selectedUser, role: v})} placeholder="Ex: Diretor, Gestor" />
                    <AdminInput label="Nível de Privilégios" value={selectedUser.access_level || ''} onChange={v => setSelectedUser({...selectedUser, access_level: v})} placeholder="Ex: Nível 1, Master" />
                    <AdminInput label="Telefone / WhatsApp" value={selectedUser.telefone || ''} onChange={v => setSelectedUser({...selectedUser, telefone: v})} />

                    <div className="space-y-3">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Estado do Terminal</label>
                       <div className="grid grid-cols-3 gap-3">
                          <StatusButton label="Ativo" active={selectedUser.status === 'ativo'} onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})} color="bg-emerald-600" />
                          <StatusButton label="Manut." active={selectedUser.status === 'manutencao'} onClick={() => setSelectedUser({...selectedUser, status: 'manutencao'})} color="bg-amber-600" />
                          <StatusButton label="Block" active={selectedUser.status === 'bloqueado'} onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})} color="bg-rose-600" />
                       </div>
                    </div>
                 </div>

                 <div className="lg:col-span-2 pt-10 border-t border-slate-100 flex gap-4">
                    <button 
                       onClick={handleSave}
                       disabled={isSyncing}
                       className="flex-1 bg-black text-white py-6 rounded-3xl font-black uppercase text-[12px] tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50"
                    >
                       {isSyncing ? 'Sincronizando Rede Master...' : isNewUser ? 'Cadastrar Operador na Nuvem' : 'Sincronizar Alterações Master'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

