    empresa_nome: '',
    nome_completo: '',
    email: '',
    telefone: '',
    data_nascimento: '',
    regime_tributario: 'Real',
    uf_padrao_origem: 'SP',
    uf_padrao_destino: 'SP',
    margem_padrao: 10,
    modo_apresentacao: false,
    senha_acesso: ''
  });
