const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);
  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>([]);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>([]);
  const [isAutoSync, setIsAutoSync] = useState(false);
  const [isDbLocked, setIsDbLocked] = useState(false);

  // Lógica de Sincronização Proativa
  useEffect(() => {
    if (isAutoSync && faturamento > 0) {
      const totalFixedValue = fixedCosts.reduce((acc, curr) => acc + curr.valor, 0);
      const calculatedOverheadPerc = (totalFixedValue / faturamento) * 100;

      // Atualiza os inputs da calculadora com o valor real do painel Overhead
      if (Math.abs(inputs.custosFixos - calculatedOverheadPerc) > 0.001) {
        setInputs(prev => ({
          ...prev,
          custosFixos: Number(calculatedOverheadPerc.toFixed(2))
        }));
      }
    }
  }, [isAutoSync, fixedCosts, faturamento]);

  useEffect(() => {
    const init = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      setSession(currentSession);

      if (currentSession) {
        try {
          const { data, error } = await supabase.from('user_configs').select('*').eq('user_id', currentSession.user.id).maybeSingle();
          if (error) setIsDbLocked(true);
          if (data) setUserProfile(data);

          const { data: oh } = await supabase.from('overhead_configs').select('*').eq('user_id', currentSession.user.id).maybeSingle();

          if (oh) {
            setFaturamento(oh.faturamento || 100000);
            setFixedCosts(oh.fixed_costs || []);
            setVariableCosts(oh.variable_costs || []);
            setIsAutoSync(!!oh.is_auto_sync);
          } else {
            // Inicialização Padrão de Segurança (Garante que o Automático funcione mesmo sem dados prévios)
            const defaultFixed: CostItem[] = [];
            INITIAL_FIXED_LIST.forEach(group => {
              group.items.forEach(desc => {
                let val = 0;
                if (desc === 'Salários administrativos') val = 8000;
                if (desc === 'Pró-labore dos sócios') val = 4500;
                if (desc === 'Aluguel do imóvel') val = 2000;
                defaultFixed.push({ id: Math.random().toString(36).substr(2, 9), categoria: group.cat, descricao: desc, valor: val });
              });
            });
            setFixedCosts(defaultFixed);
            setFaturamento(100000);
          }
        } catch (e) { console.warn("Banco travado."); }
      }
      setIsInitialized(true);
    };
    init();
  }, []);

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  // Fix: defined isMaster to resolve the "Cannot find name 'isMaster'" error
  const isMaster = session?.user?.email === MASTER_EMAIL;

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    window.location.reload();
  };

  if (!isInitialized) return null;
  if (!session) return <Login onLoginSuccess={setSession} />;

  const menuItems = [
    { id: 'calculadora', label: 'Calculadora', icon: "M3 12h18M3 6h18M3 18h18" },
    { id: 'meus-produtos', label: 'Meus Itens', icon: "M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" },
    { id: 'resumo-fiscal', label: 'Análise', icon: "M9 17v-2m3 2v-4m3 2v-6m-8-2h8a2 2 0 012 2v9a2 2 0 01-2 2H7a2 2 0 01-2-2V5a2 2 0 012-2z" },
    { id: 'catalogo', label: 'NCM 2025', icon: "M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" },
    { id: 'overhead', label: 'Overhead', icon: "M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" },
    { id: 'jarvis', label: 'Jarvis AI', icon: "M13 10V3L4 14h7v7l9-11h-7z", isAi: true },
  ];

  const handleLoadSimulation = (sim: any) => {
    setInputs(sim.inputs);
    setActiveTab('calculadora');
  };

  return (
    <div className="flex h-screen bg-[#000000] overflow-hidden">
      {/* Desktop Sidebar */}
      <aside className={`hidden lg:flex flex-col bg-black border-r border-white/5 transition-all duration-500 relative z-30 ${isSidebarCollapsed ? 'w-24' : 'w-72'}`}>
        <div className="p-8 flex items-center justify-between overflow-hidden">
          {!isSidebarCollapsed ? <TagwayHorizontalLogo light className="h-6" /> : <div className="mx-auto"><CompactLogo /></div>}
        </div>

        <nav className="flex-1 px-4 py-6 space-y-2 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => (
            <DesktopMenuButton 
              key={item.id} 
              active={activeTab === item.id} 
              onClick={() => setActiveTab(item.id as Tab)} 
              collapsed={isSidebarCollapsed}
              {...item} 
            />
          ))}
          <div className="h-px bg-white/5 my-6 mx-4"></div>
          {isMaster && (
            <DesktopMenuButton 
              active={activeTab === 'master'} 
              onClick={() => setActiveTab('master')} 
              label="Painel Master" 
              icon="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" 
              collapsed={isSidebarCollapsed}
            />
          )}
          <DesktopMenuButton 
            active={activeTab === 'configuracao'} 
            onClick={() => setActiveTab('configuracao')} 
            label="Ajustes" 
            icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" 
            collapsed={isSidebarCollapsed}
          />
        </nav>

        <div className="p-6 border-t border-white/5 space-y-4">
          <button 
            onClick={handleLogout}
            className={`w-full flex items-center gap-4 p-4 rounded-2xl text-rose-400 hover:bg-rose-500/10 transition-all ${isSidebarCollapsed ? 'justify-center' : ''}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"/></svg>
            {!isSidebarCollapsed && <span className="text-[10px] font-black uppercase tracking-widest">Encerrar</span>}
          </button>
          <button 
            onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
            className="w-full h-8 flex items-center justify-center text-white/10 hover:text-white/40 transition-all"
          >
            <div className="w-8 h-1 bg-current rounded-full"></div>
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col bg-white lg:rounded-l-[4rem] relative z-20 overflow-hidden shadow-[-40px_0_80px_rgba(0,0,0,0.4)]">
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 lg:p-12">
          {activeTab === 'calculadora' && (
            <div className="max-w-7xl mx-auto flex flex-col lg:flex-row gap-8 lg:gap-16">
              <div className="w-full lg:w-80 shrink-0">
                <FiscalHeader inputs={inputs} setInputs={setInputs} />
                <div className="h-8"></div>
                <Sidebar inputs={inputs} setInputs={setInputs} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
              </div>
              <div className="flex-1">
                <ResultsTable 
                  results={results} 
                  priceMatrix={priceMatrix} 
                  inputs={inputs} 
                  onReset={() => setInputs(defaultInputs)} 
                />
              </div>
            </div>
          )}

          {activeTab === 'catalogo' && <ProductsView onSelectNcm={(n) => {
            setInputs(prev => ({ ...prev, ncmCodigo: n.codigo, mvaOriginal: n.mvaOriginal, nomeProduto: n.descricao }));
            setActiveTab('calculadora');
          }} />}

          {activeTab === 'meus-produtos' && <MyProductsView onSelect={handleLoadSimulation} />}
          {activeTab === 'resumo-fiscal' && <ResumoFiscalView results={results} inputs={inputs} />}
          {activeTab === 'overhead' && (
            <OverheadView 
              faturamento={faturamento} 
              setFaturamento={setFaturamento}
              fixedCosts={fixedCosts}
              setFixedCosts={setFixedCosts}
              variableCosts={variableCosts}
              setVariableCosts={setVariableCosts}
              userId={session?.user?.id}
              isAutoSync={isAutoSync}
              setIsAutoSync={setIsAutoSync}
            />
          )}
          {activeTab === 'configuracao' && <ConfiguracaoView userId={session?.user?.id} />}
          {activeTab === 'master' && <AdminView />}
          {activeTab === 'jarvis' && <AIView results={results} inputs={inputs} />}
        </div>
      </main>

      {/* Mobile Bottom Dock */}
      <nav className="lg:hidden fixed bottom-0 left-0 right-0 h-20 mobile-dock flex items-center justify-around px-2 z-50">
        <MobileDockItem active={activeTab === 'calculadora'} onClick={() => setActiveTab('calculadora')} icon="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" label="Calc" />
        <MobileDockItem active={activeTab === 'meus-produtos'} onClick={() => setActiveTab('meus-produtos')} icon="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" label="Itens" />
        <MobileDockItem active={activeTab === 'jarvis'} onClick={() => setActiveTab('jarvis')} icon="M13 10V3L4 14h7v7l9-11h-7z" label="Jarvis" isAi />
        <MobileDockItem active={activeTab === 'overhead'} onClick={() => setActiveTab('overhead')} icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" label="Custos" />
        <MobileDockItem active={activeTab === 'resumo-fiscal'} onClick={() => setActiveTab('resumo-fiscal'} icon="M9 17v-2m3 2v-4m3 2v-6m-8-2h8a2 2 0 012 2v9a2 2 0 01-2 2H7a2 2 0 01-2-2V5a2 2 0 012-2z" label="Análise" />
      </nav>
    </div>
  );
};

