const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [inputs, setInputs] = useState<SimulationInputs>(defaultInputs);
  const [activeTab, setActiveTab] = useState<Tab>('calculadora');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);
  const [userProfile, setUserProfile] = useState<any>(null);
  const [faturamento, setFaturamento] = useState<number>(100000);
  const [fixedCosts, setFixedCosts] = useState<CostItem[]>([]);
  const [variableCosts, setVariableCosts] = useState<VariableCostItem[]>([]);
  const [isAutoSync, setIsAutoSync] = useState(false);

  const isMaster = useMemo(() => {
    return session?.user?.email?.toLowerCase() === MASTER_EMAIL.toLowerCase();
  }, [session]);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data } = await supabase.from('user_configs').select('*').eq('user_id', userId).maybeSingle();
      if (data) setUserProfile(data);
    } catch (e) {
      console.warn("Erro ao buscar perfil.");
    }
  }, []);

  // Saudação Dinâmica Atualizada
  const userGreetingName = useMemo(() => userProfile?.nome_completo || 'Usuário Master', [userProfile]);
  const userEmpresaName = useMemo(() => userProfile?.empresa_nome || 'Tagway Technology', [userProfile]);

  useEffect(() => {
    if (isAutoSync && faturamento > 0) {
      const totalFixedValue = fixedCosts.reduce((acc, curr) => acc + curr.valor, 0);
      const fixedPerc = (totalFixedValue / faturamento) * 100;
      const variablePerc = variableCosts.reduce((acc, curr) => acc + curr.percentual, 0);
      const totalOverheadConsolidado = Number((fixedPerc + variablePerc).toFixed(2));

      if (Math.abs(inputs.custosFixos - totalOverheadConsolidado) > 0.001) {
        setInputs(prev => ({
          ...prev,
          custosFixos: totalOverheadConsolidado
        }));
      }
    }
  }, [isAutoSync, fixedCosts, variableCosts, faturamento, inputs.custosFixos]);

  useEffect(() => {
    const init = async () => {
      const { data: { session: currentSession } } = await supabase.auth.getSession();
      setSession(currentSession);

      if (currentSession) {
        await fetchProfile(currentSession.user.id);

        try {
          const { data: oh } = await supabase.from('overhead_configs').select('*').eq('user_id', currentSession.user.id).maybeSingle();
          if (oh) {
            setFaturamento(oh.faturamento || 100000);
            setFixedCosts(oh.fixed_costs || []);
            setVariableCosts(oh.variable_costs || []);
            setIsAutoSync(!!oh.is_auto_sync);
          }
        } catch (e) { console.warn("Erro sincronia banco."); }
      }
      setIsInitialized(true);
    };
    init();
  }, [fetchProfile]);

  const results = calculateCosts(inputs);
  const priceMatrix = generatePriceMatrix(results.custoFinal, inputs);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    window.location.reload();
  };

  if (!isInitialized) return null;
  if (!session) return <Login onLoginSuccess={setSession} />;

  const menuItems = [
    { id: 'calculadora', label: 'Calc', icon: "M3 12h18M3 6h18M3 18h18" },
    { id: 'meus-produtos', label: 'Itens', icon: "M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" },
    { id: 'resumo-fiscal', label: 'Análise', icon: "M9 17v-2m3 2v-4m3 2v-6m-8-2h8a2 2 0 012 2v9a2 2 0 01-2 2H7a2 2 0 01-2-2V5a2 2 0 012-2z" },
    { id: 'overhead', label: 'Ganhos', icon: "M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2" },
    { id: 'jarvis', label: 'Jarvis', icon: "M13 10V3L4 14h7v7l9-11h-7z", isAi: true },
  ];

  const devItems = [
    { id: 'logistica', label: 'Logística', icon: "M9 17a2 2 0 11-4 0 2 2 0 014 0zM19 17a2 2 0 11-4 0 2 2 0 014 0z" },
    { id: 'estoque', label: 'Estoque', icon: "M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" },
    { id: 'metas', label: 'Metas', icon: "M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" },
    { id: 'dre', label: 'DRE', icon: "M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" },
    { id: 'caixa', label: 'Caixa', icon: "M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2z" }
  ];

  return (
    <div className="flex h-screen w-full bg-[#000000] overflow-hidden text-slate-900">
      <aside className={`hidden lg:flex flex-col border-r border-white/5 p-6 transition-all duration-300 ease-in-out relative ${isSidebarCollapsed ? 'w-[100px]' : 'w-[280px]'} h-full overflow-y-auto custom-scrollbar`}>
        <div className="mb-10 flex items-center justify-between">
          {!isSidebarCollapsed ? <TagwayHorizontalLogo className="h-7 w-auto" textColor="#FF6600" /> : <CompactLogo />}
          <button onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)} className="p-2 text-white/20 hover:text-white transition-colors">
            <svg className={`w-4 h-4 transition-transform ${isSidebarCollapsed ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 19l-7-7 7-7m8 14l-7-7 7-7" /></svg>
          </button>
        </div>

        <nav className="flex-1 space-y-1">
          {menuItems.map(item => (
            <DesktopMenuButton key={item.id} active={activeTab === item.id} onClick={() => setActiveTab(item.id as Tab)} label={item.label} icon={item.icon} isAi={item.isAi} collapsed={isSidebarCollapsed} />
          ))}
          <div className="pt-6 space-y-1">
            <p className={`text-[8px] font-black uppercase tracking-[0.3em] text-white/20 mb-3 ml-4 ${isSidebarCollapsed ? 'hidden' : ''}`}>Módulos Operacionais</p>
            {devItems.map(item => (
              <DesktopMenuButton key={item.id} active={activeTab === item.id} onClick={() => setActiveTab(item.id as Tab)} label={item.label} icon={item.icon} collapsed={isSidebarCollapsed} />
            ))}
          </div>
          <div className="pt-6 border-t border-white/5 mt-4">
            <DesktopMenuButton active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Ajustes" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" collapsed={isSidebarCollapsed} />
            {isMaster && <DesktopMenuButton active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944" collapsed={isSidebarCollapsed} />}
          </div>
        </nav>
      </aside>

      <main className="flex-1 bg-[#f8fafc] lg:rounded-l-[3rem] shadow-2xl overflow-hidden flex flex-col relative">
        <div className="lg:hidden sticky top-0 left-0 right-0 z-[110] bg-white/80 backdrop-blur-xl border-b border-slate-100 px-6 py-4 flex items-center justify-between shadow-sm">
           <div className="flex items-center gap-3">
              <TagwayHorizontalLogo className="h-6 w-auto" textColor="#64748b" /> 
           </div>
           <div className="text-right">
              <p className="text-[10px] font-black text-slate-900 tracking-tight leading-none uppercase">Bem-vindo, {userGreetingName}</p>
              <p className="text-[7px] font-bold text-slate-400 uppercase tracking-widest mt-1 italic">{userEmpresaName}</p>
           </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 lg:p-12 pb-32 lg:pb-12">
          {activeTab === 'calculadora' && (
            <div className="flex flex-col lg:flex-row gap-8 lg:gap-12 max-w-[1600px] mx-auto animate-slide-up">
              <div className="w-full lg:w-80 space-y-6 shrink-0">
                <FiscalHeader inputs={inputs} setInputs={setInputs} />
                <Sidebar inputs={inputs} setInputs={setInputs} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />
              </div>
              <div className="flex-1">
                <ResultsTable results={results} priceMatrix={priceMatrix} inputs={inputs} onReset={() => setInputs(defaultInputs)} />
              </div>
            </div>
          )}

          {activeTab === 'meus-produtos' && <MyProductsView onSelect={(sim) => { setInputs(sim.inputs); setActiveTab('calculadora'); }} />}
          {activeTab === 'resumo-fiscal' && <ResumoFiscalView results={results} inputs={inputs} />}
          {activeTab === 'catalogo' && <ProductsView onSelectNcm={(n) => { setInputs(p => ({...p, ...n, nomeProduto: n.descricao})); setActiveTab('calculadora'); }} />}
          {activeTab === 'overhead' && <OverheadView faturamento={faturamento} setFaturamento={setFaturamento} fixedCosts={fixedCosts} setFixedCosts={setFixedCosts} variableCosts={variableCosts} setVariableCosts={setVariableCosts} userId={session?.user?.id} isAutoSync={isAutoSync} setIsAutoSync={setIsAutoSync} />}
          {activeTab === 'jarvis' && <AIView results={results} inputs={inputs} />}
          {activeTab === 'configuracao' && <ConfiguracaoView userId={session?.user?.id} onLogout={handleLogout} onProfileUpdate={() => fetchProfile(session.user.id)} />}
          {activeTab === 'master' && <AdminView />}

          {['logistica', 'estoque', 'metas', 'dre', 'caixa'].includes(activeTab) && (
            <ComingSoonView 
              title={activeTab.toUpperCase()} 
              desc={`O módulo ${activeTab} está em fase de implantação para o seu terminal. Os dados operacionais serão integrados automaticamente à sua conta.`} 
              icon={devItems.find(i => i.id === activeTab)?.icon || "M13 10V3L4 14h7v7l9-11h-7z"}
              status="Sincronizando Rede" 
              date="Março 2025" 
            />
          )}
        </div>

        <div className="lg:hidden fixed bottom-0 left-0 right-0 z-[100] mobile-dock shadow-[0_-10px_40px_rgba(0,0,0,0.1)]">
           <div className="flex items-center gap-1 overflow-x-auto no-scrollbar px-4 py-3">
              {menuItems.map(item => (
                <MobileDockItem key={item.id} active={activeTab === item.id} onClick={() => setActiveTab(item.id as Tab)} label={item.label} icon={item.icon} isAi={item.isAi} colorClass={item.isAi ? 'text-indigo-600' : ''} />
              ))}
              <div className="w-px h-8 bg-slate-100 shrink-0 mx-2"></div>
              {devItems.map(item => (
                <MobileDockItem key={item.id} active={activeTab === item.id} onClick={() => setActiveTab(item.id as Tab)} label={item.label} icon={item.icon} />
              ))}

              {isMaster && (
                <>
                  <div className="w-px h-8 bg-slate-100 shrink-0 mx-2"></div>
                  <MobileDockItem active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944" colorClass="text-amber-600" />
                </>
              )}

              <MobileDockItem active={activeTab === 'configuracao'} onClick={() => setActiveTab('configuracao')} label="Ajustes" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
           </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserConfigs {
  empresa_nome: string;
  nome_completo: string;
  email: string;
  telefone: string;
  data_nascimento: string;
  regime_tributario: 'Simples' | 'Presumido' | 'Real';
  uf_padrao_origem: string;
  uf_padrao_destino: string;
  margem_padrao: number;
  modo_apresentacao: boolean;
  senha_acesso?: string;
}

interface ConfiguracaoViewProps {
  userId?: string;
  onLogout?: () => void;
  onProfileUpdate?: () => void;
}

const ConfiguracaoView: React.FC<ConfiguracaoViewProps> = ({ userId, onLogout, onProfileUpdate }) => {
  const [configs, setConfigs] = useState<UserConfigs>({
    empresa_nome: '',
    nome_completo: '',
    email: '',
    telefone: '',
    data_nascimento: '',
    regime_tributario: 'Real',
    uf_padrao_origem: 'SP',
    uf_padrao_destino: 'SP',
    margem_padrao: 10,
    modo_apresentacao: false,
    senha_acesso: ''
  });
  const [password, setPassword] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showMasterPass, setShowMasterPass] = useState(false);

  useEffect(() => {
    if (!userId) return;
    const loadConfigs = async () => {
      const { data } = await supabase
        .from('user_configs')
        .select('*')
        .eq('user_id', userId)
        .maybeSingle();

      if (data) setConfigs(prev => ({ ...prev, ...data }));
    };
    loadConfigs();
  }, [userId]);

  const handleSave = async () => {
    if (!userId) return;
    setIsSaving(true);
    try {
      const sanitizedConfigs = {
        ...configs,
        data_nascimento: configs.data_nascimento === '' ? null : configs.data_nascimento
      };

      const { error: configError } = await supabase
        .from('user_configs')
        .upsert({ user_id: userId, ...sanitizedConfigs }, { onConflict: 'user_id' });

      if (configError) throw configError;

      if (password.length >= 6) {
        const { error: authError } = await supabase.auth.updateUser({ password });
        if (authError) throw authError;
      }

      // Notifica o componente pai para atualizar a saudação no Header
      if (onProfileUpdate) onProfileUpdate();

      alert('Perfil atualizado com sucesso!');
    } catch (err: any) {
      alert('Erro ao salvar: ' + (err.message || "Erro desconhecido"));
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-10 pb-40 animate-slide-up">
      <header className="border-b border-slate-200 pb-8 flex justify-between items-end">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Configurações</h2>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Perfil Operacional & Segurança</p>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <section className="bg-white rounded-[2.5rem] p-8 lg:p-10 border border-slate-200 shadow-sm space-y-8">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
              Identidade do Usuário
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <ConfigField label="Nome Completo" value={configs.nome_completo} onChange={(v: string) => setConfigs({...configs, nome_completo: v})} />
              <ConfigField label="E-mail" type="email" value={configs.email} onChange={(v: string) => setConfigs({...configs, email: v})} />
              <ConfigField label="Empresa" value={configs.empresa_nome} onChange={(v: string) => setConfigs({...configs, empresa_nome: v})} />
              <ConfigField label="Novo Telefone" value={configs.telefone} onChange={(v: string) => setConfigs({...configs, telefone: v})} />
            </div>

            <div className="pt-8 border-t border-slate-100 space-y-6">
              <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Segurança & Acesso</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <ConfigField label="Nova Senha de Login" type="password" value={password} onChange={(v: string) => setPassword(v)} placeholder="Defina para alterar" />

                <div className="space-y-2">
                  <label className="text-[9px] font-black uppercase tracking-widest ml-1 text-slate-400">Senha Master Atual</label>
                  <div className="relative group">
                    <input 
                      type={showMasterPass ? 'text' : 'password'}
                      readOnly
                      value={configs.senha_acesso || ''}
                      className="w-full rounded-xl px-5 py-3.5 text-sm font-mono font-bold outline-none border bg-slate-50 border-slate-200 text-slate-900 pr-12 cursor-default"
                    />
                    <button 
                      onClick={() => setShowMasterPass(!showMasterPass)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-black transition-colors"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={showMasterPass ? "M15 12a3 3 0 11-6 0 3 3 0 016 0z M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" : "M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.542-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88L1 1m11 11l11 11"}/></svg>
                    </button>
                  </div>
                  <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Senha fornecida pela administração.</p>
                </div>
              </div>
            </div>

            <div className="flex flex-col md:flex-row gap-4">
              <button 
                onClick={handleSave}
                disabled={isSaving || !userId}
                className="flex-1 bg-black text-white py-5 rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-emerald-600 transition-all shadow-xl disabled:opacity-50 active:scale-[0.98]"
              >
                {isSaving ? 'Gravando Atualizações...' : 'Confirmar Alterações'}
              </button>

              {onLogout && (
                <button 
                  onClick={onLogout}
                  className="bg-rose-50 text-rose-600 border border-rose-100 py-5 px-8 rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-rose-600 hover:text-white transition-all active:scale-[0.98]"
                >
                  Sair da Conta
                </button>
              )}
            </div>
          </section>
        </div>

        <div className="space-y-6">
           <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl">
              <h4 className="text-[10px] font-black uppercase tracking-widest text-white/40 mb-6">Status do Terminal</h4>
              <div className="flex items-center gap-4 mb-8">
                 <div className="w-4 h-4 rounded-full bg-emerald-500 animate-pulse"></div>
                 <span className="text-xs font-black uppercase tracking-widest">Conectado / Seguro</span>
              </div>
              <p className="text-[9px] font-medium text-white/30 uppercase leading-relaxed italic">
                Sua conexão está criptografada via protocolo Supabase Auth. Todas as ações neste terminal são auditadas pela Tagway Master.
              </p>
           </div>
        </div>
      </div>
    </div>
  );
};

const ConfigField = ({ label, value, onChange, placeholder, type = 'text' }: any) => (
  <div className="space-y-2">
    <label className="text-[9px] font-black uppercase tracking-widest ml-1 text-slate-400">{label}</label>
    <input 
      type={type}
      value={value || ''}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full rounded-xl px-5 py-3.5 text-sm font-bold outline-none border bg-slate-50 border-slate-200 text-slate-900 focus:border-black transition-all"
    />
  </div>
);

export default ConfiguracaoView;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado' | 'manutencao';
  telefone?: string;
  is_admin: boolean;
  role?: string;
  access_level?: string;
  senha_acesso?: string;
}

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isNewUser, setIsNewUser] = useState(false);

  useEffect(() => {
    fetchUsers();
  }, []);

  const stats = useMemo(() => {
    const total = users.length;
    const ativos = users.filter(u => u.status === 'ativo').length;
    const bloqueados = users.filter(u => u.status === 'bloqueado').length;
    const manutencao = users.filter(u => u.status === 'manutencao').length;
    return { total, ativos, bloqueados, manutencao };
  }, [users]);

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .not('nome_completo', 'is', null) // Filtra registros fantasmas sem nome
        .order('nome_completo', { ascending: true });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(err.message || "Erro ao ler rede master");
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenAdd = () => {
    setIsNewUser(true);
    setSelectedUser({
      user_id: '',
      nome_completo: '',
      email: '',
      empresa_nome: '',
      status: 'ativo',
      is_admin: false,
      role: 'Operador',
      access_level: 'Nível 1',
      senha_acesso: ''
    });
  };

  const handleSave = async () => {
    if (!selectedUser) return;

    // Validação rigorosa
    if (!selectedUser.user_id?.trim() || !selectedUser.email?.trim() || !selectedUser.nome_completo?.trim()) {
      alert("ERRO CRÍTICO: ID do Usuário, Nome Completo e E-mail são obrigatórios para evitar registros fantasmas.");
      return;
    }

    setIsSyncing(true);
    try {
      let error;
      if (isNewUser) {
        const { error: insError } = await supabase
          .from('user_configs')
          .insert([selectedUser]);
        error = insError;
      } else {
        const { error: updError } = await supabase
          .from('user_configs')
          .update({
            nome_completo: selectedUser.nome_completo,
            empresa_nome: selectedUser.empresa_nome,
            status: selectedUser.status,
            role: selectedUser.role,
            access_level: selectedUser.access_level,
            telefone: selectedUser.telefone,
            email: selectedUser.email,
            senha_acesso: selectedUser.senha_acesso
          })
          .eq('user_id', selectedUser.user_id);
        error = updError;
      }

      if (error) throw error;

      alert(`✅ Sincronização Master Concluída: ${selectedUser.nome_completo} registrado.`);
      setSelectedUser(null);
      setIsNewUser(false);
      fetchUsers();
    } catch (err: any) {
      alert("Falha na Sincronização Master: " + (err.message || "Erro de dados"));
    } finally {
      setIsSyncing(false);
    }
  };

  const handleDelete = async (userId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm('⚠️ AVISO MASTER: Deseja excluir permanentemente este terminal da rede? Esta ação não pode ser desfeita.')) return;

    try {
      const { error } = await supabase.from('user_configs').delete().eq('user_id', userId);
      if (error) throw error;
      setUsers(prev => prev.filter(u => u.user_id !== userId));
      alert('Operador removido com sucesso.');
    } catch (err: any) {
      alert('Erro ao excluir: ' + err.message);
    }
  };

  const filteredUsers = useMemo(() => {
    return users.filter(u => 
      (u.email || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
      (u.nome_completo || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
      (u.empresa_nome || '').toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  return (
    <div className="max-w-7xl mx-auto space-y-10 pb-40 animate-slide-up">
      <header className="bg-black p-10 lg:p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden border border-white/5">
        <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-indigo-600/10 blur-[180px] rounded-full -mr-40 -mt-40"></div>
        <div className="relative z-10 flex flex-col xl:flex-row justify-between items-center gap-10">
          <div className="flex items-center gap-6">
             <div className="bg-indigo-500/20 p-4 rounded-3xl border border-indigo-500/20">
                <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"/></svg>
             </div>
             <div>
               <h2 className="text-4xl lg:text-5xl font-black tracking-tighter uppercase italic leading-none">Controle Master</h2>
               <p className="text-white/30 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Monitoramento Global de Operadores</p>
             </div>
          </div>

          <div className="flex flex-wrap justify-center gap-3">
            <StatPill label="Ativos" value={stats.ativos} color="text-emerald-400" />
            <StatPill label="Blocked" value={stats.bloqueados} color="text-rose-500" />
            <StatPill label="Manut." value={stats.manutencao} color="text-amber-400" />
            <div className="bg-white/10 px-6 py-4 rounded-[1.5rem] border border-white/20 text-center shadow-xl backdrop-blur-md">
              <span className="text-[7px] font-black text-white/40 uppercase block mb-1 tracking-widest">Operadores Totais</span>
              <span className="text-xl font-black font-mono text-indigo-400">{stats.total}</span>
            </div>
          </div>

          <button 
            onClick={handleOpenAdd}
            className="bg-white text-black px-8 py-5 rounded-3xl font-black uppercase text-[11px] tracking-widest hover:bg-indigo-500 hover:text-white transition-all flex items-center gap-3 shadow-2xl active:scale-95 shrink-0"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 6v6m0 0v6m0-6h6m-6 0H6"/></svg>
            Novo Operador
          </button>
        </div>
      </header>

      <div className="relative">
        <input 
          type="text" 
          placeholder="Pesquisar por nome, email ou empresa..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full bg-white border-2 border-slate-100 rounded-[2.5rem] px-8 py-5 pl-16 text-sm font-bold shadow-xl focus:border-black outline-none transition-all"
        />
        <svg className="w-6 h-6 absolute left-7 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
      </div>

      <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-900 text-white uppercase text-[9px] font-black tracking-widest italic">
                <th className="px-10 py-6">Operador</th>
                <th className="px-10 py-6">Cargo</th>
                <th className="px-10 py-6">Empresa</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-right">Ação</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                <tr><td colSpan={5} className="p-32 text-center animate-pulse text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Lendo Sinais Master...</td></tr>
              ) : filteredUsers.length === 0 ? (
                <tr><td colSpan={5} className="p-32 text-center text-[10px] font-black uppercase text-slate-300 tracking-[0.5em]">Nenhum operador registrado</td></tr>
              ) : filteredUsers.map(user => (
                <tr 
                  key={user.user_id} 
                  className="hover:bg-slate-50 transition-all group cursor-pointer" 
                  onClick={() => { setIsNewUser(false); setSelectedUser(user); }}
                >
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 font-black group-hover:bg-black group-hover:text-white transition-all">
                          {user.nome_completo?.charAt(0) || '?'}
                       </div>
                       <div>
                          <p className="text-sm font-black text-slate-900 tracking-tight leading-none">{user.nome_completo || 'Sem Nome'}</p>
                          <p className="text-[10px] font-bold text-slate-400 mt-2 italic">{user.email}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-[10px] font-black uppercase text-indigo-500 tracking-widest">{user.role || 'Operador'}</span>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-[10px] font-black uppercase text-slate-400 italic">{user.empresa_nome || 'Tagway'}</span>
                  </td>
                  <td className="px-10 py-7">
                     <StatusBadge status={user.status} />
                  </td>
                  <td className="px-10 py-7 text-right">
                     <div className="flex items-center justify-end gap-4">
                        <button 
                          onClick={(e) => handleDelete(user.user_id, e)}
                          className="p-3 text-slate-200 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"
                          title="Remover Operador"
                        >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        </button>
                        <svg className="w-4 h-4 text-slate-200 group-hover:text-black transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7"/></svg>
                     </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {selectedUser && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/95 backdrop-blur-sm">
           <div className="bg-white w-full max-w-4xl rounded-[4rem] shadow-2xl overflow-hidden animate-slide-up border border-white/10">
              <header className="bg-black p-12 text-white flex justify-between items-center relative overflow-hidden">
                 <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-emerald-500 to-rose-500"></div>
                 <div>
                    <h3 className="text-3xl font-black uppercase italic leading-none tracking-tighter">
                      {isNewUser ? 'Cadastrar Terminal' : 'Perfil Operacional'}
                    </h3>
                    <p className="text-white/40 text-[9px] font-black uppercase tracking-widest mt-3">Sincronização Cloud Tagway</p>
                 </div>
                 <button onClick={() => { setSelectedUser(null); setIsNewUser(false); }} className="text-white/20 hover:text-white transition-all bg-white/5 p-4 rounded-2xl">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
              </header>

              <div className="p-12 grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    {isNewUser && (
                      <AdminInput 
                        label="UUID do Usuário (Painel Supabase)" 
                        value={selectedUser.user_id} 
                        onChange={(v: string) => setSelectedUser({...selectedUser, user_id: v})} 
                        placeholder="Ex: 550e8400-e29b-41d4-a716..."
                      />
                    )}
                    <AdminInput label="Nome Completo *" value={selectedUser.nome_completo} onChange={(v: string) => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="E-mail *" value={selectedUser.email} onChange={(v: string) => setSelectedUser({...selectedUser, email: v})} type="email" />

                    <div className="pt-4 border-t border-slate-100">
                      <AdminInput 
                        label="Senha de Acesso Master" 
                        value={selectedUser.senha_acesso || ''} 
                        onChange={(v: string) => setSelectedUser({...selectedUser, senha_acesso: v})} 
                        placeholder="Defina a senha para este terminal"
                      />
                      <div className="mt-4 p-5 bg-rose-50 rounded-2xl border border-rose-100 flex gap-4 items-start">
                         <div className="p-2 bg-rose-100 rounded-lg text-rose-600 shrink-0">
                           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>
                         </div>
                         <div>
                            <p className="text-[10px] font-black text-rose-600 uppercase tracking-widest leading-relaxed">
                               ⚠️ NOTA DE SEGURANÇA: Esta senha será exibida no perfil do operador para o primeiro acesso. O operador tem autonomia para alterá-la posteriormente no módulo de Ajustes.
                            </p>
                         </div>
                      </div>
                    </div>
                 </div>

                 <div className="space-y-6">
                    <AdminInput label="Cargo Operacional" value={selectedUser.role || ''} onChange={(v: string) => setSelectedUser({...selectedUser, role: v})} />
                    <AdminInput label="Empresa Vinculada *" value={selectedUser.empresa_nome} onChange={(v: string) => setSelectedUser({...selectedUser, empresa_nome: v})} />

                    <div className="space-y-3">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Estado do Terminal</label>
                       <div className="grid grid-cols-3 gap-3">
                          <StatusButton label="Ativo" active={selectedUser.status === 'ativo'} onClick={() => setSelectedUser({...selectedUser, status: 'ativo'})} color="bg-emerald-600" />
                          <StatusButton label="Manut." active={selectedUser.status === 'manutencao'} onClick={() => setSelectedUser({...selectedUser, status: 'manutencao'})} color="bg-amber-600" />
                          <StatusButton label="Block" active={selectedUser.status === 'bloqueado'} onClick={() => setSelectedUser({...selectedUser, status: 'bloqueado'})} color="bg-rose-600" />
                       </div>
                    </div>
                 </div>

                 <div className="lg:col-span-2 pt-10 border-t border-slate-100 flex gap-4">
                    <button 
                       onClick={handleSave}
                       disabled={isSyncing}
                       className="flex-1 bg-black text-white py-6 rounded-3xl font-black uppercase text-[12px] tracking-[0.2em] shadow-2xl hover:bg-emerald-600 transition-all flex items-center justify-center gap-4 active:scale-95 disabled:opacity-50"
                    >
                       {isSyncing ? 'Sincronizando Rede Cloud...' : isNewUser ? 'Cadastrar Operador na Nuvem' : 'Sincronizar Atualizações Master'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

const StatPill = ({ label, value, color }: { label: string; value: number; color: string }) => (
  <div className="bg-white/5 px-4 py-3 rounded-2xl border border-white/10 text-center min-w-[80px]">
    <span className="text-[7px] font-black text-white/30 uppercase block mb-1 tracking-widest">{label}</span>
    <span className={`text-lg font-black font-mono ${color}`}>{value}</span>
  </div>
);

const StatusBadge = ({ status }: { status: string }) => {
  const styles: any = { ativo: 'bg-emerald-100 text-emerald-600', bloqueado: 'bg-rose-100 text-rose-600', manutencao: 'bg-amber-100 text-amber-600' };
  const labels: any = { ativo: 'Ativo', bloqueado: 'Block', manutencao: 'Manut.' };
  return (
    <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${styles[status]}`}>
      {labels[status]}
    </span>
  );
};

const StatusButton = ({ label, active, onClick, color }: { label: string; active: boolean; onClick: () => void; color: string }) => (
  <button onClick={onClick} className={`py-4 rounded-2xl text-[9px] font-black uppercase tracking-widest border-2 transition-all active:scale-95 ${active ? `${color} text-white border-transparent shadow-xl` : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-slate-100'}`}>
    {label}
  </button>
);

interface AdminInputProps {
  label: string;
  value: string | undefined;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
}

const AdminInput: React.FC<AdminInputProps> = ({ label, value, onChange, placeholder, type = 'text' }) => (
  <div className="space-y-2">
    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
    <input 
      type={type} 
      value={value || ''}
      onChange={(e: React.ChangeEvent<HTMLInputElement>) => onChange(e.target.value)}
      placeholder={placeholder}
      className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 text-sm font-bold outline-none focus:border-black transition-all"
    />
  </div>
);

export default AdminView;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';

interface UserConfigs {
  empresa_nome: string;
  nome_completo: string;
  email: string;
  telefone: string;
  data_nascimento: string;
  regime_tributario: 'Simples' | 'Presumido' | 'Real';
  uf_padrao_origem: string;
  uf_padrao_destino: string;
  margem_padrao: number;
  modo_apresentacao: boolean;
  senha_acesso?: string;
}

interface ConfiguracaoViewProps {
  userId?: string;
  onLogout?: () => void;
  onProfileUpdate?: () => void;
}

const ConfiguracaoView: React.FC<ConfiguracaoViewProps> = ({ userId, onLogout, onProfileUpdate }) => {
  const [configs, setConfigs] = useState<UserConfigs>({
    empresa_nome: '',
    nome_completo: '',
    email: '',
    telefone: '',
    data_nascimento: '',
    regime_tributario: 'Real',
    uf_padrao_origem: 'SP',
    uf_padrao_destino: 'SP',
    margem_padrao: 10,
    modo_apresentacao: false,
    senha_acesso: ''
  });
  const [password, setPassword] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [showMasterPass, setShowMasterPass] = useState(false);

  useEffect(() => {
    if (!userId) return;
    const loadConfigs = async () => {
      const { data } = await supabase
        .from('user_configs')
        .select('*')
        .eq('user_id', userId)
        .maybeSingle();

      if (data) setConfigs(prev => ({ ...prev, ...data }));
    };
    loadConfigs();
  }, [userId]);

  const handleSave = async () => {
    if (!userId) return;

    // Bloqueio de salvamento vazio
    if (!configs.nome_completo?.trim() || !configs.empresa_nome?.trim()) {
      alert("⚠️ DADOS INCOMPLETOS: Por favor, preencha seu Nome Completo e o Nome da Empresa antes de salvar.");
      return;
    }

    setIsSaving(true);
    try {
      const sanitizedConfigs = {
        ...configs,
        data_nascimento: configs.data_nascimento === '' ? null : configs.data_nascimento
      };

      const { error: configError } = await supabase
        .from('user_configs')
        .upsert({ user_id: userId, ...sanitizedConfigs }, { onConflict: 'user_id' });

      if (configError) throw configError;

      if (password.length >= 6) {
        const { error: authError } = await supabase.auth.updateUser({ password });
        if (authError) throw authError;
      }

      if (onProfileUpdate) onProfileUpdate();

      alert('Perfil atualizado com sucesso!');
    } catch (err: any) {
      alert('Erro ao salvar: ' + (err.message || "Erro desconhecido"));
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-10 pb-40 animate-slide-up">
      <header className="border-b border-slate-200 pb-8 flex justify-between items-end">
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Configurações</h2>
          <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px] mt-2">Perfil Operacional & Segurança</p>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <section className="bg-white rounded-[2.5rem] p-8 lg:p-10 border border-slate-200 shadow-sm space-y-8">
            <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"/></svg>
              Identidade do Usuário
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <ConfigField label="Nome Completo *" value={configs.nome_completo} onChange={(v: string) => setConfigs({...configs, nome_completo: v})} />
              <ConfigField label="E-mail" type="email" value={configs.email} onChange={(v: string) => setConfigs({...configs, email: v})} />
              <ConfigField label="Empresa *" value={configs.empresa_nome} onChange={(v: string) => setConfigs({...configs, empresa_nome: v})} />
              <ConfigField label="Novo Telefone" value={configs.telefone} onChange={(v: string) => setConfigs({...configs, telefone: v})} />
            </div>

            <div className="pt-8 border-t border-slate-100 space-y-6">
              <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Segurança & Acesso</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <ConfigField label="Nova Senha de Login" type="password" value={password} onChange={(v: string) => setPassword(v)} placeholder="Defina para alterar" />

                <div className="space-y-2">
                  <label className="text-[9px] font-black uppercase tracking-widest ml-1 text-slate-400">Senha Master Atual</label>
                  <div className="relative group">
                    <input 
                      type={showMasterPass ? 'text' : 'password'}
                      readOnly
                      value={configs.senha_acesso || ''}
                      className="w-full rounded-xl px-5 py-3.5 text-sm font-mono font-bold outline-none border bg-slate-50 border-slate-200 text-slate-900 pr-12 cursor-default"
                    />
                    <button 
                      onClick={() => setShowMasterPass(!showMasterPass)}
                      className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-black transition-colors"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={showMasterPass ? "M15 12a3 3 0 11-6 0 3 3 0 016 0z M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" : "M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.542-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88L1 1m11 11l11 11"}/></svg>
                    </button>
                  </div>
                  <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Senha fornecida pela administração.</p>
                </div>
              </div>
            </div>

            <div className="flex flex-col md:flex-row gap-4">
              <button 
                onClick={handleSave}
                disabled={isSaving || !userId}
                className="flex-1 bg-black text-white py-5 rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-emerald-600 transition-all shadow-xl disabled:opacity-50 active:scale-[0.98]"
              >
                {isSaving ? 'Gravando Atualizações...' : 'Confirmar Alterações'}
              </button>

              {onLogout && (
                <button 
                  onClick={onLogout}
