import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '../lib/supabase';

interface UserProfile {
  user_id: string;
  nome_completo: string;
  email: string;
  empresa_nome: string;
  status: 'ativo' | 'bloqueado' | 'manutencao';
  telefone?: string;
  is_admin: boolean;
  role?: string;
  access_level?: string;
  senha_acesso?: string;
}

const MASTER_EMAIL = 'tagwaytw@gmail.com';

const AdminView: React.FC = () => {
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<UserProfile | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isNewUser, setIsNewUser] = useState(false);
  const [currentUserEmail, setCurrentUserEmail] = useState<string | null>(null);

  useEffect(() => {
    fetchUsers();
    getCurrentUser();
  }, []);

  const getCurrentUser = async () => {
    const { data: { user } } = await supabase.auth.getUser();
    setCurrentUserEmail(user?.email || null);
  };

  const isMaster = useMemo(() => {
    return currentUserEmail?.toLowerCase() === MASTER_EMAIL.toLowerCase();
  }, [currentUserEmail]);

  const stats = useMemo(() => {
    const total = users.length;
    const ativos = users.filter(u => u.status === 'ativo').length;
    const bloqueados = users.filter(u => u.status === 'bloqueado').length;
    const manutencao = users.filter(u => u.status === 'manutencao').length;
    return { total, ativos, bloqueados, manutencao };
  }, [users]);

  const fetchUsers = async () => {
    setIsLoading(true);
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('user_configs')
        .select('*')
        .not('nome_completo', 'is', null)
        .order('nome_completo', { ascending: true });

      if (error) throw error;
      if (data) setUsers(data as UserProfile[]);
    } catch (err: any) {
      setErrorMessage(err.message || "Erro ao ler rede master");
    } finally {
      setIsLoading(false);
    }
  };

  const handleOpenAdd = () => {
    if (!isMaster) {
      alert("ACESSO NEGADO: Apenas o Administrador Master pode criar terminais.");
      return;
    }
    setIsNewUser(true);
    setSelectedUser({
      user_id: '',
      nome_completo: '',
      email: '',
      empresa_nome: '',
      status: 'ativo',
      is_admin: false,
      role: 'Operador',
      access_level: 'Nível 1',
      senha_acesso: ''
    });
  };

  const handleSave = async () => {
    if (!selectedUser) return;

    if (!selectedUser.user_id?.trim() || !selectedUser.email?.trim() || !selectedUser.nome_completo?.trim()) {
      alert("ERRO CRÍTICO: ID do Usuário, Nome Completo e E-mail são obrigatórios.");
      return;
    }

    setIsSyncing(true);
    try {
      let error;
      if (isNewUser) {
        const { error: insError } = await supabase
          .from('user_configs')
          .insert([selectedUser]);
        error = insError;
      } else {
        const { error: updError } = await supabase
          .from('user_configs')
          .update({
            nome_completo: selectedUser.nome_completo,
            empresa_nome: selectedUser.empresa_nome,
            status: selectedUser.status,
            role: selectedUser.role,
            access_level: selectedUser.access_level,
            telefone: selectedUser.telefone,
            email: selectedUser.email,
            senha_acesso: selectedUser.senha_acesso
          })
          .eq('user_id', selectedUser.user_id);
        error = updError;
      }

      if (error) throw error;

      alert(`✅ Sincronização Concluída: ${selectedUser.nome_completo} atualizado.`);
      setSelectedUser(null);
      setIsNewUser(false);
      fetchUsers();
    } catch (err: any) {
      alert("Falha na Sincronização: " + (err.message || "Erro de dados"));
    } finally {
      setIsSyncing(false);
    }
  };

