                 </button>
              </header>

              <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block">Acesso Operacional</label>
