                         ...selectedUser, feature_flags: { ...selectedUser.feature_flags!, jarvis_enabled: !selectedUser.feature_flags?.jarvis_enabled }
                       })} />
                       <FlagToggle label="Módulo DRE / Financeiro" active={!!selectedUser.feature_flags?.dre_enabled} onClick={() => setSelectedUser({
                         ...selectedUser, feature_flags: { ...selectedUser.feature_flags!, dre_enabled: !selectedUser.feature_flags?.dre_enabled }
                       })} />
                       <FlagToggle label="Módulo Logística" active={!!selectedUser.feature_flags?.logistica_enabled} onClick={() => setSelectedUser({
                         ...selectedUser, feature_flags: { ...selectedUser.feature_flags!, logistica_enabled: !selectedUser.feature_flags?.logistica_enabled }
                       })} />
                    </div>
                 </div>

                 <div className="space-y-6">
                    <AdminInput label="Nome do Operador" value={selectedUser.nome_completo} onChange={(v) => setSelectedUser({...selectedUser, nome_completo: v})} />
                    <AdminInput label="Unidade / Empresa" value={selectedUser.empresa_nome} onChange={(v) => setSelectedUser({...selectedUser, empresa_nome: v})} />
                    <AdminInput label="Senha de Login" value={selectedUser.senha_acesso} onChange={(v) => setSelectedUser({...selectedUser, senha_acesso: v})} />

                    <button 
                      onClick={handleSaveUser}
                      disabled={isSyncing}
                      className="w-full bg-slate-900 text-white py-6 rounded-2xl font-black uppercase text-[11px] tracking-widest mt-10 shadow-2xl hover:bg-indigo-600 transition-all disabled:opacity-50"
                    >
                      {isSyncing ? 'Sincronizando Cloud...' : 'Salvar Configurações Master'}
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

