import React, { useState, useMemo } from 'react';
import { SimulationResults, SimulationInputs } from '../types';
import { formatCurrency, calculateCosts } from '../utils/calculations';
import { supabase } from '../lib/supabase';

interface ResultsTableProps {
  results: SimulationResults;
  priceMatrix: any[];
  inputs: SimulationInputs;
  onReset?: () => void;
}

const ResultsTable: React.FC<ResultsTableProps> = ({ results, priceMatrix, inputs, onReset }) => {
  const [expandedSections, setExpandedSections] = useState<string[]>(['credits', 'purchase', 'comparativo']);
  const [isSaving, setIsSaving] = useState(false);

  // Cálculo comparativo para os 3 regimes
  const comparativos = useMemo(() => {
    const regimes: ('substituido' | 'tributado' | 'reduzido')[] = ['substituido', 'tributado', 'reduzido'];
    return regimes.map(r => ({
      regime: r,
      res: calculateCosts({ ...inputs, mode: r })
    })).sort((a, b) => b.res.margemAbsoluta - a.res.margemAbsoluta);
  }, [inputs]);

  const totalWeight = results.custoFinal + results.impostosTotais + results.margemAbsoluta;
  const pCusto = (results.custoFinal / totalWeight) * 100;
  const pFisco = (results.impostosTotais / totalWeight) * 100;
  const pLucro = (results.margemAbsoluta / totalWeight) * 100;

  const toggleSection = (id: string) => {
    setExpandedSections(prev => 
      prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]
    );
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      const { error } = await supabase.from('saved_simulations').insert({
        user_id: user.id,
        nome_produto: inputs.nomeProduto || 'Simulação Sem Nome',
        inputs: inputs,
        results: results
      });

      if (error) throw error;
