                 <PriceLevel label="Ideal" value={cat.levels['I']} color="text-emerald-500" />
                 <PriceLevel label="Desconto" value={cat.levels['D']} color="text-amber-500" />
                 <PriceLevel label="P6 (12%)" value={cat.levels['P6']} color="text-blue-500" />
               </div>
            </div>
          ))}
        </div>
      </section>
    </div>
