              {isMaster && (
                <MobileDockItem active={activeTab === 'master'} onClick={() => setActiveTab('master')} label="Master" icon="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944" colorClass="text-amber-600" />
              )}
           </div>
        </div>
      </main>
    </div>
