  const fixedPercTotal = useMemo(() => faturamento > 0 ? (totalFixed / faturamento) * 100 : 0, [totalFixed, faturamento]);
  const capTotalOverhead = useMemo(() => fixedPercTotal + totalVarWeight, [fixedPercTotal, totalVarWeight]);

